        if not hasattr(self, "data"):
            raise AttributeError("Instance must have a 'data' attribute.")
        if not isinstance(self.data, (list, bytearray)):
            raise TypeError(f"Expected list or bytearray, got {type(self.data).__name__}")
        if len(self.data) < 2:
            raise IndexError("pop_u16 requires at least two bytes of data.")

        # Pop the last byte first (least significant)
        try:
            low = self.data.pop()
            high = self.data.pop()
        except Exception as exc:
            # In case pop fails due to unexpected errors
            raise RuntimeError(f"Failed to pop bytes: {exc}") from exc

        # Validate byte values
        if not (0 <= high <= 0xFF and 0 <= low <= 0xFF):
            raise ValueError(f"Byte values out of range: high={high}, low={low}")

        return (high << 8) | low

