    16-bit unsigned integer.
    """
    # Determine the internal container that holds the bytes.  
    #  Often this is a bytearray, list of ints, or deque.  
    #  Use the most common attribute names recognized in typical
    #  byte buffer implementations.
    data_container = None
    for attr in ("_buffer", "_data", "buffer", "data", "bytes"):
        if hasattr(self, attr):
            data_container = getattr(self, attr)
            break
    if data_container is None:
        raise AttributeError(
            "No byte container found on instance; cannot pop u16."
        )

