    if not hasattr(data_container, "__len__") or not hasattr(data_container, "pop"):
        raise TypeError(
            "Byte container must support length and pop operations."
        )

    if len(data_container) < 2:
        raise IndexError("Insufficient bytes to pop a 16-bit unsigned integer")

    try:
        # In big-endian, the first popped byte is the higher-order byte.
        high = data_container.pop()
        low = data_container.pop()
    except Exception as exc:
        # If pop fails for some reason (e.g., read-only sequence), re-raise.
        raise RuntimeError("Failed to pop bytes from container") from exc

    # Validate that popped items are integers in byte range
    for byte_val, name in ((high, "high"), (low, "low")):
        if not isinstance(byte_val, int) or not (0 <= byte_val <= 0xFF):
            raise ValueError(
                f"Invalid byte value retrieved from {name} byte: {byte_val!r}"
            )

    return (high << 8) | low

def discard(self, n=-1, qid=-1, dehydration_hooks=None,
             hydration_hooks=None, **handlers):
    """
    Appends a DISCARD message to the output queue.

    :param n: number of records to discard, default = -1 (ALL)
    :param qid: query ID to discard for, default = -1 (last query)
    :param dehydration_hooks:
        Hooks to dehydrate types (dict from type (class) to dehydration
        function). Dehydration functions receive the value and returns an
        object of type understood by packstream.
    :param hydration_hooks:
        Hooks to hydrate types (mapping from type (class) to
        dehydration function). Dehydration functions receive the value of
        type understood by packstream and are free to return anything.
    :param handlers: handler functions passed into the returned Response object
    """
    # Validate and normalize numeric arguments
    if not isinstance(n, int):
        raise TypeError(f"'n' must be an int, got {type(n).__name__}")
    if n < -1:
        raise ValueError("'n' must be -1 or a non‑negative integer")
    if not isinstance(qid, int):
        raise TypeError(f"'qid' must be an int, got {type(qid).__name__}")

    # Normalise hook dictionaries
    if dehydration_hooks is None:
        dehydration_hooks = {}
    if hydration_hooks is None:
        hydration_hooks = {}
    if not isinstance(dehydration_hooks, dict):
        raise TypeError(f"'dehydration_hooks' must be a dict, got {type(dehydration_hooks).__name__}")
    if not isinstance(hydration_hooks, dict):
        raise TypeError(f"'hydration_hooks' must be a dict, got {type(hydration_hooks).__name__}")

    # Construct the DISCARD message payload
    message = {"command": "DISCARD", "n": n, "qid": qid}

    # Append to the output queue; create the queue if it doesn't exist
    if hasattr(self, "output"):
        queue = getattr(self, "output")
        if not isinstance(queue, list):
            # If the output attribute exists but isn't a list, replace it with a list
            queue = []
            setattr(self, "output", queue)
    else:
        queue = []
        setattr(self, "output", queue)

    queue.append(message)

    # Create a simple Response object if one isn't already defined on the instance
    ResponseCls = getattr(self, "Response", None)
    if ResponseCls is None:
        class _Response:
            def __init__(self, message, dehydration_hooks, hydration_hooks, handlers):
                self.message = message
                self.dehydration_hooks = dehydration_hooks
                self.hydration_hooks = hydration_hooks
                self.handlers = handlers
        ResponseCls = _Response

    # Return the Response instance
    return ResponseCls(
        message=message,
        dehydration_hooks=dehydration_hooks,
        hydration_hooks=hydration_hooks,
        handlers=handlers
    )

