        # Append to the output queue. We assume that self._output_queue exists.
        try:
            self._output_queue.append(("BEGIN", payload))
        except AttributeError:
            # If no queue attribute, create one for robustness
            self._output_queue = [("BEGIN", payload)]

        # Return a Response object if such a class is available; otherwise None.
        try:
            return Response(payload=payload, handlers=handlers)
        except NameError:
            return None

