    if not isinstance(fields, (list, tuple)):
        raise TypeError(f"fields must be a list or tuple, got {type(fields).__name__}")
    if not all(isinstance(f, str) for f in fields):
        raise TypeError("All elements in fields must be strings")
    if not isinstance(srid_map, dict):
        raise TypeError(f"srid_map must be a dict, got {type(srid_map).__name__}")

    # Extract SRID for this point type, if any
    srid = srid_map.get(name)

    # Define an __init__ that assigns the provided positional/keyword arguments
    # to the attributes defined in `fields`. If srid is defined, set it as an attribute.
    def __init__(self, *args, **kwargs):
        if len(args) > len(fields):
            raise TypeError(f"Expected at most {len(fields)} positional arguments, got {len(args)}")
        # Assign positional args
        for key, value in zip(fields, args):
            setattr(self, key, value)
        # Assign remaining keys from kwargs
        remaining_keys = set(fields) - set(kwargs.keys()) - set(args[:len(fields)])
        for key in remaining_keys:
            setattr(self, key, None)       # default to None
        for key, value in kwargs.items():
            if key not in fields:
                raise TypeError(f"Unexpected keyword argument '{key}'")
            setattr(self, key, value)
        # Set SRID if available
        if srid is not None:
            setattr(self, "srid", srid)

    # Prepare attributes for the dynamic class
    attrs = {"__init__": __init__}
    if srid is not None:
        attrs["SRID"] = srid

    # Dynamically create the subclass of Point (or object if Point is undefined)
    try:
        base_cls = Point
    except NameError:
        base_cls = object

    return type(name, (base_cls,), attrs)

