    """
    Dynamically create a Point subclass.

    Parameters
    ----------
    name : str
        The name of the new class.
    fields : list of str
        Field names for the class. Must be unique identifier strings.
    srid_map : dict
        Mapping of field names to SRID values. All keys must be present in `fields`.

    Returns
    -------
    type
        A new class with the given name and fields.
    """

    # Validate name
    if not isinstance(name, str) or not name.isidentifier():
        raise ValueError(f"Invalid class name: {name!r}")

    # Validate fields
    if not isinstance(fields, list):
        raise TypeError("fields must be a list of field names")
    field_set = set()
    for f in fields:
        if not isinstance(f, str) or not f.isidentifier():
            raise ValueError(f"Invalid field name: {f!r}")
        if f in field_set:
            raise ValueError(f"Duplicate field name: {f!r}")
        field_set.add(f)

    # Validate srid_map
    if not isinstance(srid_map, dict):
        raise TypeError("srid_map must be a dict")
    for key in srid_map:
        if key not in field_set:
            raise ValueError(f"SRID map key {key!r} not in fields")

    # Build class attributes
    attrs = {field: None for field in fields}
    attrs["srid_map"] = srid_map

    def __init__(self, *args, **kwargs):
        if args:
            if len(args) != len(fields):
                raise ValueError(
                    f"Expected {len(fields)} positional arguments, got {len(args)}"
                )
            for field_name, value in zip(fields, args):
                setattr(self, field_name, value)
        for field_name in fields:
            if field_name in kwargs:
                setattr(self, field_name, kwargs[field_name])

    def __repr__(self):
        field_str = ", ".join(f"{f}={getattr(self, f)!r}" for f in fields)
        return f"<{name}({field_str})>"

    attrs["__init__"] = __init__
    attrs["__repr__"] = __repr__

    # Create and return the new class
    return type(name, (object,), attrs)

