    class_attrs = {}
    for field_name, field_type in fields.items():
        if not isinstance(field_name, str):
            raise TypeError("Field names must be strings")
        # Default value for each field
        class_attrs[field_name] = None

    def __init__(self_inner, x, y, srid=None, **kwargs):
        # Initialize the base Point
        BasePoint.__init__(self_inner, x, y)

        # Handle SRID validation
        if srid is not None:
            if srid not in srid_map:
                raise ValueError(f"SRID {srid} is not allowed (valid SRIDs: {list(srid_map.keys())})")
            self_inner.srid = srid
        else:
            self_inner.srid = None

        # Set field values with type checking
        for fname, ftype in fields.items():
            if fname in kwargs:
                value = kwargs[fname]
                if not isinstance(value, ftype):
                    raise TypeError(f"Field '{fname}' must be of type {ftype.__name__}")
                setattr(self_inner, fname, value)
            else:
                # Explicitly set default None if not provided
                setattr(self_inner, fname, None)

