            parts.append(f"{fname}={getattr(self_inner, fname)!r}")
        return f"{name}({', '.join(parts)})"

    class_attrs['__init__'] = __init__
    class_attrs['__repr__'] = __repr__

    # Create and return the new dynamic subclass
    return type(name, (BasePoint,), class_attrs)

def deprecated(message):
    warnings = __import__('warnings')
    functools = __import__('functools')

    def decorator(func):
        if not callable(func):
            raise TypeError(f"{func!r} is not callable")
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            warnings.warn(message, category=warnings.DeprecationWarning, stacklevel=2)
            return func(*args, **kwargs)
        return wrapper
    return decorator

def deprecated(message):
    """ Decorator for deprecating functions and methods.

    ::

        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass

    """
    # Validate the message
    if not isinstance(message, str):
        raise TypeError("deprecation message must be a string")
    # Import inside the function to avoid module-level imports
    import warnings
    import functools

    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            # Emit a DeprecationWarning; use stacklevel 2 so the warning points to the caller
            warnings.warn(message, DeprecationWarning, stacklevel=2)
            return func(*args, **kwargs)
        return wrapper
    return decorator

def _shuffled(seq: Sequence[str]) -> list[str]:
    """Deterministically shuffle"""
    if not isinstance(seq, Sequence):
        raise TypeError("expected a Sequence")
    for idx, x in enumerate(seq):
        if not isinstance(x, str):
            raise TypeError(f"element {idx} is not a str")
    n = len(seq)
    # Compute a deterministic seed from the contents of the sequence
    seed = 0
    for s in seq:
        for ch in s:
            seed = (seed * 31 + ord(ch)) & 0xFFFFFFFF
    # Apply a deterministic Fisher‑Yates shuffle
    shuffled = list(seq)
    for i in range(n - 1, 0, -1):
        seed = (1664525 * seed + 1013904223) & 0xFFFFFFFF
        j = seed % (i + 1)
        shuffled[i], shuffled[j] = shuffled[j], shuffled[i]
    return shuffled

def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison

    Converts a version string into a tuple of integers.
    Non-digit separators are ignored and numeric groups are extracted.

    Examples
    --------
    >>> parse_version("1.2.3")
    (1, 2, 3)
    >>> parse_version("v1.02.beta")
    (1, 2)
    >>> parse_version("")
    ()
    >>> parse_version(None)
    ()
    """
    if not isinstance(s, str):
        return ()
    try:
        import re
    except Exception:
        return ()
    parts = re.findall(r'\d+', s)
    if not parts:
        return ()
    try:
        return tuple(int(part) for part in parts)
    except Exception:
        return ()

def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    import re
    if not isinstance(s, str):
        raise TypeError(f"Expected a string, got {type(s).__name__}")
    # Find all sequences of digits in the string
    numbers = re.findall(r'\d+', s)
    # Convert each found number to int and return as a tuple
    return tuple(int(num) for num in numbers)

def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.
    """
    def decorator(func):
        def wrapper(*args, **kwargs):
            try:
                k = key(*args, **kwargs)
            except Exception as exc:
                raise RuntimeError("Key function raised an exception") from exc
            if lock:
                # Try to use the lock as a context manager; fall back to acquire/release.
                try:
                    with lock:
                        if k in cache:
                            return cache[k]
                        result = func(*args, **kwargs)
                        cache[k] = result
                        return result
                except Exception:
                    # Fallback if the lock is not a context manager.
                    lock.acquire()
                    try:
                        if k in cache:
                            return cache[k]
                        result = func(*args, **kwargs)
                        cache[k] = result
                        return result
                    finally:
                        lock.release()
            else:
                if k in cache:
                    return cache[k]
                result = func(*args, **kwargs)
                cache[k] = result
                return result
        # Preserve function metadata
        wrapper.__name__ = func.__name__
        wrapper.__doc__ = func.__doc__
        wrapper.__dict__.update(func.__dict__)
        return wrapper
    return decorator

