                else:
                    k = key
            except Exception as e:
                # If key computation fails, do not cache; simply raise
                raise ValueError("Error computing cache key: %r" % e)

            # Helper to get or compute the value
            def get_or_set():
                try:
                    # Attempt to get value from cache
                    return cache[k]
                except KeyError:
                    # Compute, cache, and return
                    value = func(self, *args, **kwargs)
                    cache[k] = value
                    return value

            # Use lock if provided
            if lock is not None:
                try:
                    # Use as a context manager if possible
                    with lock:
                        return get_or_set()
                except AttributeError:
                    # Assume lock is a callable that returns a context manager
                    with lock():
                        return get_or_set()
            else:
                return get_or_set()

        return wrapper
    return decorator

@classmethod
    def extostr(cls, e, max_level=30, max_path_level=5):
        """
        Format an exception.
        :param e: Any exception instance.
        :type e: Exception
        :param max_level: Maximum call stack level (default 30)
        :type max_level: int
        :param max_path_level: Maximum path level (default 5)
        :type max_path_level: int
        :return The exception readable string
        :rtype str
        """
        try:
            import traceback

            tb = getattr(e, "__traceback__", None)
            if tb is None:
                return f"{type(e).__name__}: {e}"

            # Get formatted traceback lines with a depth limit
            lines = traceback.format_exception(type(e), e, tb, limit=max_level)

            def _truncate_path(path: str, level: int) -> str:
                parts = path.split("/")
                if len(parts) > level:
                    parts = parts[-level:]
                return "/".join(parts)

            new_lines = []
            for line in lines:
                # Only modify lines that contain file paths
                if line.startswith("  File "):
                    first_quote = line.find('"')
                    if first_quote != -1:
                        second_quote = line.find('"', first_quote + 1)
                        if second_quote != -1:
                            orig_path = line[first_quote + 1 : second_quote]
                            truncated = _truncate_path(orig_path, max_path_level)
                            line = (
                                line[: first_quote + 1] + truncated + line[second_quote :]
                            )
                new_lines.append(line)

            return "".join(new_lines)
        except Exception:
            # Fallback to a simple representation
            return f"{type(e).__name__}: {e}"

@classmethod
def extostr(cls, e, max_level=30, max_path_level=5):
    """
    Format an exception into a readable string with controlled traceback depth
    and truncated file paths.
    """
    try:
        # Handle None or non-exception objects gracefully
        if e is None:
            return ''
        # Ensure e behaves like an Exception
        if not hasattr(e, "__traceback__"):
            return str(e)
        exc_type = type(e).__name__
        exc_msg = str(e)

        import traceback
        import os

        # Extract traceback frames
        tb_frames = traceback.extract_tb(e.__traceback__)
        if not tb_frames:
            return f'{exc_type}: {exc_msg}'

        # Build output lines
        output = ['Traceback (most recent call last):']
        for frame in tb_frames[:max_level]:
            # Truncate file path to the last max_path_level components
            path = frame.filename
            parts = path.split(os.sep)
            if len(parts) > max_path_level:
                path = os.sep.join(['...'] + parts[-max_path_level:])
            line = f'  File "{path}", line {frame.lineno}, in {frame.name}'
            output.append(line)
            if frame.line:
                output.append(f'    {frame.line.strip()}')
        output.append(f'{exc_type}: {exc_msg}')
        return '\n'.join(output)
    except Exception as fmt_err:
        # Fallback message in case formatting fails
        return f'Exception formatting error: {fmt_err}'

@staticmethod
