        :type file_name: str
        :return: Return true (exist), false (do not exist, or invalid file name)
        :rtype bool
        """
        # Validate input
        if not isinstance(file_name, str):
            return False
        # Empty or whitespace-only file name cannot exist
        if not file_name or file_name.strip() == '':
            return False
        try:
            # Use os.path.isfile to check existence; returns True if path points to a regular file
            import os
            return os.path.isfile(file_name)
        except Exception:
            # Any exception (e.g., permission errors, invalid path) results in False
            return False

