@classmethod
def _reset_logging(cls):
    """
    Reset logging to a clean state by removing all handlers
    from the root logger and setting its level to WARNING.
    """
    try:
        import logging
        root = logging.getLogger()
        # Remove and close all handlers
        for handler in root.handlers[:]:
            try:
                root.removeHandler(handler)
                handler.close()
            except Exception:
                pass
        root.setLevel(logging.WARNING)
    except Exception:
        # In case the logging module is unavailable or any other error occurs,
        # we silently ignore to avoid breaking the caller.
        pass

@classmethod
def _reset_logging(cls):
    """
    Safely resets the class-level logger by removing all handlers and clearing any
    cached log records. The method is tolerant to missing ``logging`` imports and
    unexpected runtime errors, ensuring that it never propagates exceptions
    outward.

    This function does not return a value; it operates solely on the class's
    internal state.  It is intended for scenarios where the logging configuration
    may need to be reinitialized or fully cleared.
    """
    try:
        import logging
    except Exception:
        # If logging cannot be imported, nothing we can do so silently exit.
        return
    try:
        # Remove handlers from the class's logger, if it exists.
        if hasattr(cls, "_logger") and getattr(cls, "_logger") is not None:
            logger = cls._logger
            # Iterate over a copy of the handlers list to avoid modification errors.
            for handler in list(logger.handlers):
                try:
                    handler.close()
                except Exception:
                    # Ignore errors while closing handlers; continue cleanup.
                    pass
                try:
                    logger.removeHandler(handler)
                except Exception:
                    # Ignore if removal fails.
                    pass
            # Reset logger reference to None so subsequent uses reconstruct it.
            cls._logger = None

        # If the class stores log records or similar cached data, clear it.
        if hasattr(cls, "_log_records"):
            try:
                cls._log_records.clear()
            except Exception:
                # If the attribute is not a mutable collection, ignore the error.
                pass

        # Optional: reset any class-level configuration that might affect logging.
        # For example, removing a cached logger from the root logger namespace.
        logger_name = getattr(cls, "LOG_NAME", None)
        if logger_name:
            try:
                root_logger = logging.getLogger()
                # Remove any handlers attached to the root logger that reference this class.
                for handler in list(root_logger.handlers):
                    try:
                        if getattr(handler, "name", None) == logger_name:
                            root_logger.removeHandler(handler)
                    except Exception:
                        pass
            except Exception:
                pass
    except Exception:
        # Suppress all exceptions to make this operation safe in any context.
        pass

