def _legacy_mergeOrderings(orderings):
    """Merge multiple orderings so that within-ordering order is preserved

    Orderings are constrained in such a way that if an object appears
    in two or more orderings, then the suffix that begins with the
    object must be in both orderings.

    For example:

    >>> _mergeOrderings([
    ... ['x', 'y', 'z'],
    ... ['q', 'z'],
    ... [1, 3, 5],
    ... ['z']
    ... ])
    ['x', 'y', 'q', 1, 3, 5, 'z']

    """
    # Validate input
    if orderings is None:
        return []
    try:
        iter(orderings)
    except TypeError:
        raise TypeError("orderings must be an iterable of iterables")

    adjacency = {}
    indegree = {}
    node_order = []  # order of first appearance to make deterministic output

    for seq in orderings:
        try:
            seq_iter = iter(seq)
        except TypeError:
            raise TypeError("each ordering must be an iterable")

        seq_list = list(seq_iter)  # ensure multiple passes

        for element in seq_list:
            if element not in node_order:
                node_order.append(element)
            if element not in indegree:
                indegree[element] = 0
            if element not in adjacency:
                adjacency[element] = set()

        # add edges between consecutive elements
        for u, v in zip(seq_list, seq_list[1:]):
            if v not in adjacency[u]:
                adjacency[u].add(v)
                indegree[v] += 1

    # Kahn's algorithm for topological sort
    from collections import deque

    zero_queue = deque([node for node in node_order if indegree[node] == 0])
    result = []

    while zero_queue:
        node = zero_queue.popleft()
        result.append(node)
        for succ in adjacency[node]:
            indegree[succ] -= 1
            if indegree[succ] == 0:
                zero_queue.append(succ)

    if len(result) != len(node_order):
        raise ValueError("Cycle detected or inconsistent orderings")

    return result

