            for base in cls.__mro__:
                for nm in _collect(base):
                    if nm not in seen_all:
                        all_names.append(nm)
                        seen_all.add(nm)
            return all_names
        else:
            return _collect(cls)
    except Exception:
        # In case of any unexpected error, return an empty list to avoid crash
        return []

def names(self, all=False):  # pylint:disable=redefined-builtin
    """Return the attribute names defined by the interface."""
    if not isinstance(all, bool):
        raise TypeError("Parameter 'all' must be a boolean value.")
    try:
        # Retrieve class attributes that are not callables (methods or functions)
        class_attrs = {name: value for name, value in vars(self.__class__).items() if not callable(value)}
    except Exception as exc:
        raise RuntimeError(f"Unable to retrieve attribute names: {exc}") from exc
    if all:
        # When all=True, include every attribute regardless of name
        return sorted(class_attrs.keys())
    # Otherwise, return only public attributes (those not starting with an underscore)
    public_attrs = [name for name in class_attrs if not name.startswith("_")]
    return sorted(public_attrs)

def names(self, all=False):  # pylint:disable=redefined-builtin
    """Return the attribute names defined by the interface."""
    # Collect names declared in the class (and optionally in its bases).
    try:
        classes = self.__class__.__mro__ if all else (self.__class__,)
        names_set = set()
        for cls in classes:
            # Skip the final object because it only contains builtins.
            if cls is object:
                continue
            for name, value in cls.__dict__.items():
                # Skip private, protected, and special attributes.
                if name.startswith('_'):
                    continue
                # If the attribute is callable (method) skip it.
                if callable(value):
                    continue
                # Include properties, which are instances of property.
                if isinstance(value, property):
                    names_set.add(name)
                    continue
                # For standard class variables, include them as well
                names_set.add(name)
        return sorted(names_set)
    except Exception:
        # In case of any unforeseen error, safely return an empty list.
        return []

def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments.

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individual interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []

    # If the input is None treat it as empty
    if sequence is None:
        return output

    # Helper to decide if an object should be expanded
    def _is_expandable(obj):
        return isinstance(obj, (list, tuple))

    try:
        # Determine if sequence itself is iterable (but not a string)
        is_iterable = hasattr(sequence, "__iter__") and not isinstance(sequence, (str, bytes))
    except Exception:
        is_iterable = False

    if is_iterable:
        for item in sequence:
            if _is_expandable(item):
                # Recursively normalize nested tuples/lists
                _normalizeargs(item, output)
            else:
                output.append(item)
    else:
        output.append(sequence)

    return output

def _normalizeargs(sequence, output=None):
    """
    Normalize declaration arguments.

    Normalization arguments might contain Declarations, tuples, or single
    interfaces.

    Anything but individual interfaces or implements specs will be expanded.
    """
    if sequence is None:
        seq_iter = []
    else:
        seq_iter = sequence if isinstance(sequence, (list, tuple)) else (sequence,)

    result = []

    for item in seq_iter:
        # Expand nested sequences (but not strings or bytes)
        if isinstance(item, (list, tuple)) and not isinstance(item, (str, bytes)):
            # Recursively normalize nested items
            try:
                sub = _normalizeargs(item, None)
            except Exception:
                sub = []
            result.extend(sub)
        else:
            result.append(item)

    # If an output constructor is provided, use it to build the final container
    if output is not None:
        try:
            return output(result)
        except Exception:
            # Fallback: try using the output as a constructor that accepts an iterable
            try:
                return output(*result)
            except Exception:
                # If construction fails, return the raw result
                return result
    else:
        return result

def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []

    for item in sequence:
        # Handle strings and bytes directly (don't iterate over them)
        if isinstance(item, (str, bytes)):
            output.append(item)
            continue

        # If the item has an ``interface`` attribute, treat it as a
        # Declarion-like object.
        if hasattr(item, "interface"):
            output.append(item.interface)
            # If it also has an ``implements`` attribute, extend the result
            # with that value (which may itself be an iterable).
            impl = getattr(item, "implements", None)
            if impl is not None:
                if isinstance(impl, (list, tuple, set)):
                    output.extend(_normalizeargs(impl, []))
                else:
                    output.append(impl)
            continue

        # If the item is iterable (but not a string/bytes), recursively expand.
        if hasattr(item, "__iter__"):
            try:
                output.extend(_normalizeargs(item, []))
            except Exception as exc:
                raise ValueError(f"Failed to iterate over item {item!r}") from exc
            continue

        # Fallback: add the item as-is.
        output.append(item)

    return output

def _normalizeargs(sequence, output=None):
    """
    Normalize declaration arguments.

    Normalization arguments might contain Declarations, tuples, or single
    interfaces.

    Anything but individual interfaces or implements specs will be expanded.
    """
    # Prepare output list
    if output is None:
        output = []

    # Helper to process a single element
    def _process(el):
        # Treat strings or non-iterables as individual interfaces
        if isinstance(el, str):
            output.append(el)
            return

        if isinstance(el, tuple):
            # Preserve implements specifications, e.g., ('implements', iface, ...)
            if len(el) >= 2 and el[0] == "implements":
                output.append(el)
                return
            # Otherwise, expand the tuple
            for sub in el:
                _process(sub)
            return

        if isinstance(el, (list, set)):
            for sub in el:
                _process(sub)
            return

        # Try to iterate over other iterable types (generator, etc.)
        try:
            iterator = iter(el)
        except TypeError:
            # Not iterable: treat as individual interface/spec
            output.append(el)
        else:
            for sub in iterator:
                _process(sub)

    # If sequence is None, treat as no arguments
    if sequence is None:
        return output

    # Try to iterate over the provided sequence
    try:
        for item in sequence:
            _process(item)
    except TypeError:
        # Not iterable: treat the whole sequence as a single element
        _process(sequence)

    return output

def _c_optimizations_available():
    """
    Return the C optimization module, if available, otherwise
    a false value.

    If the optimizations are required but not available, this
    raises the ImportError.

    This does not say whether they should be used or not.
    """
    try:
        import c_optimizations
    except ImportError as exc:
        # If the optional C extension cannot be imported, we return False.
        # The caller may decide whether this is acceptable or raise the error.
        return False
    except Exception as exc:
        # A more serious error (e.g., binary incompatibility) might raise a different exception;
        # re‑raise as ImportError to signal a missing dependency.
        raise ImportError("Could not load C optimizations") from exc
    else:
        return c_optimizations

def _c_optimizations_ignored():
    """
    The opposite of `_c_optimizations_required`.
    """
    try:
        required = _c_optimizations_required()
        if not isinstance(required, bool):
            raise ValueError("Returned value from `_c_optimizations_required` must be a boolean")
        return not required
    except NameError as e:
        raise RuntimeError("Function `_c_optimizations_required` is not defined") from e
    except Exception as e:
        raise RuntimeError(f"Error evaluating `_c_optimizations_required`: {e}") from e

def _c_optimizations_ignored():
    """The opposite of `_c_optimizations_required`."""
    try:
        required = _c_optimizations_required()
    except NameError as e:
        # The required function is not defined; provide a clear error message
        raise NameError("The function `_c_optimizations_required` is not defined.") from e
    except Exception as e:
        # Re‑raise any other unexpected errors with context
        raise RuntimeError("Error evaluating `_c_optimizations_required`") from e
    return not required

def _c_optimizations_required():
    """
    Return a true value if the C optimizations are required.

    This uses the ``PURE_PYTHON`` variable as documented in `_use_c_impl`.
    """
    try:
        return not bool(PURE_PYTHON)
    except NameError:
        # If PURE_PYTHON is not defined, assume C optimizations are required.
        return True

def _c_optimizations_required():
    """
    Return a true value if the C optimizations are required.

    This uses the ``PURE_PYTHON`` variable as documented in `_use_c_impl`.
    """
    try:
        # The C optimizations are required when we are not in pure‑python mode.
        return not bool(PURE_PYTHON)
    except NameError:
        # If the global flag is not defined we assume C optimizations are needed.
        return True

def reset(self):
        """
        Reset the histogram.

        Current context is reset to an empty dict.
        Bins are reinitialized with the *initial_value*
        or with *make_bins()* (depending on the initialization).
        """
        # Reset context
        self.context = {}

        # Reinitialize bins
        # If an initial_value attribute exists and is not None use it,
        # otherwise attempt to call a method named make_bins to create bins.
        try:
            if hasattr(self, "initial_value") and self.initial_value is not None:
                # Use a copy if mutable to avoid shared state
                try:
                    from copy import deepcopy
                    self.bins = deepcopy(self.initial_value)
                except Exception:
                    # Fallback: assign directly if deepcopy fails
                    self.bins = self.initial_value
            elif hasattr(self, "make_bins") and callable(self.make_bins):
                self.bins = self.make_bins()
            else:
                # If no way to construct bins, raise an informative error
                raise AttributeError(
                    "Histogram cannot be reset: no 'initial_value' or 'make_bins' available."
                )
        except Exception as e:
            # Wrap unexpected errors to provide context
            raise RuntimeError(f"Failed to reset histogram bins: {e}") from e

        # Ensure bins is not None
        if self.bins is None:
            raise RuntimeError("Histogram bins initialization resulted in None.")

def reset(self):
        """Reset the histogram.

        Current context is reset to an empty dict.
        Bins are reinitialized with the *initial_value*
        or with *make_bins()* (depending on the initialization).
        """
        # Clear current context
        try:
            self.context = {}
        except Exception as exc:
            # If we can't reset the context, raise a runtime error
            raise RuntimeError(f"Unable to reset histogram context: {exc}") from exc

        # Reinitialize bins
        try:
            # Use initial_value if provided
            if getattr(self, "initial_value", None) is not None:
                init_val = self.initial_value
                # If the initial value itself is a dictionary, use it directly
                if isinstance(init_val, dict):
                    self.bins = init_val.copy()
                else:
                    # Otherwise create a dict for existing keys (if any)
                    current_keys = getattr(self, "bins", {}).keys()
                    self.bins = {k: init_val for k in current_keys}
            # Fall back to make_bins if initial_value isn't set
            elif getattr(self, "make_bins", None) and callable(self.make_bins):
                self.bins = self.make_bins()
            else:
                # No initial_value or make_bins, start with an empty dict
                self.bins = {}
            # Ensure we ended up with a dictionary
            if not isinstance(self.bins, dict):
                raise ValueError("Bins must be a dictionary after reset")
        except Exception as exc:
            # Roll back to a safe state before re-raising
            self.context = {}
            self.bins = {}
            raise RuntimeError(f"Failed to reset histogram bins: {exc}") from exc

def reset(self):
        """Reset the histogram.

        Current context is reset to an empty dict.
        Bins are reinitialized with the *initial_value*
        or with *make_bins()* (depending on the initialization).
        """
        # Reset the context dictionary
        for ctx_attr in ("context", "_context"):
            if hasattr(self, ctx_attr):
                try:
                    setattr(self, ctx_attr, {})
                    break
                except Exception:
                    pass

        # Determine which attribute holds the bins
        bins_attr = None
        for attr in ("bins", "_bins"):
            if hasattr(self, attr):
                bins_attr = attr
                break
        if not bins_attr:
            # No bins attribute to reset; nothing more to do
            return

        # Reinitialize the bins
        try:
            # If the instance defines an explicit initial_value, use it
            if hasattr(self, "initial_value"):
                init = getattr(self, "initial_value")
                if init is not None:
                    # Try to figure out the number of bins
                    try:
                        num = getattr(self, "num_bins")
                    except Exception:
                        try:
                            num = len(getattr(self, bins_attr))
                        except Exception:
                            num = 0
                    new_bins = [init] * num
                    setattr(self, bins_attr, new_bins)
                    return
            # Otherwise, see if we can call a make_bins() method
            if hasattr(self, "make_bins") and callable(self.make_bins):
                new_bins = self.make_bins()
                setattr(self, bins_attr, new_bins)
                return
        except Exception:
            # If anything goes wrong, fall back to an empty list
            setattr(self, bins_attr, [])

        # If we reach this point and haven't set bins, leave them unchanged
        return

def reset(self):
        """
        Reset the histogram.

        Current context is reset to an empty dict.
        Bins are reinitialized with the *initial_value*
        or with *make_bins()* (depending on the initialization).
        """
        # Reset the current context to an empty dictionary
        try:
            self.context = {}
        except AttributeError:
            # If no context attribute exists, create one
            self.context = {}

        # Reinitialize bins
        try:
            # If an explicit initial value was specified, reuse the existing
            # bin keys and assign the initial value to each
            if getattr(self, 'initial_value', None) is not None:
                existing_bins = getattr(self, 'bins', {})
                self.bins = {k: self.initial_value for k in existing_bins}
            else:
                # Otherwise regenerate the bins using the make_bins helper
                if hasattr(self, 'make_bins') and callable(self.make_bins):
                    self.bins = self.make_bins()
                else:
                    raise AttributeError(
                        "Histogram must have either 'initial_value' set "
                        "or provide a callable 'make_bins' method."
                    )
        except Exception as exc:
            # Wrap any unexpected failure in a RuntimeError for clarity
            raise RuntimeError(f"Failed to reset histogram: {exc}") from exc

def reset(self):
    """Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value*
    or with *make_bins()* (depending on the initialization).
    """
    try:
        # Reset the current context.
        self.context = {}

        # Determine how to reinitialize the bins.
        has_init_val = hasattr(self, 'initial_value') and self.initial_value is not None
        has_make_bins = hasattr(self, 'make_bins') and callable(self.make_bins)

        if has_init_val and has_make_bins:
            # Use the provided initial value for each bin returned by make_bins.
            bins = self.make_bins()
            # If make_bins returns a dict, use its keys as bin identifiers.
            try:
                if isinstance(bins, dict):
                    bins = list(bins.keys())
            except Exception:
                bins = []
            try:
                self.context = {b: self.initial_value for b in bins}
            except Exception:
                # Fallback: keep the context empty if something goes wrong.
                self.context = {}
        elif not has_init_val and has_make_bins:
            # No explicit initial value, so use the output of make_bins as the base.
            bins = self.make_bins()
            if isinstance(bins, dict):
                self.context = dict(bins)
            else:
                try:
                    self.context = {b: 0 for b in bins}
                except Exception:
                    # In case bins is not iterable, leave context empty.
                    self.context = {}
        else:
            # Neither initial_value nor make_bins are available; context remains empty.
            pass
    except Exception:
        # In any unexpected case fall back to a clean/reset context.
        try:
            self.context = {}
            if hasattr(self, 'make_bins') and callable(self.make_bins):
                bins = self.make_bins()
                if isinstance(bins, dict):
                    self.context = dict(bins)
                else:
                    self.context = {b: 0 for b in bins}
        except Exception:
            self.context = {}

def to_csv(self, separator=",", header=None):
    """.. deprecated:: 0.5 in Lena 0.5 to_csv is not used.
          Iterables are converted to tables.

    Convert graph's points to CSV.

    *separator* delimits values, the default is comma.

    *header*, if not ``None``, is the first string of the output
    (new line is added automatically).

    Since a graph can multidimensional,
    for each point first its coordinate is converted to string
    (separated by *separator*), then each part of its value.

    To convert :class:`Graph` to CSV inside a Lena sequence,
    use :class:`lena.output.ToCSV`.
    """
    # Determine iterable over points
    try:
        points_iter = self.points  # Preferred attribute
    except AttributeError:
        try:
            points_iter = iter(self)  # Fallback to iterable self
        except TypeError:
            raise TypeError("Object does not contain graph points')

    lines = []
    if header is not None:
        lines.append(str(header))

    for point in points_iter:
        # Validate point structure
        try:
            coord = point[0]
            values = point[1:]
        except Exception:
            # Point is not indexable, treat entire point as coordinate
            coord = point
            values = []

        # Convert coordinate which may be multi-dimensional
        if isinstance(coord, (list, tuple)):
            try:
                coord_str = separator.join(map(str, coord))
            except Exception:
                coord_str = str(coord)
        else:
            coord_str = str(coord)

        # Convert values
        parts = [coord_str]
        for val in values:
            if isinstance(val, (list, tuple)):
                try:
                    parts.append(separator.join(map(str, val)))
                except Exception:
                    parts.append(str(val))
            else:
                parts.append(str(val))

        csv_line = separator.join(parts)
        lines.append(csv_line)

    return "\n".join(lines)

def to_csv(self, separator=",", header=None):
    """
    Convert graph's points to CSV.

    *separator* delimits values, the default is comma.

    *header*, if not ``None``, is the first string of the output
    (new line is added automatically).

    Since a graph can be multidimensional, for each point first its
    coordinate is converted to string (separated by *separator*), then
    each part of its value.

    Returns:
        str: The CSV representation of the graph.
    """
    # Determine the iterable of points.
    points_iter = None
    if hasattr(self, "points"):
        points_iter = getattr(self, "points")
    if points_iter is None:
        # If the object itself is iterable, use it
        if hasattr(self, "__iter__"):
            points_iter = self
    if points_iter is None:
        raise RuntimeError("The object does not expose points for CSV export.")

    lines = []

    # Handle header if provided.
    if header is not None:
        lines.append(str(header))

    # Helper to convert a value into a list of string components.
    def _vals_to_str_list(value):
        if isinstance(value, (list, tuple)):
            return [str(v) for v in value]
        # Strings should not be treated as iterable here.
        if isinstance(value, str):
            return [value]
        # For other iterables (e.g., set, generator)
        try:
            iterator = iter(value)
        except TypeError:
            return [str(value)]
        # Avoid treating single numbers or strings as iterables.
        try:
            if not isinstance(value, (bytes, bytearray)):
                return [str(v) for v in iterator]
        except Exception:
            pass
        return [str(value)]

    for point in points_iter:
        try:
            # Expect point to be a pair (coord, val).
            coord, val = point[0], point[1]
        except Exception:
            # If point cannot be unpacked, treat whole point as value.
            coord, val = None, point

        coord_components = []
        if coord is not None:
            if isinstance(coord, (list, tuple)):
                # Convert each part of the coordinate.
                coord_components = [str(c) for c in coord]
            elif isinstance(coord, str):
                coord_components = [coord]
            else:
                # Non-iterable coordinate (e.g., a single number)
                coord_components = [str(coord)]

        val_components = _vals_to_str_list(val)

        # Combine coordinate and value components.
        all_components = coord_components + val_components
        line = separator.join(all_components)
        lines.append(line)

    result = "\n".join(lines)
    return result

def _get_err_indices(self, coord_name):
    """
    Return the error indices associated with a coordinate name.

    Parameters
    ----------
    coord_name : str or collection of str
        The name (or names) of the coordinate(s) whose error indices are requested.

    Returns
    -------
    list[int] or dict[str, list[int]]
        If a single name is supplied a list of integer indices is returned.
        If an iterable is supplied a dictionary mapping each name to its indices
        is returned.

    Raises
    ------
    TypeError
        If ``coord_name`` is not a string or an iterable of strings.
    KeyError
        If a supplied coordinate name cannot be found in the instance.
    """
    # Helper to process a single coordinate name
    def _single(name):
        if not isinstance(name, str):
            raise TypeError(f"Coordinate name must be a string, got {type(name).__name__}")
        # Prefer a dedicated error‑indices mapping if available
        err_map = getattr(self, "_err_indices", None)
        if isinstance(err_map, dict) and name in err_map:
            return err_map[name]
        # Fallback: try to locate the coordinate by name in the known list
        coord_list = getattr(self, "coord_names", None)
        if coord_list is None:
            coord_list = getattr(self, "coordinate_names", None)
        if coord_list is None:
            raise AttributeError("Instance has no 'coord_names' or 'coordinate_names' attribute.")
        try:
            idx = coord_list.index(name)
        except ValueError:
            raise KeyError(f"Coordinate name {name!r} not found.")
        # If the instance stores an array of errors, attempt to extract indices
        if hasattr(self, "errors"):
            try:
                err_arr = self.errors
                if hasattr(err_arr, "__getitem__"):
                    col = err_arr[:, idx]
                    # If column is NumPy array, use nonzero; otherwise iterate
                    if hasattr(col, "nonzero"):
                        return list(col.nonzero()[0])
                    else:
                        return [i for i, v in enumerate(col) if v != 0]
            except Exception:
                pass  # fall through to default
        # Default: return a single index, wrapped as a list
        return [idx]

    # Accept an iterable of names
    if isinstance(coord_name, (list, tuple, set)):
        return {nm: _single(nm) for nm in coord_name}
    # Single name case
    return _single(coord_name)

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    import numpy as np

    # Validate the coordinate name
    if not isinstance(coord_name, str):
        raise TypeError("coord_name must be a string")

    # List of possible attribute names that might store the error array
    possible_names = [
        f"err_{coord_name}",
        f"{coord_name}_err",
        f"{coord_name}err",
        f"{coord_name}Err",
        f"err{coord_name}",
        f"e_{coord_name}",
        f"e{coord_name}",
    ]

    # Find the first attribute that exists on this instance
    err_arr = None
    for name in possible_names:
        if hasattr(self, name):
            err_arr = getattr(self, name)
            break

    # If we couldn't find an error array, return an empty list
    if err_arr is None:
        return []

    # Convert to a NumPy array for easy handling; fall back to a list otherwise
    try:
        err_arr = np.asarray(err_arr)
    except Exception:
        try:
            err_arr = np.array(list(err_arr))
        except Exception:
            return []

    # Ensure we are working with a one‑dimensional array
    if err_arr.ndim > 1:
        err_arr = err_arr.ravel()

    # Build a list of indices where the error value is a finite number
    indices = []
    for i, val in enumerate(err_arr):
        # Skip None values
        if val is None:
            continue
        try:
            # val might be a NumPy scalar, Python float, or other numeric type
            if isinstance(val, (int, float, np.integer, np.floating)):
                if np.isnan(val) or not np.isfinite(val):
                    continue
            else:
                # Try converting to float to check finiteness
                fval = float(val)
                if np.isnan(fval) or not np.isfinite(fval):
                    continue
        except Exception:
            # If conversion fails, ignore this index
            continue
        indices.append(i)

    return indices

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate.

    Returns a list of indices where the error flag is true for the given
    coordinate.  Raises a KeyError if the coordinate name is not found or
    if no error mask exists for it.
    """
    # Attempt to retrieve a direct mapping of error indices
    err_indices_map = getattr(self, "_err_indices", None)
    if err_indices_map and coord_name in err_indices_map:
        indices = err_indices_map[coord_name]
        # If indices are already a list/tuple, return a copy
        if isinstance(indices, (list, tuple)):
            return list(indices)
        # Try converting an iterable (e.g., array) to a list of indices
        try:
            return [i for i, val in enumerate(indices) if val]
        except Exception:
            # If conversion fails, return the value directly if it's an int
            try:
                return [int(indices)]
            except Exception:
                pass

    # Fallback: look for a boolean mask dict mapping names to sequences of bools
    err_masks = getattr(self, "_errs", None)
    if err_masks and coord_name in err_masks:
        mask = err_masks[coord_name]
        return [i for i, val in enumerate(mask) if val]

    # Another common case: a generic error flag that applies to all coords
    generic_error_flag = getattr(self, "_error_flag", None)
    if generic_error_flag is not None:
        return [i for i, val in enumerate(generic_error_flag) if val]

    # If all attempts fail, raise an informative error
    raise KeyError(f"No error indices found for coordinate '{coord_name}'.")

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    if not isinstance(coord_name, str):
        raise TypeError(f"coord_name must be a string, got {type(coord_name).__name__}")
    if not coord_name:
        # Empty coordinate name is treated as no errors
        return []

    # Attempt to fetch the dictionary that holds error indices
    err_dict = getattr(self, "err_indices", None)
    if err_dict is None:
        # If the attribute does not exist, we cannot retrieve anything
        raise AttributeError("The instance does not have an 'err_indices' attribute.")
    if not isinstance(err_dict, dict):
        raise TypeError(f"Attribute 'err_indices' should be a dict, got {type(err_dict).__name__}")

    # Retrieve the indices for the specified coordinate
    indices = err_dict.get(coord_name)
    if indices is None:
        # No indices recorded for this coordinate
        return []

    # Ensure the indices are returned as a list
    if isinstance(indices, (list, tuple)):
        return list(indices)
    try:
        return list(indices)
    except Exception as exc:
        raise TypeError(f"Error indices for coordinate '{coord_name}' are of unsupported type "
                        f"'{type(indices).__name__}'.") from exc

def _update_context(self, context):
        """
        Update *context* with the properties of this graph.

        *context.error* is appended with indices of errors.
        Example subcontext for a graph with fields "E,t,error_E_low":
        {"error": {"x_low": {"index": 2}}}.
        Note that error names are called "x", "y" and "z"
        (this corresponds to first three coordinates,
        if they are present), which allows to simplify plotting.
        Existing values are not removed
        from *context.value* and its subcontexts.
        """
        if context is None or not isinstance(context, dict):
            return

        # Ensure error dictionary exists
        err_ctx = context.setdefault('error', {})

        # Determine coordinate names in order; fallbacks if attributes missing
        coord_names = []
        try:
            if hasattr(self, 'coordinates'):
                coord_names = list(self.coordinates)
            elif hasattr(self, 'field_names'):
                coord_names = list(self.field_names)
            elif hasattr(self, '_fields'):
                # Assume _fields is iterable of objects with attribute 'name'
                coord_names = [f.name for f in self._fields if hasattr(f, 'name')]
        except Exception:
            coord_names = []

        # Map coordinate indices to prefixes
        coord_prefix = {idx: pref for idx, pref in enumerate(['x', 'y', 'z'])}

        # Helper to extract coordinate index from error field name
        def get_coord_index(name):
            # name format: "<coord>_<suffix>" or just "<coord>"
            try:
                key = name.split('_', 1)[0]
                return coord_names.index(key)
            except Exception:
                return None

        # Iterate over error fields defined in this graph
        for attr_name in dir(self):
            if not attr_name.startswith('error_'):
                continue
            # Resolve the error object
            try:
                err_obj = getattr(self, attr_name)
            except Exception:
                continue

            # Obtain index attribute if present
            index = getattr(err_obj, 'index', None)
            if index is None:
                # Some error objects might store index in a property named 'indices' or similar
                index = getattr(err_obj, 'indices', None)
                if isinstance(index, (list, tuple)) and index:
                    index = index[0]
            if index is None:
                continue

            # Parse the rest of the name after 'error_'
            rest_name = attr_name[len('error_') :]
            # Determine coordinate prefix
            coord_idx = get_coord_index(rest_name)
            if coord_idx is not None:
                prefix = coord_prefix.get(coord_idx, 'x')
            else:
                # If nothing matches, try simple order or default to x
                # Count previous errors to assign sequential prefixes
                prefix = 'x'
            # Build the suberror key
            rest_parts = rest_name.split('_', 1)
            if len(rest_parts) == 2:
                sub_key = f"{prefix}_{rest_parts[1]}"
            else:
                sub_key = f"{prefix}"
            # Append to context
            err_ctx[sub_key] = {'index': index}
        # No explicit return; context is modified in place

def _update_context(self, context):
        """Update *context* with the properties of this graph.

        *context.error* is appended with indices of errors.
        Example subcontext for a graph with fields "E,t,error_E_low":
        {"error": {"x_low": {"index": 2}}}.
        Note that error names are called "x", "y" and "z"
        (this corresponds to first three coordinates,
        if they are present), which allows to simplify plotting.
        Existing values are not removed
        from *context.value* and its subcontexts.

        Called on "destruction" of the graph (for example,
        in :class:`.ToCSV`). By destruction we mean conversion
        to another structure (like text) in the flow.
        The graph object is not really destroyed in this process.
        """
        # Ensure context is a mapping with 'error' key
        try:
            error_ctx = context.get('error')
        except AttributeError:
            # context may be an object with attribute 'error'
            error_ctx = getattr(context, 'error', None)

        if error_ctx is None:
            # create a new error subcontext
            error_ctx = {}
            if isinstance(context, dict):
                context['error'] = error_ctx
            else:
                # try to set attribute
                setattr(context, 'error', error_ctx)

        # Determine coordinate mapping for the first three fields
        coord_names = ['x', 'y', 'z']
        try:
            fields = list(self.fields)
        except AttributeError:
            # if no fields attribute, cannot proceed
            return

        # Prepare a lookup from field name to coordinate name
        field_to_coord = {}
        for idx, fname in enumerate(fields):
            if idx < 3:
                field_to_coord[fname] = coord_names[idx]
        # Attempt to obtain error indices mapping if available
        error_indices = {}
        if hasattr(self, '_errorIndices'):
            error_indices = getattr(self, '_errorIndices')
        elif hasattr(self, 'errorIndices'):
            error_indices = getattr(self, 'errorIndices')

        # Iterate over error fields
        for fname in fields:
            if not isinstance(fname, str):
                continue
            if fname.lower().startswith('error_'):
                # Extract the variable part after 'error_'
                rest = fname[len('error_'):]
                # rest might be like 'E_low' or 'fieldname_suffix'
                # Split on first underscore to get base field and suffix
                parts = rest.split('_', 1)
                if not parts:
                    continue
                base = parts[0]
                suffix = parts[1] if len(parts) > 1 else ''
                # Find coordinate for the base field
                coord = field_to_coord.get(base)
                if coord is None:
                    # try to find full match in fields
                    try:
                        idx_base = fields.index(base)
                        if idx_base < 3:
                            coord = coord_names[idx_base]
                    except ValueError:
                        # no coordinate mapping available
                        continue
                # Construct subcontext key, e.g., 'x_low'
                sub_key = f"{coord}_{suffix}" if suffix else coord
                # Retrieve index if available, default to 0
                idx_val = error_indices.get(fname, 0)
                # Append to error context
                try:
                    sub_ctx = error_ctx.get(sub_key)
                except AttributeError:
                    sub_ctx = None
                if sub_ctx is None:
                    sub_ctx = {}
                    error_ctx[sub_key] = sub_ctx
                sub_ctx['index'] = idx_val

        # Existing values are not modified; no action required for context.value.

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    # Validate bin sequence
    try:
        n_bins = len(bins)
    except Exception as exc:
        raise TypeError("bins must be a sequence of numeric values") from exc

    # Validate edges sequence and convert to list for indexing
    try:
        edges_list = list(edges)
    except Exception as exc:
        raise TypeError("edges must be a sequence of numeric values") from exc

    # Ensure the number of edges is one more than the number of bins
    if len(edges_list) != n_bins + 1:
        raise ValueError(
            f"Number of edges ({len(edges_list)}) must equal number of bins ({n_bins}) + 1"
        )

    # Compute the integral as the sum over bin heights times bin widths
    total = 0.0
    for bin_height, edge_left, edge_right in zip(bins, edges_list[:-1], edges_list[1:]):
        try:
            bin_height_val = float(bin_height)
            width = float(edge_right - edge_left)
            total += bin_height_val * width
        except Exception as exc:
            raise TypeError(
                f"Non numeric bin height or edge encountered: {bin_height!r}, {edge_left!r}, {edge_right!r}"
            ) from exc

    return total

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    # Basic type and length checks
    if bins is None or edges is None:
        raise ValueError("bins and edges must not be None")

    try:
        nbins = len(bins)
    except TypeError:
        raise ValueError("bins must be a sequence")
    try:
        nedges = len(edges)
    except TypeError:
        raise ValueError("edges must be a sequence")

    if nedges != nbins + 1:
        raise ValueError("edges length must be len(bins) + 1")

    integral = 0.0
    for i in range(nbins):
        try:
            # Compute bin width
            left = float(edges[i])
            right = float(edges[i + 1])
            width = right - left
            if width < 0:
                raise ValueError("edges must be non-decreasing")
            # Bin value
            value = float(bins[i])
        except (TypeError, ValueError) as exc:
            raise ValueError(f"Invalid numeric value at bin {i}: {exc}") from exc
        integral += value * width

    return float(integral)

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    # Normalize inputs to lists to allow multiple passes and len checks
    try:
        bins_list = list(bins)
    except TypeError:
        raise TypeError("bins must be an iterable")
    try:
        edges_list = list(edges)
    except TypeError:
        raise TypeError("edges must be an iterable")
    # Basic sanity check on lengths
    if not edges_list:
        raise ValueError("edges cannot be empty")
    if len(bins_list) + 1 != len(edges_list):
        raise ValueError(
            "Number of edges must be exactly one more than number of bins "
            f"(got {len(bins_list)} bins and {len(edges_list)} edges)"
        )
    # If there are no bins, the integral is 0
    if not bins_list:
        return 0.0
    # Compute the integral by summing bin value times bin width
    total = 0.0
    for i, value in enumerate(bins_list):
        try:
            width = float(edges_list[i + 1] - edges_list[i])
        except Exception as exc:
            raise ValueError(f"cannot compute width between edges {edges_list[i]} and {edges_list[i+1]}")
        if width < 0:
            raise ValueError(f"edges must be non-decreasing; got negative width at bin {i}")
        try:
            total += float(value) * width
        except Exception as exc:
            raise ValueError(f"cannot multiply bin value {value} by width {width}") from exc
    return total

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    # Direct instance of FillRequest
    if isinstance(seq, FillRequest):
        return True

    # Exclude Source sequences explicitly
    if isinstance(seq, Source):
