    # Try to iterate over seq; if it fails, treat it as a single element.
    try:
        iterator = iter(seq)
    except TypeError:
        # seq is not iterable
        return _is_fill_request(seq) and not _is_source_sequence(seq)

    # seq is iterable: ensure it is not a source sequence itself.
    if _is_source_sequence(seq):
        return False

    # Look for at least one FillRequest element.
    for item in seq:
        try:
            if _is_fill_request(item):
                return True
        except Exception:
            # Ignore items that aren't well-formed objects.
            continue
    return False

