    """
    Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.
    """

    # Validate input types
    if not isinstance(d1, dict):
        raise TypeError("d1 must be a dictionary")
    if d2 is None:
        # nothing to compare against
        return d1
    if not isinstance(d2, dict):
        # d2 not a dict: treat as empty dict, all of d1 is difference
        return d1

    # depth handling
    # a level <= 0 means no further recursion; a negative value means infinite recursion
    def _diff(d1_sub, d2_sub, lvl):
        if lvl == 0:
            return {}
        result = {}
        for k, v1 in d1_sub.items():
            if k not in d2_sub:
                # key absent in d2
                if isinstance(v1, dict):
                    # When copying a dict we can reuse it because the result is read‑only
                    result[k] = v1
                else:
                    result[k] = v1
            else:
                v2 = d2_sub[k]
                if isinstance(v1, dict) and isinstance(v2, dict) and (lvl == -1 or lvl > 1):
                    sub = _diff(v1, v2, lvl - 1 if lvl > 0 else -1)
                    if sub:
                        result[k] = sub
                elif v1 != v2:
                    result[k] = v1
        return result

    return _diff(d1, d2, level)

