    def _diff(sub1, sub2, curr_level):
        result = {}
        for k, v1 in sub1.items():
            if k not in sub2:
                # Key exists only in d1; include directly
                result[k] = v1
            else:
                v2 = sub2[k]
                if isinstance(v1, dict) and isinstance(v2, dict):
                    if curr_level == -1 or curr_level > 0:
                        sub_res = _diff(v1, v2, -1 if curr_level == -1 else curr_level - 1)
                        if sub_res:
                            result[k] = sub_res
                    # If curr_level == 0, do not recurse; compare as values
                    else:
                        if v1 != v2:
                            result[k] = v1
                else:
                    if v1 != v2:
                        result[k] = v1
        return result
    return _diff(d1, d2, level)

def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.
    """
    # Validate arguments
    if not isinstance(d1, dict):
        raise TypeError("d1 must be a dictionary")
    if not isinstance(d2, dict):
        raise TypeError("d2 must be a dictionary")
    if not isinstance(level, int):
        raise TypeError("level must be an integer")
    if level < -1:
        raise ValueError("level must be >= -1")

    def _diff(a, b, lvl):
        out = {}
        for k, v in a.items():
            if k not in b:
                out[k] = v
            else:
                b_val = b[k]
                # Recurse into dictionaries if allowed
                if isinstance(v, dict) and isinstance(b_val, dict) and (lvl != 0):
                    sub = _diff(v, b_val, (lvl-1) if lvl > 0 else -1)
                    if sub:
                        out[k] = sub
                else:
                    if v != b_val:
                        out[k] = v
        return out

    return _diff(d1, d2, level)

def fill(self, coord, weight=1):
        """Fill histogram at *coord* with the given *weight*.

        Coordinates outside the histogram edges are ignored.
        """
        # Normalize coordinates to a tuple
        try:
            is_iterable = hasattr(coord, "__iter__") and not isinstance(coord, (str, bytes))
        except Exception:
            is_iterable = False
        if not is_iterable:
            coord = (coord,)
        else:
            coord = tuple(coord)

        # Validate dimensions
        if not hasattr(self, "_edges"):
            raise AttributeError("Histogram missing '_edges' attribute.")
        if not hasattr(self, "_data"):
            raise AttributeError("Histogram missing '_data' attribute.")

        ndim = len(self._edges)
        if len(coord) != ndim:
            raise ValueError(f"Coordinate length {len(coord)} does not match histogram dimensions {ndim}.")

        # Validate weight
        try:
            weight_val = float(weight)
        except Exception:
            raise TypeError(f"Weight '{weight}' is not a numeric value.")

        # Find bin indices for each coordinate
        bin_indices = []
        try:
            from bisect import bisect_right
        except Exception as e:
            raise ImportError("Failed to import bisect module.") from e

        for dim, (value, edges) in enumerate(zip(coord, self._edges)):
            # Ensure edges is a sequence
            try:
                edges_seq = list(edges)
            except Exception:
                raise TypeError(f"Edges for dimension {dim} must be a sequence.")
            if not edges_seq:
                raise ValueError(f"Edge list for dimension {dim} is empty.")

            # Place value in bin: edges[i] <= value < edges[i+1]
            pos = bisect_right(edges_seq, value) - 1
            # Check bounds
            if pos < 0 or pos >= self._data.shape[dim]:
                # Outside histogram bounds
                return
            bin_indices.append(pos)

        # Increment the histogram bin
        try:
            self._data[tuple(bin_indices)] += weight_val
        except Exception as e:
            raise RuntimeError(f"Failed to increment histogram bin at indices {bin_indices}.") from e

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    # Convert coordinate to a list (handle scalar input)
    try:
        if isinstance(coord, (int, float)):
            coord = [coord]
        coord = list(coord)
    except Exception:
        return

    # Ensure required attributes exist
    if not hasattr(self, "bin_edges") or not hasattr(self, "values"):
        return

    ndim = len(self.bin_edges)
    if len(coord) != ndim:
        return

    try:
        indices = []
        for ax, c in enumerate(coord):
            edges = self.bin_edges[ax]
            # Reject invalid or empty edges
            if not edges:
                return
            # Outside histogram range
            if c < edges[0] or c >= edges[-1]:
                return
            # Binary search to find the proper bin
            lo, hi = 0, len(edges) - 2
            idx = None
            while lo <= hi:
                mid = (lo + hi) // 2
                if edges[mid] <= c < edges[mid + 1]:
                    idx = mid
                    break
                elif c >= edges[mid + 1]:
                    lo = mid + 1
                else:
                    hi = mid - 1
            if idx is None:  # should not happen, but safety first
                return
            indices.append(idx)
        # Increment the appropriate bin by the weight
        self.values[tuple(indices)] += weight
    except Exception:
        # Fail silently to keep the histogram consistent
        pass

def fill(self, coord, weight=1):
    """
    Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    # Attempt to access the histogram data array
    data = getattr(self, 'data', None)
    if data is None:
        data = getattr(self, '_data', None)
    if data is None:
        # No data array to fill
        return

    # Convert coordinates to a tuple of integers
    try:
        indices = tuple(int(c) for c in coord)
    except (TypeError, ValueError):
        try:
            # coord might be a single value
            indices = (int(coord),)
        except (TypeError, ValueError):
            return  # Cannot interpret coordinates

    # Check dimensionality
    try:
        ndim = data.ndim
    except AttributeError:
        # If data has no ndim attribute, assume 1-D
        ndim = 1 if not isinstance(data, (list, tuple)) else len(data)

    if len(indices) != ndim:
        return  # Dimension mismatch, ignore

    # Check bounds for each dimension
    try:
        shape = data.shape
    except AttributeError:
        # If shape is not available, approximate from data list
        def get_shape(d):
            if isinstance(d, (list, tuple)):
                return (len(d),) + get_shape(d[0]) if d else (len(d),)
            return ()
        shape = get_shape(data)

    if len(shape) != ndim:
        return  # Mismatch between shape and ndim, ignore

    for idx, dim_size in zip(indices, shape):
        if idx < 0 or idx >= dim_size:
            return  # Out-of-bounds, ignore

    # Convert weight to numeric type
    try:
        w = float(weight)
    except Exception:
        return  # Weight not numeric, ignore

    # Add the weight to the appropriate bin
    try:
        data[indices] += w
    except Exception:
        # Fallback for nested list data
        def set_value(lst, inds, val):
            for i, ind in enumerate(inds[:-1]):
                lst = lst[ind]
            lst[inds[-1]] += val

        set_value(data, indices, w)

def fill(self, coord, weight=1):
        """Fill histogram at *coord* with the given *weight*.

        Coordinates outside the histogram edges are ignored.
        """
        # Verify coordinate is array-like and has correct dimensionality
        try:
            coord_arr = np.asarray(coord, dtype=float)
        except Exception as exc:
            raise ValueError(f"Coordinate {coord} cannot be converted to a numeric array.") from exc

        if coord_arr.shape[0] != getattr(self, 'ndim', None):
            raise ValueError(f"Coordinate dimension {coord_arr.shape[0]} does not match histogram dimension {getattr(self, 'ndim', None)}.")

        # Determine the bin indices for each dimension
        bin_indices = []
        for dim, c in enumerate(coord_arr):
            edges = self.edges[dim]  # assuming self.edges stores array of bin edges per dimension
            # Use left-inclusive, right-exclusive bins: ignore if c is outside the valid range
            if c < edges[0] or c >= edges[-1]:
                return  # outside histogram edges: do nothing
            # Find bin index such that edges[idx] <= c < edges[idx+1]
            idx = np.searchsorted(edges, c, side='right') - 1
            if idx < 0 or idx >= len(edges) - 1:
                return
            bin_indices.append(idx)

        # Increment the histogram counts
        try:
            w = float(weight)
        except Exception as exc:
            raise ValueError(f"Weight {weight} is not a numeric value.") from exc

        # Handle 1D histogram
        if len(bin_indices) == 1:
            self.bins[bin_indices[0]] += w
        else:
            # Multi-dimensional histogram
            self.bins[tuple(bin_indices)] += w

        return True

def _validate_labels(labels):
    """
