            - key: the label key or label value for which an error occurred as string.
            - value: the error message.
    """
    import re

    # Basic validation of input
    if not isinstance(labels, dict):
        raise TypeError("labels must be a dict")

    # Regular expressions for keys and values
    key_pattern = re.compile(r'^[a-zA-Z_][a-zA-Z0-9_.]*$')
    value_pattern = re.compile(r'^[^,]{1,255}$')  # Simplified placeholder pattern

    errors = []

    for key, value in labels.items():
        # Validate key type
        if not isinstance(key, (str, bytes)):
            errors.append({str(key): 'expected string or bytes-like object'})
        else:
            # Validate key regex
            if not key_pattern.fullmatch(key):
                errors.append({key: f"Label key '{key}' does not match the regex [...]"})

        # Validate value
        if isinstance(value, list):
            # If value is a list, treat each element separately
            for element in value:
                if not isinstance(element, (str, bytes)):
                    errors.append({str(element): 'expected string or bytes-like object'})
                else:
                    if not value_pattern.fullmatch(element):
                        errors.append({element: f"Label value '{element}' does not match the regex [...]"})
        else:
            # Non-list value
            if not isinstance(value, (str, bytes)):
                errors.append({str(value): 'expected string or bytes-like object'})
            else:
                if not value_pattern.fullmatch(value):
                    errors.append({value: f"Label value '{value}' does not match the regex [...]"})

    if errors:
        # Assuming ValidationError is defined elsewhere with a `messages` attribute
        raise ValidationError(errors)

def _validate_labels(labels):
    """
    Check that keys and values in the given labels match against their corresponding
    regular expressions.
    """
    # Regular expression patterns that match valid Kubernetes label keys and values.
    # For simplicity, we use a pattern that allows alphanumeric characters, dashes,
    # underscores, periods, and separators. The key/value must start and end with
    # an alphanumeric character and be at most 63 characters long. The pattern
    # below does not enforce the length limit because that detail is not
    # specified in the original description, but it captures the common
    # validation constraints.
    import re
    key_pattern = re.compile(r'^[A-Za-z0-9]([-A-Za-z0-9_.]*[A-Za-z0-9])?$')
    value_pattern = re.compile(r'^[A-Za-z0-9]([-A-Za-z0-9_.]*[A-Za-z0-9])?$')

    errors = []

    # If labels is not a mapping, raise a clear exception.
    try:
        items = labels.items()
    except AttributeError:
        raise TypeError("labels must be a mapping type")

    for k, v in items:
        # Validate the key
        try:
            if not key_pattern.match(k):
                errors.append({repr(k): f"Label key {repr(k)} does not match the regex"})
        except TypeError:
            errors.append({repr(k): "expected string or bytes-like object"})

        # Validate the value.  The value may be a list/tuple of strings or a single string.
        # We iterate over elements when appropriate to capture all errors.
        if isinstance(v, (list, tuple)):
            for elem in v:
                try:
                    if not value_pattern.match(elem):
                        errors.append({repr(elem): f"Label value {repr(elem)} does not match the regex"})
                except TypeError:
                    errors.append({repr(elem): "expected string or bytes-like object"})
        else:
            try:
                if not value_pattern.match(v):
                    errors.append({repr(v): f"Label value {repr(v)} does not match the regex"})
            except TypeError:
                errors.append({repr(v): "expected string or bytes-like object"})

    if errors:
        # Assume ValidationError has a constructor that accepts a list of error dicts
        # and exposes a .messages attribute containing that list.
        raise ValidationError(errors)

def validate_value(value):
    """Validate the given value against the corresponding regular expression.

    Args:
        value: the string to validate

    Raises:
        ValidationError: if the given value is not conform to the regular expression.
    """
    try:
        ValidationError
    except NameError:
        class ValidationError(Exception):
            """Fallback ValidationError if not defined elsewhere."""
            pass

    if not isinstance(value, str):
        raise ValidationError("Value must be a string")

    # Simple alphanumeric validation (acts as a stand‑in for a real regex)
    if not value.isalnum():
