def validate_value(value):
    """Validate the given value against the corresponding regular expression.

    Args:
        value: the string to validate

    Raises:
        ValidationError: if the given value is not conform to the regular expression.
    """
    # Try to determine the value and regex from different input types
    try:
        import re

        # If a dictionary is provided, look for 'value' and 'regex' keys
        if isinstance(value, dict):
            val = value.get('value')
            regex = value.get('regex')
            if regex is None:
                raise ValidationError("No regex provided for validation.")
        # If a tuple or list is provided, treat the first element as the value
        elif isinstance(value, (tuple, list)) and len(value) == 2:
            val, regex = value
        else:
            # If only a string is provided, use a default permissive regex
            val = value
            regex = r'^.+$'  # matches any non-empty string

        # Basic type checks
        if not isinstance(val, str):
            raise ValidationError(f"Value must be a string, got {type(val).__name__}.")
        if not isinstance(regex, str):
            raise ValidationError("Regex must be a string.")

        # Perform regex validation
        if not re.fullmatch(regex, val):
            raise ValidationError(f"Value '{val}' does not match regex '{regex}'.")
    except Exception as exc:
        # Re-raise ValidationError unchanged; wrap other exceptions
        if isinstance(exc, ValidationError):
            raise
        else:
            raise ValidationError(str(exc)) from None

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """
    Recursively generate a schema dictionary from a Kubernetes resource fragment.

    Args:
        manifest_dict (dict): Partial Kubernetes resources
        first_level (bool, optional): If True, indicates that the dictionary represents
            the whole observer schema of a Kubernetes resource

    Returns:
        dict: Generated partial observer_schema

    This function creates a new dictionary from ``manifest_dict`` and replaces all
    non-list and non-dict values by ``None``.

    In case of ``first_level`` dictionary (i.e. complete ``observer_schema`` for a
    resource), the values of the identifying fields are copied from the manifest file.
    """
    if not isinstance(manifest_dict, dict):
        raise TypeError(f"Expected manifest_dict to be a dict, got {type(manifest_dict).__name__}")

    schema = {}
    for key, value in manifest_dict.items():
        if isinstance(value, dict):
            schema[key] = generate_default_observer_schema_dict(value, first_level=False)
        elif isinstance(value, list):
            try:
                from . import generate_default_observer_schema_list  # type: ignore
            except Exception:  # pragma: no cover
                raise ImportError("generate_default_observer_schema_list function not available")
            schema[key] = generate_default_observer_schema_list(value, first_level=False)
        else:
            schema[key] = None

    if first_level:
        # Copy top-level identifying fields
        for id_key in ("apiVersion", "kind"):
            if id_key in manifest_dict:
                schema[id_key] = manifest_dict[id_key]

        # Extract identifying fields from metadata if present
        if "metadata" in manifest_dict and isinstance(manifest_dict["metadata"], dict):
            meta_src = manifest_dict["metadata"]
            meta_dst = {}
            for mkey in ("name", "namespace", "uid"):
                if mkey in meta_src:
                    meta_dst[mkey] = meta_src[mkey]
            if meta_dst:
                schema["metadata"] = meta_dst

    return schema

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """
    Generate a default observer_schema dictionary from a partial Kubernetes manifest dictionary.
    All non-dict and non-list values are replaced by None, except when `first_level` is True,
    in which case the top-level primitive values are preserved.

    Args:
        manifest_dict (dict): Partial Kubernetes resources.
        first_level (bool, optional): If True, indicates that the dictionary represents
                                      the whole observer_schema of a Kubernetes resource.

    Returns:
        dict: Generated partial observer_schema.
    """
    if not isinstance(manifest_dict, dict):
        raise TypeError("manifest_dict must be a dictionary")

    schema_dict = {}
    for key, value in manifest_dict.items():
        # Handle mapping (dict) values
        if isinstance(value, dict):
            schema_dict[key] = generate_default_observer_schema_dict(value, first_level=False)
        # Handle sequence (list) values
        elif isinstance(value, list):
            new_list = []
            for item in value:
                if isinstance(item, dict):
                    new_list.append(generate_default_observer_schema_dict(item, first_level=False))
                else:
                    # non-dict inside list replaced by None
                    new_list.append(None)
            schema_dict[key] = new_list
        # Primitive or other value types
        else:
            if first_level:
                schema_dict[key] = value
            else:
                schema_dict[key] = None

    return schema_dict

def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:``update_last_applied_manifest_dict_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (list): partial ``last_applied_manifest`` being
            updated
        observer_schema (list): partial ``observer_schema``
        response (list): partial response from the Kubernetes API.

    This function go through all observed fields, and initialized their value in
    last_applied_manifest if they are not yet present

    """
    # Defensive checks
    if not isinstance(last_applied_manifest, list):
        raise TypeError(
            f"last_applied_manifest must be a list, got {type(last_applied_manifest).__name__}"
        )
    if not isinstance(response, list):
        # Nothing to do if the response is not a list
        return
    # If no schema is provided, simply copy response elements
    if observer_schema is None:
        for i, item in enumerate(response):
            if i < len(last_applied_manifest):
                last_applied_manifest[i] = item
            else:
                last_applied_manifest.append(item)
        return
    # Iterate over response items
    for idx, resp_item in enumerate(response):
        # Ensure there is a corresponding element in the manifest
        if idx < len(last_applied_manifest):
            current = last_applied_manifest[idx]
        else:
            # Create a placeholder for a new element
            current = {}
            last_applied_manifest.append(current)
        # Handle dict-like objects
        if isinstance(resp_item, dict):
            # If current is not a dict, replace it
            if not isinstance(current, dict):
                current = {}
                last_applied_manifest[idx] = current
            # Recursively populate the dict
            try:
                update_last_applied_manifest_dict_from_resp(
                    current, observer_schema, resp_item
                )
            except Exception as exc:
                # If the nested update fails, raise with context
                raise RuntimeError(
                    f"Failed to update dict at index {idx} in list: {exc}"
                ) from exc
        # Handle nested lists
        elif isinstance(resp_item, list):
            # If current is not a list, replace it
            if not isinstance(current, list):
                current = []
                last_applied_manifest[idx] = current
            # Determine a suitable sub‑schema for the nested list items
            sub_schema = None
            if isinstance(observer_schema, list) and len(observer_schema) == 1:
                # Assume the list schema is a single‑item list describing the element
                sub_schema = observer_schema[0]
            # Recurse into the nested list
            try:
                update_last_applied_manifest_list_from_resp(
                    current, sub_schema, resp_item
                )
            except Exception as exc:
                raise RuntimeError(
                    f"Failed to update nested list at index {idx} in list: {exc}"
                ) from exc
        # Handle primitive types
        else:
            last_applied_manifest[idx] = resp_item
    # Any remaining items in last_applied_manifest beyond the response length are left untouched
    return

def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:``update_last_applied_manifest_dict_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (list): partial ``last_applied_manifest`` being
            updated
        observer_schema (list): partial ``observer_schema``
        response (list): partial response from the Kubernetes API.

    This function goes through all observed fields, and initializes their value
    in ``last_applied_manifest`` if they are not yet present.

    Returns:
        list: Updated ``last_applied_manifest``.
    """
    # Basic validation of input types
    if last_applied_manifest is None:
        last_applied_manifest = []
    if not isinstance(last_applied_manifest, list):
        raise TypeError("last_applied_manifest must be a list")

    if not isinstance(observer_schema, list):
        raise TypeError("observer_schema must be a list")

    if response is None:
        return last_applied_manifest
    if not isinstance(response, list):
        raise TypeError("response must be a list")

    # Ensure last_applied_manifest is at least as long as response
    # we only update indices that exist in the response
    for i, resp_item in enumerate(response):
        # Skip if response item is None (no value to update)
        if resp_item is None:
            continue

        # Ensure the result list is long enough
        while len(last_applied_manifest) <= i:
            last_applied_manifest.append(None)

        # Determine the schema slice for this index
        schema_item = observer_schema[i] if i < len(observer_schema) else None

        # If the schema item is a dict, we expect a nested dict
        if isinstance(schema_item, dict):
            sub_last = last_applied_manifest[i]
            if sub_last is None or not isinstance(sub_last, dict):
                sub_last = {}
                last_applied_manifest[i] = sub_last
            # Call the dict counterpart if available
            try:
                # The dict counterpart should exist in the same module
                sub_last = update_last_applied_manifest_dict_from_resp(
                    sub_last, schema_item, resp_item
                )
            except Exception:
                # Fall back to direct assignment if something goes wrong
                sub_last = resp_item
            last_applied_manifest[i] = sub_last

        # If the schema item is a list, we expect a nested list
        elif isinstance(schema_item, list):
            sub_last = last_applied_manifest[i]
            if sub_last is None or not isinstance(sub_last, list):
                sub_last = []
                last_applied_manifest[i] = sub_last
            sub_last = update_last_applied_manifest_list_from_resp(
                sub_last, schema_item, resp_item
            )
            last_applied_manifest[i] = sub_last

        # If the schema item is any other type, treat this as a leaf value
        else:
            # Only set the value if it has not been set yet
            if last_applied_manifest[i] is None:
                last_applied_manifest[i] = resp_item

    return last_applied_manifest

def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    """
    Recursively update the ``last_applied_manifest`` list with values
    from a Kubernetes API response. The function iterates over each
    element of the response list and ensures that every observed field
    defined in ``observer_schema`` is present in the corresponding
    element of ``last_applied_manifest``, creating nested structures as
    necessary.

    Parameters
    ----------
    last_applied_manifest : list
        The list that will be updated in place. Each element is a
        dictionary representing an item in the list.
    observer_schema : list
        A list of schema descriptors that define the fields to observe.
        Each descriptor must at least contain the key ``split`` (the
        field name) and may contain ``type`` (``core``, ``dict``,
        or ``list``) and ``children`` (for nested schemas).
    response : list
        A list of dictionaries representing the server response.
        Each dictionary may contain the same keys as defined in
        ``observer_schema``.

    Returns
    -------
    None
    """
    # Basic type checking
    if not isinstance(observer_schema, list):
        raise TypeError("observer_schema must be a list")
    if not isinstance(response, list):
        raise TypeError("response must be a list")
    if not isinstance(last_applied_manifest, list):
        raise TypeError("last_applied_manifest must be a list")

    # Iterate over each item in the response
    for idx, resp_item in enumerate(response):
        if not isinstance(resp_item, dict):
            # Skip items that are not dicts (they cannot have named fields)
            continue

        # Ensure the corresponding element exists in the manifest
        if idx < len(last_applied_manifest):
            elem = last_applied_manifest[idx]
            if not isinstance(elem, dict):
                # Replace non-dict element with an empty dict
                elem = {}
                last_applied_manifest[idx] = elem
        else:
            # Create a new dict for missing elements
            elem = {}
            last_applied_manifest.append(elem)

        # Process each observed field for this element
        for field in observer_schema:
            # Field name is expected to be in the 'split' key
            try:
                field_name = field["split"]
            except Exception:
                # Skip malformed schema descriptors
                continue

            field_type = field.get("type", "core")
            children_schema = field.get("children", [])

            # Skip if the field is already present
            if field_name in elem:
                continue

            # Fetch corresponding value from the response item
            try:
                field_value = resp_item.get(field_name)
            except Exception:
                field_value = None

            if field_type == "core":
                # Directly assign the value (may be None)
                elem[field_name] = field_value

            elif field_type in ("dict", "map"):
                # Create an empty dict and recurse if value is a dict
                elem[field_name] = {}
                if isinstance(field_value, dict):
                    try:
                        update_last_applied_manifest_dict_from_resp(
                            elem[field_name], children_schema, field_value
                        )
                    except Exception:
                        # In case the helper function fails, leave the empty dict
                        pass

            elif field_type == "list":
                # Create an empty list and recurse if value is a list
                elem[field_name] = []
                if isinstance(field_value, list):
                    try:
                        update_last_applied_manifest_list_from_resp(
                            elem[field_name], children_schema, field_value
                        )
                    except Exception:
                        # If recursion fails, leave the empty list
                        pass
            else:
                # Fallback for unknown types
                elem[field_name] = field_value

    # Done processing; function mutates last_applied_manifest in-place.

def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:`update_last_applied_manifest_dict_from_resp`, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response.

    Args:
        last_applied_manifest (list): partial ``last_applied_manifest`` being
            updated
        observer_schema (list): partial ``observer_schema``
        response (list): partial response from the Kubernetes API.

    This function goes through all observed fields, and initializes their value
    in ``last_applied_manifest`` if they are not yet present.
    """
    # Defensive type checks
    if not isinstance(last_applied_manifest, list):
        last_applied_manifest = []
    if not isinstance(response, list):
        # If the response is not a list, nothing to do
        return last_applied_manifest

    # Helper to get schema for an index safely
    def _schema_at(idx):
        if isinstance(observer_schema, list) and 0 <= idx < len(observer_schema):
            return observer_schema[idx]
        return None

    for idx, resp_item in enumerate(response):
        # Skip if response item is None – nothing to apply
        if resp_item is None:
            continue

        # Ensure last_applied_manifest has an entry for this index
        if idx >= len(last_applied_manifest):
            # Initialise based on schema if available
            sch = _schema_at(idx)
            if isinstance(sch, dict):
                elem_type = sch.get("type")
                if elem_type == "dict":
                    last_applied_manifest.append({})
                elif elem_type == "list":
                    last_applied_manifest.append([])
                else:
                    # fall back to dict-like container
                    last_applied_manifest.append({})
            else:
                # Default to a generic container
                last_applied_manifest.append({})

        # Fetch the current element
        elem = last_applied_manifest[idx]
        sch = _schema_at(idx)

        # If we have a detailed schema entry
        if isinstance(sch, dict):
            elem_type = sch.get("type")

            if elem_type == "dict":
                # Ensure element is a dict
                if not isinstance(elem, dict):
                    elem = {}
                    last_applied_manifest[idx] = elem
                # Recursively update the dict
                update_last_applied_manifest_dict_from_resp(
                    elem,
                    sch.get("schema", sch),
                    resp_item,
                )

            elif elem_type == "list":
                # Ensure element is a list
                if not isinstance(elem, list):
                    elem = []
                    last_applied_manifest[idx] = elem
                # Items schema may be a nested list or dict description
                item_schema = sch.get("items", sch)
                update_last_applied_manifest_list_from_resp(
                    elem, item_schema, resp_item
                )

            else:
                # Scalar value – overwrite only if different or missing
                if elem != resp_item:
                    last_applied_manifest[idx] = resp_item

        else:
            # No explicit schema – perform a simple set
            if elem != resp_item:
                last_applied_manifest[idx] = resp_item

    return last_applied_manifest

def update_last_applied_manifest_dict_from_resp(
    last_applied_manifest, observer_schema, response
):
    """
    Together with :func:``update_last_applied_manifest_list_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (dict): partial ``last_applied_manifest`` being
            updated
        observer_schema (dict): partial ``observer_schema``
        response (dict): partial response from the Kubernetes API.

    Raises:
        KeyError: If the observed field is not present in the Kubernetes response
        TypeError: If the provided arguments are not dictionaries

    This function goes through all observed fields in ``observer_schema``, and
    initializes their value in ``last_applied_manifest`` if they are not yet
    present.  It handles nested dictionaries by recursing and delegates list
    handling to :func:`update_last_applied_manifest_list_from_resp`.
    """
    if not isinstance(last_applied_manifest, dict):
        raise TypeError(
            f"last_applied_manifest must be a dict, got {type(last_applied_manifest).__name__}"
        )
    if not isinstance(observer_schema, dict):
        raise TypeError(
            f"observer_schema must be a dict, got {type(observer_schema).__name__}"
        )
    if not isinstance(response, dict):
        raise TypeError(
            f"response must be a dict, got {type(response).__name__}"
        )

    for key, schema_value in observer_schema.items():
        # Ensure the key exists in the response
        if key not in response:
            raise KeyError(
                f"Observed field '{key}' missing from Kubernetes response"
            )
        resp_val = response[key]

        # Handle nested dictionaries
        if isinstance(schema_value, dict) and isinstance(resp_val, dict):
            # Ensure a dict exists in the target
            target_dict = last_applied_manifest.get(key)
            if target_dict is None:
                target_dict = {}
                last_applied_manifest[key] = target_dict
            elif not isinstance(target_dict, dict):
                # If the existing value is not a dict, replace it
                target_dict = {}
                last_applied_manifest[key] = target_dict
            # Recurse into the nested dict
            update_last_applied_manifest_dict_from_resp(
                target_dict, schema_value, resp_val
            )
        else:
            # Primitive scalar or list handling
            if isinstance(resp_val, list):
                # Delegate list handling
                if key not in last_applied_manifest or not isinstance(
                    last_applied_manifest[key], list
                ):
                    last_applied_manifest[key] = []
                # The list handling function is assumed to be available in the same module
                # It may raise its own exceptions as needed
                update_last_applied_manifest_list_from_resp(
                    last_applied_manifest[key], schema_value, resp_val
                )
            else:
                # Only set if not already present
                if key not in last_applied_manifest:
                    last_applied_manifest[key] = resp_val
    # The function mutates `last_applied_manifest` in place and returns None
    return None

def update_last_applied_manifest_dict_from_resp(
    last_applied_manifest, observer_schema, response
):
    """
    Recursively updates a partial ``last_applied_manifest`` dict with fields
    observed in the Kubernetes API response.

    Parameters
    ----------
    last_applied_manifest : dict
        The dictionary to be updated in place.
    observer_schema : dict
        A mapping describing which fields should be observed.  Keys correspond
        to field names.  If a value itself is a dict with a ``properties`` key,
        it represents nested fields.
    response : dict
        The partial response from the Kubernetes API.

    Raises
    ------
    KeyError
        If an observed field is missing from ``response``.
    """
    # Helper to decide if a schema describes a nested dict.
    def _is_nested(schema):
        try:
            # Treat ``properties`` or ``map`` as an indication of nested objects.
            return isinstance(schema, dict) and bool(
                schema.get("properties") or schema.get("map") or schema.get("items")
            )
        except Exception:
            return False

    for field, schema in observer_schema.items():
        # Skip non-dict schema entries – they are considered leaf fields.
        if field not in response:
            raise KeyError(f"Observed field '{field}' not present in response")

        value = response[field]

        # Handle nested dictionaries
        if isinstance(value, dict) and _is_nested(schema):
            # Ensure the key exists in the target dict
            if field not in last_applied_manifest or not isinstance(
                last_applied_manifest[field], dict
            ):
                last_applied_manifest[field] = {}

            # Retrieve nested schema: prefer ``properties``, fallback to the whole
            # schema object if it doesn't contain a specific key.
            nested_schema = schema.get("properties") or schema.get("map") or {}
            # Recurse with the nested structures
            update_last_applied_manifest_dict_from_resp(
                last_applied_manifest[field], nested_schema, value
            )
        else:
            # For leaf values, set them only if they haven't been set yet.
            if field not in last_applied_manifest:
                last_applied_manifest[field] = value

    return last_applied_manifest

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    if app is None:
        raise ValueError("app cannot be None")

    # Extract the manifest and existing observer schemas safely
    try:
        manifest = getattr(app.spec, "manifest", [])
        if manifest is None:
            manifest = []
        # ``observer_schema`` is expected to be a dict that maps resource names
        # to their observer schema definitions.
        observer_schemas = getattr(app.spec, "observer_schema", {})
        if observer_schemas is None:
            observer_schemas = {}
    except AttributeError as exc:
        raise ValueError("app.spec does not expose expected attributes") from exc

    # Ensure we work with a mutable dict
    if not isinstance(observer_schemas, dict):
        raise TypeError("app.spec.observer_schema must be a dict")

    # Iterate over each resource in the manifest
    for idx, resource in enumerate(manifest):
        # Guard against non-dict entries in the manifest
        if not isinstance(resource, dict):
            continue

        metadata = resource.get("metadata", {})
        if not isinstance(metadata, dict):
            continue

        name = metadata.get("name")
        kind = resource.get("kind")

        # Skip resources without a name or kind
        if not name or not kind:
            continue

        # If a custom observer schema is already present, skip generation
        if name in observer_schemas:
            continue

        # Create a simple default observer schema.  This example uses the
        # resource kind and name; adjust as needed for your specific domain.
        default_schema = {
            "kind": kind,
            "apiVersion": resource.get("apiVersion", ""),
            "metadata": {"name": name},
        }

        # Store the default schema
        try:
            observer_schemas[name] = default_schema
        except TypeError:
            # If observer_schemas was an immutable mapping, recreate it
            observer_schemas = dict(observer_schemas, **{name: default_schema})

    # Assign the updated schemas back to the application spec
    try:
        app.spec.observer_schema = observer_schemas
    except Exception as exc:
        raise RuntimeError("Failed to set observer_schema on app.spec") from exc

    return app

def generate_default_observer_schema(app):
    """
    Generate the default observer schema for each Kubernetes resource present in
    ``app.spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema

    Returns:
        dict: A mapping from resource kind to its default observer schema.
              Resource kinds that already have a custom observer schema are omitted.
    """
    try:
        # Guard against missing attributes
        if not app or not hasattr(app, "spec"):
            return {}

        manifest = getattr(app.spec, "manifest", None)
        if manifest is None:
            return {}

        # Determine the iterable list of resources
        if isinstance(manifest, list):
            resources = manifest
        elif isinstance(manifest, dict):
            # If manifest is a dict, it might contain a 'resources' key
            resources = manifest.get("resources", []) or manifest.get("objects", [])
            if not isinstance(resources, list):
                return {}
        else:
            # Unrecognized manifest format
            return {}

        # Existing custom observer schemas
        existing = {}
        if hasattr(app.spec, "observer_schema"):
            existing = getattr(app.spec, "observer_schema")
        elif hasattr(app.spec, "default_observer_schema"):
            existing = getattr(app.spec, "default_observer_schema")
        if not isinstance(existing, dict):
            existing = {}

        defaults = {}
        for res in resources:
            # Res might be a dict with 'kind', or an object with .kind attribute
            if isinstance(res, dict):
                kind = res.get("kind")
            else:
                kind = getattr(res, "kind", None)

            if not kind:
                # Skip resources that do not expose a kind
                continue

            if kind not in existing and kind not in defaults:
                # Simple default schema: include all top‑level fields of the
                # resource spec and status.  If the resource is known to the
                # Kubernetes Python client, we could introspect the model,
                # but for simplicity we create a minimal schema.
                defaults[kind] = {
                    "object": {
                        "schema": {
                            "type": "object",
                            "properties": {
                                "metadata": {"type": "object"},
                                "spec": {"type": "object"},
                                "status": {"type": "object"},
                            },
                        }
                    }
                }

        return defaults
    except Exception:
        # In case of any unexpected runtime issue, return an empty dict
        return {}

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    if app is None:
        return

    # Safe extraction of spec and its attributes
    try:
        spec = getattr(app, "spec", None)
        manifest = getattr(spec, "manifest", None)
        observers = getattr(spec, "observers", None)
    except Exception:
        # In case app structure is not as expected
        return

    # If any of the required structures are missing, skip processing
    if manifest is None or observers is None:
        return

    # Ensure observers is a mutable mapping
    if not isinstance(observers, dict):
        try:
            observers = dict(observers)
        except Exception:
            observers = {}

    # Iterate over resources in the manifest
    for resource_name, resource_obj in manifest.items():
        # Skip non‑dict resources
        if not isinstance(resource_obj, dict):
            continue

        kind = resource_obj.get("kind")
        if not kind:
            continue

        # Create a default schema only if it doesn't exist
        if kind not in observers:
            # Default observer schema: target identifiers and a placeholder status
            metadata = resource_obj.get("metadata", {})
            target_name = metadata.get("name", resource_name)
            observers[kind] = {
                "_kind": kind,
                "_target": {"name": target_name},
                "status": True,
            }

    # Attach the updated observers back to the app spec
    try:
        setattr(spec, "observers", observers)
    except Exception:
        # If we cannot set the attribute, silently ignore
        pass

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    try:
        if app is None:
            raise ValueError("The 'app' argument must not be None")

        # Ensure the Application has a spec and a manifest list
        spec = getattr(app, "spec", None)
        if spec is None:
            raise AttributeError("The application has no 'spec' attribute")
        manifest = getattr(spec, "manifest", None)
        if manifest is None or not isinstance(manifest, list):
            raise AttributeError("The application spec must contain a 'manifest' list")

        # Ensure the spec has a schema.observer dictionary
        schema = getattr(spec, "schema", None)
        if schema is None:
            schema = type("obj", (), {})()
            setattr(spec, "schema", schema)

        observer_dict = getattr(schema, "observer", None)
        if observer_dict is None or not isinstance(observer_dict, dict):
            observer_dict = {}
            setattr(schema, "observer", observer_dict)

        added_schemas = {}

        for resource in manifest:
            if not isinstance(resource, dict):
                # Skip any non-dict items in the manifest
                continue
            kind = resource.get("kind")
            if not kind:
                # If the resource has no kind, skip
                continue
            # If a custom schema already exists for this kind, skip generating a default
            if kind in observer_dict:
                continue
            # Default schema: allow any additional properties
            default_schema = {
                "type": "object",
                "properties": {},
                "additionalProperties": True,
            }
            observer_dict[kind] = default_schema
            added_schemas[kind] = default_schema

        return added_schemas

    except Exception as exc:
        # Wrap unexpected errors into a RuntimeError with context
        raise RuntimeError(f"Failed to generate default observer schema: {exc}") from exc

def format(
		self,
		sql: AnyStr,
		params: Union[Dict[Union[str, int], Any], Sequence[Any]],
	) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
		"""
		Convert a SQL query that uses in‑style parameters into a form that
		can be executed with out‑style parameters.
		For a mapping of ``{name: value}`` the named parameters
		(``:name``) in *sql* are replaced by the question mark placeholder
		(`?`) and the values are returned in a list in the order in which
		the placeholders appear.  For an ordinal sequence the function
		makes sure that the number of ``?`` placeholders matches the
		length of the sequence and simply returns the original SQL
		unchanged together with a copy of the sequence.
		"""
		if isinstance(params, dict):
			# Named parameters – replace :name with ?
			if isinstance(sql, bytes):
				try:
					s = sql.decode("utf-8")
				except Exception:
					s = sql.decode("utf-8", errors="ignore")
			else:
				s = sql
			values: List[Any] = []
			new_parts: List[str] = []
			idx = 0
			length = len(s)
			while idx < length:
				ch = s[idx]
				if ch == ":":
					# attempt to parse a name
					j = idx + 1
					while j < length and (s[j].isalnum() or s[j] == "_"):
						j += 1
					if j > idx + 1:  # found a name
						name = s[idx + 1 : j]
						if name not in params:
							raise ValueError(f"Missing parameter: {name}")
						values.append(params[name])
						new_parts.append("?")
						idx = j
						continue
				new_parts.append(ch)
				idx += 1
			new_sql = "".join(new_parts)
			if isinstance(sql, bytes):
				new_sql = new_sql.encode("utf-8")
			return new_sql, values

		# Ordinal parameters – only support question‑mark style
		if isinstance(params, Sequence) and not isinstance(
			params, (str, bytes)
		):
			if isinstance(sql, bytes):
				try:
					s = sql.decode("utf-8")
				except Exception:
					s = sql.decode("utf-8", errors="ignore")
			else:
				s = sql
			placeholder_count = s.count("?")
			if placeholder_count != len(params):
				raise ValueError(
					"Number of parameters does not match number of placeholders"
				)
			# Ensure returning a list for consistency
			return sql, list(params)

		raise TypeError(
			"params must be a mapping or a sequence, not " + str(type(params))
		)

def formatmany(
        self,
        sql: AnyStr,
        many_params: Union[Iterable[Dict[Union[str, int], Any]], Iterable[Sequence[Any]]],
    ) -> Tuple[AnyStr, Union[List[Dict[Union[str, int], Any]], List[Sequence[Any]]]]:
        """
        Convert the SQL query to use the out-style parameters instead of the
        in-style parameters.

        *sql* (:class:`str` or :class:`bytes`) is the SQL query.

        *many_params* (:class:`~collections.abc.Iterable`) contains each set
        of in-style parameters (*params*).

        -   *params* (:class:`~collections.abc.Mapping` or :class:`~collections.abc.Sequence`)
            contains the set of in-style parameters. It maps each parameter
            (:class:`str` or :class:`int`) to value. If :attr:`.SQLParams.in_style`
            is a named parameter style. then *params* must be a :class:`~collections.abc.Mapping`.
            If :attr:`.SQLParams.in_style` is an ordinal parameter style. then
            *params* must be a :class:`~collections.abc.Sequence`.

        Returns a :class:`tuple` containing:

        -   The formatted SQL query (:class:`str` or :class:`bytes`).

        -   A :class:`list` containing each set of converted out-style
            parameters (:class:`dict` or :class:`list`).
        """
        # retrieve the certain styles; assume they are set on the instance
        in_style = getattr(self, "in_style", None)
        out_style = getattr(self, "out_style", "?" if self is not None else "?")

        if in_style is None:
            raise ValueError("Missing in_style attribute on object")

        # Determine whether sql is bytes or str
        is_bytes = isinstance(sql, bytes)
        if is_bytes:
            # Work with str representation for easier manipulation
            sql_str = sql.decode(errors="ignore")
        else:
            sql_str = sql

        # Helper to extract placeholders for named style
        def _extract_named(sql_text):
            placeholders = []
            i = 0
            while i < len(sql_text):
                if sql_text[i] == ":":
                    j = i + 1
                    while j < len(sql_text) and (sql_text[j].isalnum() or sql_text[j] == "_"):
                        j += 1
                    if j > i + 1:
                        placeholders.append(sql_text[i + 1 : j])
                        i = j
                    else:
                        i += 1
                else:
                    i += 1
            return placeholders

        # Helper to extract placeholders for numeric style
        def _extract_numeric(sql_text):
            placeholders = []
            i = 0
            while i < len(sql_text):
                if sql_text[i] == ":":
                    j = i + 1
                    while j < len(sql_text) and sql_text[j].isdigit():
                        j += 1
                    if j > i + 1:
                        placeholders.append(sql_text[i + 1 : j])
                        i = j
                    else:
                        i += 1
                else:
                    i += 1
            return placeholders

        # Build formatted SQL
        if in_style == "named":
            placeholders = _extract_named(sql_str)
            formatted_sql = sql_str
            for name in placeholders:
                formatted_sql = formatted_sql.replace(f":{name}", out_style)
        elif in_style == "numeric":
            placeholders = _extract_numeric(sql_str)
            formatted_sql = sql_str
            for _ in placeholders:
                formatted_sql = formatted_sql.replace(":" + str(_), out_style, 1)
        elif in_style == "qmark":
            # No conversion needed for qmark style
            formatted_sql = sql_str
            placeholders = []  # not used
        else:
            raise NotImplementedError(f"Unsupported in_style '{in_style}'")

        # Convert many_params to a list of mutable sequences
        out_params_list: List[Sequence[Any]] = []

        for params in many_params:
            if in_style == "named":
                if not isinstance(params, dict):
                    raise TypeError("For named style, each params must be a dict")
                # Preserve order of placeholders as found in the SQL
                try:
                    ordered = [params[name] for name in placeholders]
                except KeyError as exc:
                    raise KeyError(f"Missing key {exc.args[0]} in params") from None
                out_params_list.append(ordered)
            elif in_style == "numeric":
                if not isinstance(params, (list, tuple)):
                    raise TypeError("For numeric style, each params must be a sequence")
                if len(params) < len(placeholders):
                    raise ValueError("Not enough parameters for numeric placeholders")
                out_params_list.append(params[: len(placeholders)])
            elif in_style == "qmark":
                # Accept any sequence/iterable
                seq = list(params)
                out_params_list.append(seq)
            else:
                # Should not reach here due to earlier check
                raise NotImplementedError

        # Convert back to original type if needed
        if is_bytes:
            formatted_sql_bytes = formatted_sql.encode()
        else:
            formatted_sql_bytes = formatted_sql

        # Return as a tuple
        return formatted_sql_bytes, out_params_list

def validate(self, path):
    """
    Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    try:
        # Resolve path-like objects
        os = __import__('os')
        p = os.fspath(path)
        # Ensure the path exists and is a directory
        if not os.path.isdir(p):
            return False
        # A minimal check: a valid OCFL root should contain an 'objects' directory
        try:
            entries = os.listdir(p)
        except Exception:
            return False
        if 'objects' in entries:
            return True
        # Fallback: look for a manifest file typical of an OCFL repo
        for entry in entries:
            if entry.lower().startswith('manifest') and entry.lower().endswith('.json'):
                return True
        # If none of the checks pass, consider it invalid
        return False
    except Exception:
        return False

def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    import os, json
    try:
        # Resolve pyfs or pathlib to a string path
        if hasattr(path, "get_path"):
            root = path.get_path()
        else:
            root = str(path)

        if not os.path.isdir(root):
            return False

        ocfl_dir = os.path.join(root, ".ocfl")
        if not os.path.isdir(ocfl_dir):
            return False

        # Metadata.json must exist and contain required fields
        metadata_file = os.path.join(ocfl_dir, "metadata.json")
        if not os.path.isfile(metadata_file):
            return False
        try:
            with open(metadata_file, "r", encoding="utf-8") as f:
                metadata = json.load(f)
        except Exception:
            return False

        if not isinstance(metadata, dict):
            return False
        layout = metadata.get("layout")
        if layout not in ("flat", "nested"):
            return False

        # Backup directory must exist
        backup_dir = os.path.join(ocfl_dir, "backup")
        if not os.path.isdir(backup_dir):
            return False

        # Versions directory must exist
        versions_dir = os.path.join(ocfl_dir, "versions")
        if not os.path.isdir(versions_dir):
            return False

        # At least one valid version with a content subdirectory
        has_valid_version = False
        for entry in os.listdir(versions_dir):
            ver_path = os.path.join(versions_dir, entry)
            if os.path.isdir(ver_path):
                # Each version should contain a content directory
                if os.path.isdir(os.path.join(ver_path, "content")):
                    has_valid_version = True
                    break
        if not has_valid_version:
            return False

        # Current directory or symlink must exist
        current_path = os.path.join(root, "current")
        if not os.path.exists(current_path):
            return False

        return True
    except Exception:
        # Any unexpected error is treated as invalid
        return False

def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    import pathlib
    # Basic sanity checks on the input
    if path is None:
        return False
    try:
        p = pathlib.Path(path)
    except Exception:
        return False
    try:
        if not p.exists():
            return False
        # Accept both plain filesystem paths and pyfs root objects that expose a pathlib.Path
        if hasattr(p, "is_dir") and not p.is_dir():
            return False
    except Exception:
        return False

    # Attempt to perform validation using a validator available on the instance or via import
    try:
        validator = getattr(self, "validator", None)
        if validator is None:
            # Try to import a common OCFL validator
            try:
                from ocfl.validators import Validator  # type: ignore
            except Exception:
                try:
                    from ocflpy import Validator  # type: ignore
                except Exception:
                    return False
            validator = Validator()
    except Exception:
        return False

    try:
        # The validator is expected to return a tuple: (errors, warnings)
        errors, _warnings = validator.validate(p)
        # If errors is falsy or an empty iterable/list, validation passed
        return not errors
    except Exception:
        # Any exception during validation is treated as a validation failure
        return False

def validate(self, path):
    """
    Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    try:
        if not isinstance(path, str):
            return False
        # path must be a directory
        if not os.path.isdir(path):
            return False

        # OCFL objects contain an ocfl_version file at the root
        ocfl_version_path = os.path.join(path, "ocfl_version")
        if not os.path.isfile(ocfl_version_path):
            return False

        # An objects directory must exist
        objects_dir = os.path.join(path, "objects")
        if not os.path.isdir(objects_dir):
            return False

        # At least one object version should be present
        try:
            entries = os.listdir(objects_dir)
        except Exception:
            entries = []
        if not entries:
            return False

        # Basic structural check passed
        return True
    except Exception:
        # Any exception during validation results in an invalid object
        return False

def status_str(self, prefix=''):
    """Return string of validator status, with optional prefix."""
    # Validate the prefix argument
    if not isinstance(prefix, str):
        raise TypeError("prefix must be a string")

    # Attempt to retrieve the validator status from known attributes.
    # Use a cascading approach with sensible fallbacks.
    status = None
    for attr in ('status', 'state', 'status_text', 'message', 'error'):
        if hasattr(self, attr):
            status = getattr(self, attr, None)
            if status is not None:
                break

    # If no explicit status was found, use the string representation
    # of the object as a last resort.
    if status is None:
        status = str(self)

    # Ensure status is a string; if it is a collection, join its elements.
    if isinstance(status, (list, tuple, set)):
        status = ', '.join(map(str, status))
    else:
        status = str(status)

    return f"{prefix}{status}"

def status_str(self, prefix=''):
    """Return string of validator status, with optional prefix."""
    try:
        prefix = str(prefix or '')
        parts = []

        # Use explicit status attribute if present
        if hasattr(self, 'status'):
            status = getattr(self, 'status')
            parts.append(f"Status={status!s}")

        # Use is_valid boolean flag if present
        if hasattr(self, 'is_valid'):
            is_valid = getattr(self, 'is_valid')
            parts.append(f"IsValid={is_valid}")

        # Count errors if available
        if hasattr(self, 'errors'):
            errors = getattr(self, 'errors')
            if isinstance(errors, (list, tuple, set)):
                parts.append(f"Errors={len(errors)}")
            else:
                parts.append(f"Errors={errors!s}")

        # Count warnings if available
        if hasattr(self, 'warnings'):
            warnings = getattr(self, 'warnings')
            if isinstance(warnings, (list, tuple, set)):
                parts.append(f"Warnings={len(warnings)}")
            else:
                parts.append(f"Warnings={warnings!s}")

        # Fallback: if no recognized attributes, use object’s string
        if not parts:
            parts.append(f"Object={self!s}")

        return f"{prefix}{', '.join(parts)}"
    except Exception as exc:
        # In case of unexpected errors, return a readable message
        return f"{prefix}Error retrieving status: {exc}"

def status_str(self, prefix=''):
    """Return string of validator status, with optional prefix."""
    try:
        # Normalize prefix to a string
        if prefix is None:
            prefix = ''
        else:
            prefix = str(prefix)
        # Determine base status based on common attributes
        if hasattr(self, 'is_valid'):
            try:
                is_valid = bool(self.is_valid)
            except Exception:
                is_valid = False
            status = "OK" if is_valid else "Invalid"
        else:
            status = "Unknown status"
        # Append error information if present and validator is invalid
        if hasattr(self, 'error') and not getattr(self, 'is_valid', True):
            try:
                error_msg = str(self.error)
                status += f": {error_msg}"
            except Exception:
                pass
        # Append warning information if present
        if hasattr(self, 'warning'):
            try:
                warning_msg = str(self.warning)
                status += f" (Warning: {warning_msg})"
            except Exception:
                pass
        return prefix + status
    except Exception as exc:
        # On unexpected error, return a safe status string
        return f"{prefix}Status error: {exc}"

def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    if not isinstance(prefix, str):
        raise TypeError('prefix must be a string')
    # Attempt to obtain the log from common attribute names; default to empty list.
    log = getattr(self, 'validation_log', getattr(self, 'validation', []))
    if not isinstance(log, (list, tuple)):
        log = [log]
    # Convert each entry to string and apply prefix.
    lines = []
    for entry in log:
        if isinstance(entry, (list, tuple)):
            # If the entry itself is a sequence, join its string representations.
            entry_str = ' '.join(str(e) for e in entry)
        else:
            entry_str = str(entry)
        lines.append(f"{prefix}{entry_str}")
    return '\n'.join(lines)

def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    # Normalise prefix
    if prefix is None:
        prefix = ''
    # Try to get a log from common attribute names
    log = None
    for attr in ('validation_log', '_validation_log', 'log'):
        if hasattr(self, attr):
            log = getattr(self, attr)
            break
    if log is None:
        return ''  # No log present
    # If the log is already a string, just prefix it
    if isinstance(log, str):
        return f'{prefix}{log}'
    # Handle collections
    if isinstance(log, (list, tuple)):
        return '\n'.join(f'{prefix}{str(item)}' for item in log)
    if isinstance(log, dict):
        return '\n'.join(f'{prefix}{k}: {v}' for k, v in log.items())
    # Fallback: convert to string
    return f'{prefix}{str(log)}'

def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    # Attempt to find a log attribute on the instance
    log = getattr(self, 'validation_log', None)
    if log is None and hasattr(self, 'log'):
        log = getattr(self, 'log')
    # If no log found, return empty string
    if log is None:
        return ''
    # Convert the log to a list of lines
    if isinstance(log, str):
        lines = log.splitlines()
    else:
        try:
            lines = [str(item) for item in log]
        except Exception:  # log might not be iterable
            lines = [str(log)]
    # Prepend the prefix to each line, if provided
    if prefix:
        lines = [f'{prefix}{line}' for line in lines]
    # Join the lines with newline characters
    return '\n'.join(lines)

def validate(self, inventory, extract_spec_version=False):
    """
    Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    # Inventory must be a dictionary
    if not isinstance(inventory, dict):
        raise TypeError("Inventory must be a dictionary")

    # Determine the spec version to use
    spec_version = None
    # Mapping of possible type values to spec versions; adjust as needed for real specs
    TYPE_TO_SPEC = {
        "v1": 1,
        "v2": 2,
        "full": 2,
        "lite": 1,
    }

    if extract_spec_version:
        type_value = inventory.get("type")
        if type_value is not None:
            spec_version = TYPE_TO_SPEC.get(type_value)
        # If type is missing or invalid, fall back to self.spec_version
        if spec_version is None:
            spec_version = getattr(self, "spec_version", None)
    else:
        spec_version = getattr(self, "spec_version", None)

    if spec_version is None:
        raise ValueError("Could not determine specification version for the inventory")

    # Basic structural checks that depend on spec version
    # Example: spec_version 1 expects a "nodes" list, 2 expects a "hosts" dict
    if spec_version == 1:
        if "nodes" not in inventory or not isinstance(inventory["nodes"], list):
            raise ValueError("Inventory for spec version 1 must contain a 'nodes' key with a list value")
    elif spec_version == 2:
        if "hosts" not in inventory or not isinstance(inventory["hosts"], dict):
            raise ValueError("Inventory for spec version 2 must contain a 'hosts' key with a dictionary value")
    else:
        # For any other spec_version, just ensure a top-level 'data' key exists
        if "data" not in inventory:
            raise ValueError("Inventory missing required 'data' key")

    # Store the determined spec_version for downstream use (optional)
    inventory["_spec_version"] = spec_version
    return inventory

def check_digests_present_and_used(self, manifest_files, digests_used):
        """Check all digests in manifest that are needed are present and used."""
        if not isinstance(manifest_files, (list, tuple)):
            raise TypeError(f"manifest_files must be a list or tuple, got {type(manifest_files).__name__}")
        # Ensure digests_used is a set
        try:
            digests_used_set = set(digests_used)
        except Exception as e:
            raise TypeError(f"digests_used must be an iterable of digest strings: {e}")

        required_digests = set()
        for path in manifest_files:
            if not isinstance(path, str):
                raise TypeError(f"Each entry in manifest_files must be a string path, got {type(path).__name__}")
            try:
                with open(path, "r") as f:
                    for line in f:
                        digest = line.strip()
                        if digest:
                            required_digests.add(digest)
            except FileNotFoundError:
                raise FileNotFoundError(f"Manifest file not found: {path}")
            except Exception as e:
                raise IOError(f"Error reading manifest file '{path}': {e}")

        missing_in_use = required_digests - digests_used_set
        unused_in_manifest = digests_used_set - required_digests

        if missing_in_use or unused_in_manifest:
            messages = []
            if missing_in_use:
                messages.append(f"Missing digests in usage: {sorted(missing_in_use)}")
            if unused_in_manifest:
                messages.append(f"Digests used but not present in manifest: {sorted(unused_in_manifest)}")
            raise ValueError("; ".join(messages))

def check_digests_present_and_used(self, manifest_files, digests_used):
        """Check all digests in manifest that are needed are present and used."""
        # Validate input types
        if not hasattr(manifest_files, "__iter__"):
            raise TypeError("manifest_files must be an iterable of file paths.")
        if not hasattr(digests_used, "__iter__"):
            raise TypeError("digests_used must be an iterable of digest strings.")
        # Convert digests_used to a set for efficient membership tests
        try:
            used_set = set(digests_used)
        except Exception as exc:
            raise TypeError("digests_used must be convertible to a set.") from exc

        needed_digests = set()
        for path in manifest_files:
            try:
                with open(path, "r", encoding="utf-8") as fp:
                    for line in fp:
                        line = line.strip()
                        if not line:
                            continue
                        # Try colon format: algorithm: digest
                        if ":" in line:
                            _, digest = line.split(":", 1)
                            digest = digest.strip()
                            if digest:
                                needed_digests.add(digest)
                            continue
                        # Try whitespace format: algorithm digest
                        parts = line.split()
                        if len(parts) == 2:
                            digest = parts[1].strip()
                            if digest:
                                needed_digests.add(digest)
                        # If line cannot be parsed, ignore silently
            except OSError as exc:
                raise RuntimeError(f"Unable to read manifest file '{path}': {exc}") from exc

        if not needed_digests:
            # No digests needed; nothing to check
            return True

        missing = needed_digests - used_set
        if missing:
            missing_list = ", ".join(sorted(missing))
            raise ValueError(
                f"The following digests from the manifest are not present or not used: {missing_list}"
            )
        # All needed digests are present and used
        return True

def check_digests_present_and_used(self, manifest_files, digests_used):
        """Check all digests in manifest that are needed are present and used."""
        # Validate inputs
        if not isinstance(manifest_files, dict):
            raise TypeError("manifest_files must be a dict of file names to digest containers.")
        if digests_used is None:
            digests_used = set()
        elif isinstance(digests_used, (list, tuple, set)):
            digests_used = set(digests_used)
        else:
            raise TypeError("digests_used must be an iterable of digest strings.")
        # Collect all digest values present in the manifest
        present_digests = set()
        for file_name, data in manifest_files.items():
            # Support dict containing 'digests' key or any iterable of digests
            digests = None
            if isinstance(data, dict):
                digests = data.get('digests')
            if digests is None:
                # If data itself is an iterable of digests
                if isinstance(data, (list, tuple, set)):
                    digests = data
            if digests is None:
                # Unsupported format; skip but warn
                continue
            for d in digests:
                if not isinstance(d, str):
                    continue
                present_digests.add(d)
        # Determine missing and unused digests
        missing = digests_used - present_digests
        unused = present_digests - digests_used
        # Raise descriptive errors if mismatches found
        errors = []
        if missing:
            errors.append(f"Missing digests required by the system: {', '.join(sorted(missing))}.")
        if unused:
            errors.append(f"Digests present in the manifest but not marked as used: {', '.join(sorted(unused))}.")
        if errors:
            raise ValueError(" ".join(errors))
        return True

def validate_as_prior_version(self, prior):
        """
        Check that prior is a valid prior version of the current inventory object.

        The input variable prior is also expected to be an InventoryValidator object
        and both self and prior inventories are assumed to have been checked for
        internal consistency.
        """
        # Ensure prior is not None
        if prior is None:
            raise ValueError("Provided prior object is None, which is not a valid prior version.")

        # Ensure prior is an instance of the same type as self
        if not isinstance(prior, type(self)):
            raise TypeError(f"Provided prior object must be of type {type(self).__name__}, "
                            f"got {type(prior).__name__} instead.")

        # Ensure prior is not the same instance as self
        if prior is self:
            raise ValueError("Provided prior object is the same as the current inventory; "
                             "a prior version must be distinct.")

        # Helper to safely get attributes
        def _get_attr(obj, attr, default=None):
            return getattr(obj, attr, default)

        # Check unique identifier consistency (if present)
        self_id = _get_attr(self, 'id', None)
        prior_id = _get_attr(prior, 'id', None)
        if (self_id is not None or prior_id is not None) and self_id != prior_id:
            raise ValueError(f"Identifier mismatch: current inventory id={self_id} differs from prior id={prior_id}.")

        self_uuid = _get_attr(self, 'uuid', None)
        prior_uuid = _get_attr(prior, 'uuid', None)
        if (self_uuid is not None or prior_uuid is not None) and self_uuid != prior_uuid:
            raise ValueError(f"UUID mismatch: current uuid={self_uuid} differs from prior uuid={prior_uuid}.")

        # Check version ordering (if present)
        self_version = _get_attr(self, 'version', None)
        prior_version = _get_attr(prior, 'version', None)
        if self_version is not None and prior_version is not None:
            try:
                if not prior_version < self_version:
                    raise ValueError(f"Invalid version ordering: prior version={prior_version} is not less than current version={self_version}.")
            except TypeError:
                # If versions are not comparable, skip this check
                pass

        # Check timestamp ordering (if present)
        self_ts = _get_attr(self, 'timestamp', None)
        prior_ts = _get_attr(prior, 'timestamp', None)
        if self_ts is not None and prior_ts is not None:
            try:
                # Assume timestamps support comparison operators
                if not prior_ts < self_ts:
                    raise ValueError(f"Timestamp of prior ({prior_ts}) is not earlier than current ({self_ts}).")
            except TypeError:
                # If timestamps are not comparable, skip this check
                pass

        # All checks passed
        return True

def validate_as_prior_version(self, prior):
    """
    Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Basic sanity checks
    if prior is None:
        raise ValueError("The 'prior' argument must not be None.")
    if not isinstance(prior, type(self)):
        raise TypeError(
            f"'prior' must be an instance of {type(self).__name__}, "
            f"got {type(prior).__name__} instead."
        )
    if prior is self:
        raise ValueError("The 'prior' object cannot be the same instance as 'self'.")

    # Attempt to retrieve unique identifiers for comparison
    self_id = getattr(self, "inventory_id", None) or getattr(self, "id", None)
    prior_id = getattr(prior, "inventory_id", None) or getattr(prior, "id", None)
    if self_id is None or prior_id is None:
        raise AttributeError(
            "Could not determine inventory identifiers for comparison."
        )
    if self_id != prior_id:
        raise ValueError(
            f"Inventory identifiers differ: self={self_id!r}, prior={prior_id!r}."
        )

    # Attempt to retrieve revision/version numbers
    self_rev = getattr(self, "revision", None) or getattr(self, "version", None)
    prior_rev = getattr(prior, "revision", None) or getattr(prior, "version", None)
    if self_rev is None or prior_rev is None:
        raise AttributeError(
            "Could not determine revision/version for comparison."
        )
    try:
        if prior_rev >= self_rev:
            raise ValueError(
                f"Prior revision/version ({prior_rev!r}) is not older than "
                f"current revision/version ({self_rev!r})."
            )
    except TypeError:
        raise TypeError(
            f"Revision/version values are of incomparable types: "
            f"prior_rev={prior_rev!r}, self_rev={self_rev!r}."
        )

    return True

def validate_as_prior_version(self, prior):
        """Check that prior is a valid prior version of the current inventory object.

        The input variable prior is also expected to be an InventoryValidator object
        and both self and prior inventories are assumed to have been checked for
        internal consistency.
        """
        # Basic type checking
        if not isinstance(prior, type(self)):
            raise ValueError(
                f"prior must be an instance of {type(self).__name__}, got {type(prior).__name__}"
            )

        # Attempt to access the underlying inventory attribute(s)
        try:
            self_inv = self.inventory
            prior_inv = prior.inventory
        except AttributeError as exc:
            raise ValueError(
                f"Either self or prior objects do not provide an 'inventory' attribute: {exc}"
            ) from exc

        # 1. Ensure the inventory identifiers (if any) match
        id_self = getattr(self_inv, "id", None)
        id_prior = getattr(prior_inv, "id", None)
        if id_self is not None and id_prior is not None and id_self != id_prior:
            raise ValueError(
                f"Inventory identifiers differ: self.id={id_self} vs prior.id={id_prior}"
            )

        # 2. Validate version / timestamp
        # Prefer numeric 'version', fall back to datetime-like 'release_date'
        try:
            version_self = getattr(self_inv, "version", None)
            version_prior = getattr(prior_inv, "version", None)
            if version_self is not None and version_prior is not None:
                if not isinstance(version_self, (int, float)) or not isinstance(version_prior, (int, float)):
                    raise ValueError("Both versions must be numeric")
                if version_self <= version_prior:
                    raise ValueError(
                        f"Current version ({version_self}) must be greater than prior version ({version_prior})"
                    )
                # No further check needed if version passes
                return True
        except Exception:  # pragma: no cover
            pass

        # Try release_date comparison if available
        try:
            date_self = getattr(self_inv, "release_date", None)
            date_prior = getattr(prior_inv, "release_date", None)
            if date_self is not None and date_prior is not None:
                if date_self <= date_prior:
                    raise ValueError(
                        f"Current release_date ({date_self}) must be later than prior release_date ({date_prior})"
                    )
                return True
        except Exception:  # pragma: no cover
            pass

        # 3. Ensure all items present in prior exist in current (for dict-like inventories)
        if isinstance(self_inv, dict) and isinstance(prior_inv, dict):
            missing_keys = set(prior_inv.keys()) - set(self_inv.keys())
            if missing_keys:
                raise ValueError(
                    f"Current inventory is missing keys from prior: {', '.join(sorted(missing_keys))}"
                )
            # Optionally check that values are compatible (e.g., quantities non-decreasing)
            # This is domain specific; skip here.

        # 4. As a last resort, require equality of the two inventory representations
        if self_inv != prior_inv:
            raise ValueError("Current and prior inventories differ in content or structure.")

        # If we reach this point, all checks passed
        return True

def validate_as_prior_version(self, prior):
        """Check that prior is a valid prior version of the current inventory object.

        The input variable prior is also expected to be an InventoryValidator object
        and both self and prior inventories are assumed to have been checked for
        internal consistency.
        """
        # Ensure prior is an instance of the same validator class
        if not isinstance(prior, type(self)):
            raise ValueError(
                "prior must be an instance of the same validator class as self"
            )

        # Helper to safely get an attribute from an object, searching multiple names
        def _get_attr(obj, name_options):
            for name in name_options:
                if hasattr(obj, name):
                    return getattr(obj, name)
            raise AttributeError(f"Object {obj!r} missing expected attribute(s) {name_options}")

        # Ensure that both inventories refer to the same logical inventory id
        try:
            self_id = _get_attr(self, ["inventory_id", "id"])
            prior_id = _get_attr(prior, ["inventory_id", "id"])
        except AttributeError as exc:
            raise ValueError(f"Inconsistent inventory identifiers: {exc}") from exc
        if self_id != prior_id:
            raise ValueError(
                f"Inventory ids do not match (self={self_id}, prior={prior_id})"
            )

        # Get the version (or revision) numbers for comparison
        try:
            self_version = _get_attr(self, ["inventory_version", "version", "ver"])
            prior_version = _get_attr(
                prior, ["inventory_version", "version", "ver"]
            )
        except AttributeError as exc:
            raise ValueError(f"Inconsistent version attributes: {exc}") from exc

        # If any of the version attributes are None or not comparable, raise an error
        if self_version is None or prior_version is None:
            raise ValueError("One or both inventory versions are undefined")

        # Perform a numeric or lexical comparison
        try:
            # If both are numbers, compare numerically
            if isinstance(self_version, (int, float)) and isinstance(
                prior_version, (int, float)
            ):
                if prior_version >= self_version:
                    raise ValueError(
                        f"Prior version ({prior_version}) must be less than current version ({self_version})"
                    )
            else:
                # Otherwise, attempt a string comparison
                if str(prior_version) >= str(self_version):
                    raise ValueError(
                        f"Prior version ('{prior_version}') must be less than current version ('{self_version}')"
                    )
        except Exception as exc:
            # Any comparison error overrides with a clear message
            raise ValueError(f"Error comparing versions: {exc}") from exc

        # All checks passed
        return True

def validate_as_prior_version(self, prior):
    """
    Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Helper to extract comparable resource representations
    def _resources_to_set(res):
        if isinstance(res, (list, tuple, set)):
            return set(res)
        if isinstance(res, dict):
            return set(res.keys())
        # Fallback: try to extract 'name' attribute if present
        try:
            return set([r.name for r in res])
        except Exception:
            return {res}

    # Basic validation on the prior object
    if prior is None:
        raise ValueError("The prior inventory must not be None.")
    if type(prior) is not type(self):
        raise TypeError("The prior inventory must be of the same type as the current inventory.")
    # Ensure required attributes exist in both objects
    required_attrs = ['name', 'version']
    for attr in required_attrs:
        if not hasattr(self, attr):
            raise AttributeError(f"Current inventory object is missing required attribute '{attr}'.")
        if not hasattr(prior, attr):
            raise AttributeError(f"Prior inventory object is missing required attribute '{attr}'.")
    # Compare names – they must match for a valid prior
    if self.name != prior.name:
        raise ValueError(f"Inventory names differ: current='{self.name}', prior='{prior.name}'.")
    # Ensure versions are numeric and properly ordered
    try:
        current_version = self.version
        prior_version = prior.version
    except Exception as exc:
        raise ValueError(f"Unable to retrieve 'version' from inventory objects: {exc}")
    if prior_version is None or current_version is None:
        raise ValueError("Both inventories must have a defined 'version' attribute.")
    if not isinstance(current_version, (int, float)) or not isinstance(prior_version, (int, float)):
        raise TypeError("Inventory 'version' must be numeric (int or float).")
    if prior_version >= current_version:
        raise ValueError(f"Prior inventory version ({prior_version}) must be less than current version ({current_version}).")
    # Validate that all resources in the prior are present in the current inventory
    if hasattr(self, "resources") and hasattr(prior, "resources"):
        try:
            current_res_set = _resources_to_set(self.resources)
            prior_res_set = _resources_to_set(prior.resources)
        except Exception as exc:
            raise ValueError(f"Error processing resource lists: {exc}")
        missing_in_current = prior_res_set - current_res_set
        if missing_in_current:
            raise ValueError(f"The following resources from the prior inventory are missing in the current inventory: {missing_in_current}")
    return True

def get_logical_path_map(inventory, version):
    """
    Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a dictionary")

    # Result mapping
    mapping = {}

    # Fetch version-specific data; if not present, return empty dict
    version_data = inventory.get(version)
    if version_data is None:
        return mapping

    def _walk(node, current_key):
        """
        Recursively traverse the node to build mapping from logical path to set of content files.
        """
        # If node is a dictionary, dive into its key-value pairs
        if isinstance(node, dict):
            for key, value in node.items():
                # Build the full logical path by joining with '/'
                full_key = f"{current_key}/{key}".lstrip("/")
                _walk(value, full_key)
        # If node is a list, set, or tuple, treat it as the set of content files
        elif isinstance(node, (list, set, tuple)):
            mapping[current_key] = set(node)
        else:
            # Primitive value (e.g., a string path); wrap into a set
            mapping[current_key] = {node}

    _walk(version_data, "")

    return mapping

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    try:
        # If inventory is a mapping from version to a list of items
        if isinstance(inventory, dict) and all(
                isinstance(v, (list, tuple)) for v in inventory.values()
        ):
            # Target entries for the requested version
            target_entries = inventory.get(version, [])
            # Determine keys for logical path and content file
            def get_keys(item):
                # try common key names
                for key in ("logical_path_in_state", "logical_path", "path"):
                    if key in item:
                        lp_key = key
                        break
                else:
                    lp_key = "logical_path_in_state"
                for key in ("content_file", "file", "path"):
                    if key in item:
                        cf_key = key
                        break
                else:
                    cf_key = "content_file"
                return lp_key, cf_key

            # Compute mapping for the target version
            logical_map = {}
            for item in target_entries:
                if not isinstance(item, dict):
                    continue
                lp_key, cf_key = get_keys(item)
                lp = item.get(lp_key)
                cf = item.get(cf_key)
                if lp is None or cf is None:
                    continue
                logical_map.setdefault(lp, set()).add(cf)

            # Include duplicate files from later versions
            for later_ver, entries in inventory.items():
                if later_ver <= version:
                    continue
                for item in entries:
                    if not isinstance(item, dict):
                        continue
                    lp_key, cf_key = get_keys(item)
                    lp = item.get(lp_key)
                    cf = item.get(cf_key)
                    if lp in logical_map and cf:
                        logical_map[lp].add(cf)

            return logical_map

        # Otherwise assume inventory is a list or iterable of items
        # Some items may have an explicit 'version' field
        if hasattr(inventory, '__iter__'):
            # Determine overall mapping for requested version
            logical_map = {}
            for itm in inventory:
                if not isinstance(itm, dict):
                    continue
                # Determine if item pertains to the requested version
                ver = itm.get('version')
                if ver is None:
                    # Try nested state
                    state = itm.get('state')
                    if isinstance(state, dict):
                        ver = state.get('version')
                if ver != version:
                    continue

                # Determine logical path and content file keys
                lp_key = next(
                    (k for k in ("logical_path_in_state", "logical_path", "path") if k in itm),
                    "logical_path_in_state")
                cf_key = next(
                    (k for k in ("content_file", "file", "path") if k in itm),
                    "content_file")

                lp = itm.get(lp_key)
                cf = itm.get(cf_key)
                if lp is None or cf is None:
                    continue
                logical_map.setdefault(lp, set()).add(cf)

            # Include duplicates from later versions
            for itm in inventory:
                if not isinstance(itm, dict):
                    continue
                # Find the version of this item
                ver = itm.get('version')
                if ver is None and isinstance(itm.get('state'), dict):
                    ver = itm.get('state').get('version')
                if ver is None or ver <= version:
                    continue
                lp_key = next(
                    (k for k in ("logical_path_in_state", "logical_path", "path") if k in itm),
                    "logical_path_in_state")
                cf_key = next(
                    (k for k in ("content_file", "file", "path") if k in itm),
                    "content_file")
                lp = itm.get(lp_key)
                cf = itm.get(cf_key)
                if lp in logical_map and cf:
                    logical_map[lp].add(cf)

            return logical_map

        # If inventory is neither dict nor iterable, return empty mapping
        return {}
    except Exception as exc:
        # Log the exception in a real application; here we simply raise
        raise ValueError(f"Invalid inventory structure for version {version}: {exc}") from exc

def get_logical_path_map(inventory, version):
    """
    Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Validate input types
    if not isinstance(inventory, dict):
        raise TypeError(f"inventory must be a dict, got {type(inventory)!r}")
    # Handle missing version gracefully
    try:
        state = inventory[version]
    except KeyError:
        # If the requested version is not present, return empty mapping
        return {}
    # If the state itself is not a dict, cannot proceed
    if not isinstance(state, dict):
        raise TypeError(f"state for version {version} must be a dict, got {type(state)!r}")
    result = {}
    for logical_path, entry in state.items():
        # Determine content files based on entry format
        content_files = None
        if isinstance(entry, dict):
            # Prefer explicit 'content_files' key if available
            if 'content_files' in entry:
                content_files = entry['content_files']
            # If no explicit key, but contains a single path string
            elif len(entry) == 1:
                # Pick the single value
                content_files = next(iter(entry.values()))
        # If entry is list, tuple, set or other iterable
        if content_files is None:
            content_files = entry
        # Normalize to iterable of file paths
        if isinstance(content_files, str):
            # Treat single string as single file path
            files_iterable = (content_files,)
        else:
            try:
                # Ensure we can iterate
                files_iterable = iter(content_files)
            except TypeError:
                # Not iterable, skip this logical path
                continue
        # Build set of content files, filtering out non-string entries
        file_set = set()
        for f in files_iterable:
            if isinstance(f, str):
                file_set.add(f)
        # Only add to result if we found some files
        if file_set:
            result[logical_path] = file_set
    return result

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Basic input validation
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a dictionary")
    # Accept both str and numeric types for version; coerce to str for dict lookup
    ver_key = str(version)
    if ver_key not in inventory:
        # If the key is not found, raise a informative error
        raise KeyError(f"Version '{version}' not found in inventory")
    curr_map = inventory[ver_key]
    if not isinstance(curr_map, dict):
        raise ValueError("inventory[version] must map logical paths to content files (a dict)")
    # Initialize result with logical paths present in the requested version
    result = {lp: set() for lp in curr_map}
    # Populate the sets with content files found across all versions that reference the logical paths
    for _, mapping in inventory.items():
        # Skip non-dict entries; they cannot provide mapping information
        if not isinstance(mapping, dict):
            continue
        for lp, cf in mapping.items():
            if lp in result:
                result[lp].add(cf)
    return result

def get_logical_path_map(inventory, version):
    """
    Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may include references to duplicate files in
    later versions than the version being described.

    Parameters
    ----------
    inventory : dict or list
        The inventory of files. It may be a dictionary containing a 'versions'
        key mapping version identifiers to a list of file entries, or it may be
        a list of file entries where each entry contains a 'version' key.
    version : int, str, or any hashable type
        The version identifier to filter the inventory.

    Returns
    -------
    dict
        Mapping from logical path to a set of content file paths.
    """
    # Initialize the result mapping
    result = {}

    # Helper to add mapping
    def add_mapping(logical_path, content_file):
        if logical_path not in result:
            result[logical_path] = set()
        result[logical_path].add(content_file)

    try:
        # Case 1: inventory is a dict with 'versions' key
        if isinstance(inventory, dict) and 'versions' in inventory:
            # Get the specific version data
            version_data = inventory['versions'].get(version)
            if not version_data:
                # No data for this version
                return result

            # Expecting version_data to have a 'files' key or be a list directly
            files = []
            if isinstance(version_data, dict):
                if 'files' in version_data:
                    files = version_data['files']
                else:
                    # Not a standard structure, treat the dict itself as a file entry list
                    files = version_data
            elif isinstance(version_data, list):
                files = version_data
            else:
                # Unexpected format
                return result

            # Iterate through file entries
            for entry in files:
                if not isinstance(entry, dict):
                    continue
                logical_path = entry.get('logical_path')
                content_file = entry.get('content_file')
                if logical_path is None or content_file is None:
                    continue
                add_mapping(logical_path, content_file)

        # Case 2: inventory is a list of file entries with a 'version' key
        elif isinstance(inventory, list):
            for entry in inventory:
                if not isinstance(entry, dict):
                    continue
                if entry.get('version') != version:
                    continue
                logical_path = entry.get('logical_path')
                content_file = entry.get('content_file')
                if logical_path is None or content_file is None:
                    continue
                add_mapping(logical_path, content_file)

        # Case 3: inventory is a flat dict of logical_path -> content_file entries
        # Assume entries that have a 'versions' dict inside each
        elif isinstance(inventory, dict):
            for logical_path, entry_data in inventory.items():
                if isinstance(entry_data, dict):
                    # Check if entry_data itself contains version mapping
                    if 'versions' in entry_data:
                        ver_data = entry_data['versions'].get(version)
                        if ver_data and isinstance(ver_data, dict):
                            content_file = ver_data.get('content_file')
                            if content_file:
                                add_mapping(logical_path, content_file)

        # Otherwise, no recognizable format; return empty mapping
    except Exception:
        # In case of any unexpected error, return whatever has been collected so far
        pass

    return result

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Ensure the fixity block is a dictionary or a list of dictionaries, contains
    the required 'checksum' and 'checksum_method' keys for each entry, and
    that any referenced file names are present in the supplied ``manifest_files``.

    Parameters
    ----------
    fixity : dict or list
        The provided fixity block from the inventory.
    manifest_files : Iterable[str]
        A collection of file names that are expected to be referenced by the
        fixity block.

    Raises
    ------
    ValueError
        If the fixity structure is invalid or if a referenced file is not in
        ``manifest_files``.
    """
    import collections

    # Ensure we have an iterable of entries
    if isinstance(fixity, collections.abc.Mapping):
        entries = [fixity]
    elif isinstance(fixity, collections.abc.Sequence) and not isinstance(fixity, (str, bytes)):
        entries = list(fixity)
    else:
        raise ValueError("Fixity block must be a dict or a list of dicts")

    # Normalize manifest_files to a set for fast lookup
    if not isinstance(manifest_files, collections.abc.Hashable):
        manifest_set = set(manifest_files)
    else:
        # If a single string or hashable is given, treat as a single entry
        manifest_set = set([manifest_files])

    # Keys that might contain file references
    FILE_KEYS = {"file", "filepath", "path", "filename", "file_name"}

    for entry_index, entry in enumerate(entries):
        if not isinstance(entry, collections.abc.Mapping):
            raise ValueError(f"Fixity entry {entry_index} is not a dictionary")

        # Validate required fields
        if "checksum" not in entry:
            raise ValueError(f"Fixity entry {entry_index} missing required 'checksum'")
        if "checksum_method" not in entry:
            raise ValueError(f"Fixity entry {entry_index} missing required 'checksum_method'")

        # Detect referenced file(s)
        referenced_files = []

        # Look for explicit file key
        for key in FILE_KEYS:
            if key in entry:
                referenced_files.append(entry[key])

        # If no explicit key, treat top‑level keys that map to dicts as file references
        if not referenced_files:
            for key, val in entry.items():
                if isinstance(val, collections.abc.Mapping):
                    referenced_files.append(key)

        # Ensure all referenced files are in the manifest
        for ref_file in referenced_files:
            if ref_file not in manifest_set:
                raise ValueError(
                    f"Fixity entry {entry_index} references unknown file '{ref_file}' "
                    f"not present in the manifest"
                )
    # If we get here, the fixity block is considered valid
    return None

def validate_fixity(self, fixity, manifest_files):
        """
        Validate fixity block in inventory.

        Check the structure of the fixity block and make sure that only files
        listed in the manifest are referenced.
        """
        try:
            if fixity is None:
                raise ValueError("Fixity block is missing")

            # Determine the type of manifest_files (dict or iterable)
            if isinstance(manifest_files, dict):
                manifest_keys = set(manifest_files.keys())
            else:
                try:
                    manifest_keys = set(map(str, manifest_files))
                except Exception:
                    raise ValueError("Manifest files must be a dict or iterable of file identifiers")

            # Helper to validate a single file entry
            def _validate_entry(file_name, entry):
                if file_name not in manifest_keys:
                    raise ValueError(f"Fixity references unknown file '{file_name}' not present in manifest")
                if not isinstance(entry, dict):
                    raise ValueError(f"Fixity entry for file '{file_name}' must be a mapping")
                if "hash" not in entry:
                    raise ValueError(f"Fixity entry for file '{file_name}' must contain a 'hash' key")
                # Optional: check algorithm key if present
                if "algorithm" in entry and not isinstance(entry["algorithm"], str):
                    raise ValueError(f"'algorithm' for file '{file_name}' must be a string")

            if isinstance(fixity, dict):
                # Expect mapping file_name -> entry
                for fn, ent in fixity.items():
                    _validate_entry(fn, ent)
            elif isinstance(fixity, list):
                # Expect list of dicts with 'file', 'hash', optional 'algorithm'
                for item in fixity:
                    if not isinstance(item, dict):
                        raise ValueError("Each item in fixity list must be a dict")
                    if "file" not in item:
                        raise ValueError("Each fixity dict must contain a 'file' key")
                    _validate_entry(item["file"], item)
            else:
                raise ValueError("Fixity block must be a dict or a list of dicts")

            return True

        except Exception as e:
            # Re-raise with context
            raise ValueError(f"Invalid fixity block: {e}") from e

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and make sure that only files
    listed in the manifest are referenced.
    """
    # Use a set for fast membership checks
    manifest_set = set(manifest_files)
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary.")
    for file_name, entry in fixity.items():
        if file_name not in manifest_set:
            raise ValueError(
                f"Fixity block references file not present in the manifest: {file_name!r}"
            )
        if not isinstance(entry, dict):
            raise ValueError(
                f"Fixity entry for {file_name!r} must be a dictionary, got {type(entry).__name__}"
            )
        # A minimal expected structure for each entry is a checksum value
        if "checksum" not in entry:
            raise ValueError(
                f"Missing 'checksum' key in fixity entry for {file_name!r}"
            )
        # The checksum value itself should be a non-empty string
        checksum = entry["checksum"]
        if not isinstance(checksum, str) or not checksum:
            raise ValueError(
                f"Checksum for {file_name!r} must be a non-empty string."
            )
    # If all checks pass, return True
    return True

def validate_fixity(self, fixity, manifest_files):
        """Validate fixity block in inventory.

        Check the structure of the fixity block and makes sure that only files
        listed in the manifest are referenced.
        """
        # Ensure manifest_files is iterable of file names
        if not isinstance(manifest_files, (list, set, frozenset)):
            raise TypeError("manifest_files must be a list or set of filenames")

        manifest_set = set(manifest_files)

        # Fixity must be a dict or a list
        if not isinstance(fixity, (dict, list)):
            raise TypeError("fixity must be a dict or a list of dicts")

        if isinstance(fixity, dict):
            # Each key should be a known file, value should be a dict containing
            # at least a 'value' entry (the checksum) and optionally a 'type'.
            for filename, details in fixity.items():
                if filename not in manifest_set:
                    raise ValueError(f"Fixity references unknown file '{filename}'")
                if not isinstance(details, dict):
                    raise ValueError(f"Details for file '{filename}' must be a dict")
                if "value" not in details:
                    raise ValueError(f"Missing 'value' for fixity of file '{filename}'")
                if "type" in details and not isinstance(details["type"], str):
                    raise ValueError(f"'type' for file '{filename}' must be a string")
        else:  # list
            # List of dicts, each should contain 'file' and 'value'
            for item in fixity:
                if not isinstance(item, dict):
                    raise ValueError("Each item in fixity list must be a dict")
                if "file" not in item or "value" not in item:
                    raise ValueError("Each fixity dict must contain 'file' and 'value'")
                filename = item["file"]
                if filename not in manifest_set:
                    raise ValueError(f"Fixity references unknown file '{filename}'")
                if "type" in item and not isinstance(item["type"], str):
                    raise ValueError(f"'type' in fixity for file '{filename}' must be a string")

        return True

def files_list(path):
    """
    Return the files in `path`
    """
    import os
    # Ensure the provided path is handled uniformly
    try:
        # Resolve to an absolute path for consistent behavior
        abs_path = os.path.abspath(path)
    except Exception as e:
        raise ValueError(f"Invalid path '{path}': {e}") from e

    # Check if the path exists
    if not os.path.exists(abs_path):
        raise FileNotFoundError(f"Path does not exist: {abs_path}")

    # Check if the path is a directory
    if not os.path.isdir(abs_path):
        raise NotADirectoryError(f"Path is not a directory: {abs_path}")

    try:
        entries = os.listdir(abs_path)
    except OSError as e:
        raise OSError(f"Could not list directory contents for {abs_path}: {e}") from e

    files = []
    for entry in entries:
        full_entry = os.path.join(abs_path, entry)
        try:
            if os.path.isfile(full_entry):
                files.append(entry)
        except OSError:
            # Skip entries we cannot stat
            continue

    return sorted(files)

def files_list(path):
    """
    Return the files in `path`.
    If `path` does not exist or is not a directory, an empty list is returned.
    Only regular files are included, not directories or other kinds of entries.
    """
    import os
    try:
        if not isinstance(path, str):
            raise TypeError("path must be a string")
        if not os.path.isdir(path):
            return []
        result = []
        for entry in os.listdir(path):
            full_path = os.path.join(path, entry)
            if os.path.isfile(full_path):
                result.append(entry)
        return result
    except Exception:
        # Any error (e.g., permission denied) results in an empty list
        return []

def _group_files_by_xml_filename(source, xmls, files):
    """
    Group files by their XML basename.

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    source : str
        Path to the source directory (unused but kept for signature consistency).
    xmls : list of str
        List of XML filenames (full paths or basenames).
    files : list of str
        List of files in the folder or zipfile (full paths or basenames).

    Returns
    -------
    dict
        key: name of the XML file (basename with extension)
        value: list of file paths belonging to that XML group
    """
    # Helper to split path and extension without importing os
    def _split_base_ext(name):
        # Extract basename
        name = name.split('/')[-1].split('\\')[-1]
        idx = name.rfind('.')
        if idx == -1:
            return name, ''
        return name[:idx], name[idx + 1 :]

    # Validate inputs
    if not isinstance(xmls, (list, tuple)):
        return {}
    if not isinstance(files, (list, tuple)):
        return {}
    try:
        base_to_xmlkey = {}
        result = {}
        # Build mapping from base to XML key (basename with extension)
        for xml in xmls:
            if not isinstance(xml, str):
                continue
            xml_name = _split_base_ext(xml)[0] + '.' + _split_base_ext(xml)[1] if _split_base_ext(xml)[1] else _split_base_ext(xml)[0]
            base, _ = _split_base_ext(xml_name)
            base_to_xmlkey[base] = xml_name
            result[xml_name] = []

        # Group files
        for file_path in files:
            if not isinstance(file_path, str):
                continue
            file_name = _split_base_ext(file_path)[0] + '.' + _split_base_ext(file_path)[1] if _split_base_ext(file_path)[1] else _split_base_ext(file_path)[0]
            file_base, _ = _split_base_ext(file_name)
            if file_base in base_to_xmlkey:
                xml_key = base_to_xmlkey[file_base]
                result[xml_key].append(file_path)

        return result
    except Exception:
        # On any unexpected error, return empty dict
        return {}

def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
        Mapping of XML basenames to dictionaries of language codes and their file paths.
        Example:
            {
                "welcome": {"": "/path/to/welcome.xml", "en": "/path/to/welcome_en.xml"},
                "contact": {"fr": "/path/to/contact_fr.xml"}
            }
    """
    import os
    import re

    # Validate input type
    if not isinstance(folder, str):
        raise TypeError(f"folder must be a string, got {type(folder).__name__}")

    # If folder is relative, try to resolve it
    try:
        folder_path = os.path.abspath(folder)
    except Exception as exc:
        raise ValueError(f"Unable to resolve folder path: {exc}") from exc

    if not os.path.isdir(folder_path):
        # Return empty dict if the path does not exist or is not a directory
        return {}

    # Compile a simple regex for language codes (lowercase 2-3 letters)
    lang_re = re.compile(r"^[a-z]{2,3}$")

    groups = {}
    try:
        for entry in os.listdir(folder_path):
            full_path = os.path.join(folder_path, entry)
            if not os.path.isfile(full_path):
                continue
            # Only consider files ending in .xml (case-insensitive)
            if not entry.lower().endswith(".xml"):
                continue

            # Strip the extension
            name_no_ext = os.path.splitext(entry)[0]
            parts = name_no_ext.split("_")

            # If the last part looks like a language code, treat it as such
            if len(parts) > 1 and lang_re.match(parts[-1]):
                base = "_".join(parts[:-1])
                lang = parts[-1]
            else:
                base = name_no_ext
                lang = ""

            # Initialize nested dict if not present
            if base not in groups:
                groups[base] = {}
            # Avoid overriding existing entries; keep the first encountered
            if lang not in groups[base]:
                groups[base][lang] = full_path
    except OSError:
        # If any OS related error occurs, return what has been collected so far
        pass

    return groups

def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package

    Returns
    -------
    dict
        A dictionary where keys are the basenames of XML files and
        values are lists of full paths of all files that share that basename.
    """
    # Import inside the function to avoid top‑level imports
    import os

    if not isinstance(folder, str):
        raise TypeError(f"folder must be a string, got {type(folder).__name__}")
    if not os.path.exists(folder):
        raise FileNotFoundError(f"Folder '{folder}' does not exist")
    if not os.path.isdir(folder):
        raise NotADirectoryError(f"Path '{folder}' is not a directory")

    basemap = {}
    try:
        for filename in os.listdir(folder):
            filepath = os.path.join(folder, filename)
            if not os.path.isfile(filepath):
                continue
            basename, ext = os.path.splitext(filename)
            basemap.setdefault(basename, []).append(filename)
    except OSError as exc:
        raise RuntimeError(f"Error reading directory '{folder}': {exc}") from exc

    # Build result only for basenames that have an XML file
    result = {}
    for basename, files in basemap.items():
        if any(os.path.splitext(fn)[1].lower() == ".xml" for fn in files):
            result[basename] = [os.path.join(folder, fn) for fn in files]

    return result

def add_rendition(self, lang, file_path):
