def _explore_zipfile(zip_path):
    """
    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path

    Returns
    -------
    dict
        Dictionary where each key is the base path of an XML file (without extension)
        and each value is another dictionary containing the file paths inside the
        ZIP archive as keys and their corresponding contents (decoded strings for
        XML files, raw bytes otherwise) as values.

    Raises
    ------
    FileNotFoundError
        If the provided path does not exist.
    zipfile.BadZipFile
        If the file is not a valid ZIP archive.
    """
    import zipfile
    import os

    if not isinstance(zip_path, str):
        raise TypeError(f"zip_path must be a string, got {type(zip_path).__name__}")

    if not os.path.exists(zip_path):
        raise FileNotFoundError(f"Zip file not found: {zip_path}")

    try:
        with zipfile.ZipFile(zip_path, 'r') as z:
            base_to_files = {}
            for zinfo in z.infolist():
                # Skip directories
                if zinfo.is_dir():
                    continue
                file_path = zinfo.filename
                base_key = os.path.splitext(file_path)[0]
                try:
                    raw_data = z.read(zinfo)
                except RuntimeError as e:
                    # zipfile can raise RuntimeError for encrypted files or other issues
                    raise RuntimeError(f"Error reading file '{file_path}' in zip '{zip_path}': {e}") from e
                # Decode XML files to text, keep others as bytes
                if file_path.lower().endswith('.xml'):
                    try:
                        content = raw_data.decode('utf-8', errors='replace')
                    except Exception:
                        content = raw_data.decode('utf-8', errors='replace')
                else:
                    content = raw_data
                base_to_files.setdefault(base_key, {})[file_path] = content
    except zipfile.BadZipFile as e:
        raise zipfile.BadZipFile(f"Invalid zip file: {zip_path}") from e
    except FileNotFoundError as e:
        # Re-raise to provide a consistent error message
        raise FileNotFoundError(f"Zip file not found: {zip_path}") from e
    except Exception as e:
        # Catch any other unexpected errors to provide a clear message
        raise RuntimeError(f"Unexpected error while processing zip '{zip_path}': {e}") from e

    # Filter to include only groups that have an XML file
    result = {
        base: files
        for base, files in base_to_files.items()
        if any(fname.lower().endswith('.xml') for fname in files)
    }

    return result

