def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    visited = set()

    def _pretty(obj, level):
        oid = id(obj)
        if oid in visited:
            return "<Recursion>"
        # Basic types
        if obj is None:
            return "None"
        if isinstance(obj, (int, float, bool)):
            return str(obj)
        if isinstance(obj, str):
            return repr(obj)
        # Containers
        if isinstance(obj, (list, tuple, set)):
            visited.add(oid)
            if not obj:
                return [] if isinstance(obj, list) else () if isinstance(obj, tuple) else set()
            opening = "[" if isinstance(obj, list) else "(" if isinstance(obj, tuple) else "{"
            closing = "]" if isinstance(obj, list) else ")" if isinstance(obj, tuple) else "}"
            prefix = "  " * level
            inner = ""
            for i, item in enumerate(obj):
                item_str = _pretty(item, level + 1)
                inner += f"{prefix}{item_str}"
                if i < len(obj) - 1:
                    inner += ",\n"
            visited.remove(oid)
            if isinstance(obj, set):
                # Sets are displayed with braces and no trailing comma
                return f"{opening}\n{inner}\n{prefix}{closing}"
            else:
                return f"{opening}\n{inner}\n{prefix}{closing}"
        if isinstance(obj, dict):
            visited.add(oid)
            if not obj:
                return "{}"
            prefix = "  " * level
            inner = ""
            for i, (k, v) in enumerate(obj.items()):
                key_str = _pretty(k, level + 1)
                val_str = _pretty(v, level + 1)
                inner += f"{prefix}{key_str}: {val_str}"
                if i < len(obj) - 1:
                    inner += ",\n"
            visited.remove(oid)
            return f"{{\n{inner}\n{prefix}}}"
        # Objects with __dict__
        if hasattr(obj, "__dict__"):
            visited.add(oid)
            attrs = getattr(obj, "__dict__")
            if not attrs:
                return f"{type(obj).__name__}()"
            prefix = "  " * level
            inner = ""
            for i, (k, v) in enumerate(attrs.items()):
                val_str = _pretty(v, level + 1)
                inner += f"{prefix}{k}={val_str}"
                if i < len(attrs) - 1:
                    inner += ",\n"
            visited.remove(oid)
            return f"{type(obj).__name__}(\n{inner}\n{prefix})"
        # Fallback
        return repr(obj)

    result = _pretty(self, indent)
    if debug:
        return f"<{type(self).__name__} object at {hex(id(self))}>\n{result}"
    return result

def pretty(self, indent=0, debug=False):
    """
