            for slot in obj.__slots__:
                if hasattr(obj, slot):
                    attrs[slot] = getattr(obj, slot)

        if not attrs:
            return f'{prefix}{header} {{}}'

        lines = [f'{prefix}{header} {{']
        for key, val in attrs.items():
            lines.append(f'{prefix}{indent * 1}{key}: {_pretty(val, level + 1)},')
        lines.append(f'{prefix}}}')
        return '\n'.join(lines)

    # Ensure indent is an integer and non-negative
    try:
        indent_steps = int(indent)
        if indent_steps < 0:
            indent_steps = 0
    except Exception:
        indent_steps = 0

    return _pretty(self, 0)

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    visited = set()

    def _pretty(obj, level):
        # Detect recursion for container types
        obj_id = id(obj)
        if obj_id in visited:
            return "<recursion>"
        # Basic immutable types
        if isinstance(obj, (str, bytes, int, float, bool, type(None))):
            return repr(obj)
        # Add id to visited for containers
        if isinstance(obj, (list, tuple, set, dict)) or hasattr(obj, "__dict__"):
            visited.add(obj_id)

        # Lists and tuples
        if isinstance(obj, list):
            inner = ", ".join(_pretty(item, level + 1) for item in obj)
            return "[" + inner + "]"
        if isinstance(obj, tuple):
            inner = ", ".join(_pretty(item, level + 1) for item in obj)
            return "(" + inner + ("" if len(obj) == 1 else ",") + ")"
        if isinstance(obj, set):
            inner = ", ".join(_pretty(item, level + 1) for item in obj)
            return "{" + inner + "}"
        # Dictionaries
        if isinstance(obj, dict):
            inner = ", ".join(
                f"{_pretty(k, level + 1)}: {_pretty(v, level + 1)}"
                for k, v in obj.items()
            )
            return "{" + inner + "}"
        # Custom objects with __dict__
        if hasattr(obj, "__dict__"):
            header = ""
            if debug:
                header = f"{obj.__class__.__name__} (id={obj_id})"
            attrs = []
            for k, v in obj.__dict__.items():
                attrs.append(f"{k}={_pretty(v, level + 1)}")
            body = ", ".join(attrs)
            if header:
                return header + "\n" + (("  " * level) + body)
            return body
        # Fallback
        try:
            return repr(obj)
        except Exception:
            return str(obj)

    try:
        return _pretty(self, indent)
    except Exception:
        return "<error in pretty>"

def absorb(self, args):
        """
        Given an `args` sequence of expressions, return a new list of expression
        applying absorption and negative absorption.

        See https://en.wikipedia.org/wiki/Absorption_law

        Absorption::

            A & (A | B) = A, A | (A & B) = A

        Negative absorption::

            A & (~A | B) = A & B, A | (~A & B) = A | B
        """
        # Helper to get children safely
        def _children(expr):
            try:
                return expr.args
            except Exception:
                return None

        # Simplify a single expression if it matches absorption patterns
        def _simplify(expr):
            c = _children(expr)
            if not c or len(c) != 2:
                return expr
            left, right = c
            op_name = expr.__class__.__name__

            # A & (A | B) -> A
            if op_name == "And":
                # exact duplicate
                if left == right:
                    return left
                # Check for A & (A | B)
                right_c = _children(right)
                if right_c and len(right_c) == 2:
                    or_left, or_right = right_c
                    if or_left.__class__.__name__ == "Or":
                        if left == or_left or left == or_right:
                            return left
                # Negative absorption: A & (~A | B) -> A & B
                if right_c and len(right_c) == 2:
                    or_left, or_right = right_c
                    if or_left.__class__.__name__ == "Or":
                        # Find the B part (not the ~A)
                        B = None
                        if or_left.__class__.__name__ == "Not" and or_left.args[0] == left:
                            B = or_right
                        elif or_right.__class__.__name__ == "Not" and or_right.args[0] == left:
                            B = or_left
                        if B is not None:
                            return left & B

            # A | (A & B) -> A
            if op_name == "Or":
                if left == right:
                    return left
                # Check for A | (A & B)
                left_c = _children(left)
                if left_c and len(left_c) == 2:
                    and_left, and_right = left_c
                    if and_left.__class__.__name__ == "And":
                        if right == and_left or right == and_right:
                            return right
                # Negative absorption: A | (~A & B) -> A | B
                left_c = _children(left)
                if left_c and len(left_c) == 2:
                    and_left, and_right = left_c
                    if and_left.__class__.__name__ == "And":
                        # Find B part
                        B = None
                        if and_left.__class__.__name__ == "Not" and and_left.args[0] == right:
                            B = and_right
                        elif and_right.__class__.__name__ == "Not" and and_right.args[0] == right:
                            B = and_left
                        if B is not None:
                            return right | B

            return expr

        # Work iteratively until no more simplifications occur
        exprs = list(args)
        changed = True
        while changed:
            changed = False
            new_exprs = []
            for expr in exprs:
                simplified = _simplify(expr)
                if simplified is not expr:
                    changed = True
                new_exprs.append(simplified)
            exprs = new_exprs

        return exprs

def absorb(self, args):
        """
        Given an `args` sequence of expressions, return a new list of expression
        applying absorption and negative absorption.

        See https://en.wikipedia.org/wiki/Absorption_law

        Absorption::

            A & (A | B) = A, A | (A & B) = A

        Negative absorption::

            A & (~A | B) = A & B, A | (~A & B) = A | B
        """
        # Return an empty list if no arguments are supplied
        if not args:
            return []

        try:
            # Import sympy lazily to avoid unnecessary dependency for non-boolean inputs
            import sympy
        except Exception as exc:
            # If sympy is not available or fails to import, treat the input
            # as opaque objects and simply deduplicate while preserving order
            seen = set()
            result = []
            for expr in args:
                if expr not in seen:
                    seen.add(expr)
                    result.append(expr)
            return result

        # Ensure all arguments are converted to sympy expressions
        sym_args = []
        for expr in args:
            try:
                sym_expr = sympy.sympify(expr)
            except Exception:
                # If sympify fails, include the original expression
                sym_expr = expr
            sym_args.append(sym_expr)

        # Combine with logical AND and simplify
        try:
            combined = sympy.And(*sym_args)
            simplified = sympy.simplify(combined)
        except Exception:
            # If simplification fails, fall back to the original arguments list
            return args

        # Extract the arguments from the simplified expression
        try:
            # For a composite expression, .args returns the constituent subexpressions
            if isinstance(simplified, sympy.And):
                return list(simplified.args)
            if isinstance(simplified, sympy.Or):
                return list(simplified.args)
            return [simplified]
        except Exception:
            return [simplified]

def on(self, hook):
    """Decorator function to add a new handler to the registry.

    Args:
        hook (HookType): Hook attribute for which to register the handler.

    Returns:
        callable: Decorator for registering listeners for the specified hook.
    """
    if hook is None:
        raise ValueError("Hook cannot be None")
    # Ensure registry storage exists
    if not hasattr(self, "registry"):
        self.registry = {}
    def _decorator(func):
        if not callable(func):
            raise TypeError("Registered handler must be callable")
        # Register the function under the specified hook
        self.registry.setdefault(hook, []).append(func)
        return func
    return _decorator

def on(self, hook):
    """Decorator function to add a new handler to the registry.

    Args:
        hook (HookType): Hook attribute for which to register the handler.

    Returns:
        callable: Decorator for registering listeners for the specified
        hook.
    """
    if hook is None:
        raise ValueError("Hook cannot be None")

    def decorator(func):
        if not callable(func):
            raise TypeError(f"Handler must be callable, got {type(func).__name__}")
        try:
            # Ensure the registry exists
            if not hasattr(self, "_registry"):
                self._registry = {}
            # Register the function under the given hook
            handlers = self._registry.setdefault(hook, [])
            if func not in handlers:
                handlers.append(func)
        except Exception as exc:
            raise RuntimeError(f"Failed to register handler for hook {hook!r}") from exc
        return func

    return decorator

def base_config(user, etcd_host="localhost", etcd_port=2379):
    """Creates a configuration with some simple parameters, which have a default value
    that can be set.

    Args:
        user (str): the name of the user for the static authentication
