def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed,
    to unicode strings
    """
    import sys
    # If running under Python 2, wrap the function so that Unicode return values
    # are encoded to utf-8 bytes. On Python 3 no conversion is needed.
    if sys.version_info[0] < 3:
        def _wrapper(*args, **kwargs):
            result = namefunc(*args, **kwargs)
            # In Python 2, unicode is the unicode type. Convert it to bytes.
            if isinstance(result, unicode):
                try:
                    return result.encode('utf-8')
                except Exception as exc:
                    raise ValueError("Failed to encode tzname() return value: %r" % exc) from exc
            # Return any other type unchanged (e.g., bytes, None, int).
            return result
        return _wrapper
    else:
        # In Python 3, the tzname() function already returns unicode strings.
        return namefunc

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    import sys
    # In Python 2 the existing implementation already returns bytes,
    # so no wrapping is necessary.
    if sys.version_info[0] < 3:
        return namefunc

    # In Python 3 we need to wrap the function so that it returns
    # bytes instead of a Unicode string.
    def _wrapper(*args, **kwargs):
        # Preserve any exception raised by the original function.
        result = namefunc(*args, **kwargs)
        # None should remain None
        if result is None:
            return None
        # If the result is already a bytes object, return it unchanged.
        if isinstance(result, bytes):
            return result
        # If it's a Unicode string, encode it to UTF-8.
        if isinstance(result, str):
            try:
                return result.encode('utf-8')
            except Exception:
                # Fallback encoding if UTF-8 fails (unlikely for tz names).
                return result.encode('latin-1', 'replace')
        # For any other type, attempt to convert to a string and encode.
        try:
            return str(result).encode('utf-8')
        except Exception:
            # As a last resort return an empty byte string.
            return b''

    # Preserve the name and docstring of the original function.
    _wrapper.__name__   = namefunc.__name__
    _wrapper.__doc__    = namefunc.__doc__
    _wrapper.__module__ = namefunc.__module__
    return _wrapper

