def get_versions():
    """Get version information or return default if unable to do so."""
    import os
    import sys
    import subprocess

    versions = {}

    # Python version
    try:
        versions["python"] = sys.version.split()[0]
    except Exception:
        versions["python"] = "unknown"

    # Git commit hash
    try:
        # Find the directory that contains a .git folder (the repo root)
        start_dir = os.path.abspath(os.path.dirname(__file__)) if "__file__" in globals() else os.getcwd()
        repo_root = None
        current_dir = start_dir
        while True:
            if os.path.isdir(os.path.join(current_dir, ".git")):
                repo_root = current_dir
                break
            parent_dir = os.path.dirname(current_dir)
            if parent_dir == current_dir:
                break
            current_dir = parent_dir

        if repo_root:
            commit = subprocess.check_output(
                ["git", "-C", repo_root, "rev-parse", "HEAD"],
                stderr=subprocess.DEVNULL,
            ).strip().decode("utf-8")
            if commit:
                versions["git_rev"] = commit
    except Exception:
        pass

    # Application/package version
    try:
        # Try environment variable first
        app_version = os.getenv("APP_VERSION")
        if not app_version:
            # Try reading a VERSION file in the repo root
            root_dir = os.path.abspath(os.path.dirname(__file__)) if "__file__" in globals() else os.getcwd()
            version_file = os.path.join(root_dir, "VERSION")
            if os.path.isfile(version_file):
                with open(version_file, "r", encoding="utf-8") as f:
                    app_version = f.read().strip()
        if app_version:
            versions["app"] = app_version
    except Exception:
        pass

    # Set defaults if keys are missing
    if "app" not in versions:
        versions["app"] = "unknown"
    if "git_rev" not in versions:
        versions["git_rev"] = "unknown"

    return versions

def get_versions():
    """Get version information or return default if unable to do so."""
    import os
    import subprocess

    # Default return value
    versions = {'version': "0+unknown", 'full-revisionid': None}

    # Try to get package metadata
    try:
        # Determine package name from __package__ (containing the package this module belongs to)
        package_name = __package__
        # If __package__ is empty or None (e.g., executed as script), try to infer from file path
        if not package_name:
            # Attempt to get the nearest package by walking up directories
            pkg_dir = os.path.abspath(os.path.dirname(__file__))
            while pkg_dir and pkg_dir != os.path.dirname(pkg_dir):
                init_file = os.path.join(pkg_dir, "__init__.py")
                if os.path.isfile(init_file):
                    package_name = os.path.basename(pkg_dir)
                    break
                pkg_dir = os.path.dirname(pkg_dir)

        if package_name:
            # import importlib.metadata only if available
            try:
                # Python 3.8+
                from importlib.metadata import version as _pkg_version
            except ImportError:
                # fallback to importlib_metadata backport
                try:
                    from importlib_metadata import version as _pkg_version
                except ImportError:
                    _pkg_version = None

            if _pkg_version:
                try:
                    ver = _pkg_version(package_name)
                    if ver:
                        versions['version'] = ver
                except Exception:
                    pass
    except Exception:
        # Silently ignore any failures in metadata retrieval
        pass

    # Try to get the git commit hash if available
    try:
        # Only proceed if .git directory exists in project root
        repo_root = None
        # Find the repository root by looking for .git
        curr_dir = os.path.abspath(os.path.dirname(__file__))
        while curr_dir != os.path.dirname(curr_dir):
            if os.path.isdir(os.path.join(curr_dir, ".git")):
                repo_root = curr_dir
                break
            curr_dir = os.path.dirname(curr_dir)

        if repo_root:
            # Use git rev-parse to get the commit hash
            completed = subprocess.run(
                ["git", "rev-parse", "HEAD"],
                cwd=repo_root,
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                text=True,
                check=True,
            )
            commit_hash = completed.stdout.strip()
            if commit_hash:
                versions['full-revisionid'] = commit_hash
    except Exception:
        # If git is not available or any error occurs, leave full-revisionid as None
        pass

    return versions

def get_versions():
    """Get version information or return default if unable to do so."""
    # Attempt to obtain the version of the package that defines this module.
    # If that fails (e.g., the package is not installed), fall back to a
    # default placeholder.  The function is defensive: it catches
    # ImportError for older Python versions, as well as any exception
    # raised when the package metadata cannot be found.
    version_info = {'version': '0+unknown'}

    # First try the modern importlib.metadata module (Python 3.8+).
    try:
        from importlib.metadata import version as get_version, PackageNotFoundError
    except ImportError:
        # Fall back to the importlib_metadata back‑port for older Pythons.
        try:
            from importlib_metadata import version as get_version, PackageNotFoundError
        except ImportError:
            # No metadata package available – return the default.
            return version_info

    # Determine the package name.  For a regular installed package,
    # __package__ will be the dotted name.  When run as a script
    # (e.g. __name__ == "__main__") we cannot determine a package,
    # so we skip the lookup.
    pkg_name = None
    try:
        pkg_name = __package__ or __name__
    except Exception:
        # __package__ may be None, which is fine – we’ll handle that below.
        pass

    if pkg_name is None or pkg_name.startswith('__'):
        # If unable to identify the package, keep the default.
        return version_info

    # Try to fetch the distribution version.
    try:
        ver = get_version(pkg_name)
        return {'version': ver}
    except PackageNotFoundError:
        # The package is not installed – keep the default.
        return version_info
    except Exception:
        # Any other error (e.g., network issue, permission error) – keep the default.
        return version_info

def render(pieces, style):
    """Render the given version pieces into the requested style.

    Parameters
    ----------
    pieces : dict or sequence
        The version components. If a mapping, supported keys are
        ``major``, ``minor``, ``patch``, ``prerelease`` and ``build``.
        If a sequence, it is interpreted as
        (major, minor, patch, prerelease, build) in that order.
    style : str, optional
        The rendering style.

        * ``"semver"`` (default) – full semantic‑version string
          (``major.minor.patch[-prerelease][+build]``).
        * ``"numeric"`` – only ``major.minor.patch``.
        * ``"plain"`` – components joined by a dot, skipping any
          missing parts.

    Returns
    -------
    str
        The rendered version string. Missing components are omitted.
        Empty input yields an empty string.

    Raises
    ------
    TypeError
        If *pieces* is not a mapping or sequence.
    ValueError
        If any component cannot be coerced to a string or integer for
        numeric parts.
    """
    # Helper to convert numeric part
    def _to_int(value, name):
        if value is None:
            return None
        try:
            # Accept ints, strs that are digits, or floats (truncated)
            if isinstance(value, int):
                return value
            if isinstance(value, float):
                return int(value)
            if isinstance(value, str):
                if value.isdigit():
                    return int(value)
                else:
                    raise ValueError
            # Unsupported type
            raise ValueError
        except Exception:
            raise ValueError(f"Invalid {name} component: {value!r}") from None

    # Helper to coerce string component
    def _to_str(value, name):
        if value is None:
            return None
        if isinstance(value, (str, int, float)):
            return str(value)
        raise ValueError(f"Invalid {name} component type: {type(value).__name__}")

    # Parse pieces into recognised parts
    major = minor = patch = prerelease = build = None
    try:
        if isinstance(pieces, dict):
            major = _to_int(pieces.get("major"), "major")
            minor = _to_int(pieces.get("minor"), "minor")
            patch = _to_int(pieces.get("patch"), "patch")
            prerelease = _to_str(pieces.get("prerelease"), "prerelease")
            build = _to_str(pieces.get("build"), "build")
        else:
            # Sequence: interpret in order; ignore extra items
            it = iter(pieces)
            major = _to_int(next(it, None), "major")
            minor = _to_int(next(it, None), "minor")
            patch = _to_int(next(it, None), "patch")
            prerelease = _to_str(next(it, None), "prerelease")
            build = _to_str(next(it, None), "build")
    except TypeError:
        raise TypeError("pieces must be a mapping or sequence of components") from None

    # Build the string according to style
    if style is None or style == "" or style.lower() == "semver":
        # Semantic version string
        if major is None:
            return ""  # No version provided
        parts = [str(major)]
        if minor is not None:
            parts.append(str(minor))
        else:
            parts.append("0")
        if patch is not None:
            parts.append(str(patch))
        else:
            parts.append("0")
        base = ".".join(parts)
        if prerelease:
            base = f"{base}-{prerelease}"
        if build:
            base = f"{base}+{build}"
        return base

    if style.lower() == "numeric":
        if major is None:
            return ""
        parts = [str(major)]
        if minor is not None:
            parts.append(str(minor))
        else:
            parts.append("0")
        if patch is not None:
            parts.append(str(patch))
        else:
            parts.append("0")
        return ".".join(parts)

    if style.lower() == "plain":
        components = []
        for c in (major, minor, patch, prerelease, build):
            if c is None:
                continue
            components.append(str(c))
        return ".".join(components)

    # If style is unknown, fall back to semver
    return render(pieces, "semver")

def render(pieces, style):
    """Render the given version pieces into the requested style.

    Parameters
    ----------
    pieces : dict or sequence
        The version components.  Acceptable forms:
        * ``dict`` with keys ``"major"``, ``"minor"``, ``"patch"``, optional
          ``"prerelease"`` and ``"build"``.
        * ``tuple`` or ``list`` where the first three items are the major,
          minor and patch numbers (ints or int-convertible strings),
          followed optionally by a prerelease string and a build string.

    style : str
        One of ``"semver"``, ``"pep440"`` (case‑insensitive).  ``"semver"`` uses
        the Semantic Versioning format, while ``"pep440"`` uses PEP 440
        conventions.

    Returns
    -------
    str
        The formatted version string.

    Raises
    ------
    TypeError
        If ``style`` is not a string, or the ``pieces`` structure is not a
        dictionary or a sequence, or if numeric components cannot be converted
        to ``int``.
    ValueError
        If required components are missing, or if an unsupported ``style`` is
        specified.
    """
    if not isinstance(style, str):
        raise TypeError(f"style must be a string, got {type(style).__name__}")

    style_lc = style.lower()
    supported = {"semver", "pep440"}
    if style_lc not in supported:
        raise ValueError(
            f"Unsupported style '{style}'. Supported styles are: {sorted(supported)}"
        )

    # Extract components
    if isinstance(pieces, dict):
        try:
            major = pieces["major"]
            minor = pieces["minor"]
            patch = pieces["patch"]
        except KeyError as exc:
            raise ValueError(f"Missing required component {exc.args[0]!r}") from None
        prerelease = pieces.get("prerelease")
        build = pieces.get("build")
    elif isinstance(pieces, (tuple, list)):
        if len(pieces) < 3:
            raise ValueError("pieces sequence must contain at least 3 items")
        major, minor, patch = pieces[0], pieces[1], pieces[2]
        prerelease = pieces[3] if len(pieces) > 3 else None
        build = pieces[4] if len(pieces) > 4 else None
    else:
        raise TypeError(
            f"pieces must be a dict or sequence, got {type(pieces).__name__}"
        )

    # Validate and convert numeric components
    for name, val in (("major", major), ("minor", minor), ("patch", patch)):
        if val is None:
            raise ValueError(f"Missing {name}")
        if not isinstance(val, int):
            try:
                val = int(val)
            except Exception as exc:
                raise TypeError(f"{name} must be an integer-like value") from exc
        if name == "major":
            major = val
        elif name == "minor":
            minor = val
        else:
            patch = val

    # Validate prerelease and build
    if prerelease is not None and not isinstance(prerelease, str):
        raise TypeError("prerelease must be a string")
    if build is not None and not isinstance(build, str):
        raise TypeError("build must be a string")

    # Build the formatted string
    if style_lc == "semver":
        version = f"{major}.{minor}.{patch}"
        if prerelease:
            version += f"-{prerelease}"
        if build:
            version += f"+{build}"
    else:  # pep440
        version = f"{major}.{minor}.{patch}"
        if prerelease:
            # PEP 440 formatting rules
            if prerelease.startswith("rc") or prerelease.startswith("dev") or prerelease.startswith("post"):
                # For known prefixes, keep the hyphen or dot as is
                if prerelease.startswith("rc"):
                    version += f"-{prerelease}"
                else:  # dev or post
                    # Ensure a dot separates
                    if prerelease[3:].isdigit():
                        version += f".{prerelease}"
                    else:
                        version += f".{prerelease}"
            else:
                version += f".{prerelease}"
        if build:
            version += f"+{build}"

    return version

def render(pieces, style):
    """Render the given version pieces into the requested style."""
    # Validate input types
    if not isinstance(pieces, (list, tuple)):
        raise TypeError("pieces must be a list or tuple")
    if not isinstance(style, str):
        raise TypeError("style must be a string")

    # Helper to safely cast each piece to string (skip None)
    def _to_str(seq):
        return [str(x) for x in seq if x is not None]

    # Define rendering functions for supported styles
    def _semver(seq):
        seq_str = _to_str(seq)
        # Pad or truncate to at least 3 components
        major = seq_str[0] if len(seq_str) > 0 else "0"
        minor = seq_str[1] if len(seq_str) > 1 else "0"
        patch = seq_str[2] if len(seq_str) > 2 else "0"
        pre = None
        if len(seq_str) > 3:
            pre = ".".join(seq_str[3:])
        result = f"{major}.{minor}.{patch}"
        if pre:
            result += f"-{pre}"
        return result

    def _pep440(seq):
        seq_str = _to_str(seq)
        major = seq_str[0] if len(seq_str) > 0 else "0"
        minor = seq_str[1] if len(seq_str) > 1 else "0"
        patch = seq_str[2] if len(seq_str) > 2 else "0"
        rest = seq_str[3:] if len(seq_str) > 3 else []
        base = f"{major}.{minor}.{patch}"
        if rest:
            base += f"+{'.'.join(rest)}"
        return base

    def _raw(seq):
        return "".join(_to_str(seq))

    # Mapping of style name to rendering function
    style_map = {
        "semver": _semver,
        "pep440": _pep440,
        "raw": _raw
    }

    render_func = style_map.get(style.lower())
    if render_func is None:
        raise ValueError(f"Unsupported style: {style!r}")

    try:
        return render_func(pieces)
    except Exception as exc:
        # Wrap any unexpected error for clearer diagnostics
        raise RuntimeError(f"Failed to render version with style {style!r}") from exc

