    return '+'

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Validate the input types
    if isinstance(commands, str):
        cmd_parts = [commands]
    elif isinstance(commands, (list, tuple)):
        if not commands:
            raise ValueError("commands sequence cannot be empty")
        cmd_parts = list(commands)
    else:
        raise TypeError("commands must be a str or an iterable of strings")

    if args is None:
        args = []
    if not isinstance(args, (list, tuple)):
        raise TypeError("args must be a list or tuple of strings")

    # Build the final command list
    cmd = cmd_parts + [str(arg) for arg in args]

    # Set up environment variables
    if env is not None:
        if not isinstance(env, dict):
            raise TypeError("env must be a dict or None")
        env_vars = dict(os.environ)
        env_vars.update(env)
    else:
        env_vars = None

    # Decide on stderr handling
    stderr_capture = subprocess.PIPE
    if hide_stderr:
        stderr_capture = subprocess.DEVNULL

    # Verbose output
    if verbose:
        import shlex
        formatted = " ".join(shlex.quote(part) for part in cmd)
        print(f"Executing: {formatted}")

    try:
        result = subprocess.run(
            cmd,
            cwd=cwd,
            stdout=subprocess.PIPE,
            stderr=stderr_capture,
            env=env_vars,
            check=True,
            text=True,
        )
        return result
    except subprocess.CalledProcessError as e:
        raise RuntimeError(
            f"Command '{' '.join(e.cmd)}' failed with return code {e.returncode}"
        ) from e"

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Dynamically import required modules without using import statements
    subprocess = __import__('subprocess')
    shlex = __import__('shlex')
    os = __import__('os')

    # Helper to determine if an object is iterable but not a string
    def _is_iterable(obj):
        try:
            iter(obj)
            return not isinstance(obj, (str, bytes))
        except TypeError:
            return False

    # Prepare the command list
    try:
        if isinstance(commands, str):
            # If commands is a string, split it into arguments
            cmd_list = shlex.split(commands)
        elif _is_iterable(commands):
            cmd_list = list(commands)
        else:
            raise TypeError("commands must be a string or an iterable of arguments")
    except Exception as exc:
        raise ValueError(f"Failed to parse commands: {exc}") from exc

    # Append additional args if provided
    if args is not None:
        if _is_iterable(args):
            cmd_list.extend(args)
        else:
            raise TypeError("args must be an iterable of arguments")

    # Prepare the environment
    if env is not None:
        if not isinstance(env, dict):
            raise TypeError("env must be a dictionary")
        # Merge with current environment
        exec_env = os.environ.copy()
        exec_env.update(env)
    else:
        exec_env = None  # Use default environment

    # Verbose: show the command
    if verbose:
        print(f"Running command: {cmd_list}")

    try:
        result = subprocess.run(
            cmd_list,
            cwd=cwd,
            env=exec_env,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            universal_newlines=True,
            check=True  # Raise CalledProcessError on non-zero exit
        )
    except subprocess.CalledProcessError as e:
        # Capture stdout and stderr for debugging
        if verbose:
            print(f"Command failed with exit code {e.returncode}")
            print(f"stdout: {e.stdout}")
            print(f"stderr: {e.stderr}")
        raise
    except FileNotFoundError as e:
        raise FileNotFoundError(f"Command not found: {cmd_list[0]}") from e
    except Exception as e:
        raise RuntimeError(f"Failed to execute command {cmd_list}: {e}") from e

    # Optionally hide stderr output
    stderr_output = None if hide_stderr else result.stderr

    # Verbose: show output
    if verbose:
        print(f"Return code: {result.returncode}")
        print(f"stdout: {result.stdout}")
        if not hide_stderr and stderr_output:
            print(f"stderr: {stderr_output}")

    # Return a dictionary with relevant information
    return {
        'returncode': result.returncode,
        'stdout': result.stdout,
        'stderr': stderr_output
    }

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess
    import shlex
    import os

    # Build the command list
    if commands is None:
        raise ValueError("commands argument cannot be None")

    if isinstance(commands, str):
        try:
            cmd = shlex.split(commands)
        except ValueError as exc:
            raise ValueError(f"Failed to parse command string: {commands}") from exc
    elif isinstance(commands, (list, tuple)):
        cmd = list(commands)
    else:
        raise TypeError(f"commands must be a str, list, or tuple; got {type(commands).__name__}")

    # Append arguments if provided
    if args:
        if isinstance(args, (list, tuple)):
            cmd.extend(args)
        elif isinstance(args, str):
            # Treat a single string argument as a single element
            cmd.append(args)
        else:
            raise TypeError(f"args must be a str, list, or tuple; got {type(args).__name__}")

    if verbose:
        print("Running command:", " ".join(shlex.quote(part) for part in cmd))
        if cwd:
            print("  Working directory:", cwd)
        if env:
            print("  Environment variables:", env)

    # Merge environment variables if provided
    env_to_use = None
    if env is not None:
        if not isinstance(env, dict):
            raise TypeError(f"env must be a dict; got {type(env).__name__}")
        # Copy current environment and update with provided env
        env_to_use = os.environ.copy()
        env_to_use.update(env)

    # Prepare kwargs for subprocess.run
    run_kwargs = {
        "args": cmd,
        "cwd": cwd,
        "capture_output": True,
        "text": True,
        "env": env_to_use,
    }
    if hide_stderr:
        # Redirect stderr to DEVNULL
        run_kwargs["stderr"] = subprocess.DEVNULL

    try:
        completed = subprocess.run(**run_kwargs)
    except FileNotFoundError as exc:
        raise FileNotFoundError(f"Command not found: {cmd[0]}") from exc

    # Raise an error if the command failed and we are not hiding stderr
    if completed.returncode != 0:
        error_msg = f"Command '{' '.join(cmd)}' exited with status {completed.returncode}"
        if not hide_stderr:
            error_msg += f"\nStderr: {completed.stderr}"
        raise subprocess.CalledProcessError(
            completed.returncode, completed.args, output=completed.stdout, stderr=completed.stderr
        ) from None

    return completed

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""

    # Prepare the command
    if isinstance(commands, str):
        cmd_tokens = [commands]
    elif isinstance(commands, (list, tuple)):
        cmd_tokens = list(commands)
    else:
        raise TypeError("`commands` must be a string or a list/tuple of command tokens")

    if args is None:
        args_tokens = []
    elif isinstance(args, str):
        args_tokens = [args]
    elif isinstance(args, (list, tuple)):
        args_tokens = list(args)
    else:
        raise TypeError("`args` must be None, a string, or a list/tuple of arguments")

    cmd = cmd_tokens + args_tokens

    # Build the environment
    env_to_use = None
    if env is not None:
        if not isinstance(env, dict):
            raise TypeError("`env` must be a dictionary mapping environment variable names to values")
        env_copy = os.environ.copy()
        env_copy.update(env)
        env_to_use = env_copy

    # Verbose output
    if verbose:
        try:
            import shlex
            pretty_cmd = " ".join(shlex.quote(part) for part in cmd)
        except Exception:
            pretty_cmd = " ".join(str(part) for part in cmd)
        print(f"Executing: {pretty_cmd}")

    # Determine stderr handling
    stderr_option = subprocess.PIPE if not hide_stderr else subprocess.DEVNULL

    try:
        result = subprocess.run(
            cmd,
            cwd=cwd,
            env=env_to_use,
            stdout=subprocess.PIPE,
            stderr=stderr_option,
            check=False,
            text=True
        )
    except FileNotFoundError as err:
        raise RuntimeError(f"Command not found: {cmd[0]}") from err
    except Exception as err:
        raise RuntimeError(f"Error executing command {cmd[0]}: {err}") from err

    # If the command failed, include outputs in the error message
    if result.returncode != 0:
        error_msg = f"Command '{' '.join(cmd)}' exited with status {result.returncode}\n"
        if result.stdout:
            error_msg += f"--- stdout ---\n{result.stdout}\n"
        if not hide_stderr and result.stderr:
            error_msg += f"--- stderr ---\n{result.stderr}\n"
        raise RuntimeError(error_msg)

    # Return stdout (may be empty string)
    return result.stdout

def get_config():
    """Create, populate and return the VersioneerConfig() object."""
    # The VersioneerConfig class is expected to be available in the surrounding
    # context (e.g., imported from the versioneer package).  This function creates
    # an instance and sets the fields that are typically required by the
    # versioneer runtime.  If the class is not available, raise an ImportError
    # with a clear message so that callers can diagnose the problem.
    try:
        cfg = VersioneerConfig()
    except Exception as exc:  # catching broad Exception to handle missing class
        raise ImportError(
            "The 'VersioneerConfig' class required by get_config() "
            "was not found. Ensure that versioneer is correctly installed "
            "and that the class is importable."
        ) from exc

    # Set the standard configuration fields.  These values closely mirror
    # the defaults used by versioneer when a repository is initialized.
    # If any of these attributes do not exist on the cfg instance, they
    # will simply be ignored.
    try:
        cfg.tag_prefix = ""  # prefix that tags must start with
    except AttributeError:
        pass

    try:
        cfg.parentdir_prefix_version = ""  # prefix for parent directory name
    except AttributeError:
        pass

    try:
        # The file that contains the generated _version__ module.
        cfg.versionfile_source = "src/_version.py"
    except AttributeError:
        pass

    try:
        # The location where the _version__ module will be written during a
        # build/wheel operation.
        cfg.versionfile_build = "src/_version.py"
    except AttributeError:
        pass

    try:
        # Whether versioneer should search parent directories for a
        # tag-based version number.
        cfg.search_parent_directories = False
    except AttributeError:
        pass

    # Some older or customized uses of versioneer may require these
    # fields to exist even if they are left unset.
    try:
        cfg.verbose = False
    except AttributeError:
        pass

    try:
        cfg.parentdir_prefix_version = cfg.parentdir_prefix_version or "pkgname-"
    except AttributeError:
        pass

    return cfg

def get_config():
    """Create, populate and return the VersioneerConfig() object."""
    try:
        cfg = VersioneerConfig()
    except Exception as exc:
        raise RuntimeError(f"Could not instantiate VersioneerConfig: {exc}") from exc
    try:
        # Common configuration defaults used by versioneer
        cfg.versionfile_source = 'pkg/_version.py'
        cfg.tag_prefix = ''
        cfg.parentdir_prefix_version = 'pkg-'
        cfg.versionfile_suffix = '_version.py'
        cfg.verbose = False
    except Exception as exc:
        raise RuntimeError(f"Could not set attributes on VersioneerConfig: {exc}") from exc
    return cfg

_vcs_registry = {}

def register_vcs_handler(vcs):
    """Create decorator to mark a method as the handler of a VCS."""
    if not isinstance(vcs, str) or not vcs:
        raise ValueError("vcs must be a non-empty string")
    def decorator(method):
        if not callable(method):
            raise TypeError("handler must be callable")
        _vcs_registry[vcs] = method
        return method
    return decorator

def register_vcs_handler(vcs, method):  # decorator
    """Create decorator to mark a method as the handler of a VCS."""
    # Validate inputs
    if not isinstance(vcs, str):
        raise TypeError(f"vcs must be a string, got {type(vcs).__name__}")
    if not callable(method):
        raise TypeError(f"method must be callable, got {type(method).__name__}")

    # Initialize the internal registry if it doesn't exist yet
    if not hasattr(register_vcs_handler, "_registry"):
        register_vcs_handler._registry = {}

    registry = register_vcs_handler._registry

    # Register or override the handler for the given VCS
    if vcs in registry:
        # Override silently; could also log a warning if needed
        registry[vcs] = method
    else:
        registry[vcs] = method

    # Return the original method unchanged
    return method

# Helper to retrieve a handler; not required by the spec but often useful
def get_vcs_handler(vcs):
    """Retrieve the registered handler for the given VCS, if any."""
    registry = getattr(register_vcs_handler, "_registry", {})
    return registry.get(vcs, None)

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
        """
        Validate storage root hierarchy.

        Returns:
            num_objects - number of objects checked
            good_objects - number of objects checked that were found to be valid
        """
        # Ensure the root attribute exists
        if not hasattr(self, "root"):
            raise AttributeError("The object does not have a 'root' attribute.")
        root_path = getattr(self, "root")

        # Prepare digests storage if present
        digests = getattr(self, "digests", {})

        num_objects = 0
        good_objects = 0

        # Helper to safely read file and compute sha256
        def _validate_digest(filepath):
            try:
                with open(filepath, "rb") as f:
                    data = f.read()
                    # compute digest
                    if hasattr(self, "_compute_digest"):
                        # use a custom method if present
                        return self._compute_digest(data)
                    else:
                        import hashlib
                        return hashlib.sha256(data).hexdigest()
            except Exception as e:
                if show_warnings:
                    print(f"Warning: Failed to read or digest file '{filepath}': {e}")
                return None

        # If root_path is a file, check it directly
        if hasattr(os.path, "isfile") and os.path.isfile(root_path):
            num_objects = 1
            valid = True
            if validate_objects:
                try:
                    size = os.path.getsize(root_path)
                    if size == 0:
                        valid = False
                        if show_warnings:
                            print(f"Warning: File '{root_path}' is empty.")
                except Exception as e:
                    valid = False
                    if show_warnings:
                        print(f"Warning: Could not get size for file '{root_path}': {e}")
            if check_digests:
                stored = digests.get(os.path.basename(root_path))
                computed = _validate_digest(root_path)
                if stored is None or computed is None or stored.lower() != computed.lower():
                    valid = False
                    if show_warnings:
                        print(f"Warning: Digest mismatch or missing for file '{root_path}'.")
            if valid:
                good_objects = 1
            return num_objects, good_objects

        # If root_path is a directory, walk it
        if hasattr(os, "walk"):
            try:
                for dirpath, dirnames, filenames in os.walk(root_path):
                    for fname in filenames:
                        filepath = os.path.join(dirpath, fname)
                        num_objects += 1
                        valid = True

                        if validate_objects:
                            try:
                                size = os.path.getsize(filepath)
                                if size == 0:
                                    valid = False
                                    if show_warnings:
                                        print(f"Warning: File '{filepath}' is empty.")
                            except Exception as e:
                                valid = False
                                if show_warnings:
                                    print(f"Warning: Could not get size for file '{filepath}': {e}")

                        if check_digests:
                            stored = digests.get(os.path.relpath(filepath, root_path))
                            if stored is None:
                                # try using just basename
                                stored = digests.get(os.path.basename(filepath))
                            computed = _validate_digest(filepath)
                            if stored is None or computed is None or stored.lower() != computed.lower():
                                valid = False
                                if show_warnings:
                                    print(f"Warning: Digest mismatch or missing for file '{filepath}'.")

                        if valid:
                            good_objects += 1
            except Exception as e:
                if show_warnings:
                    print(f"Warning: Error walking directory '{root_path}': {e}")
        else:
            # No os.walk available; attempt simple file list
            if show_warnings:
                print("Warning: os.walk is not available; unable to traverse directory hierarchy.")
            return 0, 0

        return num_objects, good_objects

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
        """
        Validate storage root hierarchy.

        Returns:
            num_objects - number of objects checked
            good_objects - number of objects checked that were found to be valid
        """
        num_objects = 0
        good_objects = 0

        # Gather candidate objects
        try:
            candidate_objects = getattr(self, "objects", [])
            if isinstance(candidate_objects, dict):
                candidate_objects = list(candidate_objects.values())
        except Exception:
            candidate_objects = []

        for obj in list(candidate_objects):
            num_objects += 1
            valid = True

            # Object-level validation
            if validate_objects:
                try:
                    if hasattr(obj, "validate") and callable(obj.validate):
                        # Assume validate returns a bool
                        valid = bool(obj.validate())
                    elif hasattr(obj, "valid") and isinstance(obj.valid, bool):
                        valid = obj.valid
                except Exception as e:
                    valid = False
                    if show_warnings:
                        try:
                            print(f"[validate_hierarchy] Validation error for object {obj!r}: {e}")
                        except Exception:
                            pass

            # Digest check
            if check_digests and valid:
                try:
                    expected_digest = getattr(obj, "digest", None)
                    if expected_digest is not None:
                        data = getattr(obj, "data", None)
                        if data is not None:
                            # Compute digest of the data; support bytes, str, mapping or iterable of bytes/str
                            try:
                                import hashlib
                                import json

                                if isinstance(data, (bytes, bytearray)):
                                    raw = data
                                else:
                                    # Try to serialize to JSON for reproducible digest
                                    raw = json.dumps(data, sort_keys=True).encode("utf-8")
                                actual_digest = hashlib.sha256(raw).hexdigest()
                                if actual_digest != expected_digest:
                                    valid = False
                                    if show_warnings:
                                        print(f"[validate_hierarchy] Digest mismatch for object {obj!r}")
                            except Exception as e:
                                valid = False
                                if show_warnings:
                                    print(f"[validate_hierarchy] Digest computation error for object {obj!r}: {e}")
                except Exception as e:
                    valid = False
                    if show_warnings:
                        print(f"[validate_hierarchy] Digest check error for object {obj!r}: {e}")

            if valid:
                good_objects += 1

        return num_objects, good_objects

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """
    Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    # Retrieve list of objects from the instance.  If the attribute is a method
    # call it, otherwise use the value directly.
    try:
        objs = getattr(self, 'objects', [])
        if callable(objs):
            objs = objs()
    except Exception as exc:
        if show_warnings:
            print(f"[validate_hierarchy] Unable to retrieve objects: {exc}")
        return 0, 0

    num_objects = 0
    good_objects = 0

    for obj in objs:
        num_objects += 1
        try:
            # Object‑level validity
            if validate_objects:
                if hasattr(obj, 'validate') and callable(obj.validate):
                    obj_valid = bool(obj.validate())
                elif hasattr(obj, 'is_valid'):
                    obj_valid = bool(obj.is_valid)
                else:
                    # Assume valid if no explicit validation method/attribute
                    obj_valid = True
            else:
                obj_valid = True

            # Digest check
            if check_digests:
                try:
                    content = None
                    if hasattr(obj, 'get_bytes') and callable(obj.get_bytes):
                        content = obj.get_bytes()
                    elif hasattr(obj, 'content'):
                        content = obj.content
                    elif hasattr(obj, 'data'):
                        content = obj.data

                    if content is None:
                        raise ValueError("No content found for digest check")

                    # Compute digest
                    import hashlib  # allowed inside function
                    computed = hashlib.sha256(content).hexdigest()

                    stored = None
                    if hasattr(obj, 'stored_digest'):
                        stored = obj.stored_digest
                    elif hasattr(obj, 'digest'):
                        stored = obj.digest

                    if stored is None:
                        raise ValueError("No stored digest for comparison")

                    obj_valid = obj_valid and (computed == stored)
                except Exception as exc:
                    if show_warnings:
                        print(f"[validate_hierarchy] Digest check failed for {obj}: {exc}")
                    obj_valid = False

            if obj_valid:
                good_objects += 1
        except Exception as exc:
            if show_warnings:
                print(f"[validate_hierarchy] Validation error for {obj}: {exc}")

    return num_objects, good_objects

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

