    return True

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    # Validate input
    if not isinstance(version, str) or not version:
        raise ValueError("Version must be a non-empty string")
    if not version.isdigit():
        raise ValueError(f"Invalid version string: {version!r} - must contain only digits")
    try:
        current = int(version)
    except Exception as exc:
        raise ValueError(f"Could not convert version to integer: {exc}") from exc

    if current < 0:
        raise ValueError("Version number must be non-negative")

    next_num = current + 1
    # Preserve leading zeros if present
    if version[0] == '0' and len(version) > 1:
        # Use zero padding to original width; if next_num has more digits than width, the padding
        # will automatically expand to fit the number
        return str(next_num).zfill(len(version))
    else:
        return str(next_num)

def validate_version_inventories(self, version_dirs):
    """
    Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    Parameters
    ----------
    version_dirs : list[str]
        A list of version directory names assumed to be in sequence (1, 2, 3, ...).

    Returns
    -------
    dict
        A mapping from version directory to a list of tuples describing digest
        differences.  Each tuple is (content_path, current_digest, root_digest).
        Directories without an inventory or with errors will be omitted from the
        result, but the method will log appropriate messages via `self.log`.
    """
    # Use the instance's root directory if it exists; otherwise fall back to the current working directory.
    root_dir = getattr(self, 'root_dir', os.getcwd())
    inventory_file = getattr(self, 'inventory_file', 'inventory.json')
    root_inventory_path = os.path.join(root_dir, inventory_file)

    # Helper to load JSON from a given path
    def _load_json(path):
        try:
            with open(path, 'r', encoding='utf-8') as f:
                return json.load(f)
        except FileNotFoundError:
            raise FileNotFoundError(f"Inventory file not found: {path}")
        except json.JSONDecodeError as e:
            raise ValueError(f"Invalid JSON in inventory file {path}: {e}")

    # Load the root inventory once
    try:
        root_inventory = _load_json(root_inventory_path)
    except Exception as exc:
        # If the root inventory cannot be verified, stop the validation
        error_msg = f"Root inventory validation failed: {exc}"
        if hasattr(self, 'log'):
            self.log.error(error_msg)
        else:
            raise RuntimeError(error_msg)

    differences = {}

    for version in version_dirs:
        version_path = os.path.join(root_dir, version)
        try:
            inventory_path = os.path.join(version_path, inventory_file)
            inventory = _load_json(inventory_path)
        except Exception as exc:
            # Log the error and skip this version
            if hasattr(self, 'log'):
                self.log.warning(f"Skipping version {version}: {exc}")
            else:
                # If no logger, we print to stderr as a fallback
                print(f"Skipping version {version}: {exc}", file=sys.stderr)
            continue

        # Compare each item in the inventory with the root inventory
        diffs = []
        for path_in_inventory, current_digest in inventory.items():
            root_digest = root_inventory.get(path_in_inventory)
            if root_digest is None or root_digest != current_digest:
                diffs.append((path_in_inventory, current_digest, root_digest))
        if diffs:
            differences[version] = diffs

    return differences

def validate_version_inventories(self, version_dirs):
        """Each version SHOULD have an inventory up to that point.

        Also keep a record of any content digests different from those in the root inventory
        so that we can also check them when validating the content.

        version_dirs is an array of version directory names and is assumed to be in
        version sequence (1, 2, 3...).
        """
        # Ensure root inventory is available for comparison
        root_inventory = getattr(self, "root_inventory", None)
        if root_inventory is None:
            raise AttributeError("root_inventory attribute must be set before validating versions")

        # Storage for differences: {filepath: [(version, root_digest, version_digest), ...]}
        differences = {}
        seen_files = set()

        # Helper to load an inventory file
        def load_inventory(path):
            """Return mapping {filepath: digest} from an inventory file."""
            import os, json
            try:
                with open(path, "r", encoding="utf-8") as f:
                    try:
                        data = json.load(f)
                        # Assume JSON is {checksum: [file, ...], ...} or {file: checksum, ...}
                        if isinstance(data, dict):
                            # Detect which form by key type
                            if all(isinstance(k, str) and isinstance(v, list) for k, v in data.items()):
                                # checksum -> list of files
                                inv = {}
                                for chk, files in data.items():
                                    if not isinstance(files, list):  # allow single string
                                        files = [files]
                                    for fl in files:
                                        inv[fl] = chk
                                return inv
                            else:
                                # Assume file -> checksum
                                return data
                        else:
                            raise ValueError("Unexpected inventory JSON structure")
                    except json.JSONDecodeError:
                        # Fallback to simple line format: "<checksum>  <filepath>"
                        inv = {}
                        for line in f:
                            line = line.strip()
                            if not line or line.startswith("#"):
                                continue
                            parts = line.split(None, 1)
                            if len(parts) == 2:
                                chk, fl = parts
                                inv[fl] = chk
                            else:
                                # Cannot parse line
                                continue
                        return inv
            except FileNotFoundError:
                raise FileNotFoundError(f"Inventory file '{path}' does not exist")
            except Exception as e:
                raise RuntimeError(f"Failed to load inventory '{path}': {e}")

        for ver_dir in version_dirs:
            # Find inventory file in this directory
            # Try common names
            candidates = ["inventory.json", "inventory.yaml", "inventory", "manifest", "inventory.txt"]
            inv_path = None
            for cand in candidates:
                full = os.path.join(ver_dir, cand)
                if os.path.isfile(full):
                    inv_path = full
                    break
            if not inv_path:
                raise FileNotFoundError(f"No recognizable inventory file in directory '{ver_dir}'")

            version_inventory = load_inventory(inv_path)

            # Validate that the inventory is up-to-date: it must contain all previously seen files
            missing = seen_files - version_inventory.keys()
            if missing:
                # Record as an exception or log; here we raise for strictness
                raise ValueError(
                    f"Inventory in '{ver_dir}' is missing files from previous versions: "
                    f"{sorted(missing)}"
                )

            # Update seen files set
            seen_files.update(version_inventory.keys())

            # Record differences with root inventory
            for fl, dig in version_inventory.items():
                root_digest = root_inventory.get(fl)
                if root_digest is None:
                    # No entry in root; skip comparison
                    continue
                if dig != root_digest:
                    differences.setdefault(fl, []).append(
                        {"version": ver_dir, "root_digest": root_digest, "version_digest": dig}
                    )

        # Store differences on the instance for later use
        setattr(self, "inventory_differences", differences)
        # Return number of differences for convenience
        return len(differences) if differences else 0

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    from pathlib import Path

    # Normalise the input to a Path instance
    p = Path(path)

    # Basic existence check
    if not p.exists():
        return f"does not exist: {p}"

    # If it's a file, just return 'file' (might be an inventory)
    if p.is_file():
        return 'file'

    # If it's a directory, look for any file starting with "0="
    if p.is_dir():
        namaste_file = None
        try:
            for entry in p.iterdir():
                if entry.is_file() and entry.name.startswith('0='):
                    namaste_file = entry
                    break
        except Exception as exc:
            return f"error accessing directory contents: {exc}"

        if namaste_file is not None:
            try:
                with namaste_file.open('r', encoding='utf-8') as f:
                    # read first non-empty line
                    for line in f:
                        line = line.strip()
                        if line:
                            break
                    else:
                        return f"empty namaste file: {namaste_file}"
                # simple heuristic: look for key phrases
                # These patterns are illustrative and may need adjustment for a real OCFL implementation.
                if line.lower().startswith('ocfl'):
                    return 'root'
                if line.lower().startswith('object'):
                    return 'object'
            except Exception as exc:
                return f"error reading namaste file {namaste_file}: {exc}"
            return f"unknown namaste content in {namaste_file}"
        else:
            return f"no namaste file found in directory: {p}"

    # Other types (e.g., symlinks or special files) are not handled explicitly
    return f"unrecognized type for path: {p}"

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    # Helper function to safely list directory contents
    def safe_listdir(p):
        try:
            return os.listdir(p)
        except OSError as e:
            return None

    # If path is a file, return 'file'
    try:
        if os.path.isfile(path):
            return 'file'
    except OSError as e:
        return f'error accessing path as file: {e}'

    # If path is not a directory, return an error description
    try:
        if not os.path.isdir(path):
            return f'path does not exist or is not a directory: {path}'
    except OSError as e:
        return f'error accessing path as dir: {e}'

    # List namaste files named with prefix '0='
    items = safe_listdir(path)
    if items is None:
        return f'cannot list contents of directory: {path}'

    namaste_files = [f for f in items if f.startswith('0=')]
    if not namaste_files:
        return f'no namaste files found in directory: {path}'

    # Heuristic: presence of a namaste file containing "manifest" indicates root.
    for nf in namaste_files:
        if 'manifest' in nf.lower():
            return 'root'
    # Otherwise assume it's an object
    return 'object'

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    import os
    import re

    if not os.path.exists(path):
        return f"error: path does not exist: {path}"

    if os.path.isfile(path):
        return 'file'

    if not os.path.isdir(path):
        return f"error: path is not a file or directory: {path}"

    # Identify namaste files (files starting with '0=')
    try:
        entries = os.listdir(path)
    except OSError as e:
        return f"error: cannot list directory {path}: {e}"

    namaste_files = [f for f in entries if f.startswith('0=') and os.path.isfile(os.path.join(path, f))]
    if not namaste_files:
        return f"error: no namaste file (0=*) found in directory {path}"
    if len(namaste_files) > 1:
        return f"error: multiple namaste files ({', '.join(namaste_files)}) in directory {path}"

    namaste_path = os.path.join(path, namaste_files[0])
    try:
        with open(namaste_path, 'r', encoding='utf-8', errors='replace') as fh:
            for line in fh:
                line = line.strip()
                if not line:
                    continue
                # Normalize line
                if re.search(r'OCFL[-_]?ROOT', line, re.IGNORECASE):
                    return 'root'
                if re.search(r'OCFL[-_]?OBJECT', line, re.IGNORECASE):
                    return 'object'
                break
    except OSError as e:
        return f"error: cannot read namaste file {namaste_path}: {e}"

    return f"error: unknown namaste file format: {os.path.basename(namaste_path)}"

def deep_merge_nodes(nodes):
    '''
    Deep merge a list of (ScalarNode, Node) pairs, merging values for duplicate keys.
    '''
    if not nodes:
        return []

    merged = {}
    for key_node, value_node in nodes:
        key = getattr(key_node, 'value', None)
        if key in merged:
            existing_key_node, existing_value_node = merged[key]
            if isinstance(existing_value_node, ruamel.yaml.nodes.MappingNode) and isinstance(value_node, ruamel.yaml.nodes.MappingNode):
                try:
                    merged_value = _merge_mapping_nodes(existing_value_node, value_node)
                except Exception:
                    merged_value = value_node
                merged[key] = (existing_key_node, merged_value)
            else:
                # last value wins
                merged[key] = (existing_key_node, value_node)
        else:
            merged[key] = (key_node, value_node)

    return list(merged.values())


def _merge_mapping_nodes(node1, node2):
    '''
    Recursively merge two MappingNode instances. The returned node has a new
    value list but keeps the tag from node1.
    '''
    # Preserve ordering: first node1's entries, then any new entries from node2
    merged_entries = {}
    order = []

    def add_entries(node):
        for k, v in getattr(node, 'value', []):
            kval = getattr(k, 'value', None)
            if kval not in merged_entries:
                merged_entries[kval] = (k, v)
                order.append(kval)

    add_entries(node1)
    for k, v in getattr(node2, 'value', []):
        kval = getattr(k, 'value', None)
        if kval in merged_entries:
            existing_k, existing_v = merged_entries[kval]
            if isinstance(existing_v, ruamel.yaml.nodes.MappingNode) and isinstance(v, ruamel.yaml.nodes.MappingNode):
                merged_v = _merge_mapping_nodes(existing_v, v)
                merged_entries[kval] = (existing_k, merged_v)
            else:
                merged_entries[kval] = (existing_k, v)
        else:
            merged_entries[kval] = (k, v)
            order.append(kval)

    merged_value = [merged_entries[k] for k in order]
    return ruamel.yaml.nodes.MappingNode(
        getattr(node1, 'tag', 'tag:yaml.org,2002:map'),
        merged_value
    )

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    try:
        from ruamel.yaml.nodes import ScalarNode, MappingNode
    except Exception:
        # If ruamel.yaml is not available, return the original nodes unchanged.
        return nodes

    from collections import OrderedDict

    def merge_mapping_values(a_node, b_node):
        """Recursively merge two MappingNode values.

        a_node and b_node are MappingNode instances.
        Returns a new MappingNode with merged values.
        """
        if not (isinstance(a_node, MappingNode) and isinstance(b_node, MappingNode)):
            # In case one of them is not a MappingNode, favour b_node
            return b_node

        # Create a new list of merged items
        result_items = []
        seen_keys = {}
        # Helper to process each mapping node
        def process_mapping(node, overwrite=False):
            for key, val in node.value:
                key_val = key.value if isinstance(key, ScalarNode) else key
                if key_val in seen_keys:
                    # existing entry: possibly merge if both are MappingNodes
                    existing_key, existing_val = seen_keys[key_val]
                    if isinstance(existing_val, MappingNode) and isinstance(val, MappingNode):
                        merged_val = merge_mapping_values(existing_val, val)
                        # Update stored value
                        seen_keys[key_val] = (existing_key, merged_val)
                    else:
                        # Replace with newer value unless overwrite is False
                        if overwrite:
                            seen_keys[key_val] = (key, val)
                else:
                    seen_keys[key_val] = (key, val)

        # First process a_node without overwrite to keep its order
        process_mapping(a_node, overwrite=False)
        # Then process b_node with overwrite to allow last wins
        process_mapping(b_node, overwrite=True)

        # Reconstruct ordered list from seen_keys preserving order of first occurrence
        for key, val in list(seen_keys.values()):
            result_items.append((key, val))

        return MappingNode(tag='tag:yaml.org,2002:map', value=result_items)

    merged_dict = OrderedDict()
    for key_node, val_node in nodes:
        # Determine key identifier
        key_id = key_node.value if isinstance(key_node, ScalarNode) else key_node
        if key_id in merged_dict:
            # Merge values
            existing_val_node = merged_dict[key_id][1]
            if isinstance(existing_val_node, MappingNode) and isinstance(val_node, MappingNode):
                merged_val = merge_mapping_values(existing_val_node, val_node)
                merged_dict[key_id] = (merged_dict[key_id][0], merged_val)
            else:
                # Non-mapping: overwrite with last value
                merged_dict[key_id] = (key_node, val_node)
        else:
            merged_dict[key_id] = (key_node, val_node)

    return list(merged_dict.values())

def deep_merge_nodes(nodes):
    """
    Merge a list of (ScalarNode, Node) tuples, performing a deep merge for duplicate keys.
    """
    if not isinstance(nodes, list):
        raise TypeError("nodes must be a list of tuples")
    # Helper: recursively merge two MappingNodes
    def _merge_mapping_nodes(a, b):
        if not isinstance(a, a.__class__) or not isinstance(b, b.__class__):
            raise TypeError("expected both arguments to be MappingNodes")
        # Build a map from key string to pair index and pair
        existing_pairs = list(a.value)
        existing_map = {}
        for idx, (k_node, v_node) in enumerate(existing_pairs):
            try:
                key = k_node.value
            except Exception as exc:
                raise ValueError("mapping key node must have a 'value' attribute") from exc
            existing_map[key] = (idx, (k_node, v_node))
        # Merge from b into a
        for k_node_b, v_node_b in b.value:
            try:
                key_b = k_node_b.value
            except Exception as exc:
                raise ValueError("mapping key node must have a 'value' attribute") from exc
            if key_b in existing_map:
                idx_existing, (k_node_old, v_node_old) = existing_map[key_b]
                if isinstance(v_node_old, type(a)) and isinstance(v_node_b, type(a)):
                    merged_val = _merge_mapping_nodes(v_node_old, v_node_b)
                    existing_pairs[idx_existing] = (k_node_old, merged_val)
                    existing_map[key_b] = (idx_existing, (k_node_old, merged_val))
                else:
                    # last wins
                    existing_pairs[idx_existing] = (k_node_old, v_node_b)
                    existing_map[key_b] = (idx_existing, (k_node_old, v_node_b))
            else:
                existing_pairs.append((k_node_b, v_node_b))
        # Return a new MappingNode preserving the tag of 'a'
        return type(a)(tag=a.tag, value=existing_pairs)

    seen = {}
    order = []
    for item in nodes:
        if not (isinstance(item, tuple) or isinstance(item, list)) or len(item) != 2:
            raise ValueError("each element of nodes must be a 2-tuple of (key_node, value_node)")
        key_node, val_node = item
        try:
            key = key_node.value
        except Exception as exc:
            raise ValueError("key node must have a 'value' attribute") from exc
        if key in seen:
            idx, _, existing_val = seen[key]
            if isinstance(existing_val, type(val_node)) and isinstance(val_node, type(val_node)):
                if hasattr(existing_val, 'tag') and hasattr(val_node, 'tag'):
                    # Only attempt deep merge if both are mapping nodes
                    if isinstance(existing_val, existing_val.__class__) and isinstance(val_node, val_node.__class__):
                        merged_val = _merge_mapping_nodes(existing_val, val_node)
                        seen[key] = (idx, key_node, merged_val)
                        continue
            # otherwise last wins
            seen[key] = (idx, key_node, val_node)
        else:
            seen[key] = (len(order), key_node, val_node)
            order.append(key)
    # Construct result preserving original order of first occurrence
    result = []
    for key in order:
        idx, key_node, val_node = seen[key]
        result.append((key_node, val_node))
    return result

def deep_merge_nodes(nodes):
    """
    Deep merge a list of (key_node, value_node) tuples, where duplicate keys
    should have their mapping values merged recursively. Non-mapping duplicates
    are replaced by the last value seen. The function returns a new list of
    tuples with merged results.
    """
    from collections import OrderedDict

    def merge_mapping_nodes(node1, node2):
        """Recursively merge two ruamel.yaml.MappingNode instances."""
        # Preserve order: first appearance of keys in node1, then node2
        merged = OrderedDict()
        key_nodes = {}

        # Process first mapping
        for knode, v in (node1.value if hasattr(node1, "value") else []):
            k = knode.value if hasattr(knode, "value") else knode
            merged[k] = v
            key_nodes[k] = knode

        # Process second mapping, merging as required
        for knode, v in (node2.value if hasattr(node2, "value") else []):
            k = knode.value if hasattr(knode, "value") else knode
            if k in merged:
                oldv = merged[k]
                if isinstance(oldv, MappingNode) and isinstance(v, MappingNode):
                    merged[k] = merge_mapping_nodes(oldv, v)
                else:
                    merged[k] = v
            else:
                merged[k] = v
                key_nodes[k] = knode

        # Build new MappingNode value list
        new_value = [(key_nodes[k], merged[k]) for k in merged]
        # Use the tag from the first mapping node (node1) if possible
        tag = getattr(node1, "tag", None)
        return MappingNode(tag=tag, value=new_value)

    merged_results = OrderedDict()
    key_nodes = {}

    for key_node, val_node in nodes:
        # Key is identified by its scalar value if present
        key = getattr(key_node, "value", key_node)

        if key in merged_results:
            existing_val = merged_results[key]
            if isinstance(existing_val, MappingNode) and isinstance(val_node, MappingNode):
                merged_results[key] = merge_mapping_nodes(existing_val, val_node)
            else:
                merged_results[key] = val_node  # last wins for non-mapping
        else:
            merged_results[key] = val_node
            key_nodes[key] = key_node

    # Preserve order of keys as they first appeared
    return [(key_nodes[k], merged_results[k]) for k in merged_results]

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    # Basic validation
    if parser is None:
        raise TypeError('parser must not be None')
    if not hasattr(parser, "_actions"):
        raise TypeError(f'Expected an argparse.ArgumentParser instance, got {type(parser).__name__}')
    flags = []
    for action in parser._actions:
        try:
            opt_strings = action.option_strings
        except AttributeError:
            continue
        if opt_strings:
            flags.extend(opt_strings)
    return ' '.join(flags)

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    try:
        flags = []
        for action in getattr(parser, "_actions", []):
            for flag in getattr(action, "option_strings", []):
                if flag not in flags:
                    flags.append(flag)
        return " ".join(flags)
    except Exception:
        return ""

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    # Verify that the supplied object behaves like an ArgumentParser by checking for the
    # expected internal attribute `_actions`. This avoids importing argparse directly
    # and keeps the function self-contained.
    try:
        actions = parser._actions
    except AttributeError:
        raise TypeError('Expected an argparse.ArgumentParser instance')

    flags = []
    for action in actions:
        # Each action should expose `option_strings`. If it doesn't (which shouldn't
        # happen for standard argparse actions), simply skip that action.
        try:
            flags.extend(action.option_strings)
        except AttributeError:
            continue

    return ' '.join(flags)

def parser_flags(parser):
    """
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    """
    # Validate parser has the expected attribute
    if not hasattr(parser, "_actions"):
        return ""

    flags = []
    for action in parser._actions:
        # Each action may have an option_strings attr; positional arguments won't
        try:
            for opt in getattr(action, "option_strings", []):
                if isinstance(opt, str) and opt.startswith("-"):
                    flags.append(opt)
        except Exception:
            # Skip any action that doesn't expose option_strings correctly
            continue

    return " ".join(flags)

def parse_arguments(*unparsed_arguments):
    '''
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as a dict mapping from subparser name (or "global") to an argparse.Namespace instance.
    '''
    import argparse
    # Initialize parser without adding any subparsers; subparsers are expected to be defined elsewhere.
    parser = argparse.ArgumentParser(add_help=False)
    # Allow unknown arguments; they will be ignored in the namespace.
    try:
        namespace, _ = parser.parse_known_args(unparsed_arguments)
    except Exception:
        # In case of any parsing error, return an empty namespace.
        namespace = argparse.Namespace()
    return {"global": namespace}

def parse_arguments(*unparsed_arguments):
    """
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as a dict mapping from subparser name (or "global") to an argparse.Namespace instance.
    """
    from argparse import Namespace

    mapping = {}
    current_key = "global"
    current_args = []

    def _store_current():
        """Store the current arguments under the current key."""
        mapping[current_key] = Namespace(args=current_args[:])

    for token in unparsed_arguments:
        # Treat any token that does not start with '-' as a new subparser name,
        # unless it's the special '--' separator.
        if token and not token.startswith("-") and token != "--":
            # Store the previous set of arguments (if any).
            if current_args or current_key != "global":
                _store_current()
            current_key = token
            current_args = []
        else:
            current_args.append(token)

    # Store the last collected arguments.
    if current_args or current_key != "global":
        _store_current()

    # Ensure that global key exists even if no arguments were provided.
    if not mapping.get("global"):
        mapping["global"] = Namespace(args=[])

    return mapping

def parse_subparser_arguments(unparsed_arguments, subparsers):
    '''
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    '''
    # Ensure we have a list to avoid modifying the caller's data
    if not isinstance(unparsed_arguments, (list, tuple)):
        raise TypeError('unparsed_arguments must be a list or tuple of argument strings')
    args_list = list(unparsed_arguments)

    # If no subparsers, return all arguments as remaining
    if not subparsers:
        return {}, list(args_list)

    parsed_results = {}
    # Store unknown argument lists for each subparser
    unknown_lists = []

    for name, parser in subparsers.items():
        # Guard against invalid parser types
        if not hasattr(parser, 'parse_known_args'):
            continue
        try:
            parsed_ns, unknown = parser.parse_known_args(args_list)
            parsed_results[name] = parsed_ns
            unknown_lists.append(unknown)
        except Exception:
            # If parsing fails for this subparser, ignore it
            continue

    # Determine remaining arguments: those not claimed by any subparser
    if unknown_lists:
        # Compute intersection of unknown argument sets to find truly unclaimed
        remaining_set = set(unknown_lists[0])
        for unknown in unknown_lists[1:]:
            remaining_set.intersection_update(unknown)
        remaining = [arg for arg in args_list if arg in remaining_set]
    else:
        # If parsing succeeded for no subparsers (unlikely), all args are remaining
        remaining = list(args_list)

    return parsed_results, remaining

def deep_merge_nodes(nodes):
    '''
    Merge a list of (ScalarNode, value) pairs with deep merging for mapping values.
    '''
    # Helper to check if a node is a mapping.
    def is_mapping(node):
        return hasattr(node, 'tag') and hasattr(node, 'value') and isinstance(node.value, list)

    # Recursive merge of two values.
    def merge_values(a, b):
        if is_mapping(a) and is_mapping(b):
            return merge_mapping_nodes(a, b)
        # For non-mapping values, the last wins.
        return b

    # Merge two MappingNodes (deep merge of their contents).
    def merge_mapping_nodes(a, b):
        entries_a = a.value if hasattr(a, 'value') else []
        entries_b = b.value if hasattr(b, 'value') else []

        merged_entries = {}
        order = []

        # Process entries from a first.
        for key_node, val_node in entries_a:
            key = getattr(key_node, 'value', None)
            if key is None:
                continue
            merged_entries[key] = (key_node, val_node)
            order.append(key)

        # Merge/append entries from b.
        for key_node, val_node in entries_b:
            key = getattr(key_node, 'value', None)
            if key is None:
                continue
            if key in merged_entries:
                existing_val = merged_entries[key][1]
                new_val = merge_values(existing_val, val_node)
                # Keep the original key node from a (first occurrence)
                merged_entries[key] = (merged_entries[key][0], new_val)
            else:
                merged_entries[key] = (key_node, val_node)
                order.append(key)

        # Construct the new MappingNode instance.
        # Use the constructor of the first mapping node if possible.
        try:
            MappingNodeCls = type(a) if is_mapping(a) else type(b)
            new_value = [merged_entries[k] for k in order]
            return MappingNodeCls(tag=a.tag if hasattr(a, 'tag') else b.tag, value=new_value)
        except Exception:
            # Fallback: create a simple object that mimics a MappingNode
            class DummyMapping:
                __slots__ = ('tag', 'value')
            dm = DummyMapping()
            dm.tag = a.tag if hasattr(a, 'tag') else getattr(b, 'tag', None)
            dm.value = [merged_entries[k] for k in order]
            return dm

    # Main merging loop for top-level nodes.
    merged = {}
    order = []

    for key_node, val_node in nodes:
        key = getattr(key_node, 'value', None)
        if key is None:
            continue
        if key in merged:
            existing_val = merged[key][1]
            new_val = merge_values(existing_val, val_node)
            # Keep original key node from the first occurrence
            merged[key] = (merged[key][0], new_val)
        else:
            merged[key] = (key_node, val_node)
            order.append(key)

    # Reconstruct result preserving order.
    return [(merged[k][0], merged[k][1]) for k in order]

def deep_merge_nodes(nodes):
    """
    Deep merge a list of (scalar, node) tuples representing YAML mapping nodes.
    Duplicate scalar keys are merged: if both values are mapping nodes, their
    contents are recursively merged; otherwise the latter value wins.
    """
    def _is_mapping(node):
        return getattr(node, "tag", None) == "tag:yaml.org,2002:map"

    def _merge_mapping_nodes(a, b):
        """Merge two MappingNode instances."""
        # Preserve order: start with entries from `a`, then append new ones from `b`.
        order = []
        merged_map = {}
        for k_node, v_node in getattr(a, "value", []):
            key = getattr(k_node, "value", None)
            merged_map[key] = (k_node, v_node)
            order.append(key)
        for k_node, v_node in getattr(b, "value", []):
            key = getattr(k_node, "value", None)
            if key in merged_map:
                existing_k_node, existing_v_node = merged_map[key]
                if _is_mapping(existing_v_node) and _is_mapping(v_node):
                    # Recursively merge sub-mapping nodes.
                    merged_sub = _merge_mapping_nodes(existing_v_node, v_node)
                    merged_map[key] = (existing_k_node, merged_sub)
                else:
                    # Last value wins.
                    merged_map[key] = (k_node, v_node)
            else:
                merged_map[key] = (k_node, v_node)
                order.append(key)
        # Reconstruct list of tuples in the desired order.
        merged_list = [merged_map[k] for k in order]
        # Create a new MappingNode instance of the same type as `a`.
        MappingNodeType = type(a)
        return MappingNodeType(a.tag if hasattr(a, "tag") else None, merged_list)

    merged = []
    key_index = {}
    for key_node, value_node in nodes:
        key = getattr(key_node, "value", None)
        if key in key_index:
            idx = key_index[key]
            existing_key_node, existing_value_node = merged[idx]
            if _is_mapping(existing_value_node) and _is_mapping(value_node):
                merged_node = _merge_mapping_nodes(existing_value_node, value_node)
                merged[idx] = (existing_key_node, merged_node)
            else:
                merged[idx] = (existing_key_node, value_node)
        else:
            merged.append((key_node, value_node))
            key_index[key] = len(merged) - 1
    return merged

def deep_merge_nodes(nodes):
    """
    Merge a list of (key, value) node tuples, performing a deep merge for duplicate keys.
    Duplicate keys with MappingNode values are merged recursively; other duplicates
    are replaced by the last occurrence.

    Args:
        nodes (list[tuple]): List of tuples where each tuple contains a ScalarNode
            as a key and a Node (MappingNode or others) as a value.

    Returns:
        list[tuple]: The list of nodes after merging, with each key unique.
    """
    if not isinstance(nodes, list):
        raise TypeError("nodes must be a list")
    # Helper to detect MappingNode based on tag
    def is_mapping_node(node):
        return getattr(node, "tag", None) == "tag:yaml.org,2002:map"

    # Recursive merge for MappingNode
    def merge_mapping_nodes(a, b):
        if not is_mapping_node(a) or not is_mapping_node(b):
            return b
        merged_pairs = []
        pair_map = {}
        pair_index = {}
        # initialize with a's pairs
        for key, val in a.value:
            k = (key.tag, key.value)
            pair_map[k] = val
            pair_index[k] = len(merged_pairs)
            merged_pairs.append((key, val))
        # merge with b's pairs
        for key, val in b.value:
            k = (key.tag, key.value)
            if k in pair_map:
                existing_val = pair_map[k]
                if is_mapping_node(existing_val) and is_mapping_node(val):
                    merged_val = merge_mapping_nodes(existing_val, val)
                    pair_map[k] = merged_val
                    merged_pairs[pair_index[k]] = (key, merged_val)
                else:
                    pair_map[k] = val
                    merged_pairs[pair_index[k]] = (key, val)
            else:
                pair_map[k] = val
                pair_index[k] = len(merged_pairs)
                merged_pairs.append((key, val))
        # Create a new MappingNode instance of the same type as 'a'
        return type(a)(tag=a.tag, value=merged_pairs)

    result_nodes = []
    key_map = {}
    key_idx = {}
    for key_node, val_node in nodes:
        if not hasattr(key_node, "value"):
            raise TypeError("Key node must have a 'value' attribute")
        key_id = (getattr(key_node, "tag", None), key_node.value)
        if key_id in key_map:
            existing_val = key_map[key_id]
            if is_mapping_node(existing_val) and is_mapping_node(val_node):
                merged_val = merge_mapping_nodes(existing_val, val_node)
                key_map[key_id] = merged_val
                result_nodes[key_idx[key_id]] = (key_node, merged_val)
            else:
                key_map[key_id] = val_node
                result_nodes[key_idx[key_id]] = (key_node, val_node)
        else:
            key_map[key_id] = val_node
            key_idx[key_id] = len(result_nodes)
            result_nodes.append((key_node, val_node))
    return result_nodes

