def parse_arguments(*arguments):
    """
    Parse command-line arguments, accepting both optional arguments prefixed by '--'
    (with optional '=value' syntax or following value) and positional arguments.
    The parsed arguments are returned as a simple namespace object.
    """
    result = {}
    positional = []
    i = 0
    while i < len(arguments):
        arg = arguments[i]
        if isinstance(arg, str) and arg.startswith('--'):
            key = arg[2:]
            if '=' in key:
                name, value = key.split('=', 1)
                result[name] = value
            else:
                # Check if the next argument is a value (not an option)
                if i + 1 < len(arguments) and not isinstance(arguments[i + 1], str) or \
                   (i + 1 < len(arguments) and not arguments[i + 1].startswith('--')):
                    result[key] = arguments[i + 1]
                    i += 1
                else:
                    result[key] = True
        else:
            positional.append(arg)
        i += 1
    result['args'] = positional

    # Simple Namespace implementation
    class Namespace:
        def __init__(self, **kwargs):
            self.__dict__.update(kwargs)

    return Namespace(**result)

