def bash_completion():
    """
    Return a bash completion script for the borgmatic command.
    Produce this by introspecting borgmatic's command-line argument parsers.
    """
    try:
        import argparse
        import argcomplete
    except Exception:
        return ""

    # Try to import borgmatic's CLI module to create a parser.
    try:
        import borgmatic.cli.main as borgmatic_main
    except Exception:
        borgmatic_main = None

    # Create a basic ArgumentParser with the program name.
    parser = argparse.ArgumentParser(prog="borgmatic", add_help=False)

    # Attempt to configure the parser by calling known helper functions
    # that borgmatic defines for building the command-line interface.
    configured = False
    config_funcs = (
        "configure_parser",
        "add_arguments",
        "build_parser",
        "create_parser",
        "configure_command_line",
    )
    if borgmatic_main:
        for func_name in config_funcs:
            func = getattr(borgmatic_main, func_name, None)
            if callable(func):
                try:
                    # Most configure functions take a parser argument.
                    func(parser)
                    configured = True
                    break
                except Exception:
                    continue

    # If we could not find a suitable function, try to add a minimal
    # --help and --version option to keep the parser usable.
    if not configured:
        try:
            parser.add_argument("--help", "-h", action="store_true")
            parser.add_argument(
                "--version",
                action="version",
                version="%(prog)s 1.0",
            )
        except Exception:
            pass

    # Use argcomplete to generate the completion script.
    try:
        script = argcomplete.get_complete_script("borgmatic", parser=parser)
        return script
    except Exception:
        return ""

def parse_arguments(*unparsed_arguments):
    import argparse
    """
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as a dict mapping from subparser name (or "global") to an argparse.Namespace instance.
    """
    try:
        # Parser for global arguments (none defined explicitly)
        global_parser = argparse.ArgumentParser(add_help=False)
        # Parse known global arguments; everything else is unknown
        global_ns, unknown = global_parser.parse_known_args(unparsed_arguments)

        result = {"global": global_ns}

        if not unknown:
            return result

        # Identify the first argument that is not an option flag (doesn't start with '-')
        subcmd_index = None
        for i, arg in enumerate(unknown):
            if not arg.startswith('-'):
                subcmd_index = i
                break

        # If no subcommand name is found, treat all as unknown global arguments
        if subcmd_index is None:
            return result

        subcmd_name = unknown[subcmd_index]
        subcmd_args = unknown[subcmd_index + 1:]

        # Create a subparser that captures all remaining arguments
        subparser = argparse.ArgumentParser(add_help=False)
        subparser.add_argument('args', nargs=argparse.REMAINDER)

        sub_ns = subparser.parse_args(subcmd_args)
        result[subcmd_name] = sub_ns

        return result
    except Exception:
        # In the event of any parsing issue, return at least the global namespace
        try:
            from argparse import Namespace
            return {"global": Namespace()}
        except Exception:
            return {"global": type('Namespace', (), {})()}

def parse_subparser_arguments(unparsed_arguments, subparsers):
    '''
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    '''
    # Basic type validation
    if not isinstance(unparsed_arguments, (list, tuple)):
        raise TypeError("unparsed_arguments must be a list or tuple of strings")
    if not isinstance(subparsers, dict):
        raise TypeError("subparsers must be a dictionary mapping names to ArgumentParser instances")

    # If no subparsers, everything remains unparsed
    if not subparsers:
        return {}, list(unparsed_arguments)

    parsed_map = {}
    unknown_sets = []

    for name, parser in subparsers.items():
        if not hasattr(parser, 'parse_known_args'):
            raise TypeError(f"Subparser object for '{name}' does not support 'parse_known_args'")
        try:
            namespace, unknown = parser.parse_known_args(unparsed_arguments)
        except Exception as exc:
            raise ValueError(f"Error parsing arguments with subparser '{name}': {exc}") from exc
        parsed_map[name] = namespace
        unknown_sets.append(set(unknown))

    # Determine arguments that were not claimed by *any* subparser
    remaining_set = set.intersection(*unknown_sets) if unknown_sets else set()

    # Preserve original order and duplicates
    remaining = [arg for arg in unparsed_arguments if arg in remaining_set]

    return parsed_map, remaining

def parse_subparser_arguments(unparsed_arguments, subparsers):
    """
    Given a sequence of arguments and a dict from subparser name to
    argparse.ArgumentParser instance, give each requested action's subparser a
    shot at parsing all arguments. This allows common arguments like
    "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a
    parsed namespace of arguments, a list of remaining arguments not claimed
    by any subparser).
    """
    parsed_namespaces = {}
    unknown_sets = {}

    for name, parser in subparsers.items():
        try:
            # parse_known_args never raises on unknown args, but may raise
            # on argument conflicts.  We handle that gracefully.
            namespace, unknown = parser.parse_known_args(list(unparsed_arguments))
        except Exception:
            # If parsing fails, fall back to the defaults and treat the
            # whole argument list as unknown for this parser.
            namespace = parser.parse_args([])
            unknown = list(unparsed_arguments)
        parsed_namespaces[name] = namespace
        unknown_sets[name] = set(unknown)

    # Determine arguments not claimed by any subparser.
    remaining = []
    for arg in unparsed_arguments:
        if all(arg in unknown_sets.get(name, set()) for name in subparsers):
            remaining.append(arg)

    return parsed_namespaces, remaining

def paging(response, max_results):
    """
    Returns WAPI response page by page

    Args:
        response (list): WAPI response.
        max_results (int): Maximum number of objects to be returned in one page.

    Returns:
        Generator object with WAPI response split page by page.
    """
    # Validate input types
    if response is None:
        raise ValueError("response must not be None")
    if not isinstance(response, list):
        raise TypeError(f"response must be a list, got {type(response).__name__}")
    if not isinstance(max_results, int):
        raise TypeError(f"max_results must be an int, got {type(max_results).__name__}")
    if max_results <= 0:
        raise ValueError("max_results must be a positive integer")

    # Generator to yield paged slices of the response list
    def _generator():
        try:
            for start in range(0, len(response), max_results):
                end = start + max_results
                yield response[start:end]
        except Exception as exc:
            # Re-raise any unexpected error with a clearer message
            raise RuntimeError(f"Error while paging response: {exc}") from exc

    return _generator()

