def size_to_bytes(size: str) -> int:
    """
    Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    if not isinstance(size, str):
        raise TypeError("size must be a string")
    s = size.strip()
    if not s:
        raise ValueError("empty size string")
    # Separate numeric part and unit part
    num_part = ''
    unit_part = ''
    for i, ch in enumerate(s):
        if ch.isdigit() or ch == '.':
            num_part += ch
        else:
            unit_part = s[i:].strip()
            break
    if not num_part:
        raise ValueError(f"invalid size value: '{size}'")
    try:
        num_value = float(num_part)
    except Exception as exc:
        raise ValueError(f"cannot parse numeric part '{num_part}': {exc}")
    # Determine multiplier based on unit
    multiplier = 1
    if unit_part:
        unit_char = unit_part[0].upper()
        if unit_char == 'K':
            multiplier = 1000
        elif unit_char == 'M':
            multiplier = 1000 ** 2
        elif unit_char == 'G':
            multiplier = 1000 ** 3
        elif unit_char == 'T':
            multiplier = 1000 ** 4
        elif unit_char == 'P':
            multiplier = 1000 ** 5
        else:
            # Unknown or unsupported unit; raise error
            raise ValueError(f"unsupported size unit '{unit_part}' in '{size}'")
    result = num_value * multiplier
    try:
        return int(round(result))
    except Exception as exc:
        raise ValueError(f"error converting size '{size}' to bytes: {exc}")

