        for key, val in d.items():
            if key in result:
                try:
                    result[key] += val
                except Exception as exc:
                    raise TypeError(
                        f"Cannot sum values for key {key!r}: "
                        f"{result[key]!r} + {val!r}"
                    ) from exc
            else:
                result[key] = val
    return result

