def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""
    # Validate inputs
    if not isinstance(url, str):
        return url
    if not isinstance(url_args, dict):
        raise TypeError("url_args must be a dict")

    import re

    # Find placeholders like {key}
    pattern = re.compile(r'{([^{}]+)}')

    def _replace(match):
        key = match.group(1)
        if key not in url_args:
            raise KeyError(f"Missing value for URL placeholder '{key}'")
        return str(url_args[key])

    return pattern.sub(_replace, url)

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""
    if url is None:
        return ""
    if not isinstance(url, str):
        raise TypeError(f"url must be a str, got {type(url).__name__}")
    if not url_args:
        return url
    try:
        import re
    except ImportError as exc:
        raise RuntimeError("regex module required") from exc
    pattern = re.compile(r'\{(?P<key>[^}]+)\}|:(?P<key_colon>[^\/:#?]+)|<(?P<key_angle>[^>]+)>')
    def _repl(match):
        key = match.group('key') or match.group('key_colon') or match.group('key_angle')
        if key is None:
            return match.group(0)
        if key not in url_args:
            raise KeyError(f"Missing URL argument for key: {key!r}")
        value = url_args[key]
        if value is None:
            return ""
        return str(value)
    return pattern.sub(_repl, url)

