    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    try:
        if parser is None:
            return ''
        # Retrieve actions; some parsers might expose a 'get_actions' method.
        actions = getattr(parser, 'get_actions', lambda: getattr(parser, '_actions', []))()
        flags = []
        for action in actions:
            option_strings = getattr(action, 'option_strings', [])
            if option_strings:
                flags.extend(option_strings)
        return ' '.join(flags)
    except Exception:
        # In case of any unexpected error, return an empty string.
        return ''

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    The implementation collects all option strings defined for actions in the parser.
    It gracefully handles cases where the parser object does not have the expected
    attributes or when no flags are present.
    '''
    try:
        actions = getattr(parser, "_actions", None)
        if actions is None:
            return ''
    except Exception:
        return ''
    flags = []
    for action in actions:
        option_strings = getattr(action, "option_strings", [])
        for opt in option_strings:
            # include only strings that look like options (start with any prefix chars)
            if opt:
                flags.append(opt)
    return ' '.join(flags)

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    # Validate that parser is an ArgumentParser instance
    try:
        from argparse import ArgumentParser
    except Exception:
        raise TypeError("Failed to import argparse.ArgumentParser for validation")

    if not isinstance(parser, ArgumentParser):
        raise TypeError("parser must be an instance of argparse.ArgumentParser")

    # Gather all flags in the order they were added
    flags = []
    for action in getattr(parser, "_actions", []):
        # For options (e.g., -h, --help)
        if getattr(action, "option_strings", []):
            flags.extend(action.option_strings)
        # For positional arguments (no option_strings)
        elif getattr(action, "dest", None):
            flags.append(action.dest)

    # Remove duplicates while preserving order
    seen = set()
    unique_flags = []
    for f in flags:
        if f not in seen:
            seen.add(f)
            unique_flags.append(f)

    return " ".join(unique_flags)

def parser_flags(parser):
    """
    Given an argparse.ArgumentParser instance, return its argument flags
    in a space-separated string.
    """
    try:
        flags = []
        for action in getattr(parser, "_actions", []):
            for flag in getattr(action, "option_strings", []):
                flags.append(flag)
        return " ".join(flags)
    except Exception:
        return ""

def was_processed(processed, path_name, verbose):
    """
    Check if a file or directory has already been processed.

    To prevent recursion, expand the path name to an absolution path
    call this function with a set that will store all the entries and
    the entry to test. If the entry is already in the set, report the issue
    and return ``True``. Otherwise, add the entry to the set and return
    ``False`` to allow the path to be processed.
    """
    # Validate inputs
    if not isinstance(processed, set):
        raise TypeError("processed must be a set")
    if not isinstance(verbose, bool):
        raise TypeError("verbose must be a boolean")
    if path_name is None:
        if verbose:
            print("was_processed called with None as path_name; treating as not processed.")
        return False

    # Expand to absolute path
    try:
        import os
        abs_path = os.path.abspath(path_name)
    except Exception as exc:
        # If we can't resolve the path, fall back to the original input
        if verbose:
            print(f"Warning: could not resolve path '{path_name}': {exc}")
        abs_path = path_name

    # Check if already processed
    if abs_path in processed:
        if verbose:
            print(f"was_processed: '{abs_path}' has already been processed.")
        return True

    # Mark as processed and allow processing
    try:
        processed.add(abs_path)
    except Exception as exc:
        # If the object is not hashable or other issue
        if verbose:
            print(f"Error adding '{abs_path}' to processed set: {exc}")
        raise
    return False

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    # Validate `number`
    if not isinstance(number, int):
        raise TypeError(f"number must be an integer, got {type(number).__name__}")

    # Validate `alphabet`
    if not isinstance(alphabet, (list, tuple)):
        raise TypeError(f"alphabet must be a list or tuple, got {type(alphabet).__name__}")
    if len(alphabet) < 2:
        raise ValueError("alphabet must contain at least two symbols")
    for idx, sym in enumerate(alphabet):
        if not isinstance(sym, str):
            raise TypeError(f"alphabet element at index {idx} is not a string: {sym!r}")

    base = len(alphabet)

    # Handle negative numbers separately
    negative = number < 0
    number = abs(number)

    # Convert to base representation
    if number == 0:
        digits = [alphabet[0]]
    else:
        digits: List[str] = []
        while number:
            number, rem = divmod(number, base)
            digits.append(alphabet[rem])

    # Assemble most significant digit first
    result = ''.join(reversed(digits))

    # Apply optional padding
    if padding is not None:
        if not isinstance(padding, int):
            raise TypeError(f"padding must be an integer or None, got {type(padding).__name__}")
        if padding < 0:
            raise ValueError("padding must be non-negative")
        if len(result) < padding:
            result = alphabet[0] * (padding - len(result)) + result

    # Prepend sign if necessary
    if negative:
        result = '-' + result

    return result

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    # Basic validation
    if not isinstance(alphabet, list):
        raise TypeError("alphabet must be a list of strings")
    if not all(isinstance(ch, str) for ch in alphabet):
        raise TypeError("each element of alphabet must be a string")
    base = len(alphabet)
    if base < 2:
        raise ValueError("alphabet must contain at least two characters to define a base")
    if not isinstance(number, int):
        raise TypeError("number must be an integer")
    if number < 0:
        raise ValueError("negative numbers are not supported")

    if padding is not None:
        if not isinstance(padding, int):
            raise TypeError("padding must be an integer or None")
        if padding < 0:
            raise ValueError("padding cannot be negative")

    # Handle zero explicitly
    if number == 0:
        result = alphabet[0]
    else:
        digits = []
        n = number
        while n > 0:
            n, rem = divmod(n, base)
            digits.append(alphabet[rem])
        # digits list is least-significant-first, reverse to most-significant-first
        result = "".join(reversed(digits))

    # Apply padding if requested
    if padding is not None:
        pad_length = padding - len(result)
        if pad_length > 0:
            result = alphabet[0] * pad_length + result

    return result

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    # Input validation
    if not isinstance(number, int):
        raise TypeError(f"number must be an int, got {type(number).__name__}")
    if not isinstance(alphabet, list) or not all(isinstance(c, str) for c in alphabet):
        raise TypeError("alphabet must be a list of strings")
    base = len(alphabet)
    if base <= 0:
        raise ValueError("alphabet must contain at least one symbol")
    if base == 1:
        raise ValueError("alphabet cannot contain only one symbol (base must be >= 2)")
    if padding is not None:
        if not isinstance(padding, int):
            raise TypeError("padding must be an int or None")
        if padding < 0:
            raise ValueError("padding cannot be negative")

    # Handle sign
    sign = ''
    n = number
    if n < 0:
        sign = '-'
        n = -n

    # Convert number to base representation using the alphabet
    if n == 0:
        digits = [alphabet[0]]
    else:
        digits = []
        while n > 0:
            n, rem = divmod(n, base)
            digits.append(alphabet[rem])
        digits.reverse()

    result = sign + ''.join(digits)

    # Apply padding if necessary
    if padding is not None:
        pad_len = padding - len(result.lstrip('-'))  # exclude sign from padding count
        if pad_len > 0:
            # Use the first symbol of the alphabet for padding
            pad_char = alphabet[0]
            result = sign + (pad_char * pad_len) + result[len(sign):]

    return result

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    # Basic validation
    if not isinstance(number, int):
        raise TypeError("`number` must be an integer")
    if not isinstance(alphabet, list) or len(alphabet) < 2:
        raise ValueError("alphabet must be a list with at least two symbols")
    if any(not isinstance(sym, str) or len(sym) != 1 for sym in alphabet):
        raise ValueError("each alphabet entry must be a single‑character string")
    if padding is not None:
        if not isinstance(padding, int):
            raise TypeError("padding must be an integer")
        if padding < 0:
            raise ValueError("padding must be non‑negative")

    base = len(alphabet)
    neg = number < 0
    n = abs(number)

    # Convert to base
    if n == 0:
        digits = [alphabet[0]]
    else:
        digits = []
        while n:
            n, r = divmod(n, base)
            digits.append(alphabet[r])
        digits.reverse()

    # Apply padding to numeric part only
    if padding is not None and len(digits) < padding:
        digits = [alphabet[0]] * (padding - len(digits)) + digits

    numeric_str = ''.join(digits)
    return '-' + numeric_str if neg else numeric_str

def _replace_register(flow_params, register_number, register_value):
    """Replace value from flows to given register number

    'register_value' key in dictionary will be replaced by register number
    given by 'register_number'

    :param flow_params: Dictionary containing defined flows
    :param register_number: The number of register where value will be stored
    :param register_value: Key to be replaced by register number

    """
    # Validate inputs
    if not isinstance(flow_params, dict):
        raise TypeError("flow_params must be a dictionary")
    if not isinstance(register_value, str):
        raise TypeError("register_value must be a string key name")

    # Helper to replace in a single dict
    def replace_in_dict(d):
        if not isinstance(d, dict):
            return
        if register_value in d:
            d[register_value] = register_number

    # Iterate over top-level items
    for key, value in flow_params.items():
        if isinstance(value, dict):
            replace_in_dict(value)
        elif isinstance(value, list):
            # If the value is a list, iterate over elements that are dicts
            for item in value:
                replace_in_dict(item)

    return flow_params

def _replace_register(flow_params, register_number, register_value):
    """Replace value from flows to given register number

    'register_value' key in dictionary will be replaced by register number
    given by 'register_number'

    :param flow_params: Dictionary containing defined flows
    :param register_number: The number of register where value will be stored
    :param register_value: Key to be replaced by register number

    :returns: A new dictionary with the specified key replaced
    :raises ValueError: If flow_params is not a dictionary or is None
    """
    if flow_params is None or not isinstance(flow_params, dict):
        raise ValueError("flow_params must be a non‑empty dictionary")

    def _replace_in_structure(struct):
        if isinstance(struct, dict):
            new_dict = {}
            for k, v in struct.items():
                new_key = register_number if k == register_value else k
                new_dict[new_key] = _replace_in_structure(v)
            return new_dict
        elif isinstance(struct, list):
            return [_replace_in_structure(item) for item in struct]
        else:
            # For other types (int, str, etc.) leave unchanged
            return struct

    try:
        return _replace_in_structure(flow_params)
    except Exception:
        # In case of any unexpected error, return the original unchanged
        return flow_params[:] if isinstance(flow_params, list) else flow_params.copy()

