def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    if not isinstance(cls, type):
        raise TypeError(f"Expected a class object, got {type(cls).__name__}")
    result = set()

    def _collect(c):
        try:
            for sub in c.__subclasses__():
                if sub not in result:
                    result.add(sub)
                    _collect(sub)
        except Exception as exc:
            # If a subclass cannot be inspected, skip it
            raise RuntimeError(f"Error retrieving subclasses of {c.__name__}") from exc

    _collect(cls)
    return result

def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    if not isinstance(cls, type):
        raise TypeError("subclasses expects a class type as argument")
    seen = set()
    def _rec(current):
        for sub in current.__subclasses__():
            if sub not in seen:
                seen.add(sub)
                yield sub
                yield from _rec(sub)
    return set(_rec(cls))

def subclasses(cls):
    """Return all subclasses of a class, recursively."""
    if not isinstance(cls, type):
        raise TypeError(f"Expected a class, got {cls!r}")

    seen = set()
    stack = [cls]
    while stack:
        current = stack.pop()
        try:
            subs = current.__subclasses__()
        except Exception:
            # Skip types that fail to report subclasses
            continue
        for sub in subs:
            if sub not in seen:
                seen.add(sub)
                stack.append(sub)
    return seen

def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    if not isinstance(cls, type):
        raise TypeError("subclasses() expects a class as argument")
    result = set()
    direct_subs = cls.__subclasses__()
    result.update(direct_subs)
    for sub in direct_subs:
        result.update(subclasses(sub))
    return result)

def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    # Validate input: only types have subclasses
    if not isinstance(cls, type):
        return set()
    result = set()
    try:
        # Direct subclasses
        direct = cls.__subclasses__()
    except Exception:
        # In case of any unexpected errors, return what we have (empty)
        return result
    for subclass in direct:
        result.add(subclass)
        # Recursively gather subclasses of this subclass
        result.update(subclasses(subclass))
    return result

def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    # Validate input types
    if not isinstance(string, str):
        raise TypeError(f"'string' must be of type str, got {type(string).__name__}")
    if not isinstance(alphabet, list):
        raise TypeError(f"'alphabet' must be a list, got {type(alphabet).__name__}")

    # Ensure alphabet contains unique string symbols
    if len(alphabet) == 0:
        raise ValueError("Alphabet must contain at least one symbol")
    if not all(isinstance(sym, str) for sym in alphabet):
        raise TypeError("All symbols in alphabet must be strings")
    if len(set(alphabet)) != len(alphabet):
        raise ValueError("Alphabet symbols must be unique")

    base = len(alphabet)
    symbol_to_value = {sym: i for i, sym in enumerate(alphabet)}

    # Edge case: empty string returns 0
    if string == "":
        return 0

    # Special handling for base 1 (unary)
    if base == 1:
        expected_symbol = alphabet[0]
        if any(ch != expected_symbol for ch in string):
            raise ValueError(f"String contains symbols not in the unary alphabet {alphabet}")
        return len(string)

    # General case for base >= 2
    value = 0
    for ch in string:
        if ch not in symbol_to_value:
            raise ValueError(f"Symbol '{ch}' not found in alphabet {alphabet}")
        digit = symbol_to_value[ch]
        value = value * base + digit

    return value

def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    base = len(alphabet)
    if base == 0:
        raise ValueError("Alphabet must contain at least one symbol.")
    if not string:
        # Empty input string corresponds to 0
        return 0

    # Build a mapping from symbol to its numerical value
    symbol_to_value = {symbol: idx for idx, symbol in enumerate(alphabet)}

    value = 0
    for char in string:
        if char not in symbol_to_value:
            raise ValueError(f"Character '{char}' not found in alphabet.")
        digit = symbol_to_value[char]
        value = value * base + digit
    return value

def string_to_int(string: str, alphabet: list) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    # Basic validation
    if not isinstance(alphabet, (list, tuple)):
        raise TypeError("alphabet must be a list or tuple of strings")
    if len(alphabet) == 0:
        raise ValueError("alphabet cannot be empty")

    # Build mapping from symbol to its numeric value
    mapping = {}
    for idx, symbol in enumerate(alphabet):
        if not isinstance(symbol, str):
            raise TypeError("alphabet elements must be strings")
        if len(symbol) != 1:
            raise ValueError(f"alphabet element '{symbol}' must be a single character")
        if symbol in mapping:
            raise ValueError(f"duplicate symbol '{symbol}' in alphabet")
        mapping[symbol] = idx

    base = len(alphabet)
    result = 0
    for ch in string:
        if ch not in mapping:
            raise ValueError(f"character '{ch}' not found in alphabet")
        result = result * base + mapping[ch]
    return result

