def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    if not alphabet:
        raise ValueError("Alphabet cannot be empty.")
    base = len(alphabet)

    # Build a mapping from each character to its numeric value.
    try:
        char_to_value = {ch: idx for idx, ch in enumerate(alphabet)}
    except TypeError as exc:
        raise ValueError("Alphabet must be iterable and contain hashable elements.") from exc

    if not string:
        raise ValueError("Input string cannot be empty.")

    # Handle an optional leading '-' for negative numbers.
    negative = False
    if string[0] == '-':
        negative = True
        string = string[1:]
        if not string:
            raise ValueError("String '-': no digits present.")

    result = 0
    for position, ch in enumerate(string):
        if ch not in char_to_value:
            raise ValueError(f"Character '{ch}' at position {position} not found in alphabet.")
        result = result * base + char_to_value[ch]

    return -result if negative else result

def os_is_mac():
    """
    Checks if the os is macOS

    :return: True if macOS
    :rtype: bool
    """
    try:
        # On Unix-like systems, os.uname() is available
        return os.uname().sysname == 'Darwin'
    except AttributeError:
        # Fall back to platform module for cross-platform support
        try:
            import platform
            return platform.system() == 'Darwin'
        except Exception:
            # Any unexpected error, treat as non-Mac
            return False
    except Exception:
        # Any unexpected error, treat as non-Mac
        return False

def os_is_mac():
    """
    Checks if the os is macOS

    :return: True is macOS
    :rtype: bool
    """
    try:
        import sys
        platform_str = sys.platform
        # sys.platform returns 'darwin' on macOS; also can startwith 'mac' for older variants
        return platform_str == 'darwin' or platform_str.startswith('mac')
    except Exception:
        return False

