def regex_dict(item):
    """
    Convert *.cpp keys to regex keys

    Given a dict where the keys are all filenames with wildcards, convert only
    the keys into equivalent regexes and leave the values intact.

    Example:

    rules = {
        '*.cpp':
            {'a': 'arf', 'b': 'bark', 'c': 'coo'},
        '*.h':
            {'h': 'help'}
    }
    regex_keys = regex_dict(rules)

    Args:
        item: dict to convert
    Returns:
        dict with keys converted to regexes
    """
    # Ensure the input is a dictionary
    if not isinstance(item, dict):
        raise TypeError(f"Expected a dict, got {type(item).__name__}")

    # Helper to convert a wildcard pattern to a regex pattern
    def _wildcard_to_regex(pattern: str) -> str:
        # List of regex metacharacters that need escaping
        meta_chars = {'.', '(', ')', '+', '|', '^', '$', '@', '%', '&', ',', '-', 
                      '[', ']', '{', '}', '?', '/','\\'}
        # We'll construct the regex by iterating over each character
        regex_parts = []
        for ch in pattern:
            if ch == '*':
                regex_parts.append('.*')
            elif ch == '?':
                regex_parts.append('.')
            elif ch in meta_chars:
                regex_parts.append('\\' + ch)
            else:
                regex_parts.append(ch)
        return ''.join(regex_parts)

    # Build a new dictionary with transformed keys
    transformed = {}
    for key, value in item.items():
        if not isinstance(key, str):
            # If key is not a str, skip conversion and keep as is
            new_key = key
        else:
            new_key = _wildcard_to_regex(key)
