import sys, shlex

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    # Validate and prepare input
    if not isinstance(s, (str, bytes)):
        raise TypeError("s must be a string or bytes")
    if isinstance(s, bytes):
        try:
            s = s.decode()
        except Exception as exc:
            raise ValueError("bytes input could not be decoded as UTF-8") from exc

    # Resolve platform choice
    if platform == 'this':
        platform = 0 if sys.platform.lower().startswith('win') else 1
    elif platform not in (0, 1):
        raise ValueError("platform must be 1 (POSIX), 0 (Windows/CMD), or 'this'")

    # Windows style command line parsing
    def _windows_split(cmd):
        args = []
        i = 0
        n = len(cmd)
        while i < n:
            # Skip leading whitespace
            while i < n and cmd[i].isspace():
                i += 1
            if i >= n:
                break

            arg = []
            if cmd[i] == '"':
                i += 1
                backslashes = 0
                while i < n:
                    c = cmd[i]
                    if c == '\\':
                        backslashes += 1
                        i += 1
                        continue
                    if c == '"':
                        # Each pair of backslashes converts to one backslash
                        arg.append('\\' * (backslashes // 2))
                        if backslashes % 2 == 0:
                            # Ending quote
                            i += 1
                            break
                        else:
                            # Escaped quote
                            arg.append('"')
                            i += 1
                            backslashes = 0
                            continue
                    # Regular character
                    arg.append('\\' * backslashes)
                    backslashes = 0
                    arg.append(c)
                    i += 1
                # If the string ends without a closing quote, all remaining backslashes
                # are added literally
                arg.append('\\' * backslashes)
            else:
                while i < n and not cmd[i].isspace():
                    arg.append(cmd[i])
                    i += 1

            args.append(''.join(arg))
        return args

    # POSIX style command line parsing using shlex
    if platform == 1:
        try:
            return shlex.split(s, posix=True)
        except ValueError as exc:
            raise ValueError(f"POSIX split failed: {exc}") from exc
    # Windows style
    return _windows_split(s)

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    if not isinstance(s, str):
        raise TypeError("s must be a string")
    if s == '':
        return []

    if platform == 'this':
        import sys
        platform = 0 if sys.platform.startswith('win') else 1

    if platform == 1:  # POSIX
        import shlex
        try:
            return shlex.split(s, posix=True)
        except ValueError as e:
            raise ValueError(f"Unable to split string: {e}") from e

    if platform == 0:  # Windows
        def win_split(cmd):
            args = []
            arg = []
            in_quotes = False
            i = 0
            l = len(cmd)
            while i < l:
                # Skip whitespace outside quotes
                if cmd[i].isspace() and not in_quotes:
                    if arg:
                        args.append(''.join(arg))
                        arg = []
                    i += 1
                    continue

                # Count consecutive backslashes
                backslashes = 0
                while i < l and cmd[i] == '\\':
                    backslashes += 1
                    i += 1

                # Handle quotes
                if i < l and cmd[i] == '"':
                    if backslashes % 2 == 0:
                        # backslashes before an unescaped quote
                        arg.extend(['\\'] * (backslashes // 2))
                        in_quotes = not in_quotes  # toggle quoting
                        i += 1  # skip quote
                    else:
                        # odd number of backslashes -> escaped quote
                        arg.extend(['\\'] * (backslashes // 2))
                        arg.append('"')
                        i += 1
                else:
                    # No quote follows, backslashes are literal
                    arg.extend(['\\'] * backslashes)
                    if i < l:
                        arg.append(cmd[i])
                        i += 1

            if arg:
                args.append(''.join(arg))
            return args

        return win_split(s)

    raise ValueError(f"Unsupported platform specifier: {platform}")

def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    import os
    from pathlib import Path
    import shutil

    # Resolve paths
    archive = Path(archive_path)
    if not archive.is_file():
        raise FileNotFoundError(f"Archive file '{archive_path}' does not exist or is not a file.")

    base_dir = Path(tmp_path)
    try:
        base_dir.mkdir(parents=True, exist_ok=True)
    except Exception as exc:
        raise OSError(f"Could not create temporary directory '{tmp_path}': {exc}") from exc

    # Determine extraction target directory
    if filename:
        target_dir = base_dir / filename
    else:
        # Use stem (basename without extension) as directory name
        target_dir = base_dir / archive.stem

    try:
        target_dir.mkdir(parents=True, exist_ok=True)
    except Exception as exc:
        raise OSError(f"Could not create extraction directory '{target_dir}': {exc}") from exc

    # Unpack the archive
    try:
        shutil.unpack_archive(str(archive), str(target_dir))
    except shutil.ReadError as exc:
        raise RuntimeError(f"Failed to unpack archive '{archive_path}': {exc}") from exc
    except Exception as exc:
        raise RuntimeError(f"Unexpected error unpacking archive '{archive_path}': {exc}") from exc

    # Return file URL (absolute path)
    return f"file://{target_dir.resolve()}"

def parse_frequency(frequency):
    """
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    """
    # Handle trivial cases
    if frequency is None:
        return None
    if not isinstance(frequency, str):
        raise ValueError(f"Frequency must be a string, not {type(frequency).__name__}")
    freq = frequency.strip().lower()
    if freq == "" or freq == "always":
        return None

    # Split into numeric part and unit part
    tokens = freq.split()
    if len(tokens) != 2:
        raise ValueError(f"Invalid frequency format: {frequency!r}")
    number_str, unit = tokens

    # Convert number to int (allow floats that are whole numbers)
    try:
        if '.' in number_str:
            # Only allow whole numbers represented with a decimal point
            if float(number_str).is_integer():
                number = int(float(number_str))
            else:
                raise ValueError
        else:
            number = int(number_str)
    except ValueError:
        raise ValueError(f"Invalid numeric value in frequency: {number_str!r}")

    # Map units to timedelta arguments
    if unit in ("day", "days"):
        return datetime.timedelta(days=number)
    if unit in ("hour", "hours"):
        return datetime.timedelta(hours=number)
    if unit in ("minute", "minutes"):
        return datetime.timedelta(minutes=number)
    if unit in ("second", "seconds"):
        return datetime.timedelta(seconds=number)
    if unit in ("week", "weeks"):
        return datetime.timedelta(weeks=number)
    if unit in ("month", "months"):
        # Approximate a month as 30 days
        return datetime.timedelta(days=number * 30)

    raise ValueError(f"Unrecognized unit in frequency: {unit!r}")

def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None:
        return None
    freq_str = str(frequency).strip().lower()
    if freq_str == "always":
        return None
    # simple regex to capture number and unit
    import re
    match = re.fullmatch(r'\s*(\d+(\.\d+)?)\s*([a-z]+)\s*', freq_str)
    if not match:
        raise ValueError(f"Cannot parse frequency: '{frequency}'")
    number_str, _, unit = match.groups()
    try:
        value = float(number_str)
    except ValueError:
        raise ValueError(f"Invalid number in frequency: '{frequency}'")
    # Mapping of units to timedelta arguments
    unit_map = {
        'second': 'seconds', 'seconds': 'seconds',
        'minute': 'minutes', 'minutes': 'minutes',
        'hour': 'hours', 'hours': 'hours',
        'day': 'days', 'days': 'days',
        'week': 'weeks', 'weeks': 'weeks'
    }
    if unit not in unit_map:
        raise ValueError(f"Unsupported time unit in frequency: '{unit}'")
    # Weeks must be an integer
    if unit_map[unit] == 'weeks' and not value.is_integer():
        raise ValueError("Weeks must be an integer value")
    kwargs = {unit_map[unit]: int(value) if unit_map[unit] == 'weeks' else value}
    return datetime.timedelta(**kwargs)

