                if ip_addr == '::1':
                    return True
                # Full representation of ::1
                if ip_addr == '0:0:0:0:0:0:0:1':
                    return True
                # IPv6-mapped IPv4 loopback
                if ip_addr.startswith('::ffff:127.') or ip_addr.startswith('::ffff:127.'):
                    return True
        # None matched loopback
        return False
    except Exception:
        # Could not resolve or other error; consider not local
        return False

def is_local(host):
