        except OSError as exc:
            raise OSError(f"Failed to set permissions on '{config_filename}': {exc}") from exc
    except Exception as exc:
        # Cleanup partially written file to avoid leaving corrupted output
        try:
            if os.path.exists(config_filename):
                os.remove(config_filename)
        except Exception:
            pass
        raise OSError(f"Failed to write configuration to '{config_filename}': {exc}") from exc
    return None

def write_configuration(config_filename, rendered_config, mode=0o600, overwrite=False):
    '''Given a target config filename and rendered config YAML, write it out to file. Create any
    containing directories as needed. But if the file already exists and overwrite is False,
    abort before writing anything.'''
    # Validate inputs
    if not isinstance(config_filename, str) or not config_filename:
        raise ValueError("config_filename must be a non-empty string")
    if not isinstance(rendered_config, str):
        raise TypeError("rendered_config must be a string")
    if not isinstance(mode, int):
        raise TypeError("mode must be an integer")
    if mode < 0 or mode > 0o777:
        raise ValueError("mode must be in the range 0 to 0o777")
    if not isinstance(overwrite, bool):
        raise TypeError("overwrite must be a boolean")

    # Resolve absolute path and ensure directory exists
    path = os.path.abspath(config_filename)
    dir_name = os.path.dirname(path)
    if dir_name:
        os.makedirs(dir_name, exist_ok=True)

    # Check for existing file when overwrite is not allowed
    if os.path.exists(path) and not overwrite:
        raise FileExistsError(f"File {path} already exists and overwrite is False")

    # Write the rendered configuration to the file
    try:
        with open(path, "w", encoding="utf-8") as f:
            f.write(rendered_config)
        os.chmod(path, mode)
    except OSError as exc:
        # Propagate the I/O error
        raise exc

    # Return None explicitly for clarity
    return None

def _resolve_string(matcher):
    """
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    """
    # Ensure matcher is a sequence with at least one element
    try:
        iterator = iter(matcher)
    except TypeError:
        raise TypeError("matcher must be a sequence containing at least the variable name")
    # Extract the name
    try:
        name = next(iterator)
    except StopIteration:
        raise ValueError("matcher must contain at least the variable name")
    # Default value if specified
    default_provided = False
    default = None
    try:
        default = next(iterator)
        default_provided = True
    except StopIteration:
        pass
    # Retrieve the environment variable
    value = os.getenv(name)
    if value is None:
        if default_provided:
            return default
        else:
            raise EnvironmentError(f"Environment variable '{name}' is not defined and no default was provided")
    return value

def _resolve_string(matcher):
    """
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, a KeyError is raised.
    The matcher can be:
      - a string "VAR" or "VAR:default"
      - a tuple or list (name, default)
      - a dict with keys 'name' and optional 'default'
    """
    # Parse matcher
    if isinstance(matcher, dict):
        name = matcher.get('name')
        if name is None:
            raise ValueError("Dictionary matcher must contain a 'name' key")
        default = matcher.get('default')
    elif isinstance(matcher, (tuple, list)) and len(matcher) == 2:
        name, default = matcher
    elif isinstance(matcher, str):
        if ':' in matcher:
            name, default = matcher.split(':', 1)
        else:
            name, default = matcher, None
    else:
        raise TypeError("matcher must be a string, tuple/list of length 2, or dict")

    if not isinstance(name, str) or not name:
        raise ValueError("Environment variable name must be a non-empty string")

    val = os.getenv(name)
    if val is None:
        if default is not None:
            # Default may be an empty string but explicitly provided; treat as a valid default
            return default
        raise KeyError(f"Environment variable '{name}' not found and no default provided")
    return val

def _parse_image_ref(image_href: str) -> Tuple[str, str, bool]:
    """Parse an image href into composite parts.

    :param image_href: href of an image
    :returns: a tuple of the form (image_id, netloc, use_ssl)
    :raises ValueError: if the href is not a valid HTTP/HTTPS URI or missing components
    """
    try:
        parsed = urllib.parse.urlparse(image_href)
    except Exception as exc:
        raise ValueError(f"Invalid image href: {image_href}") from exc

    if not parsed.scheme or not parsed.netloc:
        raise ValueError(f"Image href must contain a scheme and netloc: {image_href}")

    if parsed.scheme.lower() not in ("http", "https"):
        raise ValueError(f"Unsupported scheme in image href: {parsed.scheme}")

    image_id = parsed.path.lstrip("/")
    if not image_id:
        raise ValueError(f"Image href must contain a path component (image id): {image_href}")

    use_ssl = parsed.scheme.lower() == "https"
    return image_id, parsed.netloc, use_ssl

def get_pattern(pattern, strip=True):
    """
    This method converts the given string to regex pattern
    """
    if not isinstance(pattern, str):
        raise TypeError("pattern must be a string")
    if strip:
        pattern = pattern.strip()
    return re.escape(pattern)

def get_pattern(pattern, strip=True):
    """
    This method converts the given string to regex pattern
    """
    if pattern is None:
        raise ValueError("pattern must not be None")
    if not isinstance(pattern, str):
        pattern = str(pattern)
    if strip:
        pattern = pattern.strip()
    try:
        # Escape all regex special characters and compile the pattern
        return re.compile(re.escape(pattern))
    except re.error as exc:
        raise ValueError(f"Invalid regex pattern generated from input: {exc}") from exc

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import sys

    # Resolve the command string
    if isinstance(commands, (list, tuple)):
        if not commands:
            raise ValueError("commands list cannot be empty")
        # Use the first command; ignore any additional commands
        command = commands[0]
        if len(commands) > 1:
            # Emit a warning if more than one command is supplied
            if verbose:
                print(f"Warning: multiple commands supplied; only the first '{command}' will be executed.", file=sys.stderr)
    elif isinstance(commands, str):
        command = commands
    else:
        raise TypeError("commands must be a string or an iterable of strings")

    # Resolve the arguments
    if args is None:
        args_list = []
    elif isinstance(args, (list, tuple)):
        args_list = list(args)
    elif isinstance(args, str):
        # Split on whitespace while respecting quoted parts
        import shlex
        args_list = shlex.split(args)
    else:
        raise TypeError("args must be a string, list, tuple, or None")

    # Build the full command
    full_cmd = [command] + args_list

    if verbose:
        print(f"Executing: {' '.join(full_cmd)!r}", file=sys.stderr)

    try:
        result = subprocess.run(
            full_cmd,
            cwd=cwd,
            env=env,
            capture_output=True,
            text=True,
            shell=False,
            check=False
        )
    except FileNotFoundError as exc:
        raise RuntimeError(f"Command not found: {command!r}") from exc
    except OSError as exc:
        raise RuntimeError(f"Error executing command {command!r}: {exc}") from exc

    # Handle errors
    if result.returncode != 0:
        raise subprocess.CalledProcessError(
            returncode=result.returncode,
            cmd=full_cmd,
            output=result.stdout,
            stderr=result.stderr
        )

    # Optionally suppress stderr output
    if not hide_stderr and result.stderr:
        print(result.stderr, file=sys.stderr)

    return result.stdout

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Local imports to avoid polluting the module namespace
    import subprocess
    import shlex
    import sys

    # Validate input types
    if not isinstance(commands, (str, list, tuple)):
        raise TypeError("commands must be a string or a list/tuple of strings")
    if not isinstance(args, (list, tuple)):
        raise TypeError("args must be a list or tuple of strings")
    if env is not None and not isinstance(env, dict):
        raise TypeError("env must be a dictionary or None")

    # Build the command list
    if isinstance(commands, str):
        try:
            cmd = shlex.split(commands)
        except Exception as e:
            raise ValueError("Failed to parse command string") from e
    else:
        cmd = [str(c) for c in commands]

    # Ensure args are strings
    cmd.extend([str(a) for a in args])

    # Verbose output
    if verbose:
        print(f"Running command: {' '.join(cmd)}", file=sys.stdout)

    # Execute the command
    try:
        stderr_mode = subprocess.DEVNULL if hide_stderr else subprocess.PIPE
        result = subprocess.run(
            cmd,
            cwd=cwd,
            env=env,
            stdout=subprocess.PIPE,
            stderr=stderr_mode,
            text=True,
            check=False,
        )
    except FileNotFoundError as e:
        raise RuntimeError(f"Executable not found: {cmd[0]}") from e
    except Exception as e:
        raise RuntimeError(f"Error running command: {' '.join(cmd)}") from e

    # Print output if verbose
    if verbose:
        if result.stdout:
            print(result.stdout, end='')
        if not hide_stderr and result.stderr:
            print(result.stderr, file=sys.stderr, end='')

    return result

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess, shlex, os
    # Validate commands
    if not commands:
        raise ValueError("`commands` must not be empty")
    # Build command list
    if isinstance(commands, str):
        cmd_list = [commands]
    else:
        try:
            cmd_list = list(commands)
        except Exception as exc:
            raise ValueError("`commands` must be a string or iterable of strings") from exc
    # Process args
    if args:
        if isinstance(args, str):
            arg_list = shlex.split(args)
        else:
            try:
                arg_list = list(args)
            except Exception as exc:
                raise ValueError("`args` must be a string or iterable of strings") from exc
    else:
        arg_list = []
    full_cmd = cmd_list + arg_list
    if verbose:
        # Print the command safely quoted
        quoted = ' '.join(shlex.quote(part) for part in full_cmd)
        print(f"Running command: {quoted}")
    # Determine stdout/stderr handling
    stdout_pipe = subprocess.PIPE
    stderr_pipe = subprocess.DEVNULL if hide_stderr else subprocess.PIPE
    try:
        result = subprocess.run(
            full_cmd,
            cwd=cwd,
            env=env if env is not None else os.environ,
            stdout=stdout_pipe,
            stderr=stderr_pipe,
            text=True,
            check=False
        )
        return result
    except FileNotFoundError as e:
        raise RuntimeError(f"Command not found: {e.filename}") from e
    except subprocess.SubprocessError as e:
        raise RuntimeError(f"Error running command: {e}") from e

