def find_roots(
    graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None
) -> Set["Node"]:
    """
    Find the roots in some sort of transitive hierarchy.

    find_roots(graph, rdflib.RDFS.subClassOf)
    will return a set of all roots of the sub-class hierarchy

    Assumes triple of the form (child, prop, parent), i.e. the direction of
    RDFS.subClassOf or SKOS.broader
    """
    # Basic sanity checks
    if graph is None or prop is None:
        return set()

    try:
        # If a set of starting nodes is provided, trace their ancestors.
        if roots:
            # Breadth‑first traversal to collect all ancestors of the supplied roots.
            ancestors: Set["Node"] = set()
            stack = list(roots)
            while stack:
                node = stack.pop()
                if node in ancestors:
                    continue
                ancestors.add(node)
                # For each parent of the current node, add to stack if not seen.
                for parent in graph.objects(node, prop):
                    if parent not in ancestors:
                        stack.append(parent)

            # Roots are those ancestors that do not have any parent via the property.
            root_set: Set["Node"] = set()
            for node in ancestors:
                # If there is no outward edge via the property, node is a root.
                if len(list(graph.objects(node, prop))) == 0:
                    root_set.add(node)
            return root_set

        # No explicit seeds: compute all nodes that appear as objects but never as subjects.
        subjects = set(graph.subjects(prop, None))
        objects = set(graph.objects(None, prop))
        return objects - subjects

    except Exception:
        # In case of any unexpected graph operation issue, return an empty set.
        return set()

def find_roots(
    graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None
) -> Set["Node"]:
    """
    Find the roots in some sort of transitive hierarchy.

    find_roots(graph, rdflib.RDFS.subClassOf)
    will return a set of all roots of the sub-class hierarchy

    Assumes triple of the form (child, prop, parent), i.e. the direction of
    RDFS.subClassOf or SKOS.broader
    """
    # Basic validation of inputs
    try:
        # Ensure the graph can produce triples
        _ = graph.triples((None, None, None))
    except Exception as exc:
        raise TypeError(
            "Expected a graph-like object supporting the triples() method."
        ) from exc

    # If no roots were supplied, collect all subjects that have the given
    # property. These are potential child nodes in the hierarchy.
    if roots is None:
        try:
            potential_roots = {s for s, p, o in graph.triples((None, prop, None))}
        except Exception as exc:
            raise ValueError(
                "Unable to iterate over triples with property "
                f"{prop!r}; may not be a valid property in the graph."
            ) from exc
    else:
        # Ensure roots is a set for efficient look‑ups and mutation
        try:
            potential_roots = set(roots)
        except Exception as exc:
            raise TypeError("The 'roots' argument must be an iterable of nodes.") from exc

    # Filter out any node that appears as the object (i.e. has a parent)
    # Children without parents are considered roots.
    roots_set: Set["Node"] = set()
    for node in potential_roots:
        try:
            has_parent = any(graph.triples((None, prop, node)))
        except Exception:
            # If querying triples fails for a node, treat it as having no parent.
            # This is a fall‑back to avoid the function crashing.
            has_parent = False
        if not has_parent:
            roots_set.add(node)

    return roots_set

def find_roots(
    graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None
) -> Set["Node"]:
    """
    Find the roots in some sort of transitive hierarchy.

    find_roots(graph, rdflib.RDFS.subClassOf)
    will return a set of all roots of the sub-class hierarchy

    Assumes triple of the form (child, prop, parent), i.e. the direction of
    RDFS.subClassOf or SKOS.broader
    """
    # Validate inputs
    if graph is None:
        raise ValueError("graph argument cannot be None")
    if not hasattr(graph, "triples"):
        raise TypeError("graph must be an rdflib Graph-like object with a triples method")
    if prop is None:
        raise ValueError("prop argument cannot be None")

    # If a custom root set was provided, copy it to avoid side effects
    if roots is None:
        roots_set: Set["Node"] = set()
    else:
        try:
            roots_set = set(roots)
        except TypeError:
            raise TypeError("roots must be a set of nodes or None")

    # Collect subjects (children) and objects (parents) of triples that use the
    # given property, ignoring any protection against duplicates.
    children: Set["Node"] = set()
    parents: Set["Node"] = set()
    try:
        for s, p, o in graph.triples((None, prop, None)):
            children.add(s)
            parents.add(o)
    except Exception as exc:
        raise RuntimeError(f"Failed to iterate triples for property {prop}: {exc}") from exc

    # Roots are parents that never appear as children.
    possible_roots = parents - children
    roots_set.update(possible_roots)

    return roots_set

def _dump_string(obj, dumper=None):
    """Dump to a py2-unicode or py3-string"""
    try:
        if dumper is None:
            s = yaml.safe_dump(obj, allow_unicode=True)
        else:
            s = yaml.dump(obj, Dumper=dumper, allow_unicode=True)
        import sys
        if sys.version_info[0] == 2:
            # In Python 2, safe_dump returns a byte string; ensure we return unicode
            if isinstance(s, str):
                s = s.decode('utf-8')
        return s
    except Exception as exc:
        raise

def _dump_string(obj, dumper=None):
    """Dump to a py2-unicode or py3-string"""
    try:
        if dumper is not None:
            yaml_str = yaml.safe_dump(obj, Dumper=dumper)
        else:
            yaml_str = yaml.safe_dump(obj)
    except yaml.YAMLError as exc:
        raise Exception(f"Error dumping YAML: {exc}") from exc
    try:
        return yaml_str.decode("utf-8")
    except AttributeError:
        return yaml_str

def make_array(shape, dtype=np.dtype("float32")):
    """
    Function to create an array with shape and dtype.

    Parameters
    ----------
    shape : tuple or int or sequence
        shape of the array to create
    dtype : `numpy.dtype` or convertible to one
        data-type of the array to create

    Returns
    -------
    numpy.ndarray
        Array with the requested shape and dtype.
    """
    # Validate and normalize shape
    try:
        if isinstance(shape, int):
            shape_tuple = (int(shape),)
        else:
            shape_tuple = tuple(int(s) for s in shape)
        if any(dim < 0 for dim in shape_tuple):
            raise ValueError("Shape dimensions must be non-negative")
    except Exception as exc:
        raise ValueError(f"Invalid shape argument: {shape!r}") from exc

    # Validate dtype
    try:
        dtype_obj = np.dtype(dtype)
    except Exception as exc:
        raise TypeError(f"Invalid dtype argument: {dtype!r}") from exc

    # Create the array
    try:
        return np.empty(shape_tuple, dtype=dtype_obj)
    except Exception as exc:
        raise RuntimeError(f"Failed to create array of shape {shape_tuple} and dtype {dtype_obj}") from exc

def gaussian(x):
    """
    Gaussian centered around 0.2 with a sigma of 0.1.
    Returns the value of the Gaussian function at x.
    Accepts scalar or array-like numeric inputs.
    Raises ValueError for non-numeric inputs or calculation errors.
    """
    try:
        arr = np.asarray(x, dtype=float)
    except Exception as e:
        raise ValueError("Input must be numeric or convertible to numeric") from e
    mu = 0.2
    sigma = 0.1
    try:
        return np.exp(-((arr - mu) ** 2) / (2 * sigma ** 2))
    except Exception as e:
        raise ValueError(f"Error computing Gaussian: {e}") from e

def gaussian(x):
    """
    Gaussian centered around 0.2 with a sigma of 0.1.
    """
    try:
        mu = 0.2
        sigma = 0.1
        arr = np.asarray(x)
        return np.exp(-((arr - mu) ** 2) / (2 * sigma**2))
    except Exception as e:
        raise ValueError(f"Invalid input for gaussian: {e}") from e

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file.
    Return the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import os
    import json
    import sys
    import logging

    parsed_configs = {}
    error_records = []

    # Normalize input to a list
    if isinstance(config_filenames, (str, bytes)):
        filenames = [config_filenames]
    else:
        try:
            filenames = list(config_filenames)
        except Exception:
            filenames = []

    # Helper to resolve environment variables in nested structures
    def _resolve_env(value):
        if isinstance(value, str):
            return os.path.expandvars(value)
        if isinstance(value, dict):
            return {k: _resolve_env(v) for k, v in value.items()}
        if isinstance(value, list):
            return [_resolve_env(item) for item in value]
        return value

    # Process overrides
    if overrides is not None and not isinstance(overrides, dict):
        # ignore invalid overrides, but log a warning
        record = logging.LogRecord(
            name='load_configurations',
            level=logging.WARNING,
            pathname='',
            lineno=0,
            msg='Overrides provided but not a dict; ignoring.',
            args=(),
            exc_info=None
        )
        error_records.append(record)
        overrides = None

    for filename in filenames:
        try:
            with open(filename, 'r') as f:
                raw = f.read()
        except Exception as exc:
            rec = logging.LogRecord(
                name='load_configurations',
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg=f'Failed to open file: {exc}',
                args=(),
                exc_info=sys.exc_info()
            )
            error_records.append(rec)
            continue

        try:
            # Attempt to parse as JSON first
            try:
                cfg = json.loads(raw)
                if not isinstance(cfg, dict):
                    raise ValueError('JSON root must be an object')
            except Exception:
                # Fallback to simple key=value parsing
                cfg = {}
                for line in raw.splitlines():
                    line = line.strip()
                    if not line or line.startswith('#'):
                        continue
                    if '=' not in line:
                        raise ValueError(f'Invalid line (no "="): {line}')
                    key, val = line.split('=', 1)
                    key = key.strip()
                    val = val.strip()
                    # Strip surrounding quotes if present
                    if (val.startswith('"') and val.endswith('"')) or (val.startswith("'") and val.endswith("'")):
                        val = val[1:-1]
                    cfg[key] = val

            if resolve_env:
                cfg = _resolve_env(cfg)

            # Apply overrides if provided
            if overrides:
                cfg.update(overrides)

            parsed_configs[filename] = cfg
        except Exception as exc:
            rec = logging.LogRecord(
                name='load_configurations',
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg=f'Error parsing configuration: {exc}',
                args=(),
                exc_info=sys.exc_info()
            )
            error_records.append(rec)
            continue

    return parsed_configs, error_records

