    # Validate the supplied version argument
    if protocol_version is not None:
        if not isinstance(protocol_version, tuple):
            raise TypeError(
                f"protocol_version must be a tuple, got {type(protocol_version).__name__}"
            )
        # Optional: ensure each element of the tuple is an integer
        if not all(isinstance(v, int) for v in protocol_version):
            raise TypeError(
                "All elements of protocol_version tuple must be integers"
            )

    # Retrieve the mapping defined on the class; fall back to empty dict if not defined
    try:
        all_handlers = getattr(cls, "_protocol_handlers", {})
    except Exception:
        all_handlers = {}

    # If no specific protocol version was requested, return a copy of the whole mapping
    if protocol_version is None:
        # Return a shallow copy to prevent accidental modifications
        return dict(all_handlers)

    # If a specific version was requested, return a dict containing that one entry (or empty)
    handler = all_handlers.get(protocol_version)
    return {protocol_version: handler} if handler is not None else {}

@classmethod
    def from_raw_values(cls, values):
        """Create a Bookmarks object from a list of raw bookmark string values.

        You should not need to use this method unless you want to deserialize
        bookmarks.

        :param values: ASCII string values (raw bookmarks)
        :type values: Iterable[str]
        """
        # Validate that `values` is an iterable and not a single string/bytes object
        if values is None:
            raise TypeError("values cannot be None")
        if isinstance(values, (str, bytes)):
            raise TypeError(
                "values must be an iterable of strings, not a single string or bytes"
            )
        try:
            iterator = iter(values)
        except TypeError as exc:
            raise TypeError("values must be an iterable of strings") from exc

        validated: list[str] = []
        for idx, item in enumerate(iterator):
            # Accept bytes by decoding to ASCII
            if isinstance(item, bytes):
                try:
                    item_str = item.decode("ascii")
                except Exception as exc:
                    raise ValueError(
                        f"Element {idx} cannot be decoded from bytes to ASCII"
                    ) from exc
            elif isinstance(item, str):
                # Ensure the string is ASCII
                try:
                    item.encode("ascii")
                except UnicodeEncodeError as exc:
                    raise ValueError(f"Element {idx} contains non-ASCII characters") from exc
                item_str = item
            else:
                raise TypeError(
                    f"Element {idx} is of type {type(item).__name__}; "
                    "expected str or bytes"
                )
            validated.append(item_str)

        # Instantiate the Bookmarks object with the validated raw values
        try:
            return cls(validated)
