            raise RuntimeError("Failed to create Bookmarks instance") from exc

@classmethod
    def from_raw_values(cls, values):
        """
        Create a Bookmarks object from a list of raw bookmark string values.

        You should not need to use this method unless you want to deserialize
        bookmarks.

        :param values: ASCII string values (raw bookmarks)
        :type values: Iterable[str]
        :return: A `Bookmarks` instance populated with parsed bookmarks.
        :raises TypeError: If `values` is not iterable or contains non-string items.
        :raises ValueError: If a raw bookmark string cannot be parsed into a Bookmark.
        """
        # Ensure we have an iterable of strings; treat a single string specially.
        if isinstance(values, str):
            raw_values = [values]
        else:
            try:
                iter(values)
            except TypeError as exc:
                raise TypeError("values must be an iterable of strings") from exc
            raw_values = list(values)

        bookmarks = []
        for raw in raw_values:
            if not isinstance(raw, str):
                raise TypeError(f"bookmark value must be a string, got {type(raw).__name__}")

            # Attempt to parse the raw string into a Bookmark instance.
            try:
                # Assume a Bookmark class exists with a `from_raw` method.
                bookmark = Bookmark.from_raw(raw)
            except AttributeError as exc:
                raise AttributeError("Bookmark class must define a `from_raw` method") from exc
            except Exception as exc:
                # Wrap any parsing exception into a ValueError with context.
                raise ValueError(f"Failed to parse bookmark from raw value: {raw!r}") from exc

            if bookmark is None:
                raise ValueError(f"Bookmark.from_raw returned None for raw value: {raw!r}")

            bookmarks.append(bookmark)

        # Instantiate and return the Bookmarks object.
        try:
            return cls(bookmarks)
        except Exception as exc:
            raise RuntimeError("Failed to create Bookmarks instance") from exc

@classmethod
def from_raw_values(cls, values):
    """Create a Bookmarks object from a list of raw bookmark string values.

    You should not need to use this method unless you want to deserialize
    bookmarks.

    :param values: ASCII string values (raw bookmarks)
    :type values: Iterable[str]
    """
    if values is None:
        raise ValueError("The 'values' argument must not be None.")
    try:
        iter(values)
    except TypeError:
        raise TypeError(f"Expected an iterable of strings, got {type(values).__name__}.")
    parsed = []
    for raw in values:
        if not isinstance(raw, str):
            raise TypeError(f"Each raw value must be a string, got {type(raw).__name__}.")
        raw = raw.strip()
        if not raw:
            continue
        # Try to split into parts by common delimiters
        parts = None
        for sep in (';', ',', '|'):
            if sep in raw:
                parts = raw.split(sep, 1)
                break
        url = title = ""
        if parts and len(parts) == 2:
            part1, part2 = parts[0].strip(), parts[1].strip()
            # Determine which part is the URL
            if part1.lower().startswith(("http://", "https://", "ftp://")):
                url, title = part1, part2
            elif part2.lower().startswith(("http://", "https://", "ftp://")):
                url, title = part2, part1
            else:
                # Default to first part as URL
                url, title = part1, part2
        else:
            # No delimiter or unexpected format: treat entire string as URL
            url = raw
            title = ""
        try:
            bookmark = Bookmark(url=url, title=title)
        except Exception:
            # Fallback: store the raw string if Bookmark cannot be constructed
            try:
                bookmark = Bookmark(raw=raw)
            except Exception:
                # If Bookmark still fails, use a simple placeholder dict
                bookmark = {"raw": raw, "url": url, "title": title}
        parsed.append(bookmark)
    # Construct the Bookmarks object; assume its constructor accepts an iterable of bookmarks
    try:
        return cls(parsed)
    except Exception as e:
        raise RuntimeError(f"Failed to create {cls.__name__} from parsed bookmarks: {e}") from e

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    # Validate input
    if seq is None:
        raise TypeError("seq argument cannot be None")
    # Determine if seq is a sequence (has length and slicing)
    try:
        seq_len = len(seq)
    except Exception:
        seq_len = None
    is_sequence = seq_len is not None and hasattr(seq, "__getitem__")
    if is_sequence:
        try:
            # Use slice if bufsize specified and positive
            if isinstance(bufsize, int) and bufsize > 0:
                new_seq = seq[:bufsize]
            else:
                new_seq = seq
            return new_seq, type(new_seq)
        except Exception:
            # Fallback to conversion below
            pass
    # seq is not a sliceable sequence; attempt to convert to a list
    try:
        seq_list = list(seq)
        if isinstance(bufsize, int) and bufsize > 0:
            seq_list = seq_list[:bufsize]
        return seq_list, list
    except Exception:
        # seq may not be iterable (e.g. an int); wrap it in a list
        return [seq], list

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    # Treat None as an empty sequence
    if seq is None:
        return [], type(seq)

    # Preserve built‑in sequence types unchanged
    if isinstance(seq, (list, tuple, str, bytes)):
        return seq, type(seq)

    # Try to consume other iterables into a list
    try:
        if bufsize is None:
            seq_list = list(seq)
        else:
            seq_list = []
            count = 0
            for item in seq:
                seq_list.append(item)
                count += 1
                if count >= bufsize:
                    break
    except TypeError:
        # seq is not iterable; treat as a single element
        seq_list = [seq]

    return seq_list, type(seq)

def _get_seq_with_type(seq, bufsize=None):
    """
    Return a (sequence, type) pair.
    Sequence is derived from *seq* (or is *seq*, if that is of a sequence type).
    """
    from collections.abc import Sequence, Iterable
    import itertools

    # Basic validation
    if seq is None:
        raise TypeError("seq cannot be None")

    # If seq already supports sequence operations, use it directly
    if isinstance(seq, Sequence):
        return seq, type(seq)

    # Must be iterable otherwise raise error
    if not isinstance(seq, Iterable):
        raise TypeError(f"Expected a sequence or iterable, got {type(seq).__name__}")

    # Convert iterable to a list (or a slice of it if bufsize is specified)
    try:
        if bufsize is None:
            seq_list = list(seq)
        else:
            if not isinstance(bufsize, int) or bufsize < 0:
                raise ValueError("bufsize must be a non-negative integer")
            seq_list = list(itertools.islice(seq, bufsize))
    except Exception as exc:
        # Provide a clear message in case of unexpected conversion failures
        raise TypeError("Failed to derive sequence from the given iterable") from exc

    return seq_list, type(seq_list)

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq* (or is *seq*, if that is of a sequence type).
    """
    # Recognize built‑in ordered sequence types
    seq_types = (list, tuple, str, bytes, bytearray, range)
    try:
        if isinstance(seq, seq_types):
            # seq is already an ordered sequence
            return seq, type(seq)

        # If seq is not a sequence, try to materialise it into a list.
        # bufsize can be used to limit the amount of memory used during conversion.
        if bufsize is None:
            try:
                seq = list(seq)
            except Exception:
                # seq is not iterable; return it as‑is with its type
                return seq, type(seq)
        else:
            # When a bufsize is provided, convert in chunks to avoid loading everything at once
            import itertools
            it = iter(seq)
            out = []
            while True:
                chunk = list(itertools.islice(it, bufsize))
                if not chunk:
                    break
                out.extend(chunk)
            seq = out

        return seq, type(seq)
    except Exception:
        # In all other unexpected cases, return the original object and its type
        return seq, type(seq)

def scale(self, other=None, recompute=False):
        """Compute or set scale (integral of the histogram).

        If *other* is ``None``, return scale of this histogram.
        If its scale was not computed before,
        it is computed and stored for subsequent use
        (unless explicitly asked to *recompute*).
        Note that after changing (filling) the histogram
        one must explicitly recompute the scale
        if it was computed before.

        If a float *other* is provided, rescale self to *other*.

        Histograms with scale equal to zero can't be rescaled.
        :exc:`.LenaValueError` is raised if one tries to do that.
        """
        # Helper to compute the integral if needed
        def _compute_scale():
            # Try a few common attribute names that may hold the data
            data_attr = None
            for name in ('data', 'bins', 'values', 'counts'):
                if hasattr(self, name):
                    data_attr = getattr(self, name)
                    break
            if data_attr is None:
                raise ValueError("No suitable data attribute found to compute scale.")
            # Compute integral as the sum of all entries
            try:
                return sum(data_attr)
            except Exception as exc:
                raise ValueError(f"Error computing scale: {exc}") from exc

        # If we are requesting the scale
        if other is None:
            # Recompute if requested or never computed
            if recompute or getattr(self, "_scale", None) is None:
                self._scale = _compute_scale()
            return self._scale

        # If a new scale is requested
        if not isinstance(other, (int, float)):
            raise TypeError("scale factor must be a number")
        # Compute current scale if not already known
        current = self.scale()
        if current == 0:
            raise LenaValueError("Cannot rescale histogram with zero scale.")
        factor = other / current

        # Apply rescaling to all numeric list-like attributes
        for name in ('data', 'bins', 'values', 'counts'):
            if hasattr(self, name):
                attr = getattr(self, name)
                # Only rescale if it is an iterable of numbers
                try:
                    scaled = [x * factor for x in attr]
                except Exception:
                    # attribute is not iterable; try direct multiplication
                    try:
                        scaled = attr * factor
                    except Exception:
                        continue  # skip non‑scalable attributes
                setattr(self, name, scaled)

        # Update the stored scale
        self._scale = other
        return None

def scale(self, other=None, recompute=False):
    """Compute or set scale (integral of the histogram).

    If *other* is ``None``, return scale of this histogram.
    If its scale was not computed before, it is computed and stored for subsequent use
    (unless explicitly asked to *recompute*).
    Note that after changing (filling) the histogram one must explicitly recompute the scale
    if it was computed before.

    If a float *other* is provided, rescale self to *other*.

    Histograms with scale equal to zero can't be rescaled.
    :exc:`.LenaValueError` is raised if one tries to do that.
    """
    # Helper to compute integral
    def _compute_integral():
        # Try common ways to compute the integral
        if hasattr(self, "integral") and callable(self.integral):
            return self.integral()
        # Fallback: sum of bin contents multiplied by bin width if available
        if hasattr(self, "data") and hasattr(self, "bin_width"):
            try:
                return float(self.data.sum() * self.bin_width)
            except Exception:
                pass
        if hasattr(self, "data") and hasattr(self.data, "sum"):
            return float(self.data.sum())
        # If the histogram can be iterated over bins with a 'content' attribute
        try:
            total = 0.0
            for bin in self:
                if hasattr(bin, "content"):
                    total += float(bin.content)
            return total
        except Exception:
            pass
        raise ValueError("Unable to compute integral for the histogram")

    # ==============================
    # Return or recompute current scale
    # ==============================
    if other is None:
        if getattr(self, "_scale_computed", False) and not recompute:
            return self._scale
        # Recompute and store
        self._scale = _compute_integral()
        self._scale_computed = True
        return self._scale

    # ==============================
    # Set scale to *other*
    # ==============================
    try:
        target_scale = float(other)
    except Exception as exc:
        raise ValueError(f"Scale must be convertible to float, got {other}") from exc

    # Ensure we have the current scale for rescaling
    current_scale = self.scale(recompute=recompute)

    # Avoid division by zero
    if current_scale == 0:
        raise LenaValueError("Cannot rescale histogram with a zero scale")

    # Compute rescaling factor
    factor = target_scale / current_scale

    # Apply rescaling
    if hasattr(self, "data") and isinstance(self.data, (list, tuple)):
        # If data is a mutable sequence of numbers
        for idx, val in enumerate(self.data):
            self.data[idx] = val * factor
    elif hasattr(self, "data") and hasattr(self.data, "__array__"):
        # If data is a NumPy array or similar
        self.data *= factor
    elif hasattr(self, "bins"):
        # If bins are objects with a 'content' or similar attribute
        for bin in self.bins:
            if hasattr(bin, "content"):
                bin.content *= factor
            elif hasattr(bin, "scale"):
                bin.scale *= factor
    else:
        # Fallback: iterate over histogram objects directly
        for bin in self:
            if hasattr(bin, "content"):
                bin.content *= factor
            elif hasattr(bin, "scale"):
                bin.scale *= factor

    # Store the new scale
    self._scale = target_scale
    self._scale_computed = True
    return self._scale

def scale(self, other=None, recompute=False):
    """
    Compute or set scale (integral of the histogram).

    If *other* is ``None``, return scale of this histogram.
    If its scale was not computed before,
    it is computed and stored for subsequent use
    (unless explicitly asked to *recompute*).
    Note that after changing (filling) the histogram
    one must explicitly recompute the scale
    if it was computed before.

    If a float *other* is provided, rescale self to *other*.

    Histograms with scale equal to zero can't be rescaled.
    :exc:`.LenaValueError` is raised if one tries to do that.
    """
    # Helper to retrieve the internal counts array
    def _get_counts():
        # Try common names that the histogram might use
        for name in ("_counts", "_data", "bins", "values", "counts"):
            if hasattr(self, name):
                return getattr(self, name)
        raise AttributeError(
            "Cannot find internal count storage in histogram instance"
        )

    # When no 'other' is provided, we return (or compute) the current scale
    if other is None:
        if not recompute and hasattr(self, "_scale"):
            return self._scale
        counts = _get_counts()
        try:
            s = sum(counts)
        except TypeError:
            # In case counts is a numpy array or similar
            s = 0.0
            for c in counts:
                s += c
        self._scale = s
        return s

    # When 'other' is given, we rescale histogram to that value
    if not isinstance(other, (int, float)):
        raise TypeError("Argument 'other' must be a numeric value")

    counts = _get_counts()
    # Determine current scale
    if hasattr(self, "_scale"):
        current_scale = self._scale
    else:
        try:
            current_scale = sum(counts)
        except TypeError:
            current_scale = 0.0
            for c in counts:
                current_scale += c

    if current_scale == 0:
        raise ValueError("Histograms with scale equal to zero can't be rescaled.")

    factor = other / current_scale

    # Scale counts in place
    if isinstance(counts, (list, tuple)):
        # lists and tuples are mutable only if list; for tuple we need reassignment
        for i in range(len(counts)):
            counts[i] = counts[i] * factor
    else:
        # Assume it supports item assignment (e.g., array, numpy array)
        try:
            for i in range(len(counts)):
                counts[i] *= factor
        except Exception:
            # Fallback: create a new collection
            new_counts = [c * factor for c in counts]
            setattr(self, counts.__class__.__name__.lower(), new_counts)

    self._scale = other
    return other

def scale(self, other=None):
        """Get or set the scale of the graph.

        If *other* is ``None``, return the scale of this graph.

        If a numeric *other* is provided, rescale to that value.
        If the graph has unknown or zero scale,
        rescaling that will raise :exc:`~.LenaValueError`.

        To get meaningful results, graph's fields are used.
        Only the last coordinate is rescaled.
        For example, if the graph has *x* and *y* coordinates,
        then *y* will be rescaled, and for a 3-dimensional graph
        *z* will be rescaled.
        All errors are rescaled together with their coordinate.
        """
        # Get operation
        if other is None:
            return getattr(self, "_scale", None)

        # Validate new scale
        if not isinstance(other, (int, float)):
            raise TypeError("Scale must be a numeric value.")
        if other == 0:
            raise ValueError("Scale cannot be zero.")

        # Current scale must be known and non-zero
        current_scale = getattr(self, "_scale", None)
        if current_scale is None or current_scale == 0:
            raise LenaValueError("Cannot rescale: current scale is unknown or zero.")

        # Determine the coordinate fields
        # Assume coordinates are stored in a mapping or DataFrame-like structure
        coord_names = getattr(self, "_coords", None)
        if coord_names is None:
            raise AttributeError("Graph has no coordinate information.")
        if not isinstance(coord_names, (list, tuple)) or not coord_names:
            raise AttributeError("Coordinate names are invalid or empty.")

        # Only rescale the last coordinate
        last_coord = coord_names[-1]

        # Compute scale factor
        factor = other / current_scale

        # Rescale coordinate values
        data = getattr(self, "_data", None)
        if data is None:
            raise AttributeError("Graph has no data to rescale.")
        try:
            # Handle common data structures: dict of lists or DataFrame-like
            if isinstance(data, dict):
                if last_coord in data:
                    data[last_coord] = [v * factor for v in data[last_coord]]
                else:
                    raise KeyError(f"Coordinate '{last_coord}' not found in data.")
            else:
                # Attempt to use pandas-like access if available
                if hasattr(data, "loc") and hasattr(data, "columns"):
                    data.loc[:, last_coord] = data.loc[:, last_coord] * factor
                else:
                    raise AttributeError("Unsupported data structure for rescaling.")
        except Exception as exc:
            raise ValueError(f"Failed to rescale data: {exc}") from exc

        # Rescale error values if present
        errors = getattr(self, "_errors", None)
        if errors and isinstance(errors, dict) and last_coord in errors:
            try:
                errors[last_coord] = [e * factor for e in errors[last_coord]]
            except Exception as exc:
                raise ValueError(f"Failed to rescale errors: {exc}") from exc

        # Update the internal scale value
        self._scale = other

        return self._scale

def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    """Convert a :class:`.histogram` to a :class:`.graph`.

    *make_value* is a function to set the value of a graph's point.
    By default it is bin content.
    *make_value* accepts a single value (bin content) without context.

    This option could be used to create graph's error bars.
    For example, to create a graph with errors
    from a histogram where bins contain
    a named tuple with fields *mean*, *mean_error* and a context
    one could use

    >>> make_value = lambda bin_: (bin_.mean, bin_.mean_error)

    *get_coordinate* defines what the coordinate
    of a graph point created from a histogram bin will be.
    It can be "left" (default), "right" and "middle".

    *field_names* set field names of the graph. Their number
    must be the same as the dimension of the result.
    For a *make_value* above they would be
    *("x", "y_mean", "y_mean_error")*.

    *scale* becomes the graph's scale (unknown by default).
    If it is ``True``, it uses the histogram scale.

    *hist* must contain only numeric bins (without context)
    or *make_value* must remove context when creating a numeric graph.

    Return the resulting graph.
    """
    # ------------- Input validation -------------------------------------------------
    if hist is None:
        raise TypeError("hist must not be None")

    if get_coordinate not in {"left", "right", "middle"}:
        raise ValueError('get_coordinate must be one of "left", "right" or "middle"')

    if not isinstance(field_names, (list, tuple)):
        raise TypeError("field_names must be a list or tuple of strings")
    if len(field_names) < 1:
        raise ValueError("field_names must contain at least one name (x)")
    if not all(isinstance(n, str) for n in field_names):
        raise TypeError("field_names must contain strings only")
    y_field_count = len(field_names) - 1

    # ------------- Extract histogram information ------------------------------------
    # Determine number of bins
    if hasattr(hist, "GetNbinsX"):
        try:
            nbins = hist.GetNbinsX()
        except Exception as exc:
            raise ValueError(f"Failed to retrieve number of bins: {exc}") from exc
        bin_index_offset = 1  # ROOT-like
    elif hasattr(hist, "__len__"):
        nbins = len(hist)
        bin_index_offset = 0
    else:
        raise TypeError("hist type is not supported: cannot determine number of bins")

    if nbins < 0:
        raise ValueError("Number of histogram bins must be non‑negative")

    # Attempt to get bin edges
    edges = None
    if hasattr(hist, "bin_edges"):
        edges = hist.bin_edges
    elif hasattr(hist, "edges"):
        edges = hist.edges

    def get_low_edge(i):
        """Return the lower edge of bin i (1‑based if ROOT‑style)."""
        if hasattr(hist, "GetBinLowEdge"):
            try:
                return hist.GetBinLowEdge(i)
            except Exception:
                pass
        if edges is not None:
            return edges[i - 1] if hasattr(hist, "GetBinLowEdge") else edges[i]
        # As a last resort use the bin index
        return i - 1

    def get_high_edge(i):
        """Return the upper edge of bin i (1‑based if ROOT‑style)."""
        if hasattr(hist, "GetBinUpEdge"):
            try:
                return hist.GetBinUpEdge(i)
            except Exception:
                pass
        if hasattr(hist, "GetBinLowEdge"):
            # In ROOT, high edge of bin i can be low edge of bin i+1
            try:
                if i < nbins:
                    return hist.GetBinLowEdge(i + 1)
                else:
                    return hist.GetBinUpEdge(i)
            except Exception:
                pass
        if edges is not None:
            return edges[i]
        # As a last resort use the bin index
        return i

    # ------------- Build graph structure --------------------------------------------
    graph = {name: [] for name in field_names}
    # Optional scale handling
    if scale is True and hasattr(hist, "scale"):
        graph["scale"] = getattr(hist, "scale")
    elif scale is not None:
        graph["scale"] = scale

    # Process each bin
    for idx in range(nbins):
        # Helper to convert idx to histogram index
        hist_idx = idx + bin_index_offset
        # Retrieve content
        if hasattr(hist, "GetBinContent"):
            try:
                content = hist.GetBinContent(hist_idx)
            except Exception as exc:
                raise ValueError(f"Failed to get bin content for bin {hist_idx}: {exc}") from exc
        else:
            try:
                content = hist[idx]
            except Exception as exc:
                raise ValueError(f"Failed to index histogram at position {idx}: {exc}") from exc

        # Build value tuple
        if make_value is None:
            values = (content,)
        else:
            try:
                values = make_value(content)
            except Exception as exc:
                raise ValueError(f"make_value failed for content {content}: {exc}") from exc

        if not isinstance(values, (list, tuple)):
            values = (values,)

        if len(values) != y_field_count:
            raise ValueError(f"make_value returned {len(values)} values, "
                             f"but field_names expects {y_field_count} y values")

        # Determine coordinate
        low = get_low_edge(hist_idx)
        high = get_high_edge(hist_idx)
        if get_coordinate == "left":
            coord = low
        elif get_coordinate == "right":
            coord = high
        else:  # middle
            coord = (low + high) / 2

        # Append to graph
        graph[field_names[0]].append(coord)
        for name, val in zip(field_names[1:], values):
            graph[name].append(val)

    return graph

def _verify(iface, candidate, tentative=False, vtype=None):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
      interface using ``iface.providedBy`` (unless *tentative* is `True`,
      in which case this step is skipped). This means that the candidate's class
      declares that it `implements <zope.interface.implementer>` the interface,
      or the candidate itself declares that it `provides <zope.interface.provider>`
      the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
      extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
       checked passed.
    :raises zope.interface.Invalid: If any of the previous
       conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """
    import inspect
    from zope.interface import Invalid
    errors = []

    # 1. Interface claim check (skip if tentative)
    if not tentative:
        try:
            if not iface.providedBy(candidate):
                errors.append(
                    Invalid(
                        f"{candidate!r} does not declare that it provides "
                        f"{iface!r}"
                    )
                )
        except Exception as exc:
            errors.append(Invalid(f"Error checking interface provision: {exc}"))

    # 2. Method existence and signature checks
    try:
        required_methods = iface.getRequiredMethods()
    except Exception:
        # Fallback: use attributes that are callable
        required_methods = []
        for name in dir(iface):
            attr = getattr(iface, name, None)
            if callable(attr):
                required_methods.append(name)

    for name in required_methods:
        if not hasattr(candidate, name):
            errors.append(
                Invalid(f"Candidate {candidate!r} does not provide required method {name!r}")
            )
            continue
        cand_method = getattr(candidate, name)
        iface_method = getattr(iface, name, None)
        # Compare signatures if both are callables
        if callable(cand_method) and callable(iface_method):
            try:
                sig_cand = inspect.signature(cand_method)
                sig_iface = inspect.signature(iface_method)
                # Simple comparison: parameter names and kinds
                params_cand = list(sig_cand.parameters.values())
                params_iface = list(sig_iface.parameters.values())
                if len(params_cand) != len(params_iface):
                    errors.append(
                        Invalid(
                            f"Signature mismatch for {name!r}: "
                            f"expected {len(params_iface)} params, "
                            f"got {len(params_cand)}"
                        )
                    )
                    continue
                for p_c, p_i in zip(params_cand, params_iface):
                    if p_c.name != p_i.name or p_c.kind != p_i.kind:
                        errors.append(
                            Invalid(
                                f"Signature mismatch for {name!r}: "
                                f"expected param {p_i.name} ({p_i.kind}), "
                                f"got {p_c.name} ({p_c.kind})"
                            )
                        )
                        break
            except Exception as exc:
                # If introspection fails, note but don't fail
                errors.append(
                    Invalid(f"Could not introspect signature for {name!r}: {exc}")
                )
        else:
            errors.append(
                Invalid(f"Attribute {name!r} of candidate {candidate!r} is not callable")
            )

    # 3. Attribute checks
    # Try to get required attributes from interface
    attr_errors = []
    try:
        # For zope.interface >=4.5
        required_attrs = getattr(iface, "getRequiredAttributes", lambda: {})()
    except Exception:
        required_attrs = {}
    if required_attrs:
        for name, desc in required_attrs.items():
            if not hasattr(candidate, name):
                attr_errors.append(
                    Invalid(f"Candidate {candidate!r} does not provide required attribute {name!r}")
                )
            else:
                # Optional: If attribute descriptor has a type check
                # but we ignore for simplicity
                pass

    errors.extend(attr_errors)

    # 4. Result handling
    if not errors:
        return True
    if len(errors) == 1:
        raise errors[0]
    # multiple errors: aggregate message
    msg = "; ".join(str(e) for e in errors)
    raise Invalid(msg)

def verifyObject(iface, candidate, tentative=False):
    """Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the interface using
      ``iface.providedBy`` (unless *tentative* is ``True``, in which case this
      step is skipped). This means that the candidate's class declares that
      it ``implements <zope.interface.implementer>`` the interface, or the
      candidate itself declares that it ``provides <zope.interface.provider>``
      the interface.

    - Making sure the candidate defines all the necessary methods.

    - Making sure the methods have the correct signature (to the extent
      possible).

    - Making sure the candidate defines all the necessary attributes.

    :return bool: Returns a true value if everything that could be
      checked passed.
    :raises zope.interface.Invalid: If any of the previous conditions does
      not hold.
    """
    import inspect
    import zope.interface

    errors = []

    # Check that the candidate provides the interface, unless tentative.
    if not tentative:
        try:
            if not iface.providedBy(candidate):
                raise zope.interface.Invalid(
                    "%r does not provide %r" % (candidate, iface)
                )
        except Exception as exc:
            # If the providedBy check itself fails, raise as Invalid.
            raise zope.interface.Invalid(
                "Error checking if %r provides %r: %s" % (candidate, iface, exc)
            ) from exc

    # Helper to compare signatures.
    def signatures_match(sig_iface, sig_candidate):
        params_iface = list(sig_iface.parameters.values())
        params_candidate = list(sig_candidate.parameters.values())

        # Skip a leading 'self' parameter if present in both.
        if params_iface and params_iface[0].name == "self" and params_candidate and params_candidate[0].name == "self":
            params_iface = params_iface[1:]
            params_candidate = params_candidate[1:]

        if len(params_iface) != len(params_candidate):
            return False

        for pi, pc in zip(params_iface, params_candidate):
            if pi.kind != pc.kind:
                return False
            if pi.default != pc.default:
                return False
            if pi.annotation != pc.annotation:
                return False
        return True

    # Check all required methods.
    methods = getattr(iface, "methods", {})
    for name, iface_method in methods.items():
        if not hasattr(candidate, name):
            errors.append(f"Missing method {name!r}")
            continue
        try:
            candidate_method = getattr(candidate, name)
        except Exception as exc:
            errors.append(f"Error accessing method {name!r}: {exc}")
            continue
        if not callable(candidate_method):
            errors.append(f"{name!r} is not callable")
            continue
        try:
            sig_iface = inspect.signature(iface_method)
            sig_candidate = inspect.signature(candidate_method)
            if not signatures_match(sig_iface, sig_candidate):
                errors.append(
                    f"Signature mismatch for {name!r}: "
                    f"candidate {sig_candidate}, expected {sig_iface}"
                )
        except ValueError as exc:
            # Could not introspect the signature
            errors.append(f"Cannot inspect signature for {name!r}: {exc}")

    # Check all required attributes.
    attributes = getattr(iface, "attributes", {})
    for name in attributes:
        try:
            if not hasattr(candidate, name):
                errors.append(f"Missing attribute {name!r}")
        except Exception as exc:
            errors.append(f"Error accessing attribute {name!r}: {exc}")

    # Report errors if any were collected.
    if errors:
        if len(errors) == 1:
            raise zope.interface.Invalid(errors[0])
        raise zope.interface.Invalid("\n".join(errors))

    return True

def verifyObject(iface, candidate, tentative=False):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
    interface using ``iface.providedBy`` (unless *tentative* is `True`,
    in which case this step is skipped). This means that the candidate's class
    declares that it `implements <zope.interface.implementer>` the interface,
    or the candidate itself declares that it `provides <zope.interface.provider>`
    the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
    extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
    checked passed.
    :raises zope.interface.Invalid: If any of the previous
    conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """
    # Local imports to avoid requiring module-level imports
    import inspect
    from zope.interface import Invalid
    from zope.interface.interface import InterfaceClass

    # Basic type checks
    if not isinstance(iface, InterfaceClass):
        raise TypeError("iface must be an InterfaceClass")
    if candidate is None:
        raise ValueError("candidate cannot be None")

    # 1. Check interface provision unless tentative
    if not tentative:
        if not iface.providedBy(candidate):
            raise Invalid(f"{candidate!r} does not provide {iface!r}")

    errors = []

    # Helper to get the underlying function from a class or instance
    def _underlying_callable(obj, name):
        if inspect.isclass(obj):
            try:
                return getattr(obj, name)
            except AttributeError:
                return None
        else:
            # For instance, fetch from class to get unbound function
            return getattr(type(obj), name, None)

    # Iterate over interface attributes and methods
    for name, attr in iface.__dict__.items():
        # Skip private/internal interface attributes
        if name.startswith('_'):
            continue
        # Check if attr is an Attribute (declared attribute)
        try:
            from zope.interface import Attribute
            is_attribute = isinstance(attr, Attribute)
        except Exception:
            is_attribute = False

        if is_attribute:
            # Check that candidate has this attribute
            if not hasattr(candidate, name):
                errors.append(f"Missing required attribute '{name}'")
            continue

        # Assume it's a method (callable)
        if not callable(attr):
            continue  # ignore non-callable entries

        # Verify candidate has this callable
        if not hasattr(candidate, name):
            errors.append(f"Missing required method '{name}'")
            continue

        # Retrieve the underlying function for signature comparison
        cand_callable = _underlying_callable(candidate, name)
        if cand_callable is None:
            errors.append(f"Missing required method '{name}'")
            continue

        if not callable(cand_callable):
            errors.append(f"Attribute '{name}' is not callable")
            continue

        # Compare signatures
        try:
            iface_sig = inspect.signature(attr)
            cand_sig = inspect.signature(cand_callable)
        except (ValueError, TypeError) as exc:
            errors.append(f"Unable to inspect signature of method '{name}': {exc}")
            continue

        def _sig_to_tuple(sig):
            return tuple(
                (p.kind, p.default is not inspect._empty, p.annotation is not inspect._empty)
                for p in sig.parameters.values()
            )

        if _sig_to_tuple(iface_sig) != _sig_to_tuple(cand_sig):
            errors.append(
                f"Signature mismatch for method '{name}': "
                f"expected {iface_sig} but got {cand_sig}"
            )

    # Raise collected errors if any
    if errors:
        if len(errors) == 1:
            raise Invalid(errors[0])
        else:
            raise Invalid("; ".join(errors))

    return True

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    Returns True if candidate satisfies the interface, otherwise raises
    a TypeError unless *tentative* is True, in which case it returns False.
    """
    if iface is None:
        raise ValueError("iface cannot be None")
    if candidate is None:
        raise ValueError("candidate cannot be None")

    # Determine the set of required attribute names from the interface.
    required = set()
    if hasattr(iface, "__abstractmethods__"):
        required.update(iface.__abstractmethods__)
    else:
        for name, val in getattr(iface, "__dict__", {}).items():
            if name.startswith("__"):
                continue
            required.add(name)

    # Check if candidate is a class or an instance.
    is_class = isinstance(candidate, type)

    # For classes we can also check direct subclassing.
    if is_class:
        if issubclass(candidate, iface):
            return True
        # otherwise fall through to check attribute presence.

    # Gather missing attributes.
    missing = []
    for name in required:
        if not hasattr(candidate, name):
            missing.append(name)

    if missing:
        msg = f"{candidate!r} does not provide all attributes of {iface!r}: {missing}"
        if tentative:
            return False
        raise TypeError(msg)

    return True

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    # Validate bases
    if not isinstance(bases, (list, tuple)):
        raise TypeError("bases must be a sequence of classes")
    if not bases:
        # Default metaclass is type
        return type

    # Gather metaclasses from bases
    base_mcs = []
    for b in bases:
        if not isinstance(b, type):
            raise TypeError(f"base {b!r} is not a class")
        base_mcs.append(b.__class__)

    # If explicit metaclass was supplied
    if explicit_mc is not None:
        if not isinstance(explicit_mc, type):
            raise TypeError(f"explicit metaclass {explicit_mc!r} is not a class")
        # Ensure explicit metaclass is compatible with all base metaclasses
        for mc in base_mcs:
            if not issubclass(explicit_mc, mc):
                raise TypeError(
                    f"explicit metaclass ({explicit_mc.__name__}) is not a subclass "
                    f"of base metaclass ({mc.__name__})"
                )
        # Make explicit metaclass part of candidate list
        candidates = [explicit_mc] + base_mcs
    else:
        candidates = base_mcs

    # Determine the most derived metaclass
    # Find metaclasses that are subclass of all others
    most_derived = []
    for candidate in candidates:
        if all(issubclass(candidate, other) for other in candidates):
            most_derived.append(candidate)

    # Resolve result
    if len(most_derived) == 0:
        # No common metaclass found; this is a conflict
        metaclass_names = ", ".join(m.__name__ for m in candidates)
        raise TypeError(
            f"metaclass conflict: no common metaclass found among ({metaclass_names})"
        )
    if len(most_derived) > 1:
        # Multiple equally derived metaclasses (unlikely unless identical)
        # If they are the same class, pick one; otherwise error
        unique_derived = set(most_derived)
        if len(unique_derived) == 1:
            return most_derived[0]
        metaclass_names = ", ".join(m.__name__ for m in unique_derived)
        raise TypeError(
            f"metaclass conflict: multiple metaclasses without a clear hierarchy ({metaclass_names})"
        )
    # Exactly one most derived metaclass
    return most_derived[0]

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    # Validate bases: must be non-empty iterable of classes
    if not hasattr(bases, '__iter__'):
        raise TypeError(f"bases must be an iterable of classes, got {bases!r}")
    bases = tuple(bases)
    if not bases:
        # No bases implies type (new-style class)
        return type

    # Helper to fetch metaclass of a base and validate
    def get_meta(base):
        if not isinstance(base, type):
            raise TypeError(f"Base {base!r} is not a class")
        return type(base)

    # Collect metaclasses of the bases
    metas = [get_meta(b) for b in bases]

    # If explicit metaclass provided
    if explicit_mc is not None:
        if not isinstance(explicit_mc, type):
            raise TypeError(f"explicit metaclass {explicit_mc!r} is not a class")
        # Ensure compatibility: explicit must be subclass of each base's metaclass
        for meta in metas:
            # If base's metaclass is subclass of explicit, explicit is OK
            # If explicit is subclass of base's metaclass, explicit is OK
            if not (issubclass(explicit_mc, meta) or issubclass(meta, explicit_mc)):
                raise TypeError(
                    f"explicit metaclass {explicit_mc.__name__} is incompatible "
                    f"with base class {meta.__name__}"
                )
        return explicit_mc

    # No explicit metaclass: find common super metaclass
    # Start with first metaclass
    common = metas[0]
    for meta in metas[1:]:
        if issubclass(meta, common):
            common = meta
        elif not issubclass(common, meta):
            raise TypeError(
                f"Conflicting metaclasses {common.__name__} and {meta.__name__}"
            )
    return common

def pop(self, key, default=__marker):
    """
    D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised.
    """
    try:
        value = self[key]
    except KeyError:
        if default is not __marker:
            return default
        raise
    del self[key]
    return value

def pop(self, key, default=__marker):
    """
    D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised.
    """
    try:
        # Attempt to retrieve the value; this will raise KeyError if the key is missing
        value = self[key]
    except KeyError:
        if default is __marker:
            # No default provided, re-raise the KeyError
            raise
        # Default was provided, return it
        return default
    else:
        # Key exists: delete it and return the value
        try:
            del self[key]
        except Exception:
            # If deletion fails for some reason, re-raise a KeyError for consistency
            raise KeyError(key)
        return value

def pop(self, key, default=__marker):
    """
    D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised.
    """
    # Use the underlying dict implementation. If this object is not a true dict,
    # the fallback will raise an AttributeError, in which case we manually manage
    # the storage using a typical attribute name (e.g., _data). This fallback
    # is defensive: if the expected attribute is not found, we let the default
    # behaviour of Python's dict pop proceed, ensuring consistency with the
    # documentation.
    try:
        if default is __marker:
            # default not supplied; may raise KeyError naturally
            return super().pop(key)
        else:
            return super().pop(key, default)
    except AttributeError:
        # Fallback for non-dict subclasses that still maintain a dict-like
        # storage attribute called `_data`. Adjust if your implementation uses
        # a different attribute name.
        data = getattr(self, "_data", None)
        if data is None:
            raise
        if key in data:
            value = data.pop(key)
            return value
        if default is not __marker:
            return default
        raise KeyError(key)
    except KeyError:
        # When default is provided, dict.pop behaves correctly. We trap
        # missing-key errors here to return the default if supplied.
        if default is not __marker:
            return default
        raise

def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    # Ensure the necessary data structures exist
    try:
        data = self._data
        freq = self._freq
    except AttributeError:
        raise AttributeError(
            "Required attributes (_data, _freq) are missing from the instance."
        ) from None

    if not data:
        raise KeyError("popitem from an empty container")

    # Identify the minimum frequency value
    min_freq = None
    for v in freq.values():
        if min_freq is None or v < min_freq:
            min_freq = v
    if min_freq is None:
        raise KeyError("Frequency data is empty; cannot determine least used item.")

    # Gather all keys that have the minimum frequency
    min_keys = [k for k, v in freq.items() if v == min_freq]
    if not min_keys:
        # Inconsistent state: data exists but no matching frequency entries
        raise KeyError("No keys with matching minimum frequency found.")

    # Resolve ties by insertion order if an ordering list is present
    key_to_remove = None
    if hasattr(self, "_order"):
        order = getattr(self, "_order")
        for k in order:
            if k in min_keys:
                key_to_remove = k
                break
    if key_to_remove is None:
        # Fall back to an arbitrary choice (first in min_keys)
        key_to_remove = min_keys[0]

    # Retrieve and remove the key/value pair
    value = data.pop(key_to_remove)
    freq.pop(key_to_remove, None)
    if hasattr(self, "_order"):
        try:
            order.remove(key_to_remove)
        except ValueError:
            # In case the key is not present in order list, ignore
            pass

    return (key_to_remove, value)

def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    # Ensure there is at least one item
    if not hasattr(self, "key_freq") or not self.key_freq:
        raise KeyError("popitem(): dictionary is empty")

    # Determine the current minimum frequency
    if hasattr(self, "min_freq") and self.min_freq is not None:
        freq = self.min_freq
        # If the min_freq mapping is missing or empty, recompute
        if not hasattr(self, "freq_map") or freq not in self.freq_map or not self.freq_map[freq]:
            if not hasattr(self, "freq_map") or not self.freq_map:
                raise KeyError("popitem(): dictionary is empty")
            freq = min(self.freq_map.keys())
    else:
        if not hasattr(self, "freq_map") or not self.freq_map:
            raise KeyError("popitem(): dictionary is empty")
        freq = min(self.freq_map.keys())

    # Pop the least recently used key from the bucket of the least frequency
    key, value = self.freq_map[freq].popitem(last=False)

    # Remove key from the frequency and key-value maps
    del self.key_freq[key]
    del self.key_value[key]

    # Clean up the frequency bucket if it is now empty
    if not self.freq_map[freq]:
        del self.freq_map[freq]
        # Update the minimum frequency if there are still items
        if self.key_freq:
            self.min_freq = min(self.key_freq.values())
        else:
            self.min_freq = None

    return key, value

def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    # Determine the cache storage and frequency mapping.
    cache = getattr(self, "cache", None)
    if cache is None:
        cache = getattr(self, "_cache", None)
    if cache is None:
        raise AttributeError("Cache storage attribute not found.")
    freq = getattr(self, "freq", None)
    if freq is None:
        freq = getattr(self, "_freq", None)
    if freq is None:
        raise AttributeError("Frequency mapping attribute not found.")

    if not cache:
        # Mimic dict.popitem behavior for empty containers.
        raise KeyError("popitem from an empty cache")

    try:
        min_freq = min(freq.values())
    except ValueError:
        # Frequency mapping is empty but cache is not – inconsistent state.
        raise KeyError("Frequency mapping is empty while cache has items")

    # Find a key with the minimal frequency.
    key = None
    for k, v in freq.items():
        if v == min_freq:
            key = k
            break
    if key is None:
        raise KeyError("No key has the minimal frequency")

    # Remove the key/value from the underlying storage and frequency map.
    value = cache.pop(key)
    freq.pop(key)
    return key, value

def popitem(self):
    """Remove and return the `(key, value)` pair least recently used."""
    try:
        # For ordered dicts that support the `last` keyword
        return super().popitem(last=False)
    except TypeError:
        # Fallback for normal dictionaries (Python ≥3.7 preserves insertion order)
        if not self:
            raise KeyError("popitem(): dictionary is empty")
        key = next(iter(self))
        return key, self.pop(key)

def popitem(self):
    """Remove and return the `(key, value)` pair least recently used."""
    # Attempt to locate the cache storage. Common names used in LRU cache
    # implementations include "cache", "_cache", "data", "_data", "store",
    # "_store", "dict", "_dict".
    cache_attr_names = ["cache", "_cache", "data", "_data", "store", "_store", "dict", "_dict"]
    cache = None
    for name in cache_attr_names:
        if hasattr(self, name):
            cache = getattr(self, name)
            break
    if cache is None:
        raise AttributeError("LRU cache storage attribute not found")

    # If the cache has a popitem method that accepts a 'last' keyword,
    # it is likely an OrderedDict or similar where 'last=False' removes
    # the least‑recently used item (the first one).
    if hasattr(cache, "popitem"):
        try:
            # Prefer explicit ordering if supported
            return cache.popitem(last=False)
        except TypeError:
            # Fallback: standard popitem for dicts or other structures
