    # Attempt to pop the most recently used item.
    try:
        # OrderedDict style: popitem(last=True) removes the last inserted/moved item.
        return container.popitem(last=True)
    except TypeError:
        # Fall back to plain dict behaviour: popitem() with no arguments.
        try:
            return container.popitem()
        except KeyError as exc:
            # Re‑raise KeyError to signal that the cache is empty.
            raise KeyError("popitem(): dictionary is empty") from exc

    # In the extremely unlikely event that neither popitem form is supported,
    # raise an informative error.
    raise TypeError(
        "The cache container does not support popitem(last=True) "
        "or popitem() methods."
    )

