def isoparse(self, dt_str):
    """
    Parse an ISO-8601 datetime string into a :class:`datetime.datetime`.

    See the original docstring for details.
    """
    import datetime
    import re
    from dateutil.tz import tzutc, tzoffset

    # Accept a stream
    if hasattr(dt_str, "read"):
        try:
            data = dt_str.read()
        except Exception as e:
            raise ValueError(f"Unable to read from stream: {e}") from e
        if isinstance(data, bytes):
            try:
                dt_str = data.decode("ascii")
            except Exception as e:
                raise ValueError("Stream contains non‑ASCII data") from e
        else:
            dt_str = str(data)
    else:
        dt_str = str(dt_str)

    # Ensure ASCII
    if any(ord(ch) > 127 for ch in dt_str):
        raise ValueError("Input contains non‑ASCII characters")

    # Split date and time parts
    if "T" in dt_str:
        date_part, time_part = dt_str.split("T", 1)
    else:
        date_part, time_part = dt_str, None

    # Helper to parse timezone
    def parse_tz(tz_str):
        if tz_str == "Z":
            return tzutc()
        m = re.match(r"([+-])(\d{2})(?::?(\d{2}))?\s*$", tz_str)
        if not m:
            raise ValueError(f"Invalid timezone offset: {tz_str!r}")
        sign = 1 if m.group(1) == "+" else -1
        hour = int(m.group(2))
        minute = int(m.group(3)) if m.group(3) else 0
        offset = sign * (hour * 3600 + minute * 60)
        if offset == 0:
            return tzutc()
        return tzoffset(None, offset)

    # ===================== DATE PARSING ===================== #
    year = month = day = 1  # defaults
    tzinfo = None

    # Detect week format
    week_match = re.match(r"^(\d{4})(?:-?W)(\d{2})(?:(?:-?)(\d))?$", date_part)
    if week_match:
        year = int(week_match.group(1))
        week = int(week_match.group(2))
        wday = int(week_match.group(3)) if week_match.group(3) else 1  # default Monday
        try:
            dt_date = datetime.date.fromisocalendar(year, week, wday)
        except Exception as e:
            raise ValueError(f"Invalid ISO week date: {date_part}") from e
        year, month, day = dt_date.year, dt_date.month, dt_date.day
    else:
        # Common formats
        if re.match(r"^\d{4}$", date_part):
            year = int(date_part)
        elif re.match(r"^\d{6}$", date_part):
            year = int(date_part[:4])
            month = int(date_part[4:6])
        elif re.match(r"^\d{8}$", date_part):
            year = int(date_part[:4])
            month = int(date_part[4:6])
            day = int(date_part[6:8])
        elif re.match(r"^\d{4}-\d{2}$", date_part):
            year, month = map(int, date_part.split("-"))
        elif re.match(r"^\d{4}-\d{2}-\d{2}$", date_part):
            year, month, day = map(int, date_part.split("-"))
        else:
            raise ValueError(f"Unrecognized date format: {date_part!r}")

    # Validate date by constructing date object
    try:
        base_date = datetime.date(year, month, day)
    except Exception as e:
        raise ValueError(f"Invalid date components: {year}-{month}-{day}") from e

    # ===================== TIME PARSING ===================== #
    hour = minute = second = microsecond = 0

    if time_part is not None:
        # Separate timezone
        tz_suffix = None
        tz_match = re.search(r"(Z|[+-]\d{2}(?::?\d{2})?)$", time_part)
        if tz_match:
            tz_suffix = tz_match.group(1)
            time_without_tz = time_part[:tz_match.start()]
        else:
            time_without_tz = time_part

        # Parse time fields
        # Accept formats with or without ':'
        c = 0
        fields = []

        # Split by ':'
        if ":" in time_without_tz:
            fields = time_without_tz.split(":")
        else:
            # No separators: deduce length
            if len(time_without_tz) in (2, 4, 6):
                fields = [time_without_tz[i:i+2] for i in range(0, len(time_without_tz), 2)]
            else:
                raise ValueError(f"Unrecognized time format: {time_without_tz!r}")

        if not fields:
            raise ValueError(f"Empty time component")

        try:
            hour = int(fields[0])
        except Exception as e:
            raise ValueError(f"Invalid hour in time: {fields[0]!r}") from e

        if len(fields) > 1:
            try:
                minute = int(fields[1])
            except Exception as e:
                raise ValueError(f"Invalid minute in time: {fields[1]!r}") from e
        if len(fields) > 2:
            sec_part = fields[2]
            if "." in sec_part or "," in sec_part:
                sec_main, frac = re.split(r"[.,]", sec_part, maxsplit=1)
                second = int(sec_main)
                micro_str = (frac + "000000")[:6]
                microsecond = int(micro_str)
            else:
                second = int(sec_part)

        # Midnight rules
        if hour == 24:
            if minute != 0 or second != 0 or microsecond != 0:
                raise ValueError("24 hour must have zero minutes, seconds, and microseconds")
            hour = 0
            # Move to next day
            try:
                base_date = base_date + datetime.timedelta(days=1)
            except Exception as e:
                raise ValueError("Invalid date increment after midnight") from e

        try:
            tzinfo = parse_tz(tz_suffix) if tz_suffix else None
        except Exception as e:
            raise ValueError(f"Invalid timezone part: {tz_suffix}") from e

    # If no timezone specified, tzinfo stays None

    # ===================== COMBINE ===================== #
    try:
        dt = datetime.datetime(
            base_date.year,
            base_date.month,
            base_date.day,
            hour,
            minute,
            second,
            microsecond,
            tzinfo=tzinfo,
        )
    except Exception as e:
        raise ValueError(f"Failed to construct datetime: {e}") from e

    return dt
