def parse(self, timestr, default=None,
              ignoretz=False, tzinfos=None, **kwargs):
        """
        Simplified parser for a subset of datetime formats.
        """
        # Validate type
        if isinstance(timestr, datetime.datetime):
            # If default provided, merge naive fields (simplistic)
            if default is not None and isinstance(default, datetime.datetime):
                # Merge non-None attributes from parsed into default
                attrs = ['year', 'month', 'day', 'hour', 'minute',
                         'second', 'microsecond', 'tzinfo']
                new_kwargs = {a: getattr(default, a) for a in attrs}
                for a in attrs:
                    if getattr(timestr, a) is not None:
                        new_kwargs[a] = getattr(timestr, a)
                return datetime.datetime(**new_kwargs)
            return timestr
        if not isinstance(timestr, str):
            raise TypeError("timestr must be a string or datetime object")

        # Handle timezone parsing with tzinfos
        def replace_tzinfo(dt, tzname):
            tzinfo_val = tzinfos.get(tzname) if tzinfos else None
            if tzinfo_val is None:
                return dt
            if isinstance(tzinfo_val, int):
                # offset in seconds
                return dt.replace(tzinfo=datetime.timezone(datetime.timedelta(seconds=tzinfo_val)))
            if isinstance(tzinfo_val, datetime.tzinfo):
                return dt.replace(tzinfo=tzinfo_val)
            # Unsupported mapping
            raise ValueError(f"Unsupported tzinfo mapping for {tzname}")

        # Strip leading/trailing whitespace
        timestr = timestr.strip()

        # If string ends with a known tz name, handle it
        tokens = timestr.split()
        tzname = None
        if tokens and tzinfos and tokens[-1] in tzinfos:
            tzname = tokens.pop()
            timestr_no_tz = " ".join(tokens)
        else:
            timestr_no_tz = timestr

        # Try fromisoformat
        try:
            dt = datetime.datetime.fromisoformat(timestr_no_tz)
        except Exception:
            # Try common fallbacks
            parsed = None
            for fmt in ("%Y-%m-%d %H:%M:%S", "%Y-%m-%d %H:%M",
                        "%Y-%m-%d", "%m/%d/%Y %H:%M", "%m/%d/%Y"):
                try:
                    parsed = datetime.datetime.strptime(timestr_no_tz, fmt)
                    break
                except Exception:
                    continue
            if parsed is None:
                raise ValueError(f"Unable to parse datetime string: {timestr}")
            dt = parsed

        # Apply timezone if present
        if tzname:
            dt = replace_tzinfo(dt, tzname)

        # Apply ignoretz
        if ignoretz and dt.tzinfo is not None:
            dt = dt.replace(tzinfo=None)

        # Merge with default if provided
        if default is not None and isinstance(default, datetime.datetime):
            dt = datetime.datetime(
                default.year, default.month, default.day,
                dt.hour, dt.minute, dt.second, dt.microsecond,
                tzinfo=dt.tzinfo
            )

        return dt

def parse(self, timestr, default=None, ignoretz=False, tzinfos=None, **kwargs):
    """
    Minimal implementation of dateutil.parser.parse that parses dates
    in the form ``YYYY-MM-DD`` or ``YYYY-MM-DD HH:MM:SS[.ffffff]`` with
    an optional timezone abbreviation or name.  It accepts the same
    parameters as the real ``dateutil.parser.parse`` but only supports a
    subset of formats.
    """
    import re
    from datetime import datetime, timedelta, timezone

    # Internal helper: convert a tzinfo-like object to datetime.tzinfo
    def _get_tzinfo(name, offset):
        """Return a tzinfo instance corresponding to ``offset`` seconds."""
        if isinstance(offset, int):
            return timezone(timedelta(seconds=offset), name=name)
        if isinstance(offset, timezone):
            return offset
        # Fall back to naive tzinfo if something unexpected
        return None

    # Validate input
    if timestr is None or not isinstance(timestr, str):
        raise TypeError("timestr must be a string")

    if default is not None and not isinstance(default, datetime):
        raise TypeError("default must be a datetime instance or None")

    # Regular expression to capture date, time, and optional timezone
    pattern = re.compile(
        r"""^(?P<date>\d{4}-\d{2}-\d{2})?         # optional date
            (?:[ T](?P<time>\d{2}:\d{2}:\d{2}(?:\.\d{1,6})?))?   # optional time
            (?:[ ](?P<tzname>[A-Za-z/_-]+))?      # optional tz abbreviation
            $""",
        re.VERBOSE,
    )
    m = pattern.match(timestr.strip())
    if not m:
        raise ValueError(f"Unparseable string: {timestr!r}")

    # Parse date
    date_part = m.group("date")
    if date_part:
        try:
            year, month, day = map(int, date_part.split("-"))
        except Exception:
            raise ValueError(f"Invalid date part in string: {timestr!r}")
    else:
        if default is None:
            raise ValueError(f"No date information and no default supplied: {timestr!r}")
        year, month, day = default.year, default.month, default.day

    # Parse time
    time_part = m.group("time")
    if time_part:
        try:
            # allow fractional seconds
            main, *_ = time_part.split(".") if "." in time_part else (time_part, None)
            hour, minute, second = map(int, main.split(":"))
            microsecond = 0
            if "." in time_part:
                frac = time_part.split(".")[1]
                microsecond = int((frac + "000000")[:6])
        except Exception:
            raise ValueError(f"Invalid time part in string: {timestr!r}")
    else:
        if default is None:
            raise ValueError(f"No time information and no default supplied: {timestr!r}")
        hour, minute, second, microsecond = (
            default.hour,
            default.minute,
            default.second,
            default.microsecond,
        )

    # Handle timezone
    tzinfo = None
    if not ignoretz:
        tzname = m.group("tzname")
        if tzname:
            # Check tzinfos mapping first
            if tzinfos and isinstance(tzinfos, dict) and tzname in tzinfos:
                offset = tzinfos[tzname]
                tzinfo = _get_tzinfo(tzname, offset)
            else:
                # As a very limited fallback, handle UTC and GMT
                if tzname.upper() in ("UTC", "GMT"):
                    tzinfo = timezone.utc
                else:
                    # Unknown tz, raise error
                    raise ValueError(f"Unknown timezone name: {tzname!r}")

    # Construct datetime
    try:
        dt = datetime(
            year, month, day, hour, minute, second, microsecond, tzinfo
        )
    except Exception as exc:
        raise ValueError(f"Failed to construct datetime: {exc}") from exc

    # Merge with default if supplied
    if default is not None and default is not dt:
        # If any component is missing in timestr, keep it from default
        # (Since we already used defaults for missing parts, this is a noop)
        pass

    return dt

