def format_dt(dt):
    """
    Format a datetime in the way that D* nodes expect.
    The expected format is ISO 8601 UTC time without microseconds,
    e.g. '2024-04-07T12:34:56Z'.
    """
    import datetime
    from datetime import timezone

    try:
        # Handle string input
        if isinstance(dt, str):
            try:
                # Attempt ISO format parsing (Python 3.7+)
                dt_obj = datetime.datetime.fromisoformat(dt)
            except Exception:
                # Fallback to common patterns
                for fmt in ("%Y-%m-%d %H:%M:%S", "%Y-%m-%dT%H:%M:%S"):
                    try:
                        dt_obj = datetime.datetime.strptime(dt, fmt)
                        break
                    except Exception:
                        dt_obj = None
                if dt_obj is None:
                    raise ValueError(f"Unable to parse datetime string: {dt}")

        # Handle timestamp (int or float)
        elif isinstance(dt, (int, float)):
            dt_obj = datetime.datetime.fromtimestamp(dt, tz=timezone.utc)

        # Handle datetime objects
        elif isinstance(dt, datetime.datetime):
            dt_obj = dt

        else:
            raise TypeError(f"Unsupported type for format_dt: {type(dt)}")

        # Ensure timezone-aware; assume UTC if naive
        if dt_obj.tzinfo is None:
            dt_obj = dt_obj.replace(tzinfo=timezone.utc)
        # Convert to UTC
        dt_utc = dt_obj.astimezone(timezone.utc)
        # Format without microseconds
        return dt_utc.strftime("%Y-%m-%dT%H:%M:%SZ")

    except Exception as exc:
        raise ValueError(f"format_dt error: {exc}")

def format_dt(dt):
    """
    Format a datetime in the way that D* nodes expect.
    The expected format is an ISO‑8601 string in UTC with milliseconds
    precision, e.g. "2023-07-21T15:30:45.123Z".
    """
    if dt is None:
        raise ValueError("dt cannot be None")

    # Ensure we are dealing with a datetime
    if not hasattr(dt, "astimezone") or not hasattr(dt, "tzinfo"):
        raise TypeError("dt must be a datetime.datetime instance")

    # If naive, assume UTC
    if dt.tzinfo is None:
        try:
            # Python 3.2+ provides timezone.utc
            import datetime as _dt
            dt = dt.replace(tzinfo=_dt.timezone.utc)
        except Exception:
            # Fallback if timezone is not available: treat as UTC
            class _UTC(_dt.tzinfo):
                def utcoffset(self, dt_):
                    return _dt.timedelta(0)
                def tzname(self, dt_):
                    return "Z"
                def dst(self, dt_):
                    return _dt.timedelta(0)
            dt = dt.replace(tzinfo=_UTC())

    # Convert to UTC
    try:
        dt_utc = dt.astimezone(_dt.timezone.utc)
    except Exception:
        # If astimezone not available, manually adjust using tzinfo
        dt_utc = dt
        if dt.tzinfo and hasattr(dt.tzinfo, "utcoffset"):
            offset = dt.tzinfo.utcoffset(dt)
            if offset:
                dt_utc = dt - offset

    # Format with milliseconds; Python >=3.6 supports timespec
    try:
        iso_str = dt_utc.isoformat(timespec="milliseconds")
    except TypeError:
        # Fallback for older Python versions
        iso_str = dt_utc.strftime("%Y-%m-%dT%H:%M:%S.%f")[:-3]

    # Ensure trailing 'Z' for UTC
    if iso_str.endswith("+00:00"):
        iso_str = iso_str.replace("+00:00", "Z")
    elif iso_str.endswith("Z"):
        pass
    else:
        iso_str += "Z"

    return iso_str

