def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    if not isinstance(text, str):
        return ''
    try:
        import re
        from html.parser import HTMLParser

        class LinkProcessor(HTMLParser):
            def __init__(self):
                super().__init__()
                self.result = []

            def handle_starttag(self, tag, attrs):
                lower_tag = tag.lower()
                attrs = list(attrs)
                if lower_tag == 'a':
                    # Convert attrs to dict for easy manipulation
                    attr_dict = dict(attrs)
                    if 'target' not in attr_dict:
                        attr_dict['target'] = '_blank'
                    if 'rel' not in attr_dict:
                        attr_dict['rel'] = 'noopener noreferrer'
                    # Reconstruct attrs list
                    attrs = list(attr_dict.items())
                parts = [f'<{tag}']
                for k, v in attrs:
                    parts.append(f' {k}="{v}"')
                # Self‑closing tags
                if tag.lower() in {
                    'area', 'base', 'br', 'col', 'embed',
                    'hr', 'img', 'input', 'link', 'meta',
                    'param', 'source', 'track', 'wbr'
                }:
                    parts.append(' />')
                else:
                    parts.append('>')
                self.result.append(''.join(parts))

            def handle_startendtag(self, tag, attrs):
                # Treat same as starttag but with a space and slash
                parts = [f'<{tag}']
                for k, v in attrs:
                    parts.append(f' {k}="{v}"')
                parts.append(' />')
                self.result.append(''.join(parts))

            def handle_endtag(self, tag):
                self.result.append(f'</{tag}>')

            def handle_data(self, data):
                url_pattern = re.compile(
                    r'\b((?:https?://|ftp://)[^\s<>"\'\\)]+)', re.I)

                def repl(match):
                    url = match.group(1)
                    return (
                        f'<a href="{url}" target="_blank" rel="noopener noreferrer">'
                        f'{url}</a>'
                    )

                self.result.append(url_pattern.sub(repl, data))

            def get_html(self):
                return ''.join(self.result)

        parser = LinkProcessor()
        parser.feed(text)
        return parser.get_html()
    except Exception:
        # In case of any unexpected error, return the original text
        return text

def fetch_content_type(url: str) -> Optional[str]:
    """
    Fetch the HEAD of the remote url to determine the content type.
    Returns the value of the 'Content-Type' header if available, otherwise None.
    Handles invalid URLs, network errors, and missing headers gracefully.
    """
    # Ensure the URL has a scheme; default to http if missing
    if not url.lower().startswith(("http://", "https://")):
        url = "http://" + url

    try:
        import urllib.request
        import urllib.error

        # Create a HEAD request (Python 3.3+ supports method keyword)
        req = urllib.request.Request(url, method="HEAD")
        with urllib.request.urlopen(req, timeout=10) as response:
            return response.getheader("Content-Type")
    except urllib.error.HTTPError as e:
        # HTTPError is still a response; try to extract header
        if hasattr(e, "getheader"):
            return e.getheader("Content-Type")
        return None
    except (urllib.error.URLError, ValueError, Exception):
        # Catch network errors, malformed URL, or any unexpected exception
        return None

