    # Try XRD (XML) parsing
    try:
        root = ET.fromstring(document)
    except Exception as e:
        raise ValueError(f"Unable to parse webfinger document: {e}")

    def localname(tag: str) -> str:
        return tag.split('}', 1)[-1] if '}' in tag else tag

    result: Dict[str, object] = {}

    # Subject
    subject_elem = next((child for child in root if localname(child.tag) == 'Subject'), None)
    if subject_elem is not None and subject_elem.text:
        result['subject'] = subject_elem.text.strip()

    # Aliases
    aliases = [child.text.strip() for child in root if localname(child.tag) == 'Alias' and child.text]
