    # Properties
    properties: Dict[str, str] = {}
    for prop in root.findall('.//'):
        if localname(prop.tag) == 'Property' and prop.text:
            rel = prop.attrib.get('rel')
            if rel:
                properties[rel] = prop.text.strip()
    if properties:
        result['properties'] = properties

    # Links
    links: list[dict] = []
    for link in root.findall('.//'):
        if localname(link.tag) == 'Link':
            href = link.attrib.get('href')
            rel = link.attrib.get('rel')
