            if href:
                link_dict: dict = {'href': href}
                if rel:
                    link_dict['rel'] = rel
                if t:
                    link_dict['type'] = t
                links.append(link_dict)
    if links:
        result['links'] = links

    if not result:
        raise ValueError("Unable to detect valid Diaspora webfinger format.")
    return result

