    Notes
    -----
    Any non‑existent or non‑directory paths are silently ignored.
    """
    import os

    # Normalize the directory list
    if isinstance(settings_dirs, (str, bytes)):
        dirs = [settings_dirs]
    else:
        try:
            dirs = list(settings_dirs)
        except Exception:
            raise TypeError("settings_dirs must be a string or an iterable of strings")

    matched_files = []

    for dir_path in dirs:
        if not isinstance(dir_path, str):
            continue
        try:
            if not os.path.isdir(dir_path):
                continue
            for entry in os.listdir(dir_path):
                full_path = os.path.join(dir_path, entry)
                if not os.path.isfile(full_path):
                    continue

                if spec_option:
                    if isinstance(spec_option, str):
                        if spec_option.startswith('.'):
                            if not entry.lower().endswith(spec_option.lower()):
                                continue
                        else:
                            if spec_option.lower() not in entry.lower():
                                continue
                    else:
                        # spec_option is not a string, skip filtering
                        pass

                matched_files.append(entry)
        except OSError:
            # Skip directories that can't be accessed
            continue

    matched_files.sort()
    return matched_files

def list_of_file_names(settings_dirs, spec_option):
    """
    Return a list of file paths found in the directories specified by `settings_dirs`.  
    `settings_dirs` can be a single path string or an iterable of path strings.  
    `spec_option` specifies a glob-style pattern. If `spec_option` is ``None`` or empty,
    all files are returned. The function returns the full path for each file and
    ignores directories.  
    Errors like nonexistent directories or invalid patterns are handled gracefully
    by skipping the problematic entries.  The resulting list is sorted alphabetically.
    """
    import os
    import glob
    # Normalize settings_dirs to a list of strings
    if isinstance(settings_dirs, (str, bytes)):
        dirs = [settings_dirs]
    else:
        try:
            dirs = list(settings_dirs)
        except Exception:
            raise TypeError("settings_dirs must be a string or an iterable of strings")

    if spec_option is None or spec_option == "":
        pattern = "*"
    else:
        pattern = spec_option

    found_files = []
    for d in dirs:
        if not isinstance(d, (str, bytes)):
            continue  # skip invalid directory entries
        # Ensure d is a directory
        if not os.path.isdir(d):
            continue
        # Build the glob pattern
        glob_pattern = os.path.join(d, pattern)
        try:
            # Use recursive glob if pattern contains **; otherwise normal glob
            files = glob.glob(glob_pattern, recursive=True)
        except Exception:
            continue
        for f in files:
            if os.path.isfile(f):
                found_files.append(f)
    # Return sorted list of file paths
    return sorted(found_files)

