        data = spec_content
    if data is None:
        raise IRValidatorException("Spec content is empty or could not be parsed.")
    if not isinstance(data, dict):
        raise IRValidatorException(f"Spec root must be a mapping/dict, got {type(data)}")
    # required fields for the spec
    required_fields = ["name", "steps"]
    missing = [field for field in required_fields if field not in data]
    if missing:
        raise IRValidatorException(f"Missing required fields in spec: {', '.join(missing)}")
    # additional basic validation for the 'steps' section
    steps = data["steps"]
    if not isinstance(steps, list):
        raise IRValidatorException("Spec 'steps' must be a list.")
    for idx, step in enumerate(steps):
        if not isinstance(step, dict):
            raise IRValidatorException(f"Step {idx} is not a dict.")
        if "name" not in step:
            raise IRValidatorException(f"Step {idx} missing required 'name' field.")
    return data

