    """Resolves the include dict directive in the spec files."""
    def _merge(base, new):
        for k, v in new.items():
            if k in base and isinstance(base[k], dict) and isinstance(v, dict):
                _merge(base[k], v)
            else:
                base[k] = v

    if not isinstance(parser_dict, dict):
        raise TypeError("parser_dict must be a dict")
    include_key = None
    for key in ("include_groups", "include"):
        if key in parser_dict:
            include_key = key
            break
    if include_key is None:
        return parser_dict
    include_val = parser_dict.pop(include_key)
    if isinstance(include_val, str):
        paths = [include_val]
    elif isinstance(include_val, (list, tuple)):
        paths = list(include_val)
    else:
        raise ValueError("include_groups must be a string or a list of strings")
    merged = dict(parser_dict)
    for p in paths:
        try:
            with open(p, "r", encoding="utf-8") as fp:
                inc_dict = json.load(fp)
        except Exception as exc:
            raise RuntimeError(f"Failed to load include file '{p}': {exc}") from exc
        if not isinstance(inc_dict, dict):
            raise TypeError(f"Included file '{p}' must contain a JSON object")
        _merge(merged, inc_dict)
    return merged

def _include_groups(self, parser_dict):
        """Resolves the include dict directive in the spec files."""
        import collections

        if not isinstance(parser_dict, dict):
            raise TypeError("parser_dict must be a dict")

        def _deep_merge(dest, src):
            """Recursively merge src dict into dest, overriding values."""
            for k, v in src.items():
                if k in dest and isinstance(dest[k], dict) and isinstance(v, collections.abc.Mapping):
                    dest[k] = _deep_merge(dict(dest[k]), v)
                else:
                    dest[k] = v
            return dest

        def _resolve_group(name, visited):
            if name not in parser_dict:
                raise KeyError(f"Included group '{name}' not found in parser_dict")
            if name in visited:
                cycle = " -> ".join(visited + [name])
                raise ValueError(f"Circular include detected: {cycle}")
            visited.append(name)

            # Work with a shallow copy so we don't alter the original dict
            raw_def = parser_dict[name]
            if not isinstance(raw_def, collections.abc.Mapping):
                return raw_def  # Non-dict values are returned as-is

            group_def = dict(raw_def)  # shallow copy
            include_val = group_def.pop("include", None)
            merged = {}

            if include_val is not None:
                # Handle include directives that can be string, list or dict
                def _include_item(item):
                    """Return a merged dict for a single include item."""
                    if isinstance(item, str):
                        return _resolve_group(item, visited.copy())
                    if isinstance(item, collections.abc.Mapping):
                        # Mapping of group -> fields list (or nested mapping)
                        merged_map = {}
                        for inc_key, inc_val in item.items():
                            if inc_key not in parser_dict:
                                continue  # silently ignore missing key
                            sub_def = parser_dict[inc_key]
                            if isinstance(inc_val, collections.abc.Sequence) and not isinstance(inc_val, str):
                                # Include only specified fields
                                if isinstance(sub_def, collections.abc.Mapping):
                                    sub_map = {f: sub_def.get(f) for f in inc_val if f in sub_def}
                                    merged_map = _deep_merge(merged_map, sub_map)
                            else:
                                # Full include of the referenced group
                                merged_map = _deep_merge(merged_map, _resolve_group(inc_key, visited.copy()))
                        return merged_map
                    if isinstance(item, collections.abc.Sequence):
                        # List of items (strings or mappings)
                        nested = {}
                        for sub in item:
                            nested = _deep_merge(nested, _include_item(sub))
                        return nested
                    # Unsupported type, ignore
                    return {}

                if isinstance(include_val, str):
                    merged = _resolve_group(include_val, visited.copy())
                elif isinstance(include_val, collections.abc.Mapping):
                    merged = _include_item(include_val)
                elif isinstance(include_val, collections.abc.Sequence):
                    merged = {}
                    for elem in include_val:
                        merged = _deep_merge(merged, _include_item(elem))
                else:
                    # Unsupported include type; ignore
                    merged = {}

            # Finally merge the group's own fields (overriding includes)
            merged = _deep_merge(merged, group_def)
            return merged

        # Resolve all groups in the parser_dict
        for key in list(parser_dict.keys()):
            try:
                parser_dict[key] = _resolve_group(key, [])
            except Exception:
                # Preserve original value if resolution fails
                pass
        # No explicit return value needed (modifies parser_dict in place)

def _include_groups(self, parser_dict):
        """Resolves the include dict directive in the spec files."""
        # Guard against non‑dict input
        if not isinstance(parser_dict, dict):
            return parser_dict

        # Find an include directive (either "$include" or "include")
        include_key = "$include" if "$include" in parser_dict else "include"
        include_value = parser_dict.pop(include_key, None)

        # Resolve the include value if present
        if include_value is not None:
            # Supported include value types: dict, list of dicts, or unsupported (ignored)
            if isinstance(include_value, dict):
                included_dict = include_value
            elif isinstance(include_value, list):
                included_dict = {}
                for inc in include_value:
                    if isinstance(inc, dict):
                        included_dict.update(inc)
            else:
                included_dict = {}

            # Recursively resolve any nested includes inside the included dict
            if included_dict:
                included_dict = self._include_groups(included_dict)

            # Merge the resolved includes into the current parser_dict
            parser_dict.update(included_dict)

        # Recursively walk nested structures to resolve any further include directives
        for key, value in list(parser_dict.items()):
            if isinstance(value, dict):
                parser_dict[key] = self._include_groups(value)
            elif isinstance(value, list):
                new_list = []
                for item in value:
                    if isinstance(item, dict):
                        new_list.append(self._include_groups(item))
                    else:
                        new_list.append(item)
                parser_dict[key] = new_list

        return parser_dict

