            else:
                default_val = getattr(info, 'default', None)
        except Exception:
            default_val = None
        if default_val is not None:
            val = default_val
        # 2. Environment variable fallback if defined
        if val is None:
            try:
                if isinstance(info, dict):
                    env_name = info.get('env')
                else:
                    env_name = getattr(info, 'env', None)
            except Exception:
