        defaults[key] = val
    return defaults

def get_spec_defaults(self):
    """
    Resolve arguments' values from spec and other sources.

    This method attempts to extract default values for arguments
    defined in the object's spec. It also merges defaults from a
    few potential alternative sources such as `default_overrides`
    and `env` attributes if they exist. The function is tolerant to
    missing or malformed data and will simply ignore any parts
    that cannot be processed.
    """
    defaults = {}

    # ----- Extract defaults from the spec -----
    try:
        spec = getattr(self, 'spec', None) or getattr(self, '_spec', None)
        if isinstance(spec, dict):
            args = spec.get('arguments', [])
        elif isinstance(spec, list):
            args = spec
        else:
            args = []

        for arg in args:
            # Handle both dict-like and object-like specifications
            if isinstance(arg, dict):
                name = arg.get('name')
                if name is not None:
                    defaults[name] = arg.get('default')
            else:
                name = getattr(arg, 'name', None)
                if name is not None:
                    defaults[name] = getattr(arg, 'default', None)
    except Exception:
        # Any error in reading the spec is silently ignored
        pass

    # ----- Merge defaults from 'default_overrides' if present -----
    try:
        overrides = getattr(self, 'default_overrides', None)
        if isinstance(overrides, dict):
            defaults.update(overrides)
    except Exception:
        pass

    # ----- Merge defaults from an 'env' mapping if present -----
    try:
        env = getattr(self, 'env', {})
        if isinstance(env, dict):
            for k, v in env.items():
                if k not in defaults:
                    defaults[k] = v
    except Exception:
        pass

    return defaults

