def validate_arg_deprecation(self, cli_args, answer_file_args):
    """Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """
    import warnings

    # Ensure the inputs are dictionaries (or None)
    if cli_args is not None and not isinstance(cli_args, dict):
        raise TypeError("cli_args must be a dict (or None)")
    if answer_file_args is not None and not isinstance(answer_file_args, dict):
        raise TypeError("answer_file_args must be a dict (or None)")

    cli_args = cli_args or {}
    answer_file_args = answer_file_args or {}

    # Retrieve the mapping of deprecated arguments (old_name -> new_name or None)
    deprecated_map = getattr(self, "deprecated_args", {})
    if not isinstance(deprecated_map, dict):
        # Nothing to validate if no mapping is provided
        return

    # Collect all keys from both argument sources
    all_keys = list(cli_args.keys()) + list(answer_file_args.keys())
    seen = set()

    # Emit warnings for deprecated arguments
    for key in all_keys:
        if key in seen:
            continue
        if key in deprecated_map:
            replacement = deprecated_map[key]
            if replacement:
                msg = f"Argument '{key}' is deprecated. Use '{replacement}' instead."
            else:
                msg = f"Argument '{key}' is deprecated and will be removed in a future version."
            warnings.warn(msg, DeprecationWarning)
            seen.add(key)

    # Emit warnings if both a deprecated key and its replacement are present
    for old, new in deprecated_map.items():
        if new:  # only check when there is a replacement name
            if old in cli_args and new in cli_args:
                warnings.warn(
                    f"Both deprecated argument '{old}' and its replacement '{new}' are set in the CLI."
                    f" Consider removing the deprecated '{old}'.",
                    RuntimeWarning)
            if old in answer_file_args and new in answer_file_args:
                warnings.warn(
                    f"Both deprecated argument '{old}' and its replacement '{new}' are set in the answer file."
                    f" Consider removing the deprecated '{old}'.",
                    RuntimeWarning)

def validate_arg_deprecation(self, cli_args, answer_file_args):
    """Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """
    # Ensure inputs are dictionaries
    if not isinstance(cli_args, dict):
        raise TypeError(f"cli_args must be a dict, got {type(cli_args).__name__}")
    if not isinstance(answer_file_args, dict):
        raise TypeError(f"answer_file_args must be a dict, got {type(answer_file_args).__name__}")

    # Retrieve deprecated argument mapping; default to empty dict if not defined
    deprecated_map = getattr(self, "deprecated_arguments", {})
    if not isinstance(deprecated_map, dict):
        raise TypeError(f"deprecated_arguments must be a dict, got {type(deprecated_map).__name__}")

    # Merge answer file arguments and CLI arguments (CLI takes precedence)
    merged_args = {**answer_file_args, **cli_args}

    # Identify deprecated arguments that are actually used
    used_deprecated = []
    for arg in merged_args:
        if arg in deprecated_map:
            # Skip warning if the recommended new argument is also present
            new_arg = deprecated_map[arg]
            if new_arg and new_arg in merged_args:
                continue
            used_deprecated.append((arg, new_arg))

    # If any deprecated arguments are used, notify the user
    if used_deprecated:
        import sys
        for deprecated, new in used_deprecated:
            if new:
                message = f"Warning: Argument '{deprecated}' is deprecated. Use '{new}' instead."
            else:
                message = f"Warning: Argument '{deprecated}' is deprecated."
            # Print to stderr so it doesn't interfere with normal output
            print(message, file=sys.stderr)

def validate_arg_deprecation(self, cli_args, answer_file_args):
        """Validates and prints the deprecated arguments.

        :param cli_args: the dict of arguments from cli
        :param answer_file_args:  the dict of arguments from files
        """
        import warnings

        # Ensure input types are dicts; allow None or missing values gracefully
        if cli_args is None:
            cli_args = {}
        if answer_file_args is None:
            answer_file_args = {}

        if not isinstance(cli_args, dict):
