        if not isinstance(answer_file_args, dict):
            raise TypeError(f"answer_file_args must be a dict, got {type(answer_file_args).__name__}")

        # Deprecated arguments mapping: key -> replacement name
        # If the class has no such attribute, we treat there as no deprecations.
        deprecated_map = getattr(self, "deprecated_args", {})
        if not isinstance(deprecated_map, dict):
            raise TypeError(f"deprecated_args must be a dict if defined, got {type(deprecated_map).__name__}")

        warned_keys = set()

        # Helper to warn about a specific key
        def warn_for(key, source):
            if key in warned_keys:
                return
            replacement = deprecated_map.get(key)
            if replacement:
                msg = f"Argument '{key}' is deprecated (used in {source}). Use '{replacement}' instead."
            else:
                msg = f"Argument '{key}' is deprecated (used in {source})."
            warnings.warn(msg, DeprecationWarning)
            warned_keys.add(key)

        # Check CLI arguments
        for key in cli_args:
            if key in deprecated_map:
                warn_for(key, "CLI")

        # Check answer file arguments, avoid duplicate warnings
        for key in answer_file_args:
            if key in deprecated_map and key not in warned_keys:
                warn_for(key, "Answer file")

        # No value is returned; side-effect is warnings.

def validate_arg_deprecation(self, cli_args, answer_file_args):
