    """
    # Validate input type
    if not isinstance(command_name, str):
        raise TypeError(f"command_name must be a string, got {type(command_name).__name__}")

    # Attempt to retrieve the options mapping.  Use getattr to avoid attribute errors
    try:
        command_options = getattr(self, "_command_options", None)
        if command_options is None:
            raise AttributeError
    except AttributeError:
        raise RuntimeError(
            "The object does not contain a '_command_options' attribute that holds command configurations."
        )

    # Ensure command exists
    if command_name not in command_options:
        raise ValueError(f"Unknown command '{command_name}'. Available commands: {sorted(command_options)}")

    # Safely retrieve the options; allow None or non-iterable values
    options = command_options.get(command_name)
    if options is None:
        return []

    # If options is a list/tuple/set, return a new list; otherwise try to iterate and collect
    if isinstance(options, (list, tuple, set)):
        return list(options)
    else:
        try:
            return list(options)
        except TypeError:
            # If it's a single option or any non-iterable, wrap it in a list
            return [options] if options is not None else []

