    # Extract option strings from the parser's actions
    try:
        option_set = set()
        for action in getattr(parser, "_actions", []):
            # `option_strings` attribute holds the list of flags for an action
            option_strings = getattr(action, "option_strings", None)
            if option_strings:
                # Add each option string (short or long forms) to the set
                for opt in option_strings:
                    if opt:  # ignore empty strings just in case
                        option_set.add(opt)
    except Exception as exc:
        raise RuntimeError(f"Failed to parse options from the parser for "
                           f"command '{command_name}': {exc}") from exc

    # Return a sorted list of unique option strings
    return sorted(option_set)

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name.
    Returns the option spec if found, otherwise None.
    """
    # Validate arguments
    if command_name is None or argument_name is None:
        return None

    # Resolve command key: use a string representation
    if isinstance(command_name, str):
        command_key = command_name
    else:
        command_key = getattr(command_name, "__name__", None) \
                      or getattr(command_name, "name", None) \
                      or str(command_name)

    # Retrieve the command registry; fall back to an empty dict
    cmd_registry = getattr(self, "commands", None) or getattr(self, "registry", None) or {}
    if not isinstance(cmd_registry, dict):
        cmd_registry = {}

    # Find the command specification
    command_spec = cmd_registry.get(command_key)
    if command_spec is None:
        # Try searching by name attribute on spec objects
        for spec in cmd_registry.values():
            if getattr(spec, "name", None) == command_key or getattr(spec, "command_name", None) == command_key:
                command_spec = spec
                break
        if command_spec is None:
            return None

    # Extract the options mapping from the command spec
    if isinstance(command_spec, dict):
        options = command_spec.get("options", {})
    else:
        options = getattr(command_spec, "options", {})

    if not isinstance(options, dict):
        options = {}

    # Look up the argument name (case‑insensitive fallback)
    option_spec = options.get(argument_name)
    if option_spec is None:
        for key, spec in options.items():
            if key.lower() == argument_name.lower():
                option_spec = spec
                break

    return option_spec

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name."""
    # Validate input types
    if not isinstance(command_name, str):
        raise TypeError(f"command_name must be a string, got {type(command_name).__name__}")
    if not isinstance(argument_name, str):
        raise TypeError(f"argument_name must be a string, got {type(argument_name).__name__}")

    # Ensure the commands mapping exists
    if not hasattr(self, 'commands') or not isinstance(self.commands, dict):
        raise AttributeError("The object does not have a 'commands' dictionary attribute")

    # Retrieve the command configuration
    try:
        cmd_cfg = self.commands[command_name]
    except KeyError as exc:
        raise KeyError(f"Command '{command_name}' not found in available commands") from exc

    # Attempt to find the option specification
    try:
        # Direct mapping: command->argument->spec
        if isinstance(cmd_cfg, dict) and argument_name in cmd_cfg:
            return cmd_cfg[argument_name]
        # Nested under an 'options' key
        if isinstance(cmd_cfg, dict) and 'options' in cmd_cfg:
            options_section = cmd_cfg['options']
            if isinstance(options_section, dict) and argument_name in options_section:
                return options_section[argument_name]
        # If not found, raise
        raise KeyError()
    except KeyError as exc:
        raise KeyError(f"Specification for option '{argument_name}' in command '{command_name}' not found") from exc

def get_silent_args(self, args):
    """
    Return the names of arguments that are considered "silent".

    An argument is considered silent if its value is None, False, an empty string,
    or an empty collection (list, tuple, set, dict).  The argument collection
    can be a mapping, an object with a __dict__ attribute (e.g., argparse.Namespace),
    or an iterable of 2‑item tuples (e.g., produced by zip or a list of key/value
    pairs).  Invalid input types raise a TypeError.

    :param args: The received arguments; may be a mapping, a namespace-like
                 object, or an iterable of (key, value) pairs.
    :return: list of names (keys) whose values are considered silent.
    """
    if args is None:
        return []

    # Convert the input into a dictionary if possible
    if isinstance(args, dict):
        data = args
    elif hasattr(args, "__dict__"):
        try:
            data = vars(args)
        except Exception as exc:
            raise TypeError("Failed to extract arguments from the object") from exc
    elif isinstance(args, list) or isinstance(args, tuple):
        # Accept list/tuple of 2‑item sequences
        try:
            data = dict(args)
        except Exception as exc:
            raise TypeError("Argument list must contain (key, value) tuples") from exc
    else:
        raise TypeError("args must be a mapping, namespace, or sequence of (key, value) pairs")

    if not isinstance(data, dict):
        raise TypeError("Unable to interpret args as a dictionary of arguments")

    silent_names = []
    for key, value in data.items():
        if value is None or value is False:
            silent_names.append(key)
        elif isinstance(value, str) and value == "":
            silent_names.append(key)
        elif isinstance(value, (list, tuple, set, dict)) and len(value) == 0:
            silent_names.append(key)

    return silent_names

def get_silent_args(self, args):
    """list of silenced argument

    :param args: The received arguments.
    :return: list, silenced argument names
    """
    silent = []

    try:
        # Handle mapping types (e.g., dict)
        if hasattr(args, 'items'):
            for key, value in args.items():
                # Consider empty or False values as silent
                if value is None or value == '' or (isinstance(value, bool) and value is False):
                    silent.append(key)
                else:
                    # Also treat keys that explicitly indicate quiet/silent
                    lk = key.lower()
                    if lk in ('quiet', 'silent', 'quietness'):
                        silent.append(key)

        # Handle iterable types (list, tuple, set, etc.)
        elif isinstance(args, (list, tuple, set)):
            for item in args:
                # Handle key-value pairs
                if isinstance(item, tuple) and len(item) == 2:
                    key, value = item
                    if value is None or value == '' or (isinstance(value, bool) and value is False):
                        silent.append(key)
                    else:
                        lk = key.lower()
                        if lk in ('quiet', 'silent', 'quietness'):
                            silent.append(key)
                # Handle simple flag strings
                elif isinstance(item, str):
                    il = item.lower()
                    if il in ('-q', '-quiet', '--quiet'):
                        silent.append(item)
        # Unsupported types are ignored
    # Gracefully handle any exception (e.g., if args is not iterable)
    except Exception:
        pass

    return silent

def get_silent_args(self, args):
    """
    list of silenced argument

    :param args: The received arguments.
    :return: list, slienced argument names
    """
    # List of keywords that usually indicate a sensitive argument
    silent_keywords = (
        "password", "pass", "pwd", "secret", "token",
        "key", "auth", "authorization", "apikey", "api_key", "api_token",
        "credential", "credentials",
    )

    if args is None:
        return []

    try:
        silent_keys = []

        def record(key):
            """Add a key to silent_keys preserving order and uniqueness."""
            if key not in silent_keys:
                silent_keys.append(key)

        # Handle dictionary of arguments
        if isinstance(args, dict):
            for key in args.keys():
                if isinstance(key, str) and any(k in key.lower() for k in silent_keywords):
                    record(key)

        else:
            # Assume iterable (list/tuple) of key/value pairs or key strings.
            for item in args:
                if isinstance(item, tuple) and len(item) >= 1:
                    key = item[0]
                else:
                    key = item
                if isinstance(key, str) and any(k in key.lower() for k in silent_keywords):
                    record(key)

        return silent_keys
    except Exception:
        # On any unexpected error, return an empty list to avoid breaking callers.
        return []

def get_silent_args(self, args):
    """list of silenced argument

    :param args: The received arguments.
    :return: list, slienced argument names
    """
    try:
        # If args is None, nothing to process
        if args is None:
            return []

        # If args is a mapping (like dict), return keys where value is None
        if hasattr(args, "items"):
            return [k for k, v in args.items() if v is None]

        # If args is a sequence (list, tuple, set), handle various shapes
        if isinstance(args, (list, tuple, set)):
            silent = []
            for item in args:
                # If item is a (name, value) pair, check the value
                if isinstance(item, tuple) and len(item) >= 2:
                    if item[1] is None:
                        silent.append(item[0])
                else:
                    # Treat non-tuple items as argument names to silence
                    silent.append(item)
            return silent

        # For any other type, return an empty list
        return []
    except Exception:
        # On unexpected errors, return an empty list as a safe fallback
        return []

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided. """
    # Ensure args is a mapping like dictionary
    if args is None:
        raise TypeError("args cannot be None")
    if not isinstance(args, dict):
        raise TypeError("args must be a dictionary mapping argument names to values")
    # Determine the list of required arguments. Prefer an attribute named 'required_args',
    # but fall back to 'requires_args' if it exists, and finally to an empty list.
    required = getattr(self, "required_args", None)
    if required is None:
        required = getattr(self, "requires_args", [])
    if not isinstance(required, (list, tuple, set)):
        raise TypeError("required_args must be a list, tuple, or set of argument names")
    # Find any missing required arguments
    missing = [arg for arg in required if arg not in args]
    if missing:
        missing_str = ", ".join(sorted(missing))
        raise ValueError(f"Missing required argument(s): {missing_str}")
    return True

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided."""
    # Validate the input type
    if args is None:
        raise ValueError("Argument 'args' cannot be None.")
    if not isinstance(args, dict):
        raise TypeError(f"Expected 'args' to be a dict, got {type(args).__name__}.")

    # Retrieve the list or set of required argument names
    required = getattr(self, "required_args", None)
    if required is None:
        # If no required attributes defined, nothing to validate
        return True

    # Ensure required is iterable
    try:
        iter(required)
    except TypeError:
        raise TypeError("Attribute 'required_args' must be an iterable of argument names.")

    # Find any missing arguments
    missing = [name for name in required if name not in args]
    if missing:
        missing_str = ", ".join(missing)
        raise ValueError(f"Missing required arguments: {missing_str}.")

    return True

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided."""
    # Determine which attributes on self describe required arguments.
    # We try a few common names: required_args, required_parameters, required.
    # If none are found, assume no specific required arguments.
    required = getattr(self, "required_args", None)
    if required is None:
        required = getattr(self, "required_parameters", None)
    if required is None:
        required = getattr(self, "required", None)
    # If still None, no required arguments to check.
    if required is None:
        return

    # Ensure required is an iterable of names.
    if not isinstance(required, (list, tuple, set)):
        try:
            required = list(required)
        except Exception:
            raise TypeError("The 'required' attribute must be an iterable of argument names.")

    # Validate that args is supplied.
    if args is None:
        raise TypeError("Argument 'args' cannot be None.")

    # Determine whether args is a mapping or a regular object.
    is_mapping = isinstance(args, dict)

    missing = []
    for name in required:
        if is_mapping:
            if name not in args:
                missing.append(name)
        else:
            # For non-mappings we consider an attribute missing if it
            # does not exist or if its value is None.
            if not hasattr(args, name):
                missing.append(name)
            elif getattr(args, name) is None:
                missing.append(name)

    if missing:
        raise ValueError(f"Missing required arguments: {', '.join(missing)}")
    # If all required arguments are present, simply return None.

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided."""
    # Ensure args is a dictionary
    if args is None:
        args = {}
    if not isinstance(args, dict):
        raise TypeError("`args` must be a dictionary or None.")
    # Retrieve the list of required argument names
    required = getattr(self, "required", None)
    if required is None:
        required = getattr(self, "required_args", None)
    if required is None:
        raise AttributeError("No `required` or `required_args` attribute found on the instance.")
    # Ensure required is iterable
    try:
        iter(required)
    except Exception:
        raise TypeError("`required` must be an iterable of argument names.")
    # Determine missing arguments (not present or value is None)
    missing = [name for name in required if name not in args or args[name] is None]
    # If any required argument is missing, return False
    if missing:
        return False
    return True

