def _get_conditionally_required_args(self, command_name, options_spec, args):
        """
        List arguments with ``required_when`` condition matched.

        :param command_name: the command name.
        :param options_spec:  the list of command spec options.
        :param args: the received input arguments
        :return: list, list of argument names with matched ``required_when`` condition
        """
        # Validate inputs
        if not isinstance(options_spec, (list, tuple)):
            return []
        if not isinstance(args, dict):
            args = {}

        matched = []
        for opt in options_spec:
            # Each option should at least have a name to refer to it
            name = opt.get("name")
            if not name:
                continue

            cond = opt.get("required_when")
            if cond is None:
                continue

            try:
                # Normalise condition to a list for convenient processing
                if isinstance(cond, str):
                    cond_list = [cond]
                elif isinstance(cond, (list, tuple)):
                    cond_list = list(cond)
                else:
                    cond_list = None

                if cond_list is not None:
                    # Assume a list of other options that must be present (and truthy)
                    if all(key in args and bool(args.get(key)) for key in cond_list):
                        matched.append(name)
                elif callable(cond):
                    # If ``required_when`` is a callable, invoke it with the args and
                    # command name. It should return a boolean.
                    if cond(args, command_name):
                        matched.append(name)
                else:
                    # Unsupported type; skip
                    continue
            except Exception:
                # Any error evaluating the condition means it does not match
                continue

        return matched

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """
    List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when`` condition
    """
    # Ensure args is a dict for key lookup
    try:
        args_dict = dict(args)
    except Exception:
        # In case args is not dict-like, treat as empty
        args_dict = {}

    required = []

    for spec in options_spec:
        # Skip invalid spec entries
        if not isinstance(spec, dict):
            continue

        arg_name = spec.get("name") or spec.get("argument") or spec.get("param")
        if not arg_name:
            continue

        cond = spec.get("required_when")
        if cond is None:
            continue

        matched = False
        try:
            # Case: condition is a callable
            if callable(cond):
                matched = bool(cond(args_dict))

            # Case: condition is a string expression
            elif isinstance(cond, str):
                # Use eval with args as local variables
                matched = bool(eval(cond, {}, args_dict))

            # Case: condition is a list/tuple/set of argument names
            elif isinstance(cond, (list, tuple, set)):
                # All specified args must be truthy
                matched = all(bool(args_dict.get(name)) for name in cond)

            # Case: condition is a dict of name: value pairs
            elif isinstance(cond, dict):
                matched = all(args_dict.get(k) == v for k, v in cond.items())

            else:
                # Unsupported condition type: ignore
                matched = False
        except Exception:
            # If any error during evaluation, treat as not matched
            matched = False

        if matched:
            required.append(arg_name)

    return required

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    Parameters:
        args (dict): The received arguments where keys are parameter names
            and values are the corresponding values. Strings (or lists/tuples
            of strings) will be validated against the maximum length. The
            maximum length can be set on the instance via an attribute
            ``MAX_LENGTH``; if not present, a default of 255 is used.

    Raises:
        TypeError: If ``args`` is not a dictionary.
        ValueError: If any string value exceeds the allowed length. The
            exception message contains details about each offending
            argument.

    Returns:
        None
    """
    if not isinstance(args, dict):
        raise TypeError(f"args must be a dict, got {type(args).__name__}")

    max_len = getattr(self, "MAX_LENGTH", 255)
    errors = {}

    for key, value in args.items():
        # Check simple string values
        if isinstance(value, str):
            if len(value) > max_len:
                errors[key] = f"Length {len(value)} exceeds maximum {max_len}"
        # Check lists or tuples of strings
        elif isinstance(value, (list, tuple)):
            for idx, item in enumerate(value):
                if isinstance(item, str) and len(item) > max_len:
                    errors.setdefault(key, []).append(
                        f"Index {idx} length {len(item)} exceeds maximum {max_len}"
                    )
        # For all other types, no length validation is performed
        else:
            continue

    if errors:
        raise ValueError(f"Length validation failed: {errors}")

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    if args is None:
        return True

    # Normalize args to a mapping
    if isinstance(args, dict):
        arg_map = args
    elif isinstance(args, list):
        arg_map = {}
        for item in args:
            if isinstance(item, (list, tuple)) and len(item) == 2:
                arg_map[item[0]] = item[1]
            else:
                raise TypeError("List elements must be 2-tuples of (name, value).")
    elif hasattr(args, "__dict__"):  # e.g., argparse.Namespace
        arg_map = vars(args)
    else:
        raise TypeError(
            "Unsupported args type: expected dict, list of 2-tuples, or Namespace object."
        )

    # Retrieve the mapping of argument names to maximum lengths
    max_len_map = getattr(self, "max_lengths", None)
    if not isinstance(max_len_map, dict):
        # No length restrictions defined; nothing to validate
        return True

    # Validate each argument against its max length
    for name, max_len in max_len_map.items():
        value = arg_map.get(name)
        if value is None:
            continue  # No value supplied; skip
        if isinstance(value, str):
            try:
                length = len(value)
            except Exception:
                continue  # Cannot determine length; skip
            if max_len is not None and length > max_len:
                raise ValueError(
                    f"Argument '{name}' length ({length}) exceeds maximum allowed ({max_len})."
                )
    return True

def validate_length_args(self, args):
    """Check if the value of arguments is not longer than the length specified.

    The method inspects ``args`` and ensures that for each argument the
    length of its value does not exceed the limit that is defined either
    globally via ``self.max_length`` or per‑argument via ``self.length_limits``.
    No return value is needed; a :class:`ValueError` is raised when an
    argument exceeds its allowed length.

    :param args: The received arguments.  This may be a mapping of
                 argument names to values, a sequence of values, or a
                 single value.
    """
    # Determine a per-argument length limit mapping, if available.
    # ``self.length_limits`` should be a mapping ``name -> max_len``.
    # If it doesn't exist or is not a mapping, we fall back to a single
    # global ``self.max_length`` value.
    length_limits = {}
    if hasattr(self, "length_limits") and isinstance(self.length_limits, dict):
        length_limits = self.length_limits

    global_max = getattr(self, "max_length", None)

    def _check_one(name, value):
        """Check a single value against the appropriate limit."""
        limit = length_limits.get(name, global_max)
        if limit is None:
            # No limit defined; nothing to validate.
            return
        # Some objects may not support len(); ignore those.
        try:
            val_len = len(value)
        except Exception:
            return
        if val_len > limit:
            raise ValueError(
                f"Argument '{name}' length {val_len} exceeds maximum allowed {limit}"
            )

    # Handle various possible types for ``args``.
    if isinstance(args, dict):
        for key, val in args.items():
            _check_one(key, val)
    elif isinstance(args, (list, tuple)):
        for idx, val in enumerate(args):
            # For positional arguments we use the index as the name
            _check_one(f"arg{idx}", val)
    else:
        # A single value; use a generic name.
        _check_one("value", args)
    # No return; the method will raise ValueError if a violation occurs.

def validate_choices_args(self, args):
        """
        Check if value of choice arguments is one of the available choices.

        :param args: The received arguments. It can be a mapping (like a dict) or an object
                     with attributes (e.g., argparse.Namespace).
        :raises TypeError: If the provided `args` is not compatible with the expected
                           interface or if the internal `choices` configuration is malformed.
        :raises ValueError: If any argument is present in the provided `args` but its
                            value(s) are not among the allowed choices.
        """
        # Retrieve the mapping of argument names to allowed choice lists.
        choices = getattr(self, "choices", None)
        if choices is None:
            # No choices defined; nothing to validate.
            return
        if not isinstance(choices, dict):
            raise TypeError(f"Expected self.choices to be a dict, got {type(self.choices).__name__}")

        # Helper to fetch a value from the provided args object.
        def _get_value(arg_name):
            if isinstance(args, dict):
                return args.get(arg_name)
            # For argparse.Namespace or similar objects.
            if hasattr(args, "__dict__"):
                return getattr(args, arg_name, None)
            # Fallback: try to use mapping protocol
            if hasattr(args, "get"):
                return args.get(arg_name)
            raise TypeError("The provided args object is not a dict or a namespace-style object.")

        for arg_name, allowed in choices.items():
            # Skip validation if the allowed choices are not iterable or empty.
            if allowed is None or not hasattr(allowed, "__iter__"):
                continue
            # Normalize allowed values to a set for efficient membership checks.
            allowed_set = set(allowed)

            try:
                val = _get_value(arg_name)
            except Exception:
                # If we cannot fetch the value, skip validation for this arg.
                continue

            if val is None:
                # Optional argument not supplied; skip.
                continue

            # Handle iterable values (e.g., list, tuple) separately.
            if isinstance(val, (list, tuple, set)):
                invalid = [v for v in val if v not in allowed_set]
                if invalid:
                    raise ValueError(
                        f"Argument '{arg_name}': values {invalid} are not among the allowed choices {allowed}"
                    )
                continue

            # Single scalar value.
            if val not in allowed_set:
                raise ValueError(
                    f"Argument '{arg_name}': value '{val}' is not among the allowed choices {allowed}"
                )
        # All choices validated successfully. Nothing to return.

def validate_choices_args(self, args):
    """
    Check if value of choice arguments is one of the available choices.

    :param args: The received arguments (could be a dict, a Namespace, or any object
                 with attributes corresponding to argument names).
    :raises ValueError: If an argument's value is not among its allowed choices.
    """
    # Determine where the allowed choices are stored.  Many command
    # libraries keep these in a dict of name -> list of choices; try
    # several common names.
    try:
        allowed = getattr(self, "choices", None)
    except Exception:
        allowed = None
    if allowed is None:
        try:
            allowed = getattr(self, "_choices", None)
        except Exception:
            allowed = None

    if not isinstance(allowed, dict):
        # No choices to validate against
        return

    # Normalize the received args to a mapping of argument name -> value.
    if isinstance(args, dict):
        args_map = args
    else:
        # Attempt to introspect an object like argparse.Namespace
        args_map = {}
        for key in dir(args):
            if key.startswith("_"):
                continue
            try:
                args_map[key] = getattr(args, key)
            except Exception:
                continue

    # Validate each argument that has defined choices
    for name, value in args_map.items():
        if name not in allowed:
            continue  # no restrictions on this argument
        if value is None:
            continue  # skip None, allowed by most arg parsers

        # If the argument accepts multiple values (list/tuple), check each element
        if isinstance(value, (list, tuple)):
            if not all(v in allowed[name] for v in value):
                raise ValueError(
                    f"Invalid choice for argument '{name}': {value}. "
                    f"Available choices: {allowed[name]}"
                )
        else:
            if value not in allowed[name]:
                raise ValueError(
                    f"Invalid choice for argument '{name}': {value}. "
                    f"Available choices: {allowed[name]}"
                )
    # If we reach here, all choice arguments are valid.  The method returns None.

def validate_choices_args(self, args):
        """Check if value of choice arguments is one of the available choices.

        :param args: The received arguments.
        """
        # Basic validation of input type
        if not isinstance(args, dict):
            raise TypeError(f"Expected args to be a dict, got {type(args).__name__}")

        # self._choices is expected to be a dict mapping argument names to
        # iterable of allowed values. If not defined, nothing to validate.
        choices_map = getattr(self, "_choices", {})
        if not isinstance(choices_map, dict):
            raise TypeError(f"Expected self._choices to be a dict, got {type(choices_map).__name__}")

        for arg_name, allowed in choices_map.items():
            # Skip if this argument not supplied
            if arg_name not in args:
                continue

            val = args[arg_name]

            # Provide support for list/tuple arguments (multiple selections)
            if isinstance(val, (list, tuple)):
                invalid = [v for v in val if v not in allowed]
                if invalid:
                    raise ValueError(
                        f"Invalid value(s) {invalid!r} for argument '{arg_name}'. "
                        f"Allowed values: {sorted(allowed)}"
                    )
            else:
                if val not in allowed:
                    raise ValueError(
                        f"Invalid value {val!r} for argument '{arg_name}'. "
                        f"Allowed values: {sorted(allowed)}"
                    )

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    Args:
        args: The received arguments (expected to be a mapping of argument names to values).

    Raises:
        TypeError: If ``args`` is not a mapping type.
        ValueError: If a value for a choice argument is not among the allowed choices.
    """
    # Basic input validation
    if not isinstance(args, dict):
        raise TypeError("args must be a dictionary of argument names to values")

    # Helper to get choices for a given argument name
    def get_choices(name):
        # Prefer an explicit `_choice_args` attribute if present
        if hasattr(self, "_choice_args"):
            ca = getattr(self, "_choice_args")
            if isinstance(ca, dict):
                return ca.get(name)
        # Fallback to an argument schema that may store a 'choices' list
        if hasattr(self, "_arg_schema"):
            schema = getattr(self, "_arg_schema")
            if isinstance(schema, dict) and name in schema:
                node = schema[name]
                if isinstance(node, dict):
                    return node.get("choices")
        return None

    # Iterate over provided arguments and validate against allowed choices
    for arg_name, value in args.items():
        choices = get_choices(arg_name)
        if choices is None:
            # No explicit choice constraint; nothing to check
            continue

        # If value is an iterable (list/tuple), validate each item
        if isinstance(value, (list, tuple)):
            for item in value:
                if item not in choices:
                    raise ValueError(
                        f"Invalid value for argument '{arg_name}': {item!r} "
                        f"not in allowed choices {choices}"
                    )
        else:
            if value not in choices:
                raise ValueError(
                    f"Invalid value for argument '{arg_name}': {value!r} "
                    f"not in allowed choices {choices}"
                )
    # No return value needed; the method raises if validation fails.

def validate_min_max_args(self, args):
        """Check if value of arguments is between minimum and maximum values.

        :param args: The received arguments.
        :type args: dict
        :raises TypeError: If the provided args is not a dict.
        :raises ValueError: If an argument value is outside its defined range.
        """
        # Validate input type
        if args is None:
            raise ValueError("Arguments cannot be None.")
        if not isinstance(args, dict):
            raise TypeError(f"Expected args to be a dict, got {type(args).__name__}")

        # Retrieve argument constraints from the instance; if not present, skip validation.
        constraints = getattr(self, "arg_constraints", {})
        if not isinstance(constraints, dict):
            # If constraints is not a dict, the validation cannot proceed sensibly.
            raise TypeError("Instance attribute 'arg_constraints' must be a dict mapping argument names to constraints.")

        for name, value in args.items():
            # Skip None values – no validation needed for missing values
            if value is None:
                continue

            # Get the constraint for the current argument, if any
            constraint = constraints.get(name)
            if constraint is None:
                # No constraints defined for this argument; skip validation
                continue

            # Determine min and max from the constraint definition
            min_val = None
            max_val = None

            if isinstance(constraint, dict):
                min_val = constraint.get("min")
                max_val = constraint.get("max")
            elif isinstance(constraint, (tuple, list)):
                # Expect a 2‑element sequence: (min, max)
                if len(constraint) == 2:
                    min_val, max_val = constraint
            else:
                # Unsupported constraint format
                raise TypeError(f"Unsupported constraint type for argument '{name}': {type(constraint).__name__}")

            # Validate that value is numeric
            if not isinstance(value, (int, float)):
                raise TypeError(f"Value for argument '{name}' must be numeric, got {type(value).__name__}")

            # Perform range checks, if bounds are specified
            if min_val is not None and value < min_val:
                raise ValueError(
                    f"Value for argument '{name}' ({value}) is below the minimum allowed ({min_val})."
                )
            if max_val is not None and value > max_val:
                raise ValueError(
                    f"Value for argument '{name}' ({value}) exceeds the maximum allowed ({max_val})."
                )

def validate_min_max_args(self, args):
        """Check if value of arguments is between minimum and maximum values.

        The method accepts an iterable of argument specifications. Each specification
        can be either a mapping (dict) with keys ``'value'``, ``'min'`` and ``'max'`` or
        a sequence (tuple/list) of three elements ``(value, min, max)``. The method
        returns ``True`` only if for every specification ``min <= value <= max``;
        otherwise ``False``. Any malformed specification or type error will cause
        the method to return ``False`` rather than raising an exception.
        """
        if args is None:
            return False

        try:
            for spec in args:
                # Try to fetch into a tuple (value, min, max)
                if isinstance(spec, dict):
                    if not all(k in spec for k in ("value", "min", "max")):
                        return False
                    value, min_val, max_val = spec["value"], spec["min"], spec["max"]
                elif isinstance(spec, (list, tuple)):
                    if len(spec) != 3:
                        return False
                    value, min_val, max_val = spec
                else:
                    return False

                # Ensure numeric types
                if not all(isinstance(v, (int, float)) for v in (value, min_val, max_val)):
                    return False

                # Validate logical min <= max
                if min_val > max_val:
                    return False

                # Check value bounds
                if not (min_val <= value <= max_val):
                    return False
        except Exception:
            # Catch unexpected issues (like iteration failures) and return False
            return False

        return True

def validate_min_max_args(self, args):
    """
    Check if value of arguments is between minimum and maximum values.
    The class is expected to have `min_value` and `max_value` attributes.
    Raises ValueError if any argument is out of bounds,
    and TypeError if non-numeric arguments are encountered.
    """
    min_val = getattr(self, "min_value", None)
    max_val = getattr(self, "max_value", None)
    if min_val is None or max_val is None:
        raise AttributeError("Instance must define `min_value` and `max_value` attributes")
    if args is None:
        raise ValueError("Arguments cannot be None")

    invalid = []

    def _check(val, path=""):
        # Reject bool (subclass of int) and string
        if isinstance(val, bool):
            raise TypeError(f"Boolean values are not allowed: {val}")
        if isinstance(val, str):
            raise TypeError(f"String values are not allowed: '{val}'")
        if isinstance(val, (int, float)):
            if val < min_val or val > max_val:
                invalid.append((path or "value", val))
        elif isinstance(val, dict):
            for k, v in val.items():
                new_path = f"{path}.{k}" if path else f"{k}"
                _check(v, new_path)
        elif isinstance(val, (list, tuple, set)):
            for idx, v in enumerate(val):
                new_path = f"{path}[{idx}]" if path else f"[{idx}]"
                _check(v, new_path)
        else:
            raise TypeError(f"Unsupported argument type: {type(val).__name__} ({val})")

    try:
        _check(args)
    except TypeError as exc:
        raise

    if invalid:
        parts = []
        for p, v in invalid:
            parts.append(f"{p}={v}")
        raise ValueError(
            f"Values not in range [{min_val}, {max_val}]: " + ", ".join(parts)
        )
    # If we reach here, all values are within bounds
    return None

def create_complex_argumet_type(self, subcommand, type_name, option_name,
                                    spec_option):
        """Build the complex argument type

        :param subcommand: the command name
        :param type_name: the complex type name
