            if not isinstance(option_name, str):
                raise TypeError("option_name must be a string")
            if spec_option is None:
                spec_option = {}
            elif not isinstance(spec_option, dict):
                raise TypeError("spec_option must be a dictionary or None")
        except Exception as exc:
            # Provide clearer error message
            raise ValueError(f"Invalid input parameters: {exc}") from exc

        # Build the complex argument type representation.
        # Because no specific ComplexArgumentType class is provided in the
        # surrounding context, we represent the type as a dictionary.
        complex_type = {
            "subcommand": subcommand,
            "type_name": type_name,
            "option_name": option_name,
            "specifications": spec_option,
        }

        # Validation of required spec fields if any
        try:
            # Example: enforce that 'type' key is present in spec_option if provided
            if "type" in spec_option:
                if not isinstance(spec_option["type"], str):
                    raise ValueError("spec_option['type'] must be a string")
            # Example: if 'choices' present, it must be a list
            if "choices" in spec_option:
                if not isinstance(spec_option["choices"], (list, tuple)):
                    raise ValueError("spec_option['choices'] must be a list or tuple")
        except Exception as exc:
            raise ValueError(f"Invalid spec_option contents: {exc}") from exc

