def create_complex_argumet_type(self, subcommand, type_name, option_name,
                                spec_option):
    """
    Build the complex argument type

    :param subcommand: the command name (string)
    :param type_name: the complex type name (string)
    :param option_name: the option name (string)
    :param spec_option: option's specifications (dict or None)
    :return: the complex type instance
    """
    # Input validation
    try:
        if not isinstance(subcommand, str):
            raise TypeError(f"subcommand must be a string, got {type(subcommand).__name__}")
        if not isinstance(type_name, str):
            raise TypeError(f"type_name must be a string, got {type(type_name).__name__}")
        if not isinstance(option_name, str):
            raise TypeError(f"option_name must be a string, got {type(option_name).__name__}")
        if spec_option is not None and not isinstance(spec_option, dict):
            raise TypeError(f"spec_option must be a dict or None, got {type(spec_option).__name__}")
    except Exception as exc:
        # Re-raise with a clear message
        raise ValueError(f"Invalid arguments for create_complex_argumet_type: {exc}") from exc

    class ComplexArgumentType:
        """
        Simple holder for a complex argument type used by the command-line
        parser or schema builder.
        """
        def __init__(self, subcommand, type_name, option_name, spec_option):
            self.subcommand = subcommand
            self.type_name = type_name
            self.option_name = option_name
            self.spec_option = spec_option or {}

        def __repr__(self):
            return (f"<ComplexArgumentType subcommand={self.subcommand!r} "
                    f"type_name={self.type_name!r} "
                    f"option_name={self.option_name!r} "
                    f"spec_option={self.spec_option!r}>")

        def to_dict(self):
            """
            Convert the instance to a plain dictionary, suitable for
            serialization or further processing.
            """
            return {
                'subcommand': self.subcommand,
                'type_name': self.type_name,
                'option_name': self.option_name,
                'spec_option': self.spec_option
            }

    try:
        return ComplexArgumentType(subcommand, type_name, option_name, spec_option)
    except Exception as exc:
        raise RuntimeError(f"Failed to create complex argument type: {exc}") from exc

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    # Default return to avoid failures when args are None or malformed
    default_return = ({}, {})

    try:
        if not args:
            return default_return

        # Convert various input types to a dictionary
        if isinstance(args, dict):
            arg_dict = args
        elif isinstance(args, list):
            # list of key/value tuples
            if all(isinstance(item, tuple) and len(item) == 2 for item in args):
                arg_dict = {k: v for k, v in args}
            else:
                # list of strings like "--key=value"
                arg_dict = {}
                for item in args:
                    if not isinstance(item, str):
                        continue
                    if item.startswith("--"):
                        item = item[2:]
                    # Treat '--flag' as True
                    if "=" in item:
                        key, value = item.split("=", 1)
                        arg_dict[key] = value
                    else:
                        arg_dict[item] = True
        else:
            # Unsupported type
            return default_return

        # Known control keys that should not be written to the spec yml
        control_keys = {
            "help", "version", "debug", "verbose", "quiet", "quiet_mode", "quiet_all",
            "log", "log_file", "log_level",
            "output", "output_file", "format",
            "dry_run", "dry", "force", "force_overwrite",
            "config", "config_file",
            "inplace", "overwrite",
        }

        control_args = {}
        nested_args = {}
        for key, value in arg_dict.items():
            if key in control_keys:
                control_args[key] = value
            else:
                nested_args[key] = value

        return control_args, nested_args

    except Exception:
        # In case of any unexpected error, return empty dicts
        return default_return

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    control_args = {}
    nested_args = {}

    if args is None:
        return control_args, nested_args

    # Accept dict or sequence of key/value pairs
    def add_pair(k, v):
        if isinstance(k, str) and k.startswith("control_"):
            control_args[k] = v
        else:
            nested_args[k] = v

    try:
        if isinstance(args, dict):
            for k, v in args.items():
                add_pair(k, v)
        else:
            # Assume iterable of key/value pairs or strings
            for item in args:
                if isinstance(item, (list, tuple)) and len(item) == 2:
                    k, v = item
                    add_pair(k, v)
                elif isinstance(item, str):
                    # Try split on first '='
                    if "=" in item:
                        k, v = item.split("=", 1)
                        add_pair(k.strip(), v.strip())
                    else:
                        # Treat as flag with boolean True
                        add_pair(item.strip(), True)
                else:
                    # Unsupported format, skip
                    continue
    except Exception:
        # In case of any unexpected error, return what we have
        return control_args, nested_args

    return control_args, nested_args

def get_nested_custom_and_control_args(self, args):
    """
    Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.  It can be one of:
        * a dictionary of key/value pairs
        * a list of 2‑tuples (key, value)
        * a list of dictionaries
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    control_args = {}
    nested_args = {}

    def _add_nested(d, key_parts, value):
        """Recursively build nested dictionary from dotted key parts."""
        part = key_parts[0]
        if len(key_parts) == 1:
            d[part] = value
        else:
            if part not in d or not isinstance(d[part], dict):
                d[part] = {}
            _add_nested(d[part], key_parts[1:], value)

    if args is None:
        return control_args, nested_args

    # Normalize args into iterable of (key, value)
    items = []
    try:
        if isinstance(args, dict):
            items = list(args.items())
        elif isinstance(args, list):
            for item in args:
                if isinstance(item, tuple) and len(item) == 2:
                    items.append(item)
                elif isinstance(item, dict):
                    items.extend(item.items())
    except Exception:
        # If any unexpected format, just return empty dicts
        return control_args, nested_args

    for key, value in items:
        if not isinstance(key, str):
            # Skip invalid keys
            continue
        # Identify control arguments (prefix "control_" or known control keys)
        if key.startswith("control_"):
            # Strip the prefix if desired
            stripped = key[len("control_") :]
            control_args[stripped] = value
            continue

        # Determine if key uses dotted notation for nested arguments
        if "." in key:
            key_parts = key.split(".")
            _add_nested(nested_args, key_parts, value)
        else:
            nested_args[key] = value

    return control_args, nested_args

def get_nested_custom_and_control_args(self, args):
        """Split input arguments into control and nested arguments.

        Controls arguments: control the IR behavior. These arguments
            will not be put into the spec yml file
        Nested arguments: are used by the Ansible playbooks and will be put
            into the spec yml file.
        Custom arguments: Custom ansible variables to be used instead of the
            normal nested usage.

        :param args: the collected list or dict of args.
        :return: (dict, dict): flat dicts (control_args, nested_args)
        """
        control_args = {}
        nested_args = {}
        try:
            if args is None:
                return control_args, nested_args

            # Accept either dict or list of key/value tuples
            if isinstance(args, dict):
                items = args.items()
            elif isinstance(args, (list, tuple)):
                # Expect list of (key, value) tuples or a list of strings "key=value"
                items = []
                for item in args:
                    if isinstance(item, (list, tuple)) and len(item) == 2:
                        items.append((item[0], item[1]))
                    elif isinstance(item, str):
                        if '=' in item:
                            k, v = item.split('=', 1)
                            items.append((k.strip(), v.strip()))
                        else:
                            # Treat whole string as key with None value
                            items.append((item.strip(), None))
                    else:
                        raise TypeError(f"Unsupported item type: {type(item)}")
            else:
                raise TypeError(f"Unsupported args type: {type(args)}")

            for key, value in items:
                if not isinstance(key, str):
                    raise TypeError(f"Argument key must be a string, got {type(key)}")
                low_key = key.lower()
                if low_key.startswith('control_'):
                    # Keep original key name
                    control_args[key] = value
                elif low_key.startswith('custom_'):
                    # Custom args become nested args with prefix stripped
                    nested_key = key[7:]  # len('custom_')
                    nested_args[nested_key] = value
                else:
                    nested_args[key] = value
        except Exception as exc:
            raise ValueError(f"Failed to split nested/custom/control args: {exc}") from exc

        return control_args, nested_args

@staticmethod
    def merge_extra_vars(vars_dict, extra_vars=None):
        """Extend ``vars_dict`` with ``extra-vars``

        :param vars_dict: Dictionary to merge extra-vars into
        :param extra_vars: List of extra-vars
        """
        # Validate input dictionary
        if not isinstance(vars_dict, dict):
            raise TypeError(f"vars_dict must be a dict, got {type(vars_dict).__name__}")

        # Nothing to do if extra_vars is None or empty
        if not extra_vars:
            return vars_dict

        # Helper for JSON parsing
        try:
            from json import loads as json_loads
        except Exception:
            json_loads = None

        # Normalize extra_vars to an iterable
        if isinstance(extra_vars, dict):
            items = [extra_vars]
        else:
            try:
                iter(extra_vars)
                items = list(extra_vars)
            except TypeError:
                items = [extra_vars]

        for item in items:
            if isinstance(item, dict):
                # Directly update with dict
                vars_dict.update(item)
            elif isinstance(item, str):
                # Strip whitespace
                raw = item.strip()
                if not raw:
                    continue
                # Handle key=value pairs
                if '=' in raw:
                    key, val = raw.split('=', 1)
                    key = key.strip()
                    val = val.strip()
                    if json_loads:
                        try:
                            parsed_val = json_loads(val)
                            val = parsed_val
                        except Exception:
                            # If JSON parsing fails, keep original string
                            pass
                    vars_dict[key] = val
                else:
                    # If string has no '=' treat as boolean flag (True)
                    key = raw
                    vars_dict[key] = True
            else:
                # Unsupported types are ignored silently
                continue

        return vars_dict

@staticmethod
def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    :return: New dictionary containing merged values
    """
    # Validate vars_dict
    if vars_dict is None:
        vars_dict = {}
    if not isinstance(vars_dict, dict):
        raise TypeError("vars_dict must be a dict")

    # If no extra vars supplied, return a copy of the original dictionary
    if extra_vars is None:
        return dict(vars_dict)

    # Prepare a copy of the original dict to avoid mutating input
    merged = dict(vars_dict)

    # If extra_vars is a dict, update directly
    if isinstance(extra_vars, dict):
        merged.update(extra_vars)
        return merged

    # Handle string inputs as single item
    if isinstance(extra_vars, str):
        extra_items = [extra_vars]
    else:
        try:
            iter(extra_vars)
            extra_items = list(extra_vars)
        except TypeError:
            raise TypeError("extra_vars must be a dict, list, tuple, or any iterable of strings")

    for item in extra_items:
        if not isinstance(item, str):
            # Skip non-string entries silently
            continue
        if '=' not in item:
            # Skip invalid format silently
            continue

        key, value = item.split('=', 1)
        key = key.strip()
        value = value.strip()

        if not key:
            # Skip entries without a key
            continue

        # Attempt to interpret the value as JSON (handles numbers, booleans, lists, dicts, etc.)
        try:
            import json
            parsed_value = json.loads(value)
        except Exception:
            parsed_value = value  # Treat as plain string if JSON parsing fails

        merged[key] = parsed_value

    return merged

@staticmethod
    def merge_extra_vars(vars_dict, extra_vars=None):
        """Extend ``vars_dict`` with ``extra-vars``

        :param vars_dict: Dictionary to merge extra-vars into
        :param extra_vars: List of extra-vars
        :returns: The updated dictionary
        :raises ValueError: If an ``extra-`` entry is malformed
        """
        if not isinstance(vars_dict, dict):
            raise ValueError("vars_dict must be a dictionary")
        if not extra_vars:
            return vars_dict

        for item in extra_vars:
            if isinstance(item, dict):
                # Merge dictionary entries directly
                vars_dict.update(item)
                continue

            if isinstance(item, str):
                if "=" not in item:
                    raise ValueError(f"Malformed extra-var entry: '{item}'. Expected 'key=value'.")
                key, value = item.split("=", 1)
                key = key.strip()
                value = value.strip()
                if not key:
                    raise ValueError(f"Malformed extra-var entry: '{item}'. Key cannot be empty.")
                vars_dict[key] = value
                continue

            # Unsupported type
            raise ValueError(f"Unsupported extra-var type: {type(item).__name__}")

        return vars_dict

@staticmethod
def merge_extra_vars(vars_dict, extra_vars=None):
    """
    Extend ``vars_dict`` with ``extra-vars``.

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars (supports dict, list/tuple of dicts or string representations)
    :return: The updated dictionary
    """
    # Validate that vars_dict is a dictionary
    if not isinstance(vars_dict, dict):
        raise TypeError(f"vars_dict must be a dict, got {type(vars_dict).__name__}")

    # If no extra values to merge, simply return the original dictionary
    if extra_vars is None:
        return vars_dict

    # Helper to process a single key=value string
    def _process_kv_string(kv_str):
        if kv_str is None:
            return
        if not isinstance(kv_str, str):
            raise TypeError(f"Expected string for key=value pair, got {type(kv_str).__name__}")
        if '=' not in kv_str:
            raise ValueError(f"Invalid extra var string '{kv_str}'. Expected format 'key=value'.")
        key, value = kv_str.split('=', 1)
        key = key.strip()
        value = value.strip()
        if not key:
            raise ValueError(f"Empty key in extra var string '{kv_str}'.")
        vars_dict[key] = value

    # Process based on the type of extra_vars
    if isinstance(extra_vars, dict):
        vars_dict.update(extra_vars)
    elif isinstance(extra_vars, (list, tuple)):
        for item in extra_vars:
            if isinstance(item, dict):
                vars_dict.update(item)
            elif isinstance(item, str):
                _process_kv_string(item)
            else:
                raise TypeError(f"Unsupported item type {type(item).__name__} in extra_vars list; "
                                f"expected dict or str.")
    elif isinstance(extra_vars, str):
        _process_kv_string(extra_vars)
    else:
        raise TypeError(f"extra_vars must be a dict, list, tuple, or str; got {type(extra_vars).__name__}")

    return vars_dict

@staticmethod
def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if not isinstance(vars_dict, dict):
        raise TypeError("vars_dict must be a dictionary")
    if extra_vars is None:
        return

    def _convert_value(val):
        """Attempt to convert a string value to a Python type."""
        val = val.strip()
        lower = val.lower()
        if lower == "true":
            return True
        if lower == "false":
            return False
        if lower in ("none", "null"):
            return None
        # Remove surrounding quotes if present
        if (val.startswith('"') and val.endswith('"')) or (val.startswith("'") and val.endswith("'")):
            return val[1:-1]
        # Numeric conversion
        try:
            return int(val)
        except ValueError:
            pass
        try:
            return float(val)
        except ValueError:
            pass
        return val

    def _process_assignment(assignment):
        if "=" not in assignment:
            return
        key, val = assignment.split("=", 1)
        key = key.strip()
        if key:
            vars_dict[key] = _convert_value(val)

    if isinstance(extra_vars, dict):
        vars_dict.update(extra_vars)
    elif isinstance(extra_vars, str):
        # Split on whitespace and newlines, ignoring empty tokens
        tokens = [tok for tok in extra_vars.replace("\n", " ").split() if tok]
        for tok in tokens:
            _process_assignment(tok)
    elif isinstance(extra_vars, (list, tuple)):
        for item in extra_vars:
            if isinstance(item, dict):
                vars_dict.update(item)
            elif isinstance(item, str):
                _process_assignment(item)
            else:
                raise TypeError("Invalid item in extra_vars list/tuple: must be str or dict")
    else:
        raise TypeError("extra_vars must be a dict, list, tuple, or string")
    return None

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     workspace
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    # Imports are local to avoid adding module level imports
    import subprocess
    import json
    import os

    # Resolve the full path of the playbook relative to the workspace
    if not os.path.isabs(playbook_path):
        workspace_path = getattr(ir_workspace, "workspace_dir", "")
        playbook_path = os.path.join(workspace_path, playbook_path)

    if not os.path.isfile(playbook_path):
        raise FileNotFoundError(f"Playbook '{playbook_path}' does not exist")

    cmd = ["ansible-playbook", playbook_path]

    # Handle verbosity
    if verbose:
        try:
            v_level = int(verbose)
        except Exception:
            raise ValueError(f"Invalid verbosity level: {verbose}")
        cmd.extend(["-" + "v" * v_level])

    # Handle extra_vars
    if extra_vars:
        if not isinstance(extra_vars, dict):
            raise TypeError("extra_vars must be a dict")
        try:
            json_vars = json.dumps(extra_vars)
        except Exception as e:
            raise ValueError(f"Could not serialize extra_vars: {e}")
        cmd.extend(["--extra-vars", json_vars])

    # Handle ansible_args
    if ansible_args:
        if not isinstance(ansible_args, dict):
            raise TypeError("ansible_args must be a dict")
        for key, val in ansible_args.items():
            if key is None:
                continue
            # Ensure flag style
            if not isinstance(key, str):
                raise TypeError(f"Argument key '{key}' must be a string")
            if val is True:
                cmd.append(key)
            elif val is False or val is None:
                # do not include flag
                continue
            else:
                cmd.extend([key, str(val)])

    # Execute the command
    try:
        result = subprocess.run(
            cmd,
            cwd=ir_workspace.workspace_dir if hasattr(ir_workspace, "workspace_dir") else None,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            check=False
        )
    except FileNotFoundError:
        raise FileNotFoundError("ansible-playbook executable not found. "
                                "Ensure Ansible is installed and in PATH.")
    except Exception as e:
        raise RuntimeError(f"Error running ansible-playbook: {e}")

    # Log output
    if ir_plugin and hasattr(ir_plugin, "log"):
        ir_plugin.log(result.stdout)
        ir_plugin.log(result.stderr, level="error")

    # Raise error on non-zero exit if desired
    if result.returncode != 0:
        raise RuntimeError(f"ansible-playbook failed with return code {result.returncode}\n"
                           f"STDOUT:\n{result.stdout}\nSTDERR:\n{result.stderr}")

    return result

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    import subprocess
    import json
    import shlex
    from pathlib import Path

    # Validate playbook path
    if not playbook_path:
        raise ValueError("playbook_path must be provided")
    playbook_file = Path(playbook_path)
    if not playbook_file.is_file():
        raise ValueError(f"Playbook '{playbook_path}' does not exist or is not a file")

    # Base command
    cmd = ["ansible-playbook", str(playbook_file)]

    # Verbosity
    if verbose is not None:
        if isinstance(verbose, int):
            if verbose < 0:
                raise ValueError("Verbosity level must be non-negative")
            cmd.extend([f"-v" for _ in range(verbose)])
        elif isinstance(verbose, str):
            # Accept strings like '-vvv' or '-v'
            if verbose.startswith("-"):
                # Split into individual flags
                flags = list(verbose)
                for flag in flags:
                    if flag != '-':
                        cmd.append(flag)
            else:
                raise ValueError("Verbose string must start with '-'")
        else:
            raise TypeError("Verbose must be int or str")

    # Additional ansible arguments
    if ansible_args is not None:
        if not isinstance(ansible_args, dict):
            raise TypeError("ansible_args must be a dict")
        for key, value in ansible_args.items():
            if not key:
                continue
            opt = f"--{key.lstrip('-')}"
            if isinstance(value, bool):
                if value:
                    cmd.append(opt)
                else:
                    # skip false flags
                    continue
            elif value is None:
                cmd.append(opt)
            elif isinstance(value, (list, tuple)):
                for val in value:
                    if isinstance(val, bool) and val is True:
                        cmd.append(opt)
                    else:
                        cmd.extend([opt, str(val)])
            else:
                cmd.extend([opt, str(value)])

    # Extra vars
    if extra_vars is not None:
        if not isinstance(extra_vars, dict):
            raise TypeError("extra_vars must be a dict")
        try:
            json_vars = json.dumps(extra_vars, ensure_ascii=False)
        except (TypeError, ValueError) as exc:
            raise ValueError(f"extra_vars could not be serialized to JSON: {exc}") from exc
        cmd.extend(["--extra-vars", json_vars])

    # Setup environment
    env = dict(**subprocess.os.environ)
    env.setdefault("ANSIBLE_FORCE_COLOR", "1")

    # Log the command for debugging, but mask sensitive data if any
    safe_cmd = [shlex.quote(part) if isinstance(part, str) else part for part in cmd]
    ir_plugin.debug(f"Running ansible-playbook: {' '.join(map(str, safe_cmd))}")

    try:
        # Execute command
        result = subprocess.run(
            cmd,
            capture_output=True,
            text=True,
            env=env,
            cwd=ir_workspace.path if hasattr(ir_workspace, "path") else None,
        )
    except FileNotFoundError as exc:
        raise RuntimeError("ansible-playbook executable not found") from exc
    except subprocess.SubprocessError as exc:
        raise RuntimeError(f"Error running ansible-playbook: {exc}") from exc

    # Log output
    if result.stdout:
        ir_plugin.info(f"ansible-playbook stdout:\n{result.stdout}")
    if result.stderr:
        ir_plugin.warn(f"ansible-playbook stderr:\n{result.stderr}")

    if result.returncode != 0:
        raise subprocess.CalledProcessError(
            result.returncode, cmd, output=result.stdout, stderr=result.stderr
        )

    return (result.returncode, result.stdout, result.stderr)

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """
    Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    import subprocess
    import json
    from pathlib import Path

    # Ensure playbook file exists
    playbook_path = Path(playbook_path)
    if not playbook_path.is_file():
        raise FileNotFoundError(f"Playbook not found: {playbook_path}")

    # Resolve ansible-playbook binary
    try:
        ansible_exe = shutil.which("ansible-playbook")
        if ansible_exe is None:
            raise FileNotFoundError("ansible-playbook executable not found in PATH.")
    except Exception:
        # If shutil not imported, search manually
        for exe in ["ansible-playbook"]:
            found = subprocess.run(
                ["which", exe], stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True
            )
            if found.returncode == 0 and found.stdout.strip():
                ansible_exe = found.stdout.strip()
                break
        else:
            raise FileNotFoundError("ansible-playbook executable not found in PATH.")

    # Build command
    cmd = [ansible_exe, str(playbook_path)]

    # Add verbosity
    if verbose:
        if isinstance(verbose, int):
            if verbose < 1:
                pass
            else:
                cmd.append("-v" * verbose)
        else:
            # If verbose is a string, add it directly
            cmd.append(str(verbose))

    # Add ansible_args
    if ansible_args:
        for key, value in ansible_args.items():
            if value is True:
                cmd.append(f"--{key}")
            elif value is False or value is None:
                continue
            else:
                # Convert list/tuple to comma-separated string
                if isinstance(value, (list, tuple)):
                    value = ",".join(str(v) for v in value)
                cmd.append(f"--{key}={value}")

    # Add extra_vars
    if extra_vars:
        try:
            ev = json.dumps(extra_vars)
        except Exception:
            ev = str(extra_vars)
        cmd.extend(["--extra-vars", ev])

    # Execute command
    try:
        result = subprocess.run(
            cmd,
            capture_output=True,
            text=True,
            check=False,
        )
    except FileNotFoundError as exc:
        raise FileNotFoundError(
            f"Failed to execute ansible-playbook: {exc}"
        ) from exc

    # Raise on non-zero exit code
    if result.returncode != 0:
        raise subprocess.CalledProcessError(
            returncode=result.returncode,
            cmd=cmd,
            output=result.stdout,
            stderr=result.stderr,
        )

    return result

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                      extra_vars=None, ansible_args=None):
    """
    Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     workspace
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    # Build the base command
    cmd = ['ansible-playbook']

    # Add verbosity flag if requested
    if verbose:
        # Ensure verbose is an integer ≥ 1
        try:
            level = int(verbose)
            if level > 0:
                cmd.append("-" + "v" * level)
        except Exception:
            # silently ignore invalid verbosity values
            pass

    # Append explicit Ansible arguments
    if ansible_args and isinstance(ansible_args, dict):
        for key, value in ansible_args.items():
            flag = f"--{key}"
            if isinstance(value, bool):
                if value:
                    cmd.append(flag)
            elif isinstance(value, (list, tuple)):
                for part in value:
                    cmd.extend([flag, str(part)])
            else:
                cmd.extend([flag, str(value)])

    # Append the playbook path
    if not playbook_path:
        raise ValueError("playbook_path must be provided")
    cmd.append(playbook_path)

    # Append extra variables if provided
    if extra_vars:
        try:
            import json
            cmd.extend(['--extra-vars', json.dumps(extra_vars)])
        except Exception as e:
            raise ValueError(f"Failed to serialize extra_vars: {e}") from e

    # Execute the command
    try:
        import subprocess
        result = subprocess.run(
            cmd,
            capture_output=True,
            text=True,
            check=True,
        )
    except subprocess.CalledProcessError as e:
        # We can optionally log the error via ir_plugin if it supports logging
        if hasattr(ir_plugin, "log") and hasattr(ir_plugin.log, "error"):
            ir_plugin.log.error(f"Ansible playbook failed: {e.stderr}")
        raise RuntimeError(f"Ansible playbook execution failed: {e.stderr}") from e
    except FileNotFoundError as e:
        raise RuntimeError("ansible-playbook executable not found") from e
    except Exception as e:
        raise RuntimeError(f"Unexpected error running ansible-playbook: {e}") from e

    # Return stdout of the run
    return result.stdout

def _run_playbook(cli_args, vars_dict, ir_workspace, ir_plugin):
    """
    Runs ansible cli with vars dict

    :param vars_dict: dict, Will be passed as Ansible extra-vars
    :param cli_args: the list  of command line arguments
    :param ir_workspace: An Infrared Workspace object represents the active
     workspace
    :param ir_plugin: An InfraredPlugin object of the current plugin
    :return: ansible results
    """
    # Validate input types
    if not isinstance(cli_args, list) or not all(isinstance(arg, str) for arg in cli_args):
        raise TypeError("cli_args must be a list of strings")
    if not isinstance(vars_dict, dict):
        raise TypeError("vars_dict must be a dictionary")
    if ir_workspace is None:
        raise ValueError("ir_workspace cannot be None")
    if ir_plugin is None:
        raise ValueError("ir_plugin cannot be None")

    # Import necessary modules locally to avoid global imports
    try:
        import json
        import subprocess
        import os
    except Exception as e:
        raise RuntimeError(f"Required modules not available: {e}")

    # Prepare the command
    cmd = ["ansible-playbook"] + cli_args
    # Append extra-vars JSON string; if user already provided -e, we'll still add one
    try:
        extra_vars_str = json.dumps(vars_dict, separators=(",", ":"))
    except (TypeError, ValueError) as e:
        raise ValueError(f"vars_dict cannot be JSON serializable: {e}")
    cmd += ["-e", extra_vars_str]

    # Determine working directory from workspace; fallback to current directory
    cwd = None
    try:
        # Infrared's workspace might expose a property 'workspace_path' or 'root_dir'
        if hasattr(ir_workspace, "workspace_path"):
            cwd = getattr(ir_workspace, "workspace_path")
        elif hasattr(ir_workspace, "root_dir"):
            cwd = getattr(ir_workspace, "root_dir")
        elif hasattr(ir_workspace, "root"):
            cwd = getattr(ir_workspace, "root")
        if cwd and not os.path.isdir(cwd):
            raise FileNotFoundError(f"Workspace path does not exist: {cwd}")
    except Exception:
        cwd = None

    # Prepare environment
    env = os.environ.copy()

    # Execute the command
    try:
        completed = subprocess.run(
            cmd,
            cwd=cwd,
            env=env,
            capture_output=True,
            text=True,
            check=False,  # We'll handle non-zero return codes ourselves
        )
    except FileNotFoundError:
        raise RuntimeError("ansible-playbook command not found. "
                           "Ensure Ansible is installed and available in PATH.")
    except Exception as e:
        raise RuntimeError(f"Error executing ansible-playbook: {e}")

    # Build result dictionary
    result = {
        "returncode": completed.returncode,
        "stdout": completed.stdout,
        "stderr": completed.stderr,
    }

    # If there's a plugin-specific result processing, let it handle the results
    # The plugin may provide a method `parse_ansible_output` to further process
    if hasattr(ir_plugin, "parse_ansible_output") and callable(ir_plugin.parse_ansible_output):
        try:
            processed = ir_plugin.parse_ansible_output(completed.stdout, completed.stderr, completed.returncode)
            if isinstance(processed, dict):
                result.update(processed)
        except Exception:
            # Ignore plugin processing errors to avoid masking the original result
            pass

    return result

def _run_playbook(cli_args, vars_dict, ir_workspace, ir_plugin):
    """Runs ansible cli with vars dict

    :param vars_dict: dict, Will be passed as Ansible extra-vars.
    :param cli_args: the list of command line arguments.
    :param ir_workspace: An Infrared Workspace object represents the active workspace.
    :param ir_plugin: An InfraredPlugin object of the current plugin.
    :return: dict with keys 'rc', 'stdout', 'stderr' representing ansible results.
    """
    import subprocess
    import json
    import os

    # Validate inputs
    if not isinstance(cli_args, list):
        raise TypeError("cli_args must be a list of command line arguments")
    if vars_dict is None:
        vars_dict = {}
    if not isinstance(vars_dict, dict):
        raise TypeError("vars_dict must be a dictionary")

    # Build command
    cmd = ["ansible-playbook"] + cli_args

    # Serialize vars_dict to JSON string for --extra-vars
    # Only add if vars_dict is not empty
    if vars_dict:
        try:
            extra_vars_json = json.dumps(vars_dict, separators=(",", ":"))
        except (TypeError, ValueError) as e:
            raise ValueError(f"vars_dict contains non-serializable values: {e}") from e
        cmd += ["--extra-vars", extra_vars_json]

    # Determine working directory and environment
    cwd = None
    env = os.environ.copy()

    # Attempt to get workspace directory if available
    if ir_workspace is not None:
        workspace_dir = None
        # Common attributes for workspace path
        for attr in ("path", "root", "get_path", "workspace_dir"):
            if hasattr(ir_workspace, attr):
                try:
                    workspace_dir = getattr(ir_workspace, attr)
                except Exception:
                    workspace_dir = None
                if callable(workspace_dir):
                    try:
                        workspace_dir = workspace_dir()
                    except Exception:
                        workspace_dir = None
                break
        if workspace_dir and isinstance(workspace_dir, str) and os.path.isdir(workspace_dir):
            cwd = workspace_dir

    # Attempt to get plugin specific environment settings if provided
    if ir_plugin is not None:
        plugin_env = None
        for attr in ("get_env", "env", "extra_env"):
            if hasattr(ir_plugin, attr):
                try:
                    plugin_env = getattr(ir_plugin, attr)
                except Exception:
                    plugin_env = None
                if callable(plugin_env):
                    try:
                        plugin_env = plugin_env()
                    except Exception:
                        plugin_env = None
                break
        if plugin_env and isinstance(plugin_env, dict):
            env.update(plugin_env)

    try:
        result = subprocess.run(
            cmd,
            cwd=cwd,
            env=env,
            capture_output=True,
            text=True,
            check=False,  # We capture rc ourselves
        )
    except FileNotFoundError as e:
        # ansible-playbook command not found
        raise RuntimeError(
            f"Unable to find 'ansible-playbook' executable. Please ensure Ansible is installed and in PATH."
        ) from e
    except Exception as e:
        # Generic error in running the command
        raise RuntimeError(f"Error running ansible-playbook: {e}") from e

    return {
        "rc": result.returncode,
        "stdout": result.stdout,
        "stderr": result.stderr,
    }

def _convert_non_cli_args(self, parser_name, values_dict):
        """Casts arguments to correct types by modifying values_dict in place.

        By default all the values are strings. This method attempts to
        convert those strings into booleans, integers, or floats when
        appropriate. Lists of strings are also processed element‑wise.
        Any value that cannot be converted is left unchanged.

        :param parser_name: The command name, e.g. main, virsh, ospd, etc.  (Ignored in this implementation)
        :param values_dict: The dictionary of arguments.  The dictionary is modified in place.
        """
        if not isinstance(values_dict, dict):
            return

        # Helper to convert a single string value
        def _convert_val(v):
            if not isinstance(v, str):
                return v
            s = v.strip()
            if s.lower() in {"true", "false"}:
                return s.lower() == "true"
            # Handle integer
            if s.isdigit() or (s.startswith('-') and s[1:].isdigit()):
                try:
                    return int(s)
                except ValueError:
                    pass
            # Handle float
            try:
                return float(s)
            except ValueError:
                pass
            return v

        for key, value in list(values_dict.items()):
            if isinstance(value, list):
                # Convert each element if it is a string
                new_list = []
                for item in value:
                    new_list.append(_convert_val(item))
                values_dict[key] = new_list
            else:
                values_dict[key] = _convert_val(value)

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict in place.

    By default all the values are strings.  If a ``_arg_type_map`` attribute
    exists on the instance it must be a mapping of ``parser_name`` to another
    mapping of argument name to the desired type (e.g. ``int``, ``bool``).
    Any argument that is not listed will be heuristically converted.

    Parameters
    ----------
    parser_name : str
        The command name, e.g. ``main``, ``virsh``, ``ospd``, etc.
    values_dict : dict
        Dictionary of the raw values (typically all strings).

    Returns
    -------
    dict
        The same dictionary instance, which has been modified in place.
    """
    if not isinstance(values_dict, dict):
        raise TypeError(f"values_dict must be a dict, got {type(values_dict).__name__}")

    # Type mapping for this parser, if defined
    type_map = getattr(self, "_arg_type_map", {}).get(parser_name, {})

    for key, raw_val in values_dict.items():
        # Preserve None values; nothing to cast
        if raw_val is None:
            continue

        target_type = type_map.get(key)

        # If a target type is explicitly defined, honour it.
        if target_type is not None:
            # Special handling for ``list``: split on comma
            if target_type is list:
                try:
                    # Accept strings, tuples, lists, or already-listy values
                    if isinstance(raw_val, (list, tuple)):
                        values_dict[key] = [str(v).strip() for v in raw_val if v is not None]
                    else:
                        values_dict[key] = [item.strip() for item in str(raw_val).split(",") if item.strip()]
                    continue
                except Exception:
                    # Fall through to keep the original if conversion failed
                    pass

            try:
                if target_type is bool:
                    # Preserve bools
                    if isinstance(raw_val, bool):
                        values_dict[key] = raw_val
                    elif isinstance(raw_val, str):
                        lowered = raw_val.lower()
                        if lowered in ("true", "1", "yes", "y"):
                            values_dict[key] = True
                        elif lowered in ("false", "0", "no", "n"):
                            values_dict[key] = False
                        else:
                            # Try numeric interpretation
                            values_dict[key] = bool(int(raw_val))
                    else:
                        values_dict[key] = bool(raw_val)
                else:
                    values_dict[key] = target_type(raw_val)
            except Exception:
                # If the target type conversion fails, keep the raw string
                pass
        else:
            # No explicit type: attempt heuristic conversion
            if isinstance(raw_val, bool):
                continue  # already correct
            if isinstance(raw_val, str):
                stripped = raw_val.strip()
                lowered = stripped.lower()
                if lowered in ("true", "1", "yes", "y"):
                    values_dict[key] = True
                elif lowered in ("false", "0", "no", "n"):
                    values_dict[key] = False
                else:
                    # Try integer conversion first
                    try:
                        # Handles +, -, 0x, etc.
                        int_val = int(stripped, 0)
                        values_dict[key] = int_val
                    except Exception:
                        # Try float conversion
                        try:
                            values_dict[key] = float(stripped)
                        except Exception:
                            # Leave as string
                            pass
    return values_dict

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    # Validate inputs
    if not isinstance(values_dict, dict):
        raise TypeError("values_dict must be a dictionary")

    # Helper to cast a single value
    def _cast_value(val):
        # If value is already non-string and not list, leave as is
        if not isinstance(val, str):
            if isinstance(val, list):
                return [_cast_value(v) for v in val]
            return val

        stripped = val.strip()
        # Handle booleans
        lowered = stripped.lower()
        if lowered in ("true", "false"):
            return lowered == "true"
        # Handle None representations
        if lowered in ("none", ""):
            return None
        # Handle numeric types
        # Integer
        try:
            if stripped.startswith(('+', '-')) and stripped[1:].isdigit():
                return int(stripped)
            if stripped.isdigit():  # positive int
                return int(stripped)
        except Exception:
            pass
        # Float
        try:
            return float(stripped)
        except Exception:
            pass
        # List represented by comma separation (if appropriate)
        if "," in stripped:
            parts = [p.strip() for p in stripped.split(",")]
            # Attempt to cast each part, but only if they all represent the same type
            casted_parts = [_cast_value(p) for p in parts]
            # Return list if multiple, else single element
            return casted_parts if len(casted_parts) > 1 else casted_parts[0]
        # Fallback to original string
        return stripped

    # Iterate over dictionary items and cast them in place
    for key in list(values_dict.keys()):
        try:
            values_dict[key] = _cast_value(values_dict[key])
        except Exception:
            # If any unexpected error occurs, keep the original value
            continue
    # No explicit return is needed; values_dict is modified in place.

def _convert_non_cli_args(self, parser_name, values_dict):
        """Casts arguments to correct types by modifying values_dict param.

        By default all the values are strings. This method applies a fixed
        conversion mapping for known parsers. If conversion fails a
        ValueError is raised. Unknown arguments are left untouched.
        """
        # Define conversion rules per parser.
        mapping = {
            'main': {
                'debug': lambda v: v.lower() in ('true', '1', 'yes', 'y'),
                'count': int,
                'timeout': int,
                'threshold': float,
                'tags': lambda v: [x.strip() for x in v.split(',') if x],
            },
            'virsh': {
                'listeners': int,
                'timeout': int,
                'config': str,   # explicit cast to keep type consistency
                'vnc_port': int,
                'gui': lambda v: v.lower() in ('true', '1', 'yes', 'y'),
            },
            'ospd': {
                'max_workers': int,
                'retry': int,
                'verbose': lambda v: v.lower() in ('true', '1', 'yes', 'y'),
                'timeout': float,
                'paths': lambda v: [x.strip() for x in v.split(',') if x],
            },
        }

        conv_map = mapping.get(parser_name, {})

        for arg, conv in conv_map.items():
            if arg in values_dict and values_dict[arg] is not None:
                try:
                    # Ensure string input before conversion
                    val = values_dict[arg]
                    # If conversion is a callable that expects a string
                    values_dict[arg] = conv(val)
                except Exception as exc:
                    raise ValueError(
                        f"Failed to convert argument '{arg}' for parser "
                        f"'{parser_name}': {exc}"
                    ) from exc
        # No return needed; values_dict is mutated in place.

def get_plugin_spec_flatten_dict(plugin_dir):
    """
    Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json
    try:
        import yaml
    except ImportError:
        yaml = None

    # Resolve plugin directory path
    try:
        plugin_dir = os.path.abspath(plugin_dir)
    except Exception:
        return {}

    if not os.path.isdir(plugin_dir):
        return {}

    # Determine spec file path; try JSON first, then YAML formats
    spec_file = None
    for fname in ('plugin.json', 'plugin.yml', 'plugin.yaml'):
        fpath = os.path.join(plugin_dir, fname)
        if os.path.isfile(fpath):
            spec_file = fpath
            break

    if not spec_file:
        return {}

    # Load the spec
    try:
        with open(spec_file, 'r', encoding='utf-8') as f:
            if spec_file.endswith('.json'):
                data = json.load(f)
            else:
                if yaml is None:
                    return {}
                data = yaml.safe_load(f)
    except Exception:
        return {}

    # Helper to flatten nested dicts
    def _flatten(d, parent_key=''):
        flat = {}
        if not isinstance(d, dict):
            return flat
        for k, v in d.items():
            new_key = f"{parent_key}.{k}" if parent_key else k
            if isinstance(v, dict):
                flat.update(_flatten(v, new_key))
            else:
                flat[new_key] = v
        return flat

    return _flatten(data) if isinstance(data, dict) else {}

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    from pathlib import Path
    import json, yaml

    def _flatten_dict(d, parent_key='', sep='.'):
        """Recursively flattens a dictionary."""
        items = {}
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(_flatten_dict(v, new_key, sep=sep))
            else:
                items[new_key] = v
        return items

    p = Path(plugin_dir)
    if not p.is_dir():
        raise ValueError(f"Provided plugin_dir '{plugin_dir}' is not a directory")

    spec_file = None
    possible_yaml = ['plugin.yaml', 'plugin.yml', 'spec.yaml', 'config.yaml']
    possible_json = ['plugin.json', 'spec.json', 'config.json']
    for fname in possible_yaml + possible_json:
        candidate = p / fname
        if candidate.is_file():
            spec_file = candidate
            break

    if spec_file is None:
        raise FileNotFoundError(f"No plugin spec file found in '{plugin_dir}'")

    try:
        if spec_file.suffix in {'.yaml', '.yml'}:
            with spec_file.open('r', encoding='utf-8') as f:
                data = yaml.safe_load(f)
        elif spec_file.suffix == '.json':
            with spec_file.open('r', encoding='utf-8') as f:
                data = json.load(f)
        else:
            raise ValueError(f"Unsupported spec file format: {spec_file.suffix}")
    except Exception as e:
        raise RuntimeError(f"Failed to load plugin spec from '{spec_file}': {e}")

    if not isinstance(data, dict):
        raise ValueError(f"Plugin spec root should be a dictionary, got {type(data).__name__}")

    return _flatten_dict(data)

