    except Exception as exc:
        raise ValueError(f"Error validating plugin_dir: {exc}") from exc

    # Possible spec filenames (common patterns)
    spec_filenames = [
        "plugin_spec.json",
        "metadata.json",
        "spec.json",
        "plugin.json",
        "plugin.yaml",
        "plugin.yml",
    ]

    # Locate the spec file
    spec_path = None
    for fname in spec_filenames:
        candidate = os.path.join(plugin_dir, fname)
        if os.path.exists(candidate):
            spec_path = candidate
            break

    if not spec_path:
        raise FileNotFoundError("No plugin spec file found in the directory")

    # Load spec content
    import json
    try:
        if spec_path.lower().endswith((".yaml", ".yml")):
            # YAML support requires PyYAML; if not available, fail gracefully
            try:
                import yaml
                with open(spec_path, "r", encoding="utf-8") as f:
                    spec_data = yaml.safe_load(f)
            except ImportError:
                raise RuntimeError("YAML parsing requested but PyYAML is not installed")
            except Exception as exc:
                raise ValueError(f"Error parsing YAML spec file: {exc}") from exc
        else:
            with open(spec_path, "r", encoding="utf-8") as f:
                spec_data = json.load(f)
    except json.JSONDecodeError as exc:
        raise ValueError(f"Invalid JSON in spec file: {exc}") from exc
    except Exception as exc:
        raise RuntimeError(f"Failed to read or parse spec file: {exc}") from exc

    if not isinstance(spec_data, dict):
        raise ValueError("Spec file must contain a JSON object at the top level")

    # Flatten nested dictionary
    def _flatten(d, parent_key=""):
        items = {}
        for k, v in d.items():
            new_key = f"{parent_key}.{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(_flatten(v, new_key))
            elif isinstance(v, list):
                # Store list as a comma-separated string or keep as JSON string
                # Here we convert to a JSON-formatted string for readability
                items[new_key] = json.dumps(v, ensure_ascii=False)
            else:
                items[new_key] = v
        return items

    try:
        flat_dict = _flatten(spec_data)
    except Exception as exc:
        raise RuntimeError(f"Error flattening spec data: {exc}") from exc

    return flat_dict

