def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    import os
    env_var = "CONFIG_PATH"
    # Only set the env var if it is not already defined or empty
    if not os.getenv(env_var):
        # Retrieve the config path from the instance.
        # Use getattr in case the attribute name changes or is missing.
        config_path = getattr(self, "config_path", None)
        if config_path is None:
            raise AttributeError(
                f"{self.__class__.__name__} instance has no attribute 'config_path'"
            )
        try:
            # Ensure we are storing a string representation of the path
            os.environ[env_var] = str(config_path)
        except (OSError, ValueError) as exc:
            # Wrap the original exception to provide clearer context
            raise RuntimeError(
                f"Failed to set environment variable '{env_var}': {exc}"
            ) from exc
    return os.getenv(env_var)  # Return the set or existing value for convenience.

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    env_var = "CONFIG_PATH"
    try:
        # Check if the environment variable is already set
        if not os.environ.get(env_var):
            # Prefer a value stored in the instance if available
            default_path = getattr(self, "config_path", None)
            # Fallback to a standard config file in the current working directory
            if default_path is None:
                default_path = os.path.abspath(os.path.join(os.getcwd(), "config.yaml"))
            os.environ[env_var] = default_path
    except Exception:
        # Silently ignore any issues setting the environment variable
        pass

