        # Silently ignore any issues (e.g., permission errors or a read‑only environment)
        pass

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    # Validate types
    if not isinstance(path, str) or not isinstance(root, str):
        raise TypeError("Both path and root must be strings")
    # Empty root is not valid
    if root == "":
        raise ValueError("Root must not be an empty string")
    # Ensure root matches as a prefix
    # If root does not end with a separator, it can still be a prefix
    # (e.g., root='C:\\foo', path='C:\\foo\\bar')
    # If root ends with a separator, it must match exactly
    if not path.startswith(root):
        # Try adding a separator to the root if it doesn't already have one
        if not root.endswith("/") and not root.endswith("\\"):
            alt_root = root + "/"
            if path.startswith(alt_root):
                root = alt_root
            else:
                alt_root = root + "\\"
                if path.startswith(alt_root):
                    root = alt_root
                else:
                    raise ValueError(f"Root '{root}' not found in path '{path}'")
        else:
            raise ValueError(f"Root '{root}' not found in path '{path}'")
    # Extract the remaining part
    remaining = path[len(root):]
    # Remove a leading separator if present
    if remaining.startswith("/") or remaining.startswith("\\"):
        remaining = remaining[1:]
    # If nothing remains after stripping, raise an error
    if remaining == "":
        raise ValueError(f"Path '{path}' is identical to root '{root}', no relative path remains")
    return remaining

def strip_root(path, root):
    """
    Remove root from path, throw exception on failure.
    Returns the relative path after stripping the root prefix.
    Raises ValueError if root is not a prefix of path.
    """
    if not isinstance(path, str):
        raise TypeError(f"path must be a string, got {type(path).__name__}")
    if not isinstance(root, str):
        raise TypeError(f"root must be a string, got {type(root).__name__}")

    # Normalise both paths to use '/' as separator for comparison
    path_norm = path.replace("\\", "/")
    root_norm = root.replace("\\", "/")

    # Remove trailing slashes from root, but keep a single '/' if root is '/'
    if root_norm != "/":
        while root_norm.endswith("/") and len(root_norm) > 1:
            root_norm = root_norm[:-1]
    else:
        root_norm = "/"

    # Remove trailing slashes from path
    while path_norm.endswith("/") and len(path_norm) > 1:
        path_norm = path_norm[:-1]

    # Empty root is not allowed
    if root_norm == "":
        raise ValueError("root path cannot be empty")

    # If the two paths are identical, return an empty string
    if path_norm == root_norm:
        return ""

    # Special case: root is the filesystem root "/"
    if root_norm == "/":
        # Strip leading slashes from the path
        return path_norm.lstrip("/")

    # Check for root plus a separator at the start of the path
    prefix = root_norm + "/"
    if path_norm.startswith(prefix):
        return path_norm[len(prefix) :]
    else:
        raise ValueError(f"root '{root}' does not match the beginning of path '{path}'")
